INSERT INTO `aartis` (`id`, `aarti_name`, `deity_name`, `category_id`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `verses`, `chorus`, `significance`, `instructions`, `audio_url`, `audio_duration`, `video_url`, `lyrics_url`, `is_premium`, `views_count`, `likes_count`, `display_order`, `created_at`, `updated_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1, 'Jai Ganesh Jai Ganesh Jai Ganesh Deva', 'Ganesh', 21, 'जय गणेश जय गणेश जय गणेश देवा। माता जाकी पार्वती पिता महादेवा॥\r\nएक दंत दयावंत चार भुजा धारी। माथे सिंदूर सोहे मूसे की सवारी॥\r\nअंधन को आंख देते कोढ़न को काया। बांझन को पुत्र देते निर्धन को माया॥\r\nसूर्य शाम शरण आए फल पाए। दीनन की लाज रखो शंभु सुत वारी॥\r\nजय गणेश जय गणेश जय गणेश देवा। माता जाकी पार्वती पिता महादेवा॥', 'Jai Ganesh Jai Ganesh Jai Ganesh Deva Mata Jaki Parvati Pita Mahadeva\r\nEk Dant Dayavant Char Bhuja Dhari Mathe Sindur Sohe Muse Ki Savari\r\nAndhan Ko Ankh Dete Kodhan Ko Kaya Banjhan Ko Putra Dete Nirdhan Ko Maya\r\nSurya Sham Sharan Aaye Fal Pave Dinan Ki Laj Rakho Shambhu Sut Vari\r\nJai Ganesh Jai Ganesh Jai Ganesh Deva Mata Jaki Parvati Pita Mahadeva', 'जय गणेश जय गणेश जय गणेश देवा। माता पार्वती और पिता महादेव हैं। एक दंत, दयावंत, चार भुजाधारी। माथे पर सिंदूर सुशोभित, मूषक वाहन। अंधों को आंख देते, कोढ़ियों को स्वस्थ शरीर। बांझों को पुत्र देते, निर्धनों को धन। सूर्य और शाम को शरण आने से फल मिलता है। हे शंभुपुत्र, दीनों की लाज रखो।', 'Victory to Ganesh, victory to Ganesh, victory to Lord Ganesh. Mother Parvati and Father Mahadev. One-tusked, compassionate, four-armed. Vermillion adorns the forehead, mouse is the vehicle. You give sight to the blind, health to lepers. You grant children to the barren, wealth to the poor. Coming to your shelter at sunrise and sunset, one reaps the fruits. O son of Shambhu, protect the dignity of the humble.\r\nVictory to Ganesh, victory to Ganesh, victory to Lord Ganesh.', NULL, 'जय गणेश जय गणेश जय गणेश देवा', 'गणेश जी की आरती विशेष रूप से किसी भी शुभ कार्य के आरंभ में, गणेश चतुर्थी पर, और प्रतिदिन संध्या के समय की जाती है। इससे विघ्नों का नाश होता है और कार्यों में सफलता मिलती है।', 'दीपक या कपूर जलाकर, भक्ति भाव से यह आरती गाएं। आरती के बाद प्रसाद वितरण करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(2, 'Om Jai Shiv Omkara', 'Shiva', 21, 'ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा। ब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा॥\r\nॐ जय शिव ओंकारा॥\r\nएकानन चतुरानन पंचानन राजे। हंसानन गरुड़ासन वृषवाहन साजे॥\r\nॐ जय शिव ओंकारा॥\r\nदो भुज चार चतुर्भुज दसभुज अति सोहे। त्रिगुण रूप निरखते त्रिभुवन जन मोहे॥\r\nॐ जय शिव ओंकारा॥\r\nअक्षय माला वनमाला मुंडमाला धारी। त्रिपुरारी कंसारी कर माला धारी॥\r\nॐ जय शिव ओंकारा॥', 'Om Jai Shiv Omkara, Swami Jai Shiv Omkara Brahma Vishnu Sadashiv, Ardhangidhara\r\nOm Jai Shiv Omkara\r\nEkanan Chaturanana Panchanana Raje Hamsanana Garudasana Vrishavahana Saje\r\nOm Jai Shiv Omkara\r\nDo Bhuja Char Chaturbhuja Dasabhuja Ati Sohe Triguna Rupa Nirakhate Tribhuvana Jana Mohe\r\nOm Jai Shiv Omkara\r\nAkshaya Mala Vanamala Mundamala Dhari Tripurari Kamsari Kara Mala Dhari\r\nOm Jai Shiv Omkara', 'ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा। ब्रह्मा, विष्णु और सदाशिव, अर्धांगिनी धारण करने वाले। एक मुख, चार मुख, पंचमुख राजते हैं। हंस वाहन, गरुड़ वाहन, वृषभ वाहन सुशोभित हैं। दो भुज, चार भुज, चतुर्भुज, दस भुज अति शोभित हैं। त्रिगुण रूप को तीनों लोकों के लोग निहारते हैं। अक्षय माला, वनमाला, मुंडमाला धारण करने वाले। त्रिपुरारि, कंसारि, कर माला धारण करने वाले।', 'Om, Victory to Shiva, the embodiment of Om. Brahma, Vishnu, and Sadashiva, with the consort by their side. One-faced, four-faced, five-faced, all resplendent. Swan-mounted, eagle-mounted, bull-mounted, all adorned. Two-armed, four-armed, ten-armed, greatly resplendent. The three worlds are enchanted by the three-fold form. Wearing the garland of rudraksha, forest flowers, and skulls. Destroyer of Tripura, slayer of Kamsa, wearing the garland of hands.', NULL, 'ॐ जय शिव ओंकारा', 'शिव जी की आरती प्रतिदिन सोमवार, शिवरात्रि, और सायंकाल में की जाती है। इससे मन को शांति मिलती है, रोगों से मुक्ति मिलती है।', 'बेलपत्र, धतूरा, भांग आदि चढ़ाकर, दीपक जलाकर श्रद्धा से आरती करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'Jai Vishnu Bhagwan', 'Vishnu', 21, 'जय विष्णु भगवान, स्वामी जय विष्णु भगवान। शंख चक्र गदा पद्म, धारी सनातन॥\r\nजय विष्णु भगवान॥\r\nनीलांबर सुंदर, पीतांबर धारी। लक्ष्मी पति मुकुंद, जय जगत विहारी॥\r\nजय विष्णु भगवान॥\r\nकमल नयन विश्वंभर, करुणा के सागर। भक्तों के दुख हरते, कष्ट निवारण करते॥\r\nजय विष्णु भगवान॥\r\nनारद घर आए, संकट हर लाए। भक्त जनों की नैया, पार लगा जाए॥\r\nजय विष्णु भगवान॥', 'Jai Vishnu Bhagwan, Swami Jai Vishnu Bhagwan Shankha Chakra Gada Padma, Dhari Sanatan\r\nJai Vishnu Bhagwan\r\nNeelambar Sundar, Pitambar Dhari Lakshmi Pati Mukund, Jai Jagat Vihari\r\nJai Vishnu Bhagwan\r\nKamal Nayan Vishwambar, Karuna Ke Sagar Bhakton Ke Dukh Harte, Kasht Nivaran Karte\r\nJai Vishnu Bhagwan\r\nNarad Ghar Aaye, Sankat Har Layee Bhakta Janon Ki Naiya, Paar Laga Jaye\r\nJai Vishnu Bhagwan', 'जय विष्णु भगवान, स्वामी जय विष्णु भगवान। शंख, चक्र, गदा, पद्म धारण करने वाले, सनातन। नीलांबर सुंदर, पीतांबर धारण करने वाले। लक्ष्मी पति, मुकुंद, जय जगत विहारी। कमल नयन, विश्वंभर, करुणा के सागर। भक्तों के दुख हरते हैं, कष्ट निवारण करते हैं। नारद घर आए, संकट हर लाए। भक्त जनों की नैया पार लगा जाए।', 'Victory to Lord Vishnu, victory to Lord Vishnu. Holder of conch, discus, mace, and lotus, the eternal one. Beautiful in blue robes, adorned in yellow silk. Consort of Lakshmi, the liberator, the wanderer of the universe. Lotus-eyed, sustainer of the world, ocean of compassion. He removes the sorrows of devotees, alleviates their troubles. Narada came home and removed all obstacles. May the boat of devotees cross the ocean of existence.', NULL, 'जय विष्णु भगवान', 'विष्णु जी की आरती प्रतिदिन, विशेषकर गुरुवार को, और सायंकाल में की जाती है। इससे धन, समृद्धि और मान-सम्मान की प्राप्ति होती है।', 'तुलसी दल, फूल और दीपक से आरती करें। शुद्धता और श्रद्धा का विशेष ध्यान रखें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Om Jai Lakshmi Mata', 'Lakshmi', 21, 'ॐ जय लक्ष्मी माता, स्वामी जय लक्ष्मी माता। विष्णु प्रिया सुखदाता, मोक्ष प्रदाता॥\r\nॐ जय लक्ष्मी माता॥\r\nचंद्र सूर्य प्रभा कर निर्मल, रश्मि समाना। भक्त मन भावन, भक्त मन भावन, कमल सन्ना॥\r\nॐ जय लक्ष्मी माता॥\r\nकामना पूरक, धन धान्य पूरक, महिमा सुख आता। माता रूपेण, माता रूपेण, सब सुख दाता॥\r\nॐ जय लक्ष्मी माता॥\r\nजो कोई तुमको ध्याता, सुख संपत्ति पाता। पुत्र मित्र वृद्धि, पुत्र मित्र वृद्धि, सब कुछ आता॥\r\nॐ जय लक्ष्मी माता॥', 'Om Jai Lakshmi Mata, Swami Jai Lakshmi Mata Vishnu Priya Sukhdata, Moksha Pradata\r\nOm Jai Lakshmi Mata\r\nChandra Surya Prabha Kar Nirmal, Rashmi Samana Bhakta Man Bhavan, Bhakta Man Bhavan, Kamal Sanna\r\nOm Jai Lakshmi Mata\r\nKamana Purak, Dhana Dhanya Purak, Mahima Sukh Ata Mata Rupen, Mata Rupen, Sab Sukh Data\r\nOm Jai Lakshmi Mata\r\nJo Koi Tumko Dhyata, Sukh Sampatti Pata Putra Mitra Vriddhi, Putra Mitra Vriddhi, Sab Kuch Ata\r\nOm Jai Lakshmi Mata', 'ॐ जय लक्ष्मी माता, स्वामी जय लक्ष्मी माता। विष्णु प्रिया, सुखदाता, मोक्ष प्रदाता। चंद्र-सूर्य की प्रभा कर, निर्मल रश्मि समान। भक्त मन भावन, कमलासन। कामना पूरक, धन-धान्य पूरक, महिमा सुख आता। माता रूपेण सब सुख दाता। जो कोई तुमको ध्याता, सुख-संपत्ति पाता। पुत्र, मित्र, वृद्धि, सब कुछ आता।', 'Om, Victory to Mother Lakshmi, victory to Mother Lakshmi. Beloved of Vishnu, giver of happiness, bestower of liberation. Radiant like the moon and sun, pure like their rays. Pleasing to the minds of devotees, seated on a lotus. Fulfiller of desires, bestower of grains and wealth, your glory brings happiness. In motherly form, you give all happiness. Whoever meditates upon you gains happiness and prosperity. Children, friends, growth, everything comes.', NULL, 'ॐ जय लक्ष्मी माता', 'लक्ष्मी माता की आरती प्रतिदिन, विशेषकर शुक्रवार को, और दीपावली पर विशेष रूप से की जाती है। इससे धन-धान्य की वृद्धि होती है।', 'लाल फूल, लाल चुनरी, गुड़, चावल, दीपक से आरती करें। आरती के बाद प्रसाद वितरण करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Om Jai Saraswati Mata', 'Saraswati', 21, 'ॐ जय सरस्वती माता, स्वामी जय सरस्वती माता। ब्रह्मा की प्रिय दुलारी, विद्या की दाता॥\r\nॐ जय सरस्वती माता॥\r\nहंस वाहन राजती, श्वेत वर्ण सोहे। पुस्तक दक्षिण हाथ में, वीणा मन मोहे॥\r\nॐ जय सरस्वती माता॥\r\nमानसरोवर विहारी, शुद्ध ज्ञान की दाता। सब विद्या की देवी, सब की आधार माता॥\r\nॐ जय सरस्वती माता॥\r\nजो कोई तुमको ध्याता, विद्या बल पाता। मूर्खता दूर करती, मति विवेक दाता॥\r\nॐ जय सरस्वती माता॥', 'Om Jai Saraswati Mata, Swami Jai Saraswati Mata Brahma Ki Priya Dulari, Vidya Ki Data\r\nOm Jai Saraswati Mata\r\nHans Vahan Rajati, Shwet Varna Sohe Pustak Dakshin Hath Mein, Veena Man Mohe\r\nOm Jai Saraswati Mata\r\nManasarovar Vihari, Shuddha Gyan Ki Data Sab Vidya Ki Devi, Sab Ki Aadhar Mata\r\nOm Jai Saraswati Mata\r\nJo Koi Tumko Dhyata, Vidya Bal Pata Murkhata Dur Karti, Mati Vivek Data\r\nOm Jai Saraswati Mata', 'ॐ जय सरस्वती माता, स्वामी जय सरस्वती माता। ब्रह्मा की प्रिय दुलारी, विद्या की दाता। हंस वाहन राजती, श्वेत वर्ण सोहे। पुस्तक दक्षिण हाथ में, वीणा मन मोहे। मानसरोवर विहारी, शुद्ध ज्ञान की दाता। सब विद्या की देवी, सब की आधार माता। जो कोई तुमको ध्याता, विद्या-बल पाता। मूर्खता दूर करती, मति-विवेक दाता।', 'Om, Victory to Mother Saraswati, victory to Mother Saraswati. Dear beloved of Brahma, bestower of knowledge. Riding the swan, resplendent in white. Book in the right hand, veena enchanting the mind. Wanderer of Manasarovar, giver of pure knowledge. Goddess of all learning, mother who supports all. Whoever meditates upon you gains knowledge and strength. You remove ignorance, bestow intelligence and wisdom.', NULL, 'ॐ जय सरस्वती माता', 'सरस्वती माता की आरती प्रतिदिन, विशेषकर बुधवार को, और वसंत पंचमी पर विशेष रूप से की जाती है। इससे विद्या, बुद्धि और कला में वृद्धि होती है।', 'सफेद फूल, सफेद वस्त्र, किताबें, दीपक से आरती करें। विद्यार्थी विशेष लाभ प्राप्त करते हैं।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Jai Ambe Gauri', 'Durga', 21, 'जय अम्बे गौरी, मैया जय श्यामा गौरी। तुमको निशिदिन ध्यावत, हरि ब्रह्म शिवरी॥\r\nजय अम्बे गौरी॥\r\nमंगल मूर्ति मनोहर, कल्याण के करता। शिव शक्ति शुभ भक्ति, भक्तों सुख भरता॥\r\nजय अम्बे गौरी॥\r\nसृष्टि रूप तुम जननी, जगत जननी माता। तुम हो सबकी रक्षक, सबके विधाता॥\r\nजय अम्बे गौरी॥\r\nमांगलिक कार्यों में, सब सिद्धि दाता। सभी मनोरथ पूर्ण कर, सब विघ्न हरता॥\r\nजय अम्बे गौरी॥', 'Jai Ambe Gauri, Maiya Jai Shyama Gauri Tumko Nishidin Dhyavat, Hari Brahma Shivari\r\nJai Ambe Gauri\r\nMangal Murti Manohar, Kalyan Ke Karta Shiv Shakti Shubh Bhakti, Bhakton Sukh Bharta\r\nJai Ambe Gauri\r\nSrishti Rup Tum Janani, Jagat Janani Mata Tum Ho Sabki Rakshak, Sabke Vidhata\r\nJai Ambe Gauri\r\nMangalik Karyon Mein, Sab Siddhi Data Sabhi Manorath Purna Kar, Sab Vighn Harta\r\nJai Ambe Gauri', 'जय अम्बे गौरी, मैया जय श्यामा गौरी। तुमको निशिदिन ध्यावत, हरि, ब्रह्म, शिवरी। मंगल मूर्ति मनोहर, कल्याण के करता। शिव शक्ति शुभ भक्ति, भक्तों सुख भरता। सृष्टि रूप तुम जननी, जगत जननी माता। तुम हो सबकी रक्षक, सबके विधाता। मांगलिक कार्यों में, सब सिद्धि दाता। सभी मनोरथ पूर्ण कर, सब विघ्न हरता।', 'Victory to Mother Ambe Gauri, Mother Shyama Gauri. You are meditated upon day and night by Hari, Brahma, and Shiva. Auspicious form, captivating, doer of welfare. Shiva, Shakti, auspicious devotion, you fill devotees with happiness. You are the form of creation, mother of the universe, mother of the world. You are the protector of all, the ordainer of all. In auspicious ceremonies, you bestow all powers. You fulfill all desires, remove all obstacles.', NULL, 'जय अम्बे गौरी', 'दुर्गा माता की आरती प्रतिदिन, विशेषकर मंगलवार और शुक्रवार को, और नवरात्रि में विशेष रूप से की जाती है। इससे सभी विघ्नों का नाश होता है।', 'लाल फूल, लाल चुनरी, दीपक से आरती करें। नवरात्रि में विशेष आयोजन करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Aarti Keeje Hanuman Lala Ki', 'Hanuman', 21, 'आरती कीजै हनुमान लला की। दुष्ट दलन रघुनाथ कला की॥\r\nजा को देहु बुद्धि बल, पाए। सहज दर्शन रघुनंदन आए॥\r\nआरती कीजै हनुमान लला की॥\r\nराम रूप धरि जगत पिता, संकट हरत भक्तन सुख दाता। जय जय श्री राम रघुवीरा, संकट मोचन सुख सुख सारा॥\r\nआरती कीजै हनुमान लला की॥\r\nबजरंग बलि महावीरा, भक्तन के हो सहायक वीरा। संकट हरत भक्तन के, सुख संपत्ति देत प्रभु तुरत ही के॥\r\nआरती कीजै हनुमान लला की॥', 'Aarti Kije Hanuman Lala Ki Dusht Dalana Raghunatha Kala Ki\r\nJa Ko Dehu Buddhi Bal, Pave Sahaj Darshan Raghunandan Aave\r\nAarti Kije Hanuman Lala Ki\r\nRam Roop Dhari Jagat Pita, Sankat Harat Bhaktan Sukh Data Jai Jai Shri Ram Raghuvira, Sankat Mochan Sukh Sukh Sara\r\nAarti Kije Hanuman Lala Ki\r\nBajrang Bali Mahavira, Bhaktan Ke Ho Sahayak Vira Sankat Harat Bhaktan Ke, Sukh Sampatti Det Prabhu Turat Hi Ke\r\nAarti Kije Hanuman Lala Ki', 'आरती कीजै हनुमान लला की। दुष्ट दलन रघुनाथ कला की। जाको देहु बुद्धि-बल, पावै। सहज दर्शन रघुनंदन आवै। राम रूप धरि जगत पिता, संकट हरत भक्तन सुख दाता। जय जय श्री राम रघुवीरा, संकट मोचन सुख सुख सारा। बजरंग बलि महावीरा, भक्तन के हो सहायक वीरा। संकट हरत भक्तन के, सुख संपत्ति देत प्रभु तुरत ही के।', 'Perform aarti of dear Hanuman. The destroyer of evil, the embodiment of Rama\'s power. Whom you give wisdom and strength, they effortlessly attain the vision of Rama. Perform aarti of dear Hanuman. Taking the form of Rama, the father of the universe, remover of troubles, giver of happiness to devotees. Victory to Shri Ram, the hero of Raghu, reliever of troubles, the essence of all happiness. Perform aarti of dear Hanuman. Bajrang Bali, the great hero, be the helper of devotees. You remove the troubles of devotees, give happiness and prosperity quickly.', NULL, 'आरती कीजै हनुमान लला की', 'हनुमान जी की आरती प्रतिदिन, विशेषकर मंगलवार और शनिवार को की जाती है। इससे बल, बुद्धि और साहस की प्राप्ति होती है।', 'सिंदूर, लाल फूल, चोला, दीपक से आरती करें। मंगलवार को विशेष रूप से की जाती है।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Om Jai Jagdish Hare', 'Krishna', 21, 'ॐ जय जगदीश हरे, स्वामी जय जगदीश हरे। भक्त जनों के संकट, क्षण में दूर करे॥\r\nॐ जय जगदीश हरे॥\r\nजो ध्यावे फल पावे, दुख बिनसे मन का। स्वामी दुख बिनसे मन का। सुख संपत्ति घर आवे, सुख संपत्ति घर आवे, कष्ट मिटे तन का॥\r\nॐ जय जगदीश हरे॥\r\nमात पिता तुम मेरे, शरण गहूं किसकी। स्वामी शरण गहूं किसकी। तुम बिन और न दूजा, तुम बिन और न दूजा, आस करूं जिसकी॥\r\nॐ जय जगदीश हरे॥\r\nतुम पूरण परमात्मा, तुम अंतर्यामी। स्वामी तुम अंतर्यामी। पारब्रह्म परमेश्वर, पारब्रह्म परमेश्वर, तुम सबके स्वामी॥\r\nॐ जय जगदीश हरे॥', 'Om Jai Jagdish Hare, Swami Jai Jagdish Hare Bhakta Janon Ke Sankat, Kshan Mein Door Kare\r\nOm Jai Jagdish Hare\r\nJo Dhyave Phal Pave, Dukh Binse Man Ka Swami Dukh Binse Man Ka Sukh Sampatti Ghar Aave, Sukh Sampatti Ghar Aave, Kasht Mite Tan Ka\r\nOm Jai Jagdish Hare\r\nMata Pita Tum Mere, Sharan Gahun Kiski Swami Sharan Gahun Kiski Tum Bin Aur Na Duja, Tum Bin Aur Na Duja, Aas Karun Jiski\r\nOm Jai Jagdish Hare\r\nTum Puran Paramatma, Tum Antaryami Swami Tum Antaryami Parabrahma Parameshwar, Parabrahma Parameshwar, Tum Sabke Swami\r\nOm Jai Jagdish Hare', 'ॐ जय जगदीश हरे, स्वामी जय जगदीश हरे। भक्त जनों के संकट, क्षण में दूर करे। जो ध्यावे फल पावे, दुख बिनसे मन का। सुख संपत्ति घर आवे, कष्ट मिटे तन का। मात-पिता तुम मेरे, शरण गहूं किसकी। तुम बिन और न दूजा, आस करूं जिसकी। तुम पूरण परमात्मा, तुम अंतर्यामी। पारब्रह्म परमेश्वर, तुम सबके स्वामी।', 'Om, Victory to the Lord of the Universe, victory to the Lord of the Universe. He removes the troubles of devotees in an instant. Those who meditate obtain fruit, the sorrows of the mind disappear. Happiness and prosperity come to the home, the afflictions of the body are removed. You are my mother and father, whose refuge should I take? Without you, there is no other, on whom I can place my hope. You are the complete Supreme Soul, you are the inner dweller. Supreme Brahman, Supreme Lord, you are the master of all.', NULL, 'ॐ जय जगदीश हरे', 'यह आरती सभी देवताओं के लिए है, विशेषकर विष्णु और कृष्ण के लिए। प्रतिदिन सायंकाल में की जाती है। सभी प्रकार के सुख और शांति की प्राप्ति होती है।', 'दीपक जलाकर, श्रद्धा से आरती करें। आरती के बाद प्रसाद वितरण करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(9, 'Jai Santoshi Mata', 'Santoshi', 21, 'जय संतोषी माता, मैया जय संतोषी माता। अपने भक्तों के कष्ट, दूर करती सदा॥\r\nजय संतोषी माता॥\r\nगुड़ चना पसंद, भोग लगाए। संतोषी माता का, व्रत जो जन ध्याए॥\r\nजय संतोषी माता॥', 'Jai Santoshi Mata, Maiya Jai Santoshi Mata Apne Bhakton Ke Kasht, Door Karti Sada\r\nJai Santoshi Mata\r\nGud Chana Pasand, Bhog Lagaye Santoshi Mata Ka, Vrat Jo Jan Dhyaye\r\nJai Santoshi Mata', 'जय संतोषी माता, मैया जय संतोषी माता। अपने भक्तों के कष्ट, दूर करती सदा। गुड़-चना पसंद, भोग लगाए। संतोषी माता का, व्रत जो जन ध्याए।', 'Victory to Mother Santoshi, victory to Mother Santoshi. She always removes the troubles of her devotees. She loves jaggery and chickpeas, offer them as bhog. Whoever observes the fast of Mother Santoshi.', NULL, 'जय संतोषी माता', 'संतोषी माता की आरती शुक्रवार को विशेष रूप से की जाती है। इससे सुख-शांति और संतोष की प्राप्ति होती है।', 'गुड़-चना का भोग लगाएं, दीपक जलाकर आरती करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(10, 'Jai Sai Nath', 'Sai Baba', 21, 'जय साईं नाथ, स्वामी जय साईं नाथ। भक्त जनों के संकट, क्षण में दूर करो॥\r\nजय साईं नाथ॥\r\nसाईं बाबा दर्शन दीजो, दर्शन दीजो। अपने भक्तों को, भक्तों को प्रसाद दीजो॥\r\nजय साईं नाथ॥', 'Jai Sai Nath, Swami Jai Sai Nath Bhakta Janon Ke Sankat, Kshan Mein Door Karo\r\nJai Sai Nath\r\nSai Baba Darshan Dijo, Darshan Dijo Apne Bhakton Ko, Bhakton Ko Prasad Dijo\r\nJai Sai Nath', 'जय साईं नाथ, स्वामी जय साईं नाथ। भक्त जनों के संकट, क्षण में दूर करो। साईं बाबा दर्शन दीजो, दर्शन दीजो। अपने भक्तों को, भक्तों को प्रसाद दीजो।', 'Victory to Sai Nath, victory to Sai Nath. Remove the troubles of devotees in an instant. Sai Baba, grant us vision, grant us vision. Give your blessings to your devotees.', NULL, 'जय साईं नाथ', 'साईं बाबा की आरती प्रतिदिन सायंकाल में की जाती है। इससे सभी कष्टों का नाश होता है।', 'दीपक जलाकर, श्रद्धा से आरती करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(11, 'Jai Ganga Mata', 'Ganga', 21, 'जय गंगा माता, स्वामी जय गंगा माता। त्रिपथगा विमल जल, हरो सब तापा॥\r\nजय गंगा माता॥\r\nहर की चरण पखारे, ब्रह्मा जटा धरे। शिव शीश विराजे, देवन सुख करे॥\r\nजय गंगा माता॥', 'Jai Ganga Mata, Swami Jai Ganga Mata Tripathaga Vimal Jal, Haro Sab Tapa\r\nJai Ganga Mata\r\nHar Ki Charan Pakhare, Brahma Jata Dhare Shiv Seesh Viraje, Devan Sukh Kare\r\nJai Ganga Mata', 'जय गंगा माता, स्वामी जय गंगा माता। त्रिपथगा विमल जल, हरो सब तापा। हर की चरण पखारे, ब्रह्मा जटा धरे। शिव शीश विराजे, देवन सुख करे।', 'Victory to Mother Ganga, victory to Mother Ganga. Your pure water flows in three paths, remove all afflictions. You wash the feet of Hari, Brahma holds you in his matted locks. You reside on Shiva\'s head, you bring happiness to the gods.', NULL, 'जय गंगा माता', 'गंगा माता की आरती सायंकाल में, गंगा स्नान के समय, और गंगा दशहरा पर की जाती है। इससे पापों का नाश होता है।', 'दीपक जलाकर, गंगा जल से आरती करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:49:39', '2026-03-23 17:49:39', NULL, NULL, NULL, NULL, NULL, NULL),
(12, 'Jai Surya Dev Bhagwan', 'Surya', 21, 'जय सूर्य देव भगवान, स्वामी जय सूर्य देव भगवान। सात घोड़े का रथ है, रथी भगवान॥\r\nजय सूर्य देव भगवान॥\r\nपूर्व दिशा में रहते, जग को प्रकाश दें। नवग्रहों में प्रथम, सबके स्वामी हैं॥\r\nजय सूर्य देव भगवान॥\r\nआदित्य हृदय पुण्य, रोग नाश करते। नेत्रों के देवता, आरोग्य दाता हैं॥\r\nजय सूर्य देव भगवान॥\r\nजो कोई ध्यान धरे, सुख संपत्ति पावे। संकट में सहायक, भक्तन तारणहार॥\r\nजय सूर्य देव भगवान॥', 'Jai Surya Dev Bhagwan, Swami Jai Surya Dev Bhagwan Saat Ghode Ka Rath Hai, Rathi Bhagwan\r\nJai Surya Dev Bhagwan\r\nPurv Disha Mein Rahte, Jag Ko Prakash De Navgrahon Mein Pratham, Sabke Swami Hain\r\nJai Surya Dev Bhagwan\r\nAditya Hridaya Punya, Rog Nash Karte Netron Ke Devta, Arogya Data Hain\r\nJai Surya Dev Bhagwan\r\nJo Koi Dhyan Dhare, Sukh Sampatti Pave Sankat Mein Sahayak, Bhaktan Taranhar\r\nJai Surya Dev Bhagwan', 'जय सूर्य देव भगवान, स्वामी जय सूर्य देव भगवान। सात घोड़े का रथ है, रथी भगवान। पूर्व दिशा में रहते, जग को प्रकाश दें। नवग्रहों में प्रथम, सबके स्वामी हैं। आदित्य हृदय पुण्य, रोग नाश करते। नेत्रों के देवता, आरोग्य दाता हैं। जो कोई ध्यान धरे, सुख संपत्ति पावे। संकट में सहायक, भक्तन तारणहार।', 'Victory to Lord Surya Dev, victory to Lord Surya Dev. He rides a chariot drawn by seven horses. He resides in the east, giving light to the world. First among the nine planets, the lord of all. The Aditya Hridaya is sacred, destroys diseases. Lord of the eyes, bestower of health. Whoever meditates upon him gains happiness and prosperity. Helper in times of crisis, savior of devotees.', NULL, 'जय सूर्य देव भगवान', 'सूर्य देव की आरती प्रतिदिन सूर्योदय के समय, रविवार को विशेष रूप से की जाती है। इससे नेत्र रोग दूर होते हैं, आरोग्य की प्राप्ति होती है।', 'जल, लाल फूल, चावल, गुड़ अर्पित करें। सूर्य को जल चढ़ाने के बाद आरती करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(13, 'Jai Chandra Dev', 'Chandra', 21, 'जय चन्द्र देव भगवान, स्वामी जय चन्द्र देव भगवान। श्वेत वर्ण सुहावन, शीतलता दाता॥\r\nजय चन्द्र देव भगवान॥\r\nरोहिणी के पति, कलानिधि कहलाते। सोमवार व्रत धारी, मन को सुख दाता॥\r\nजय चन्द्र देव भगवान॥\r\nदूध समान वर्ण, श्वेत वस्त्र धारी। शिव के शीश विराजे, जग के उजियारी॥\r\nजय चन्द्र देव भगवान॥\r\nजो कोई ध्यान धरे, मन शांति पावे। चन्द्र देव की कृपा, सब संकट मिटावे॥\r\nजय चन्द्र देव भगवान॥', 'Jai Chandra Dev Bhagwan, Swami Jai Chandra Dev Bhagwan Shwet Varn Suhavan, Sheetalta Data\r\nJai Chandra Dev Bhagwan\r\nRohini Ke Pati, Kalanidhi Kehlate Somvar Vrat Dhari, Man Ko Sukh Data\r\nJai Chandra Dev Bhagwan\r\nDoodh Saman Varn, Shwet Vastra Dhari Shiv Ke Sheesh Viraje, Jag Ke Ujiyari\r\nJai Chandra Dev Bhagwan\r\nJo Koi Dhyan Dhare, Man Shanti Pave Chandra Dev Ki Kripa, Sab Sankat Mitave\r\nJai Chandra Dev Bhagwan', 'जय चन्द्र देव भगवान, स्वामी जय चन्द्र देव भगवान। श्वेत वर्ण सुहावन, शीतलता दाता। रोहिणी के पति, कलानिधि कहलाते। सोमवार व्रत धारी, मन को सुख दाता। दूध समान वर्ण, श्वेत वस्त्र धारी। शिव के शीश विराजे, जग के उजियारी। जो कोई ध्यान धरे, मन शांति पावे। चन्द्र देव की कृपा, सब संकट मिटावे।', 'Victory to Lord Chandra Dev, victory to Lord Chandra Dev. Pleasant white complexion, bestower of coolness. Husband of Rohini, known as the treasury of phases. Observer of Monday fasts, giver of happiness to the mind. White like milk, wearing white garments. Residing on Shiva\'s head, illuminator of the world. Whoever meditates upon you attains peace of mind. By the grace of Chandra Dev, all troubles are removed.', NULL, 'जय चन्द्र देव भगवान', 'चन्द्र देव की आरती सोमवार को, पूर्णिमा और अमावस्या पर विशेष रूप से की जाती है। इससे मानसिक शांति, सुख-समृद्धि की प्राप्ति होती है।', 'सफेद फूल, चावल, दूध, जल अर्पित करें। आरती के बाद चन्द्र को अर्घ्य दें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(14, 'Jai Shani Dev', 'Shani', 21, 'जय शनि देव भगवान, स्वामी जय शनि देव भगवान। नील वर्ण सुहावन, ध्यान धरे जन॥\r\nजय शनि देव भगवान॥\r\nसूर्य पुत्र कहलाते, छाया के संतान। कर्म फल दाता, न्याय के धारी॥\r\nजय शनि देव भगवान॥\r\nगरुड़ चढ़ कर आते, शनि दर्शन देत। भक्तों के संकट, क्षण में हर लेत॥\r\nजय शनि देव भगवान॥\r\nतेल तिल भोग लगे, उज्जैन के धाम। शनि महाराज की, सबसे महिमा॥\r\nजय शनि देव भगवान॥', 'Jai Shani Dev Bhagwan, Swami Jai Shani Dev Bhagwan Neel Varn Suhavan, Dhyan Dhare Jan\r\nJai Shani Dev Bhagwan\r\nSurya Putra Kehlate, Chhaya Ke Santan Karma Phal Data, Nyay Ke Dhari\r\nJai Shani Dev Bhagwan\r\nGarud Chad Kar Aate, Shani Darshan Det Bhakton Ke Sankat, Kshan Mein Har Let\r\nJai Shani Dev Bhagwan\r\nTel Til Bhog Lage, Ujjain Ke Dham Shani Maharaj Ki, Sabse Mahima\r\nJai Shani Dev Bhagwan', 'जय शनि देव भगवान, स्वामी जय शनि देव भगवान। नील वर्ण सुहावन, ध्यान धरे जन। सूर्य पुत्र कहलाते, छाया के संतान। कर्म फल दाता, न्याय के धारी। गरुड़ चढ़ कर आते, शनि दर्शन देत। भक्तों के संकट, क्षण में हर लेत। तेल तिल भोग लगे, उज्जैन के धाम। शनि महाराज की, सबसे महिमा।', 'Victory to Lord Shani Dev, victory to Lord Shani Dev. Pleasant dark complexion, whom people meditate upon. Known as the son of the Sun, child of Chaya. Bestower of the fruits of karma, upholder of justice. Coming on a crow, granting visions to devotees. He removes the troubles of devotees in an instant. Oil and sesame are offered, at the abode of Ujjain. The glory of Shani Maharaj is the greatest.', NULL, 'जय शनि देव भगवान', 'शनि देव की आरती शनिवार को विशेष रूप से की जाती है। इससे शनि की साढ़ेसाती, ढैया और अन्य अशुभ प्रभाव शांत होते हैं।', 'तेल, तिल, काले तिल, काले फूल, उड़द दाल अर्पित करें। शनि मंदिर जाकर विशेष पूजा करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(15, 'Shri Ram Chandra Kripalu', 'Rama', 21, 'श्री राम चन्द्र कृपालु भजमन, हरण भव भय दारुणम्। नवकंज लोचन, कंज मुख, कर कंज पद कंजारुणम्॥\r\nआरती श्री रामचन्द्र जी की॥\r\nकन्दर्प अगणित अमित छवि, नव नील नीरद सुन्दरम्। पटपीत मानहु तड़ित रुचि, शुचि नौमि जनक सुतावरम्॥\r\nआरती श्री रामचन्द्र जी की॥\r\nभजु दीनबन्धु दिनेश दानव दैत्य वंश निकन्दनम्। रघुनन्द आनन्द कन्द कोशल चन्द्र दशरथ नन्दनम्॥\r\nआरती श्री रामचन्द्र जी की॥', 'Shri Ram Chandra Kripalu Bhajman, Haran Bhav Bhaya Darunam Navkanj Lochan, Kanj Mukh, Kar Kanj Pad Kanjarunam\r\nAarti Shri Ramchandra Ji Ki\r\nKandarp Aganit Amit Chhavi, Nav Neel Nirad Sundaram Patpit Manhu Tadit Ruchi, Shuchi Naumi Janak Sutavaram\r\nAarti Shri Ramchandra Ji Ki\r\nBhaju Deenbandhu Dinesh Danav Daitya Vansh Nikandanam Raghunand Anand Kand Koshai Chandra Dashrath Nandanam\r\nAarti Shri Ramchandra Ji Ki', 'श्री राम चन्द्र कृपालु भजमन, हरण भव भय दारुणम्। नवकंज लोचन, कंज मुख, कर कंज पद कंजारुणम्। कन्दर्प अगणित अमित छवि, नव नील नीरद सुन्दरम्। पटपीत मानहु तड़ित रुचि, शुचि नौमि जनक सुतावरम्। भजु दीनबन्धु दिनेश दानव दैत्य वंश निकन्दनम्। रघुनन्द आनन्द कन्द कोशल चन्द्र दशरथ नन्दनम्।', 'O mind, sing of the merciful Shri Ramachandra, who removes the terrible fear of worldly existence. He has lotus-like eyes, a lotus-like face, and hands and feet that are like red lotuses. His beauty surpasses countless Cupids, he is as beautiful as a fresh rain cloud. His yellow garments shine like lightning; I bow to the pure one, the consort of Janaka\'s daughter. Sing of the friend of the humble, the lord of the day, the destroyer of the demon and giant races. The joy of the Raghu dynasty, the moon of Kosala, the son of Dasharatha.', NULL, 'आरती श्री रामचन्द्र जी की', 'राम जी की आरती प्रतिदिन सायंकाल में, रामनवमी पर विशेष रूप से की जाती है। इससे जीवन के सभी दुख दूर होते हैं।', 'फूल, फल, दीपक, धूप, रोली, चावल अर्पित करें। आरती के बाद रामायण का पाठ करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(16, 'Shri Krishna Govind', 'Krishna', 21, 'आरती कृष्णा गोविन्दा, स्वामी आरती कृष्णा गोविन्दा। जगत गुरु दयालु, पूर्ण काम दाता॥\r\nआरती कृष्णा गोविन्दा॥\r\nवृन्दावन के वासी, गोकुल के धनी। नटवर नागर कन्हैया, राधा के सजनी॥\r\nआरती कृष्णा गोविन्दा॥\r\nमाखन चोर कहलाये, ब्रज की नारिन के। कालिया नाग मर्दन, गोवर्धन धारी॥\r\nआरती कृष्णा गोविन्दा॥\r\nमुरली मनोहर सुन्दर, श्याम सलोना। भक्तों के संकट, दूर करे क्षण में॥\r\nआरती कृष्णा गोविन्दा॥', 'Aarti Krishna Govinda, Swami Aarti Krishna Govinda Jagat Guru Dayalu, Purna Kam Data\r\nAarti Krishna Govinda\r\nVrindavan Ke Vasi, Gokul Ke Dhani Natavar Nagar Kanhaiya, Radha Ke Sajni\r\nAarti Krishna Govinda\r\nMakhan Chor Kehlaye, Braj Ki Narin Ke Kaliya Nag Mardan, Govardhan Dhari\r\nAarti Krishna Govinda\r\nMurali Manohar Sundar, Shyam Salona Bhakton Ke Sankat, Door Kare Kshan Mein\r\nAarti Krishna Govinda', 'आरती कृष्णा गोविन्दा, स्वामी आरती कृष्णा गोविन्दा। जगत गुरु दयालु, पूर्ण काम दाता। वृन्दावन के वासी, गोकुल के धनी। नटवर नागर कन्हैया, राधा के सजनी। माखन चोर कहलाये, ब्रज की नारिन के। कालिया नाग मर्दन, गोवर्धन धारी। मुरली मनोहर सुन्दर, श्याम सलोना। भक्तों के संकट, दूर करे क्षण में।', 'Aarti to Krishna Govinda, aarti to Krishna Govinda. The Guru of the world, the compassionate, the fulfiller of all desires. Resident of Vrindavan, lord of Gokul. The divine dancer, the youth Kanhaiya, the companion of Radha. Known as the butter thief, loved by the women of Braj. Tamer of the Kaliya serpent, lifter of Govardhan. Enchanting flute player, beautiful, handsome Shyam. He removes the troubles of devotees in an instant.', NULL, 'आरती कृष्णा गोविन्दा', 'कृष्ण जी की आरती प्रतिदिन सायंकाल में, जन्माष्टमी पर विशेष रूप से की जाती है। इससे प्रेम, भक्ति और आनंद की प्राप्ति होती है।', 'फूल, पंचामृत, माखन-मिश्री, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(17, 'Ambe Tu Hai Jagdambe', 'Durga', 21, 'अम्बे तू है जगदम्बे, माता तू है जगदम्बे। सुखियों के दुख दूर कर, दुखियों के दुख हर॥\r\nजय अम्बे गौरी मैया, जय श्यामा गौरी॥\r\nतेरे हाथों में त्रिशूल, तेरे हाथों में शूल। तेरे हाथों में खप्पर, तेरे हाथों में शंख॥\r\nजय अम्बे गौरी मैया, जय श्यामा गौरी॥\r\nशेर पर सवार है, सब पर भारी है। दानव दल संहारक, माता दुर्गा भारी॥\r\nजय अम्बे गौरी मैया, जय श्यामा गौरी॥\r\nमांगलिक कार्यों में, सब सिद्धि दाता। सभी मनोरथ पूर्ण कर, सब विघ्न हरता॥\r\nजय अम्बे गौरी मैया, जय श्यामा गौरी॥', 'Ambe Tu Hai Jagdambe, Mata Tu Hai Jagdambe Sukhiyon Ke Dukh Door Kar, Dukhiyon Ke Dukh Har\r\nJai Ambe Gauri Maiya, Jai Shyama Gauri\r\nTere Hathon Mein Trishool, Tere Hathon Mein Shool Tere Hathon Mein Khappar, Tere Hathon Mein Shankh\r\nJai Ambe Gauri Maiya, Jai Shyama Gauri\r\nSher Par Sawar Hai, Sab Par Bhari Hai Danav Dal Sanharak, Mata Durga Bhari\r\nJai Ambe Gauri Maiya, Jai Shyama Gauri\r\nMangalik Karyon Mein, Sab Siddhi Data Sabhi Manorath Purna Kar, Sab Vighn Harta\r\nJai Ambe Gauri Maiya, Jai Shyama Gauri', 'अम्बे तू है जगदम्बे, माता तू है जगदम्बे। सुखियों के दुख दूर कर, दुखियों के दुख हर। तेरे हाथों में त्रिशूल, तेरे हाथों में शूल। तेरे हाथों में खप्पर, तेरे हाथों में शंख। शेर पर सवार है, सब पर भारी है। दानव दल संहारक, माता दुर्गा भारी। मांगलिक कार्यों में, सब सिद्धि दाता। सभी मनोरथ पूर्ण कर, सब विघ्न हरता।', 'O Mother Ambe, you are the mother of the universe. Remove the sorrows of the happy, remove the sorrows of the sorrowful. In your hands are the trident, in your hands are the spear. In your hands are the skull cup, in your hands are the conch. Seated on a lion, you are mighty over all. Destroyer of demon armies, Mother Durga is powerful. In auspicious works, you are the bestower of all powers. You fulfill all desires, remove all obstacles.', NULL, 'जय अम्बे गौरी मैया, जय श्यामा गौरी', 'दुर्गा माता की आरती नवरात्रि के नौ दिनों में विशेष रूप से, और प्रतिदिन सायंकाल में की जाती है। इससे सभी संकट दूर होते हैं।', 'लाल फूल, लाल चुनरी, दीपक, धूप, नैवेद्य अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(18, 'Jai Tulsi Mata', 'Tulsi', 21, 'जय तुलसी माता, स्वामी जय तुलसी माता। विष्णु प्रिया सुखदाता, पाप नाश दाता॥\r\nजय तुलसी माता॥\r\nतुलसी वन की शोभा, सबसे न्यारी। विष्णु चरणों में, तुम हो प्यारी॥\r\nजय तुलसी माता॥\r\nतुलसी के दर्शन, पाप नाश करें। तुलसी का पूजन, मोक्ष प्रदान करें॥\r\nजय तुलसी माता॥\r\nरोग नाश करती, शोक नाश करती। सब मनोरथ पूर्ण कर, सुख संपत्ति भरती॥\r\nजय तुलसी माता॥', 'Jai Tulsi Mata, Swami Jai Tulsi Mata Vishnu Priya Sukhdata, Pap Nash Data\r\nJai Tulsi Mata\r\nTulsi Van Ki Shobha, Sabse Nyari Vishnu Charanon Mein, Tum Ho Pyari\r\nJai Tulsi Mata\r\nTulsi Ke Darshan, Pap Nash Karen Tulsi Ka Poojan, Moksh Pradan Karen\r\nJai Tulsi Mata\r\nRog Nash Karti, Shok Nash Karti Sab Manorath Purna Kar, Sukh Sampatti Bharti\r\nJai Tulsi Mata', 'जय तुलसी माता, स्वामी जय तुलसी माता। विष्णु प्रिया सुखदाता, पाप नाश दाता। तुलसी वन की शोभा, सबसे न्यारी। विष्णु चरणों में, तुम हो प्यारी। तुलसी के दर्शन, पाप नाश करें। तुलसी का पूजन, मोक्ष प्रदान करें। रोग नाश करती, शोक नाश करती। सब मनोरथ पूर्ण कर, सुख संपत्ति भरती।', 'Victory to Mother Tulsi, victory to Mother Tulsi. Beloved of Vishnu, giver of happiness, destroyer of sins. The beauty of the Tulsi grove is unique. You are dear to the feet of Vishnu. Just seeing Tulsi destroys sins. Worshipping Tulsi grants liberation. She destroys diseases, destroys sorrows. Fulfills all desires, fills with happiness and prosperity.', NULL, 'जय तुलसी माता', 'तुलसी माता की आरती प्रतिदिन सायंकाल में, तुलसी विवाह पर विशेष रूप से की जाती है। इससे घर में सुख-शांति और समृद्धि आती है।', 'तुलसी के पौधे के पास दीपक जलाकर आरती करें। फूल, जल अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(19, 'Jai Kali Mata', 'Kali', 21, 'जय काली माता, स्वामी जय काली माता। भक्तन के संकट, दूर करो माता॥\r\nजय काली माता॥\r\nकराल वदन वाली, मुण्डमाल धारी। शव पर विराजे, रक्तबीज हारी॥\r\nजय काली माता॥\r\nखड्ग कर धारी, दानव दल हारी। दक्षिणा काली, भक्तन उद्धारी॥\r\nजय काली माता॥\r\nरक्त वस्त्र सोहे, भक्तन मन मोहे। काली माता की, महिमा अगाध है॥\r\nजय काली माता॥', 'Jai Kali Mata, Swami Jai Kali Mata Bhaktan Ke Sankat, Door Karo Mata\r\nJai Kali Mata\r\nKaral Vadan Wali, Mundamal Dhari Shav Par Viraje, Raktabij Hari\r\nJai Kali Mata\r\nKhadg Kar Dhari, Danav Dal Hari Dakshina Kali, Bhaktan Uddhari\r\nJai Kali Mata\r\nRakt Vastra Sohe, Bhaktan Man Mohe Kali Mata Ki, Mahima Agadh Hai\r\nJai Kali Mata', 'जय काली माता, स्वामी जय काली माता। भक्तन के संकट, दूर करो माता। कराल वदन वाली, मुण्डमाल धारी। शव पर विराजे, रक्तबीज हारी। खड्ग कर धारी, दानव दल हारी। दक्षिणा काली, भक्तन उद्धारी। रक्त वस्त्र सोहे, भक्तन मन मोहे। काली माता की, महिमा अगाध है।', 'Victory to Mother Kali, victory to Mother Kali. Remove the troubles of devotees, O Mother. One with a fierce face, wearing a garland of skulls. Seated on a corpse, slayer of Raktabija. Holding a sword, destroyer of demon armies. Dakshina Kali, savior of devotees. Red garments adorn you, enchanting the minds of devotees. The glory of Mother Kali is immeasurable.', NULL, 'जय काली माता', 'काली माता की आरती अमावस्या की रात्रि में, और काली पूजा पर विशेष रूप से की जाती है। इससे सभी बुरी शक्तियों का नाश होता है।', 'लाल फूल, लाल वस्त्र, मांस-मदिरा (जहां प्रचलन हो), दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(20, 'Jai Bhairav Deva', 'Bhairav', 21, 'जय भैरव देवा, स्वामी जय भैरव देवा। काशी के रखवाले, शिव के गण देवा॥\r\nजय भैरव देवा॥\r\nश्वान वाहन राजे, खड्ग कर धारी। रुद्र के अवतार, भक्तन उद्धारी॥\r\nजय भैरव देवा॥\r\nकाल भैरव कहलाये, काशी के कोतवाल। भक्तों के संकट, दूर करो तत्काल॥\r\nजय भैरव देवा॥\r\nभैरव की आरती, जो कोई गावे। सब संकट दूर हो, सुख संपत्ति पावे॥\r\nजय भैरव देवा॥', 'Jai Bhairav Deva, Swami Jai Bhairav Deva Kashi Ke Rakhavale, Shiv Ke Gan Deva\r\nJai Bhairav Deva\r\nShvan Vahan Raje, Khadg Kar Dhari Rudra Ke Avatar, Bhaktan Uddhari\r\nJai Bhairav Deva\r\nKal Bhairav Kehlaye, Kashi Ke Kotwal Bhakton Ke Sankat, Door Karo Tatkal\r\nJai Bhairav Deva\r\nBhairav Ki Aarti, Jo Koi Gaave Sab Sankat Door Ho, Sukh Sampatti Pave\r\nJai Bhairav Deva', 'जय भैरव देवा, स्वामी जय भैरव देवा। काशी के रखवाले, शिव के गण देवा। श्वान वाहन राजे, खड्ग कर धारी। रुद्र के अवतार, भक्तन उद्धारी। काल भैरव कहलाये, काशी के कोतवाल। भक्तों के संकट, दूर करो तत्काल। भैरव की आरती, जो कोई गावे। सब संकट दूर हो, सुख संपत्ति पावे।', 'Victory to Lord Bhairav, victory to Lord Bhairav. Protector of Kashi, the attendant of Shiva. You ride a dog, holding a sword in your hand. Incarnation of Rudra, savior of devotees. Known as Kal Bhairav, the guardian of Kashi. Remove the troubles of devotees immediately. Whoever sings the aarti of Bhairav, all troubles are removed, they gain happiness and prosperity.', NULL, 'जय भैरव देवा', 'भैरव देव की आरती मंगलवार और रविवार को, अष्टमी तिथि पर विशेष रूप से की जाती है। इससे काल सर्प दोष, शत्रु बाधा दूर होती है।', 'काले तिल, काले फूल, नारियल, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(21, 'Jai Shitala Mata', 'Shitala', 21, 'जय शीतला माता, स्वामी जय शीतला माता। रोग नाश करती, शीतलता दाता॥\r\nजय शीतला माता॥\r\nचेचक रोग हरती, भक्तन तारती। शीतला माता की, महिमा अपार है॥\r\nजय शीतला माता॥\r\nगधे पर सवारी, नील वर्ण धारी। हाथ में सूप लिए, ब्रह्मा की दुलारी॥\r\nजय शीतला माता॥\r\nढेरू नाम पुत्र, हनुमान संगी। भक्तों के दुख हरती, सबकी मांगी॥\r\nजय शीतला माता॥', 'Jai Shitala Mata, Swami Jai Shitala Mata Rog Nash Karti, Sheetalta Data\r\nJai Shitala Mata\r\nChechak Rog Harti, Bhaktan Tartai Shitala Mata Ki, Mahima Apar Hai\r\nJai Shitala Mata\r\nGadhe Par Savari, Neel Varn Dhari Hath Mein Soop Liye, Brahma Ki Dulari\r\nJai Shitala Mata\r\nDheru Naam Putra, Hanuman Sangi Bhakton Ke Dukh Harti, Sabki Mangi\r\nJai Shitala Mata', 'जय शीतला माता, स्वामी जय शीतला माता। रोग नाश करती, शीतलता दाता। चेचक रोग हरती, भक्तन तारती। शीतला माता की, महिमा अपार है। गधे पर सवारी, नील वर्ण धारी। हाथ में सूप लिए, ब्रह्मा की दुलारी। ढेरू नाम पुत्र, हनुमान संगी। भक्तों के दुख हरती, सबकी मांगी।', 'Victory to Mother Shitala, victory to Mother Shitala. Destroyer of diseases, bestower of coolness. Removes smallpox and other diseases, saves devotees. The glory of Mother Shitala is boundless. Seated on a donkey, of blue complexion. Holding a winnowing fan in her hand, beloved of Brahma. Son named Dheru, accompanied by Hanuman. She removes the sorrows of devotees, fulfills everyone\'s wishes.', NULL, 'जय शीतला माता', 'शीतला माता की आरती बुधवार को, और चेचक जैसे रोगों से बचाव के लिए की जाती है। इससे रोगों से मुक्ति मिलती है।', 'शीतल जल, गुड़, चावल, फल, सूप, दीपक अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(22, 'Jai Santoshi Mata', 'Santoshi', 21, 'जय संतोषी माता, मैया जय संतोषी माता। अपने भक्तों के कष्ट, दूर करती सदा॥\r\nजय संतोषी माता॥\r\nगुड़ चना पसंद, भोग लगाए। संतोषी माता का, व्रत जो जन ध्याए॥\r\nजय संतोषी माता॥\r\nशुक्रवार व्रत करे, सो सुख संपत्ति पावे। संतोषी माता की, कृपा सब पावे॥\r\nजय संतोषी माता॥\r\nमाता के दरबार में, सब कुछ मिलता। भक्त जनों का, सब दुख हरता॥\r\nजय संतोषी माता॥\r\nसुख समृद्धि घर आवे, मनवांछित फल पावे। संतोषी माता की, आरती जो गावे॥\r\nजय संतोषी माता॥', 'Jai Santoshi Mata, Maiya Jai Santoshi Mata Apne Bhakton Ke Kasht, Door Karti Sada\r\nJai Santoshi Mata\r\nGud Chana Pasand, Bhog Lagaye Santoshi Mata Ka, Vrat Jo Jan Dhyaye\r\nJai Santoshi Mata\r\nShukravar Vrat Kare, So Sukh Sampatti Pave Santoshi Mata Ki, Kripa Sab Pave\r\nJai Santoshi Mata\r\nMata Ke Darbar Mein, Sab Kuch Milta Bhakta Janon Ka, Sab Dukh Harta\r\nJai Santoshi Mata\r\nSukh Samriddhi Ghar Aave, Manvanchhit Phal Pave Santoshi Mata Ki, Aarti Jo Gaave\r\nJai Santoshi Mata', 'जय संतोषी माता, मैया जय संतोषी माता। अपने भक्तों के कष्ट, दूर करती सदा। गुड़ चना पसंद, भोग लगाए। संतोषी माता का, व्रत जो जन ध्याए। शुक्रवार व्रत करे, सो सुख संपत्ति पावे। संतोषी माता की, कृपा सब पावे। माता के दरबार में, सब कुछ मिलता। भक्त जनों का, सब दुख हरता। सुख समृद्धि घर आवे, मनवांछित फल पावे। संतोषी माता की, आरती जो गावे।', 'Victory to Mother Santoshi, victory to Mother Santoshi. She always removes the troubles of her devotees. She loves jaggery and chickpeas, offer them as bhog. Whoever observes the fast of Mother Santoshi. Those who observe the Friday fast gain happiness and prosperity. Everyone receives the grace of Mother Santoshi. In the court of the Mother, everything is available. She removes all sorrows of devotees. Happiness and prosperity come home, desired fruits are obtained. Whoever sings the aarti of Mother Santoshi.', NULL, 'जय संतोषी माता', 'संतोषी माता की आरती शुक्रवार को, संतोषी माता के व्रत के दिन विशेष रूप से की जाती है। इससे सुख-समृद्धि, संतोष और मनोवांछित फल की प्राप्ति होती है।', 'गुड़-चना, फल, फूल, दीपक अर्पित करें। शुक्रवार का व्रत विशेष रूप से लाभकारी है।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(23, 'Jai Skandamata', 'Skandamata', 21, 'जय स्कन्दमाता, जय स्कन्दमाता। सिंह वाहिनी माता, स्कन्द सुख दाता॥\r\nजय स्कन्दमाता॥\r\nकुमार के माता, विधि विधान करती। चतुर्भुजा माता, सब सुख भरती॥\r\nजय स्कन्दमाता॥\r\nभक्तों की रक्षा, सदा तुम करती। संकट में ही, माता दर्शन करती॥\r\nजय स्कन्दमाता॥\r\nस्कन्दमाता की, आरती जो गावे। सब सुख संपत्ति, मनवांछित पावे॥\r\nजय स्कन्दमाता॥', 'Jai Skandamata, Jai Skandamata Singh Vahini Mata, Skand Sukh Data\r\nJai Skandamata\r\nKumar Ke Mata, Vidhi Vidhan Karti Chaturbhuja Mata, Sab Sukh Bharti\r\nJai Skandamata\r\nBhakton Ki Raksha, Sada Tum Karti Sankat Mein Hi, Mata Darshan Karti\r\nJai Skandamata\r\nSkandamata Ki, Aarti Jo Gaave Sab Sukh Sampatti, Manvanchhit Pave\r\nJai Skandamata', 'जय स्कन्दमाता, जय स्कन्दमाता। सिंह वाहिनी माता, स्कन्द सुख दाता। कुमार के माता, विधि विधान करती। चतुर्भुजा माता, सब सुख भरती। भक्तों की रक्षा, सदा तुम करती। संकट में ही, माता दर्शन करती। स्कन्दमाता की, आरती जो गावे। सब सुख संपत्ति, मनवांछित पावे।', 'Victory to Skandamata, victory to Skandamata. The lion-riding mother, giver of happiness to Skanda. Mother of Kartikeya, you perform all rituals. The four-armed mother, you fill with all happiness. You always protect your devotees. In times of crisis, Mother appears. Whoever sings the aarti of Skandamata, attains all happiness and prosperity, their desires are fulfilled.', NULL, 'जय स्कन्दमाता', 'स्कन्दमाता की आरती नवरात्रि के पांचवें दिन, और कार्तिकेय से संबंधित पूजा में की जाती है। इससे संतान सुख, ज्ञान और शक्ति की प्राप्ति होती है।', 'लाल फूल, फल, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(24, 'Jai Katyayani', 'Katyayani', 21, 'जय कात्यायनी, जय कात्यायनी। सिंह वाहिनी माता, महिषासुर हारी॥\r\nजय कात्यायनी॥\r\nकन्या रूप धरी, वर मांगन आई। भक्तों की रक्षा, सदा तुम करती॥\r\nजय कात्यायनी॥\r\nकात्यायन ऋषि की, तपस्या तोड़ी। माता ने जन्म लिया, पापों को छोड़ी॥\r\nजय कात्यायनी॥\r\nकात्यायनी की, आरती जो गावे। सब मनोरथ पूर्ण कर, सुख संपत्ति पावे॥\r\nजय कात्यायनी॥', 'Jai Katyayani, Jai Katyayani Singh Vahini Mata, Mahishasur Hari\r\nJai Katyayani\r\nKanya Roop Dhari, Var Mangan Aai Bhakton Ki Raksha, Sada Tum Karti\r\nJai Katyayani\r\nKatyayan Rishi Ki, Tapasya Tori Mata Ne Janm Liya, Papon Ko Chori\r\nJai Katyayani\r\nKatyayani Ki, Aarti Jo Gaave Sab Manorath Purna Kar, Sukh Sampatti Pave\r\nJai Katyayani', 'जय कात्यायनी, जय कात्यायनी। सिंह वाहिनी माता, महिषासुर हारी। कन्या रूप धरी, वर मांगन आई। भक्तों की रक्षा, सदा तुम करती। कात्यायन ऋषि की, तपस्या तोड़ी। माता ने जन्म लिया, पापों को छोड़ी। कात्यायनी की, आरती जो गावे। सब मनोरथ पूर्ण कर, सुख संपत्ति पावे।', 'Victory to Katyayani, victory to Katyayani. The lion-riding mother, slayer of Mahishasura. Taking the form of a maiden, you came to grant boons. You always protect your devotees. You broke the penance of Sage Katyayan. Mother took birth, leaving behind sins. Whoever sings the aarti of Katyayani, their all desires are fulfilled, they gain happiness and prosperity.', NULL, 'जय कात्यायनी', 'कात्यायनी माता की आरती नवरात्रि के छठे दिन, और विवाह के लिए विशेष रूप से की जाती है। इससे शीघ्र विवाह, सुखद वैवाहिक जीवन की प्राप्ति होती है।', 'महुआ के फूल, पीले फूल, फल, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(25, 'Jai Kalaratri', 'Kalaratri', 21, 'जय कालरात्री, जय कालरात्री। गधे पर सवारी, कराल दंत धारी॥\r\nजय कालरात्री॥\r\nकाले वर्ण सोहे, मुण्डमाल धारी। भक्तों के संकट, दूर करो भारी॥\r\nजय कालरात्री॥\r\nरक्तबीज हारी, दानव दल भारी। दक्षिणा काली, रूप तुम्हारी॥\r\nजय कालरात्री॥\r\nकालरात्री की, आरती जो गावे। सब भय दूर हो, सुख संपत्ति पावे॥\r\nजय कालरात्री॥', 'Jai Kalaratri, Jai Kalaratri Gadhe Par Savari, Karal Dant Dhari\r\nJai Kalaratri\r\nKale Varn Sohe, Mundamal Dhari Bhakton Ke Sankat, Door Karo Bhari\r\nJai Kalaratri\r\nRaktabij Hari, Danav Dal Bhari Dakshina Kali, Roop Tumhari\r\nJai Kalaratri\r\nKalaratri Ki, Aarti Jo Gaave Sab Bhay Door Ho, Sukh Sampatti Pave\r\nJai Kalaratri', 'जय कालरात्री, जय कालरात्री। गधे पर सवारी, कराल दंत धारी। काले वर्ण सोहे, मुण्डमाल धारी। भक्तों के संकट, दूर करो भारी। रक्तबीज हारी, दानव दल भारी। दक्षिणा काली, रूप तुम्हारी। कालरात्री की, आरती जो गावे। सब भय दूर हो, सुख संपत्ति पावे।', 'Victory to Kalaratri, victory to Kalaratri. Seated on a donkey, bearing fierce teeth. Dark-complexioned, wearing a garland of skulls. Remove the great troubles of devotees. Slayer of Raktabija, destroyer of demon armies. Your form is that of Dakshina Kali. Whoever sings the aarti of Kalaratri, all fears are removed, they gain happiness and prosperity.', NULL, 'जय कालरात्री', 'कालरात्री माता की आरती नवरात्रि के सातवें दिन, और रात्रि में विशेष रूप से की जाती है। इससे सभी भय, शत्रु बाधा, ग्रह दोष दूर होते हैं।', 'नीले फूल, लाल फूल, गुड़, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(26, 'Jai Mahagauri', 'Mahagauri', 21, 'जय महागौरी, जय महागौरी। श्वेत वर्ण सोहे, श्वेत वस्त्र धारी॥\r\nजय महागौरी॥\r\nवृषभ वाहिनी माता, चतुर्भुज धारी। भक्तों के संकट, दूर करो भारी॥\r\nजय महागौरी॥\r\nशंख चक्र धारी, अभय वरदानी। माता महागौरी, सब सुखदायिनी॥\r\nजय महागौरी॥\r\nमहागौरी की, आरती जो गावे। सब पाप दूर हो, सुख संपत्ति पावे॥\r\nजय महागौरी॥', 'Jai Mahagauri, Jai Mahagauri Shwet Varn Sohe, Shwet Vastra Dhari\r\nJai Mahagauri\r\nVrishabh Vahini Mata, Chaturbhuj Dhari Bhakton Ke Sankat, Door Karo Bhari\r\nJai Mahagauri\r\nShankh Chakra Dhari, Abhay Var Dani Mata Mahagauri, Sab Sukhdayini\r\nJai Mahagauri\r\nMahagauri Ki, Aarti Jo Gaave Sab Pap Door Ho, Sukh Sampatti Pave\r\nJai Mahagauri', 'जय महागौरी, जय महागौरी। श्वेत वर्ण सोहे, श्वेत वस्त्र धारी। वृषभ वाहिनी माता, चतुर्भुज धारी। भक्तों के संकट, दूर करो भारी। शंख चक्र धारी, अभय वरदानी। माता महागौरी, सब सुखदायिनी। महागौरी की, आरती जो गावे। सब पाप दूर हो, सुख संपत्ति पावे।', 'Victory to Mahagauri, victory to Mahagauri. Resplendent in white complexion, wearing white garments. The bull-riding mother, four-armed. Remove the great troubles of devotees. Holding conch and discus, bestower of fearlessness and boons. Mother Mahagauri, giver of all happiness. Whoever sings the aarti of Mahagauri, all sins are removed, they gain happiness and prosperity.', NULL, 'जय महागौरी', 'महागौरी माता की आरती नवरात्रि के आठवें दिन, और सोमवार को विशेष रूप से की जाती है। इससे सभी पापों का नाश, आरोग्य, सौभाग्य की प्राप्ति होती है।', 'सफेद फूल, सफेद वस्त्र, दूध, दही, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(27, 'Jai Siddhidatri', 'Siddhidatri', 21, 'जय सिद्धिदात्री, जय सिद्धिदात्री। कमल वाहिनी माता, सिद्धि सुख दात्री॥\r\nजय सिद्धिदात्री॥\r\nचतुर्भुज धारी, शंख चक्र धारी। अष्ट सिद्धि दाता, भक्तन उद्धारी॥\r\nजय सिद्धिदात्री॥\r\nदेवताओं ने माता, पूजा की भारी। सिद्धिदात्री माता, सब सुखदायिनी॥\r\nजय सिद्धिदात्री॥\r\nसिद्धिदात्री की, आरती जो गावे। सब सिद्धि पावे, सुख संपत्ति पावे॥\r\nजय सिद्धिदात्री॥', 'Jai Siddhidatri, Jai Siddhidatri Kamal Vahini Mata, Siddhi Sukh Datri\r\nJai Siddhidatri\r\nChaturbhuj Dhari, Shankh Chakra Dhari Ashta Siddhi Data, Bhaktan Uddhari\r\nJai Siddhidatri\r\nDevataon Ne Mata, Pooja Ki Bhari Siddhidatri Mata, Sab Sukhdayini\r\nJai Siddhidatri\r\nSiddhidatri Ki, Aarti Jo Gaave Sab Siddhi Pave, Sukh Sampatti Pave\r\nJai Siddhidatri', 'जय सिद्धिदात्री, जय सिद्धिदात्री। कमल वाहिनी माता, सिद्धि सुख दात्री। चतुर्भुज धारी, शंख चक्र धारी। अष्ट सिद्धि दाता, भक्तन उद्धारी। देवताओं ने माता, पूजा की भारी। सिद्धिदात्री माता, सब सुखदायिनी। सिद्धिदात्री की, आरती जो गावे। सब सिद्धि पावे, सुख संपत्ति पावे।', 'Victory to Siddhidatri, victory to Siddhidatri. The lotus-riding mother, bestower of powers and happiness. Four-armed, holding conch and discus. Bestower of the eight powers, savior of devotees. The gods themselves worshipped the Mother greatly. Mother Siddhidatri, giver of all happiness. Whoever sings the aarti of Siddhidatri, attains all powers, gains happiness and prosperity.', NULL, 'जय सिद्धिदात्री', 'सिद्धिदात्री माता की आरती नवरात्रि के नौवें दिन, और किसी भी शुभ कार्य के पूर्ण होने पर की जाती है। इससे सभी सिद्धियों की प्राप्ति होती है।', 'लाल फूल, कमल के फूल, फल, दीपक, धूप अर्पित करें।', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 17:55:09', '2026-03-23 17:55:09', NULL, NULL, NULL, NULL, NULL, NULL),
(28, 'Sukhakarta Dukhaharta (Marathi Ganpati Aarti)', 'Ganesh', 21, 'सुखकर्ता दुःखहर्ता वार्ता विघ्नाची। नुरवे पुरवी प्रेमे कृपा जयाची॥\r\nसर्वांगी सुंदर उटी शेंदूराची। जय देव जय देव जय मंगलमूर्ती॥\r\nध्यानी आले मनामनी देहबुद्धी विसरा। मुखी तुझे नाम अक्षर तीनचि असरा॥\r\nदातारा दीनवरा तू सर्वां पालनकर्ता। जय देव जय देव जय मंगलमूर्ती॥\r\nआरती ओवाळू तुजला मोरया। म्हणोनिया आरती गातो मी आजा॥\r\nदास तुझा मी तुजला शरण माझा। जय देव जय देव जय मंगलमूर्ती॥', 'Sukhakarta Dukhharta Varta Vighnachi Nurave Purave Preme Kripa Jayachi Sarvangi Sundar Uti Shendurachi Jai Dev Jai Dev Jai Mangalmurti Dhyani Aale Manamani Dehabuddhi Visara Mukhi Tujhe Naam Akshar Tinchi Asara Datara Dinavara Tu Sarvan Palankarta Jai Dev Jai Dev Jai Mangalmurti Aarti Ovalu Tujala Moraya Mhononiya Aarti Gato Mi Aaja Das Tuza Mi Tujala Sharan Maza Jai Dev Jai Dev Jai Mangalmurti', 'सुख देने वाले, दुःख हरने वाले, विघ्नों की वार्ता। नुरवे (कमी) पूरी करते, प्रेम से कृपा जिनकी। सर्वांग सुंदर, शेंदूर की उटी। जय देव, जय देव, जय मंगलमूर्ति। ध्यान में आते, मन में देहबुद्धि भूल जाओ। मुख में तेरा नाम तीन अक्षर (ॐ गं) ही असर करता है। दातार, दीनवर, तू सबका पालन करता है। आरती ओवाळूं तुझे मोरया। कहकर आरती गाता हूं मैं आज। दास तेरा मैं, तेरी शरण मेरी।', 'Giver of happiness, remover of sorrows, remover of obstacles. He fulfills, with love and grace. Beautiful in every limb, adorned with vermillion. Victory to the Lord, victory to the auspicious form. When you come in meditation, forget the consciousness of the body. Your three-syllable name is effective. Giver to the poor, you sustain all. I wave the aarti before you, O Moraya. Singing this aarti today, I am your servant, I take refuge in you.', NULL, 'सुखकर्ता दुःखहर्ता वार्ता विघ्नाची', 'गणपतीची ही आरती महाराष्ट्रात सर्वात प्रसिद्ध आहे. संत समर्थ रामदासांनी रचलेली ही आरती कोणत्याही शुभ कार्याच्या सुरुवातीला, गणेश चतुर्थीला, आणि प्रतिदिन सायंकाळी गायली जाते.', 'शेंदूर, दुर्वा, मोदक, फुले अर्पण करून दीपक ओवाळा. आरतीनंतर तत्काळ प्रसाद वाटा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(29, 'Jai Datta Guruvar (Marathi Datta Aarti)', 'Dattatreya', 21, 'जय जय दत्ता गुरुवर, जय दत्ता गुरुवर। भक्तांच्या रक्षणाला सदा तयार॥\r\nजय जय दत्ता गुरुवर॥\r\nब्रह्मा विष्णु महेशाचा अवतार। तीनही लोकांमध्ये तू एकच धर्मसार॥\r\nजय जय दत्ता गुरुवर॥\r\nदिगंबर दिगंबर श्रीपाद वल्लभ। नृसिंह सरस्वती गुरुचरित्र गाभ॥\r\nजय जय दत्ता गुरुवर॥\r\nगंगाधर त्र्यंबकेश्वर महुर नगरी। गिरनार वैजनाथ तू सर्वांवरी॥\r\nजय जय दत्ता गुरुवर॥\r\nआरती ओवाळू तुझी गुरुराया। सर्व संकटे दूर होतील माया॥\r\nजय जय दत्ता गुरुवर॥', 'Jai Jai Datta Guruvar Jai Datta Guruvar Bhaktancha Rakshanala Sada Tayar Jai Jai Datta Guruvar Brahma Vishnu Maheshacha Avatar Tinhi Lokamadhye Tu Ekach Dharmasar Jai Jai Datta Guruvar Digambar Digambar Shripad Vallabh Nrusimha Saraswati Gurucharitra Gabh Jai Jai Datta Guruvar Gangadhar Tryambakeshwar Mahur Nagari Girnar Vaijnath Tu Sarvanvari Jai Jai Datta Guruvar Aarti Ovalu Tuzhi Gururaaya Sarva Sankate Door Hotil Maya Jai Jai Datta Guruvar', 'जय जय दत्ता गुरुवर, जय जय दत्ता गुरुवर। भक्तांच्या रक्षणाला सदा तयार। ब्रह्मा, विष्णु, महेशाचा अवतार। तिन्ही लोकांमध्ये तू एकच धर्मसार। दिगंबर दिगंबर, श्रीपाद वल्लभ। नृसिंह सरस्वती, गुरुचरित्र गाभ। गंगाधर, त्र्यंबकेश्वर, महुर नगरी। गिरनार, वैजनाथ, तू सर्वांवरी। आरती ओवाळू तुझी गुरुराया। सर्व संकटे दूर होतील माया।', 'Victory to Lord Datta, the supreme Guru. Always ready to protect devotees. Incarnation of Brahma, Vishnu, and Mahesh. You alone are the essence of dharma in all three worlds. The naked one, the naked one, Shripad Vallabh. Nrusimha Saraswati, the glory of Gurucharitra. Gangadhar, Tryambakeshwar, the city of Mahur. Girnar, Vaijnath, you are above all. I wave the aarti before you, O Guru. All troubles will be removed.', NULL, 'जय जय दत्ता गुरुवर', 'दत्तात्रेयांची ही आरती दत्त जयंती, गुरुपौर्णिमा, आणि प्रतिदिन सकाळी गायली जाते. यामुळे गुरुकृपा प्राप्त होते आणि सर्व संकटे दूर होतात.', 'गुलाल, फुले, दीपक, धूप, नैवेद्य अर्पण करा. आरतीनंतर गुरुचरित्र वाचन करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(30, 'Jai Jai Shankar Deva (Marathi Shankar Aarti)', 'Shiva', 21, 'जय जय शंकर देवा, जय जय शंकर देवा। भोळ्या भंडारा, महादेवा॥\r\nजय जय शंकर देवा॥\r\nत्र्यंबक त्रिनेत्रा, चंद्रशेखरा। गंगाधर शूलपाणी, भक्तांच्या रक्षणा॥\r\nजय जय शंकर देवा॥\r\nनागेंद्र हारा, भूतनाथा। कैलासवासी, शंकरा॥\r\nजय जय शंकर देवा॥\r\nपार्वती वल्लभा, विश्वनाथा। सदाशिवा, शिवशंकरा॥\r\nजय जय शंकर देवा॥\r\nआरती ओवाळू, तुझी महादेवा। संकटी पडले, रक्षण करा रे देवा॥\r\nजय जय शंकर देवा॥', 'Jai Jai Shankar Deva Jai Jai Shankar Deva Bholyan Bhandara Mahadeva Jai Jai Shankar Deva Tryambak Trinetra Chandrashekhara Gangadhar Shulapani Bhaktancha Rakshana Jai Jai Shankar Deva Nagendra Hara Bhootnatha Kailasavasi Shankara Jai Jai Shankar Deva Parvati Vallabha Vishwanatha Sadashiva Shivashankara Jai Jai Shankar Deva Aarti Ovalu Tuzhi Mahadeva Sankati Padale Rakshan Kara Re Deva Jai Jai Shankar Deva', 'जय जय शंकर देवा, जय जय शंकर देवा। भोळ्या भंडारा, महादेवा। त्र्यंबक, त्रिनेत्रा, चंद्रशेखरा। गंगाधर, शूलपाणी, भक्तांच्या रक्षणा। नागेंद्र हारा, भूतनाथा। कैलासवासी, शंकरा। पार्वती वल्लभा, विश्वनाथा। सदाशिवा, शिवशंकरा। आरती ओवाळू, तुझी महादेवा। संकटी पडले, रक्षण करा रे देवा।', 'Victory to Lord Shankar Deva, victory to Lord Shankar Deva. The simple-hearted one, the great lord. The three-eyed one, the moon-crested one. Bearer of Ganga, holder of the trident, protector of devotees. Adorned with serpents, lord of ghosts. Dweller of Kailasa, O Shankara. Consort of Parvati, lord of the universe. The eternal, the auspicious one. I wave the aarti before you, O Mahadeva. We are in trouble, protect us, O Lord.', NULL, 'जय जय शंकर देवा', 'शंकराची ही आरती सोमवार, शिवरात्री, आणि प्रतिदिन सायंकाळी गायली जाते. यामुळे मानसिक शांती, आरोग्य, आणि सर्व संकटांपासून मुक्ती मिळते.', 'बेलपत्र, धतुरा, भांग, फुले, दीपक अर्पण करा. आरतीनंतर शिवपंचाक्षरी मंत्राचा जप करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(31, 'Jai Jai Amba Bhavani (Marathi Devi Aarti)', 'Durga', 21, 'जय जय अंबे भवानी, जय जय अंबे भवानी। तूच जगाची जननी, तूच दीनांची दैन्यहारी॥\r\nजय जय अंबे भवानी॥\r\nसिंहवाहिनी माता, महिषासुर मर्दिनी। दुर्गे भवानी, तारक रक्षिणी॥\r\nजय जय अंबे भवानी॥\r\nकोल्हापुरी महालक्ष्मी, तुझी नगरी। तुळजापुरी भवानी, सकळांची सुखकरी॥\r\nजय जय अंबे भवानी॥\r\nआरती ओवाळू, तुझी आई माऊली। सर्व संकटे दूर होतील, दया करी माऊली॥\r\nजय जय अंबे भवानी॥', 'Jai Jai Ambe Bhavani Jai Jai Ambe Bhavani Tuch Jagachi Janani Tuch Dinanchi Dainyahari Jai Jai Ambe Bhavani Simhavahini Mata Mahishasur Mardini Durge Bhavani Tarak Rakshini Jai Jai Ambe Bhavani Kolhapuri Mahalakshmi Tuzhi Nagari Tuljapuri Bhavani Sakalanchi Sukhakari Jai Jai Ambe Bhavani Aarti Ovalu Tuzhi Aai Mauli Sarva Sankate Door Hotil Daya Kari Mauli Jai Jai Ambe Bhavani', 'जय जय अंबे भवानी, जय जय अंबे भवानी। तूच जगाची जननी, तूच दीनांची दैन्यहारी। सिंहवाहिनी माता, महिषासुर मर्दिनी। दुर्गे भवानी, तारक रक्षिणी। कोल्हापुरी महालक्ष्मी, तुझी नगरी। तुळजापुरी भवानी, सकळांची सुखकरी। आरती ओवाळू, तुझी आई माऊली। सर्व संकटे दूर होतील, दया करी माऊली।', 'Victory to Mother Amba Bhavani, victory to Mother Amba Bhavani. You are the mother of the universe, you remove the suffering of the poor. The lion-riding mother, slayer of Mahishasura. O Durga Bhavani, the protector who helps one cross. Kolhapur\'s Mahalakshmi, your city. Tuljapur\'s Bhavani, bringer of happiness to all. I wave the aarti before you, O Mother. All troubles will be removed, have mercy, O Mother.', NULL, 'जय जय अंबे भवानी', 'देवीची ही आरती नवरात्रात, मंगळवार, शुक्रवार, आणि आषाढी-कार्तिकी एकादशीस विशेष गायली जाते. यामुळे सर्व संकटे दूर होतात आणि शक्ती प्राप्त होते.', 'लाल फुले, लाल चुनरी, दीपक, धूप, नैवेद्य अर्पण करा. आरतीनंतर देवीच्या मंत्राचा जप करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(32, 'Jai Jai Vitthala (Marathi Pandharpur Aarti)', 'Vithoba', 21, 'जय जय विठ्ठला, जय जय विठ्ठला। पंढरीच्या राया, तूच देवा दयाळा॥\r\nजय जय विठ्ठला॥\r\nरखुमाई वल्लभा, तूच देवा निरंजना। भक्तांच्या संकटी, तूच एक आधारा॥\r\nजय जय विठ्ठला॥\r\nनामा तुकाराम, ज्ञानेश्वर सावळा। तुझ्या भक्तांवरी, तुझा सदा सोहळा॥\r\nजय जय विठ्ठला॥\r\nआरती ओवाळू, तुझी रे पांडुरंगा। वारी करी आम्ही, येईन माऊलीसंगा॥\r\nजय जय विठ्ठला॥', 'Jai Jai Vitthala Jai Jai Vitthala Pandharichya Raya Tu Deva Dayala Jai Jai Vitthala Rakhumai Vallabha Tu Deva Niranjana Bhaktancha Sankati Tu Ek Aadhara Jai Jai Vitthala Nama Tukaram Dnyaneshwar Savala Tujhya Bhaktanvari Tuja Sada Sohala Jai Jai Vitthala Aarti Ovalu Tuzhi Re Panduranga Wari Kari Amhi Yein Maulisinga Jai Jai Vitthala', 'जय जय विठ्ठला, जय जय विठ्ठला। पंढरीच्या राया, तूच देवा दयाळा। रखुमाई वल्लभा, तूच देवा निरंजना। भक्तांच्या संकटी, तूच एक आधारा। नामा तुकाराम, ज्ञानेश्वर सावळा। तुझ्या भक्तांवरी, तुझा सदा सोहळा। आरती ओवाळू, तुझी रे पांडुरंगा। वारी करी आम्ही, येईन माऊलीसंगा।', 'Victory to Lord Vitthala, victory to Lord Vitthala. Lord of Pandharpur, you are the compassionate one. Consort of Rakhumai, you are the pure one. In the troubles of devotees, you are the only support. Nama, Tukaram, and the dark Dnyaneshwar. There is always a celebration of your devotees. I wave the aarti before you, O Panduranga. We go on pilgrimage, I will come with the mother.', NULL, 'जय जय विठ्ठला', 'विठ्ठलाची ही आरती आषाढी-कार्तिकी एकादशीस, वारीच्या वेळी, आणि प्रतिदिन सायंकाळी गायली जाते. यामुळे भक्ती, श्रद्धा, आणि आध्यात्मिक उन्नती प्राप्त होते.', 'तुळशीपत्र, फुले, दीपक, धूप अर्पण करा. आरतीनंतर विठ्ठलाचे कीर्तन करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(33, 'Jai Jai Tulshi Mata (Marathi Tulshi Aarti)', 'Tulsi', 21, 'जय जय तुळशी माता, जय जय तुळशी माता। विष्णूच्या चरणी, तुझी सदा वासना॥\r\nजय जय तुळशी माता॥\r\nतुळशी वृंदावनी, तूच देवी पावन। पापनाशिनी माता, सकळांची रक्षण॥\r\nजय जय तुळशी माता॥\r\nआरती ओवाळू, तुझी आई माऊली। सुख संपत्ती द्यावी, दया करी माऊली॥\r\nजय जय तुळशी माता॥', 'Jai Jai Tulshi Mata Jai Jai Tulshi Mata Vishnuchya Charani Tuzhi Sada Vasana Jai Jai Tulshi Mata Tulshi Vrindavani Tu Devi Pavan Papanashini Mata Sakalanchi Rakshan Jai Jai Tulshi Mata Aarti Ovalu Tuzhi Aai Mauli Sukh Sampatti Dyavi Daya Kari Mauli Jai Jai Tulshi Mata', 'जय जय तुळशी माता, जय जय तुळशी माता। विष्णूच्या चरणी, तुझी सदा वासना। तुळशी वृंदावनी, तूच देवी पावन। पापनाशिनी माता, सकळांची रक्षण। आरती ओवाळू, तुझी आई माऊली। सुख संपत्ती द्यावी, दया करी माऊली।', 'Victory to Mother Tulsi, victory to Mother Tulsi. Your desire is always at the feet of Vishnu. Tulsi of Vrindavan, you are the holy goddess. Destroyer of sins, protector of all. I wave the aarti before you, O Mother. Grant us happiness and prosperity, have mercy, O Mother.', NULL, 'जय जय तुळशी माता', 'तुळशीची ही आरती प्रतिदिन सायंकाळी, तुळशी विवाहाच्या वेळी, आणि प्रत्येक गुरुवारी गायली जाते. यामुळे घरात सुख-शांती आणि समृद्धी येते.', 'तुळशीच्या वृंदावनासमोर दीपक ओवाळा. फुले, जल अर्पण करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(34, 'Jai Jai Satyanarayan (Marathi Satyanarayan Aarti)', 'Satyanarayan', 21, 'जय जय सत्यनारायण, जय जय सत्यनारायण। तुझे नाम घेतां, सर्व संकटे हरती॥\r\nजय जय सत्यनारायण॥\r\nब्रह्मा विष्णु महेशाचा, तूच देवा आधार। सत्यरूपी नारायणा, तूच साचा संसार॥\r\nजय जय सत्यनारायण॥\r\nभक्तांच्या भक्तीला, तू देवा सादर। सत्यनारायणाची, ही आरती सुंदर॥\r\nजय जय सत्यनारायण॥\r\nआरती ओवाळू, तुझी रे नारायणा। सर्व सुखे घरा येतील, दया करी रे देवा॥\r\nजय जय सत्यनारायण॥', 'Jai Jai Satyanarayan Jai Jai Satyanarayan Tuje Naam Gheta Sarva Sankate Harti Jai Jai Satyanarayan Brahma Vishnu Maheshacha Tu Deva Aadhar Satyarupi Narayana Tu Sachi Sansar Jai Jai Satyanarayan Bhaktancha Bhaktila Tu Deva Sadar Satyanarayanachi Hi Aarti Sundar Jai Jai Satyanarayan Aarti Ovalu Tuzhi Re Narayana Sarva Sukhe Ghara Yetil Daya Kari Re Deva Jai Jai Satyanarayan', 'जय जय सत्यनारायण, जय जय सत्यनारायण। तुझे नाम घेतां, सर्व संकटे हरती। ब्रह्मा विष्णु महेशाचा, तूच देवा आधार। सत्यरूपी नारायणा, तूच साचा संसार। भक्तांच्या भक्तीला, तू देवा सादर। सत्यनारायणाची, ही आरती सुंदर। आरती ओवाळू, तुझी रे नारायणा। सर्व सुखे घरा येतील, दया करी रे देवा।', 'Victory to Lord Satyanarayan, victory to Lord Satyanarayan. Chanting your name removes all troubles. You are the support of Brahma, Vishnu, and Mahesh. O Narayana, the embodiment of truth, you are the real world. You are responsive to the devotion of devotees. This is the beautiful aarti of Satyanarayan. I wave the aarti before you, O Narayana. All happiness will come to the home, have mercy, O Lord.', NULL, 'जय जय सत्यनारायण', 'सत्यनारायणाची ही आरती पौर्णिमेला, संकष्टी चतुर्थीला, आणि कोणत्याही शुभ कार्यानंतर गायली जाते. यामुळे मनोकामना पूर्ण होतात.', 'पंचामृत, फुले, दुर्वा, दीपक, धूप अर्पण करा. आरतीनंतर सत्यनारायणाची कथा ऐका.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(35, 'Tukoba Tukoba (Sant Tukaram Aarti)', 'Sant Tukaram', 21, 'जय देवा जय देवा, जय तुकारामा। भक्तीची माळ तुझी, देही सर्वांधामा॥\r\nजय देवा जय देवा॥\r\nपंढरीच्या वारीला, तूच निघाला। आबीर गुलाल उधळीत, गेला आनंदे॥\r\nजय देवा जय देवा॥\r\nअभंगांची गाणी, तूच गायिला। विठ्ठल नाम घेतां, सुखी झाला॥\r\nजय देवा जय देवा॥\r\nआरती ओवाळू, तुजला तुकारामा। सर्व संकटे दूर होतील, येईन माऊलीच्या धामा॥\r\nजय देवा जय देवा॥', 'Jai Deva Jai Deva Jai Tukarama Bhaktichi Mal Tuzhi Dehi Sarvandhama Jai Deva Jai Deva Pandharichya Warila Tuch Nighala Abir Gulal Udhalit Gela Aanande Jai Deva Jai Deva Abhangachi Gani Tuch Gayila Vitthal Naam Gheta Sukhi Jhala Jai Deva Jai Deva Aarti Ovalu Tujala Tukarama Sarva Sankate Door Hotil Yein Maulichya Dhama Jai Deva Jai Deva', 'जय देवा जय देवा, जय तुकारामा। भक्तीची माळ तुझी, देही सर्वांधामा। पंढरीच्या वारीला, तूच निघाला। आबीर गुलाल उधळीत, गेला आनंदे। अभंगांची गाणी, तूच गायिला। विठ्ठल नाम घेतां, सुखी झाला। आरती ओवाळू, तुजला तुकारामा। सर्व संकटे दूर होतील, येईन माऊलीच्या धामा।', 'Victory to Lord, victory to Lord, victory to Tukaram. Your garland of devotion is in everyone\'s body. You set out for the Pandharpur pilgrimage. You went joyfully, throwing gulal. You sang the songs of abhangas. Chanting Vitthal\'s name, you became happy. I wave the aarti before you, O Tukaram. All troubles will be removed, I will come to the mother\'s abode.', NULL, 'जय देवा जय देवा', 'संत तुकारामांची ही आरती पंढरीच्या वारीच्या वेळी, आषाढी-कार्तिकी एकादशीस, आणि प्रतिदिन सकाळी गायली जाते. यामुळे भक्ती, श्रद्धा आणि सद्गुरुकृपा प्राप्त होते.', 'पिवळी फुले, फळे, दीपक, धूप अर्पण करा. आरतीनंतर तुकारामांच्या अभंगांचे पठण करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(36, 'Jai Jai Dnyaneshwara (Sant Dnyaneshwar Aarti)', 'Sant Dnyaneshwar', 21, 'जय जय ज्ञानेश्वरा, जय तुकारामा। तुझ्या भक्तीचा मार्ग, दावी सर्व धामा॥\r\nजय जय ज्ञानेश्वरा॥\r\nज्ञानेश्वरी रचिली, तूने अभंगा। विठ्ठल नाम घेतां, सुखी झाला सर्वांगा॥\r\nजय जय ज्ञानेश्वरा॥\r\nआळंदीच्या नगरी, तूच देवा वासी। भक्तांच्या संकटी, तूच सदा सहवासी॥\r\nजय जय ज्ञानेश्वरा॥\r\nआरती ओवाळू, तुजला ज्ञानेश्वरा। सर्व सुखे घरा येतील, दया करी रे ईश्वरा॥\r\nजय जय ज्ञानेश्वरा॥', 'Jai Jai Dnyaneshwara Jai Tukarama Tujhya Bhakticha Marg Davi Sarva Dhama Jai Jai Dnyaneshwara Dnyaneshwari Rachili Tune Abhanga Vitthal Naam Gheta Sukhi Jhala Sarvanga Jai Jai Dnyaneshwara Aalandichya Nagari Tu Deva Vasi Bhaktancha Sankati Tu Sada Sahavasi Jai Jai Dnyaneshwara Aarti Ovalu Tujala Dnyaneshwara Sarva Sukhe Ghara Yetil Daya Kari Re Ishwara Jai Jai Dnyaneshwara', 'जय जय ज्ञानेश्वरा, जय तुकारामा। तुझ्या भक्तीचा मार्ग, दावी सर्व धामा। ज्ञानेश्वरी रचिली, तूने अभंगा। विठ्ठल नाम घेतां, सुखी झाला सर्वांगा। आळंदीच्या नगरी, तूच देवा वासी। भक्तांच्या संकटी, तूच सदा सहवासी। आरती ओवाळू, तुजला ज्ञानेश्वरा। सर्व सुखे घरा येतील, दया करी रे ईश्वरा।', 'Victory to Lord Dnyaneshwara, victory to Tukaram. You showed the path of devotion to all. You composed the Dnyaneshwari and abhangas. Chanting Vitthal\'s name, you became completely happy. In the city of Alandi, you dwell, O Lord. In the troubles of devotees, you are always with them. I wave the aarti before you, O Dnyaneshwara. All happiness will come to the home, have mercy, O Lord.', NULL, 'जय जय ज्ञानेश्वरा', 'संत ज्ञानेश्वरांची ही आरती आळंदी येथे, पालखी सोहळ्याच्या वेळी, आणि प्रतिदिन सकाळी गायली जाते. यामुळे ज्ञान, भक्ती आणि सद्गुरुकृपा प्राप्त होते.', 'फुले, फळे, दीपक, धूप अर्पण करा. आरतीनंतर ज्ञानेश्वरीचे पठण करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:29', '2026-03-23 18:11:29', NULL, NULL, NULL, NULL, NULL, NULL),
(37, 'Jai Jai Kanhopatra (Sant Kanhopatra Aarti)', 'Sant Kanhopatra', 21, 'जय जय कान्होपात्रे, जय सावित्री। तुझ्या भक्तीची माळ, सर्वांच्या गात्री॥\r\nजय जय कान्होपात्रे॥\r\nपंढरीच्या वारीला, तूच निघाली। विठ्ठल नाम घेतां, सुखी झाली॥\r\nजय जय कान्होपात्रे॥\r\nआरती ओवाळू, तुझी आई माऊली। सर्व संकटे दूर होतील, दया करी माऊली॥\r\nजय जय कान्होपात्रे॥', 'Jai Jai Kanhopatre Jai Savitri Tujhya Bhaktichi Mal Sarvancha Gatree Jai Jai Kanhopatre Pandharichya Warila Tuch Nighali Vitthal Naam Gheta Sukhi Jhalil Jai Jai Kanhopatre Aarti Ovalu Tuzhi Aai Mauli Sarva Sankate Door Hotil Daya Kari Mauli Jai Jai Kanhopatre', 'जय जय कान्होपात्रे, जय सावित्री। तुझ्या भक्तीची माळ, सर्वांच्या गात्री। पंढरीच्या वारीला, तूच निघाली। विठ्ठल नाम घेतां, सुखी झाली। आरती ओवाळू, तुझी आई माऊली। सर्व संकटे दूर होतील, दया करी माऊली।', 'Victory to Kanhopatra, victory to Savitri. The garland of your devotion is sung by all. You set out for the Pandharpur pilgrimage. Chanting Vitthal\'s name, you became happy. I wave the aarti before you, O Mother. All troubles will be removed, have mercy, O Mother.', NULL, 'जय जय कान्होपात्रे', 'संत कान्होपात्रा यांची ही आरती पंढरीच्या वारीच्या वेळी आणि प्रतिदिन सायंकाळी गायली जाते. यामुळे भक्ती आणि श्रद्धा वाढते.', 'फुले, फळे, दीपक अर्पण करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:30', '2026-03-23 18:11:30', NULL, NULL, NULL, NULL, NULL, NULL),
(38, 'Gondhal Aarti (Marathi)', 'Traditional', 21, 'जय जय गोंधळीया, जय जय गोंधळीया। तुझ्या नामाचा गजर, सर्वांना सुखदायीया॥\r\nजय जय गोंधळीया॥\r\nडमरु डमरु वाजे, टाळ मृदंग गाजे। गोंधळाच्या नादात, सारे जन नाचे॥\r\nजय जय गोंधळीया॥\r\nआरती ओवाळू, तुझी रे गोंधळीया। सर्व सुखे घरा येतील, दया करी रे देवा॥\r\nजय जय गोंधळीया॥', 'Jai Jai Gondhaliya Jai Jai Gondhaliya Tujhya Namacha Gajar Sarvanna Sukhadayiya Jai Jai Gondhaliya Damru Damru Vaje Taal Mridang Gaje Gondhalachya Nadat Sare Jan Nache Jai Jai Gondhaliya Aarti Ovalu Tuzhi Re Gondhaliya Sarva Sukhe Ghara Yetil Daya Kari Re Deva Jai Jai Gondhaliya', 'जय जय गोंधळीया, जय जय गोंधळीया। तुझ्या नामाचा गजर, सर्वांना सुखदायीया। डमरु डमरु वाजे, टाळ मृदंग गाजे। गोंधळाच्या नादात, सारे जन नाचे। आरती ओवाळू, तुझी रे गोंधळीया। सर्व सुखे घरा येतील, दया करी रे देवा।', 'Victory to Gondhaliya, victory to Gondhaliya. The chanting of your name brings happiness to all. Damru sounds, cymbals and drums resound. In the rhythm of Gondhal, all people dance. I wave the aarti before you, O Gondhaliya. All happiness will come to the home, have mercy, O Lord.', NULL, 'जय जय गोंधळीया', 'गोंधळाची ही आरती गोंधळ कार्यक्रमात, जागरणाच्या वेळी, आणि देवीच्या उत्सवात गायली जाते. यामुळे सर्व संकटे दूर होतात.', 'दीपक, धूप, टाळ, मृदंगासह आरती करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:30', '2026-03-23 18:11:30', NULL, NULL, NULL, NULL, NULL, NULL),
(39, 'Jai Jai Bhairavnatha (Marathi Bhairav Aarti)', 'Bhairav', 21, 'जय जय भैरवनाथा, जय जय भैरवनाथा। तुझ्या नामाचा गजर, सर्वांना सुखदाता॥\r\nजय जय भैरवनाथा॥\r\nश्वान वाहन राजे, खड्ग कर धारी। काशीचे कोतवाल, भक्तांचे तारणहारी॥\r\nजय जय भैरवनाथा॥\r\nआरती ओवाळू, तुझी भैरवनाथा। सर्व संकटे दूर होतील, दया करी रे नाथा॥\r\nजय जय भैरवनाथा॥', 'Jai Jai Bhairavnatha Jai Jai Bhairavnatha Tujhya Namacha Gajar Sarvanna Sukhadata Jai Jai Bhairavnatha Shvan Vahan Raje Khadg Kar Dhari Kashi Che Kotwal Bhaktanche Taranhari Jai Jai Bhairavnatha Aarti Ovalu Tuzhi Bhairavnatha Sarva Sankate Door Hotil Daya Kari Re Natha Jai Jai Bhairavnatha', 'जय जय भैरवनाथा, जय जय भैरवनाथा। तुझ्या नामाचा गजर, सर्वांना सुखदाता। श्वान वाहन राजे, खड्ग कर धारी। काशीचे कोतवाल, भक्तांचे तारणहारी। आरती ओवाळू, तुझी भैरवनाथा। सर्व संकटे दूर होतील, दया करी रे नाथा।', 'Victory to Lord Bhairavnath, victory to Lord Bhairavnath. The chanting of your name brings happiness to all. You ride a dog, holding a sword. Guardian of Kashi, savior of devotees. I wave the aarti before you, O Bhairavnath. All troubles will be removed, have mercy, O Lord.', NULL, 'जय जय भैरवनाथा', 'भैरवनाथाची ही आरती अष्टमी तिथीला, मंगळवारी, आणि रविवारी गायली जाते. यामुळे काल सर्प दोष, शत्रु बाधा, आणि भय दूर होते.', 'काळी फुले, तेल, तिळ, दीपक, धूप अर्पण करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:30', '2026-03-23 18:11:30', NULL, NULL, NULL, NULL, NULL, NULL),
(40, 'Jai Jai Malhari (Khandoba Aarti)', 'Khandoba', 21, 'जय जय मल्हारी, जय जय मल्हारी। तुझ्या भक्तांच्या, सदा सुखकारी॥\r\nजय जय मल्हारी॥\r\nजेजुरीच्या नगरी, तूच देवा वासी। भक्तांच्या संकटी, तूच सदा सहवासी॥\r\nजय जय मल्हारी॥\r\nम्हसोबा तुझा सखा, बाणू तुझी सखी। काळूबाई माता, सर्वांची सुखकरी॥\r\nजय जय मल्हारी॥\r\nआरती ओवाळू, तुझी रे मल्हारी। सर्व संकटे दूर होतील, दया करी रे हरी॥\r\nजय जय मल्हारी॥', 'Jai Jai Malhari Jai Jai Malhari Tujhya Bhaktancha Sada Sukhakari Jai Jai Malhari Jejurichya Nagari Tu Deva Vasi Bhaktancha Sankati Tu Sada Sahavasi Jai Jai Malhari Mhasoba Tuja Sakha Banu Tuji Sakhi Kalubai Mata Sarvanchi Sukhakari Jai Jai Malhari Aarti Ovalu Tuzhi Re Malhari Sarva Sankate Door Hotil Daya Kari Re Hari Jai Jai Malhari', 'जय जय मल्हारी, जय जय मल्हारी। तुझ्या भक्तांच्या, सदा सुखकारी। जेजुरीच्या नगरी, तूच देवा वासी। भक्तांच्या संकटी, तूच सदा सहवासी। म्हसोबा तुझा सखा, बाणू तुझी सखी। काळूबाई माता, सर्वांची सुखकरी। आरती ओवाळू, तुझी रे मल्हारी। सर्व संकटे दूर होतील, दया करी रे हरी।', 'Victory to Malhari, victory to Malhari. Always the source of happiness for your devotees. In the city of Jejuri, you dwell, O Lord. In the troubles of devotees, you are always with them. Mhasoba is your friend, Banu is your companion. Mother Kalubai brings happiness to all. I wave the aarti before you, O Malhari. All troubles will be removed, have mercy, O Lord.', NULL, 'जय जय मल्हारी', 'खंडोबाची ही आरती मंगळवारी, सोमवारी, आणि जेजुरी यात्रेच्या वेळी विशेष गायली जाते. यामुळे सर्व संकटे दूर होतात.', 'हळद, कुंकू, फुले, दीपक, धूप अर्पण करा. आरतीनंतर खंडोबाचे भजन करा.', NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-23 18:11:30', '2026-03-23 18:11:30', NULL, NULL, NULL, NULL, NULL, NULL);
