INSERT INTO `categories` (`id`, `name`, `description`, `icon_url`, `display_order`, `created_at`) VALUES
(1, 'Ganesh Mantras', 'Complete collection of Lord Ganesha mantras - for removing obstacles, wisdom, and new beginnings', '/icons/ganesha.png', 1, '2026-03-18 02:17:34'),
(2, 'Shiva Mantras', 'Complete collection of Lord Shiva mantras - for liberation, transformation, and spiritual power', '/icons/shiva.png', 2, '2026-03-18 02:18:19'),
(3, 'Vishnu Mantras', 'Complete collection of Lord Vishnu mantras - for preservation, prosperity, and peace', '/icons/vishnu.png', 3, '2026-03-18 02:25:50'),
(4, 'Devi Mantras', 'Complete collection of Divine Mother mantras - for strength, protection, and spiritual power', '/icons/devi.png', 4, '2026-03-18 02:34:30'),
(5, 'Navagraha Mantras', 'Complete collection of Nine Planet mantras - for astrological balance, prosperity, and protection from malefic effects', '/icons/navagraha.png', 5, '2026-03-18 02:51:52'),
(6, 'Healing Mantras', 'Powerful mantras for physical, mental, and spiritual healing - for health, wellness, and protection from diseases', '/icons/healing.png', 6, '2026-03-18 11:40:36'),
(7, 'Hanuman Mantras', 'Complete collection of Lord Hanuman mantras - for strength, protection, courage, and devotion. Hanuman is the symbol of strength, energy, and unwavering devotion to Lord Rama', '/icons/hanuman.png', 7, '2026-03-18 11:47:40'),
(8, 'Guru Mantras', 'Complete collection of Guru mantras - for spiritual guidance, wisdom, and removing ignorance. \"Guru\" means remover of darkness (Gu = darkness, Ru = remover)', '/icons/guru.png', 8, '2026-03-23 03:08:37'),
(9, 'Lakshmi Mantras', 'Complete collection of Goddess Lakshmi mantras - for wealth, prosperity, abundance, and good fortune. Lakshmi is the consort of Lord Vishnu and the goddess of material and spiritual prosperity', '/icons/lakshmi.png', 9, '2026-03-23 03:08:49'),
(10, 'Saraswati Mantras', 'Complete collection of Goddess Saraswati mantras - for knowledge, wisdom, arts, music, and learning. Saraswati is the goddess of knowledge, music, arts, wisdom, and learning, and the consort of Lord Brahma', '/icons/saraswati.png', 10, '2026-03-23 03:09:22'),
(11, 'Brahma Mantras', 'Complete collection of Lord Brahma mantras - for creation, knowledge, wisdom, and the Vedas. Brahma is the creator god in Hinduism, part of the Trimurti along with Vishnu and Shiva, and the consort of Goddess Saraswati', '/icons/brahma.png', 11, '2026-03-23 03:11:34'),
(12, 'Indra & Vedic Deities', 'Complete collection of mantras for Indra and other Vedic deities - including Agni, Vayu, Varuna, Surya, Chandra, Yama, and other important gods from the Vedas', '/icons/vedic.png', 12, '2026-03-23 03:15:20'),
(13, 'Regional Deities', 'Complete collection of mantras for regional and folk deities - including Ayyappa, Venkateshwara, Vithoba, Jagannath, Murugan, and other beloved regional forms of the divine', '/icons/regional.png', 13, '2026-03-23 03:15:39'),
(14, 'Vedic Suktas & Hymns', 'Complete collection of ancient Vedic hymns (Suktas) from the Rigveda and other Vedas - including Purusha Sukta, Narayana Sukta, Sri Sukta, and other powerful hymns for spiritual upliftment', '/icons/vedic_suktas.png', 14, '2026-03-23 03:32:31'),
(15, 'Tantric & Sri Vidya Mantras', 'Powerful mantras from Tantric tradition and Sri Vidya worship - including Sri Chakra, Lalita Sahasranama, Bala Tripurasundari, and other esoteric mantras for spiritual transformation', '/icons/tantric.png', 16, '2026-03-23 04:00:39'),
(17, 'Dasha Mahavidya Mantras', 'Complete collection of the Ten Great Wisdom Goddesses (Dasha Mahavidya) mantras - including Kali, Tara, Tripura Sundari, Bhuvaneshwari, Bhairavi, Chinnamasta, Dhumavati, Bagalamukhi, Matangi, and Kamala. These powerful tantric deities represent the ten aspects of the Divine Mother', '/icons/dasha_mahavidya.png', 17, '2026-03-23 04:07:55'),
(18, 'Nava Durga Mantras', 'Complete collection of the Nine Forms of Goddess Durga (Navadurga) mantras - worshiped during Navaratri. Each form represents a unique aspect of the Divine Mother: Shailaputri, Brahmacharini, Chandraghanta, Kushmanda, Skandamata, Katyayani, Kalaratri, Mahagauri, and Siddhidatri', '/icons/nava_durga.png', 18, '2026-03-23 04:17:15'),
(19, 'Bhakti Movement Hymns', 'Sacred hymns and verses from the Bhakti Movement saints - including Kabir, Mirabai, Tulsidas, Surdas, Tukaram, Namdev, and other great devotional poets who spread the path of love and devotion', '/icons/bhakti.png', 20, '2026-03-23 04:26:59'),
(21, 'Aartis', 'Complete collection of Aartis for various deities - devotional hymns sung during worship with lamps', '/icons/aarti.png', 21, '2026-03-23 17:49:39');
INSERT INTO `chalisa` (`id`, `chalisa_name`, `deity_name`, `language`, `total_verses`, `author`, `description`, `significance`, `benefits`, `best_time`, `recommended_day`, `verses`, `audio_url`, `video_url`, `is_premium`, `views_count`, `likes_count`, `created_at`, `updated_at`) VALUES
(1, 'Hanuman Chalisa', 'Hanuman', 'Hindi', 40, 'Goswami Tulsidas', 'हनुमान चालीसा गोस्वामी तुलसीदास जी द्वारा रचित 40 चौपाइयों का स्तोत्र है। यह भगवान हनुमान को समर्पित सबसे लोकप्रिय और शक्तिशाली स्तोत्र है।', 'हनुमान चालीसा का पाठ संकटों से मुक्ति दिलाने वाला, बल-बुद्धि-विद्या प्रदान करने वाला और सभी मनोकामनाओं को पूर्ण करने वाला माना जाता है।', 'नियमित पाठ से मानसिक शांति, आत्मविश्वास, शारीरिक शक्ति, शत्रुओं पर विजय और सभी प्रकार के भय से मुक्ति मिलती है।', 'प्रातःकाल स्नान के बाद या सायंकाल में', 'मंगलवार, शनिवार', '[\r\n    {\"verse_no\":1,\"text\":\"श्री गुरु चरन सरोज रज, निज मनु मुकुरु सुधारि। बरनउँ रघुबर बिमल जसु, जो दायकु फल चारि॥\"},\r\n    {\"verse_no\":2,\"text\":\"बुद्धिहीन तनु जानिके, सुमिरौं पवन-कुमार। बल बुद्धि विद्या देहु मोहिं, हरहु कलेस विकार॥\"},\r\n    {\"verse_no\":3,\"text\":\"जय हनुमान ज्ञान गुन सागर। जय कपीस तिहुँ लोक उजागर॥\"},\r\n    {\"verse_no\":4,\"text\":\"राम दूत अतुलित बल धामा। अंजनि-पुत्र पवनसुत नामा॥\"},\r\n    {\"verse_no\":5,\"text\":\"महाबीर बिक्रम बजरंगी। कुमति निवार सुमति के संगी॥\"},\r\n    {\"verse_no\":6,\"text\":\"कंचन बरन बिराज सुबेसा। कानन कुंडल कुंचित केसा॥\"},\r\n    {\"verse_no\":7,\"text\":\"हाथ बज्र औ ध्वजा बिराजै। काँधे मूँज जनेऊ साजै॥\"},\r\n    {\"verse_no\":8,\"text\":\"शंकर सुवन केसरी नंदन। तेज प्रताप महा जग बंदन॥\"},\r\n    {\"verse_no\":9,\"text\":\"विद्यावान गुनी अति चातुर। राम काज करिबे को आतुर॥\"},\r\n    {\"verse_no\":10,\"text\":\"प्रभु चरित्र सुनिबे को रसिया। राम लखन सीता मन बसिया॥\"},\r\n    {\"verse_no\":11,\"text\":\"सूक्ष्म रूप धरि सियहिं दिखावा। बिकट रूप धरि लंक जरावा॥\"},\r\n    {\"verse_no\":12,\"text\":\"भीम रूप धरि असुर संहारे। रामचंद्र के काज सवारे॥\"},\r\n    {\"verse_no\":13,\"text\":\"लाय सजीवन लखन जियाये। श्रीरघुबीर हरषि उर लाये॥\"},\r\n    {\"verse_no\":14,\"text\":\"रघुपति कीन्ही बहुत बड़ाई। तुम मम प्रिय भरतहि सम भाई॥\"},\r\n    {\"verse_no\":15,\"text\":\"सहस बदन तुम्हरो जस गावैं। अस कहि श्रीपति कंठ लगावैं॥\"},\r\n    {\"verse_no\":16,\"text\":\"सनकादिक ब्रह्मादि मुनीसा। नारद सारद सहित अहीसा॥\"},\r\n    {\"verse_no\":17,\"text\":\"जम कुबेर दिगपाल जहाँ ते। कबि कोबिद कहि सके कहाँ ते॥\"},\r\n    {\"verse_no\":18,\"text\":\"तुम उपकार सुग्रीवहिं कीन्हा। राम मिलाय राज पद दीन्हा॥\"},\r\n    {\"verse_no\":19,\"text\":\"तुम्हरो मंत्र बिभीषन माना। लंकेश्वर भए सब जग जाना॥\"},\r\n    {\"verse_no\":20,\"text\":\"जुग सहस्र जोजन पर भानू। लील्यो ताहि मधुर फल जानू॥\"},\r\n    {\"verse_no\":21,\"text\":\"प्रभु मुद्रिका मेलि मुख माहीं। जलधि लाँघि गये अचरज नाहीं॥\"},\r\n    {\"verse_no\":22,\"text\":\"दुर्गम काज जगत के जेते। सुगम अनुग्रह तुम्हरे तेते॥\"},\r\n    {\"verse_no\":23,\"text\":\"राम दुआरे तुम रखवारे। होत न आज्ञा बिनु पैसारे॥\"},\r\n    {\"verse_no\":24,\"text\":\"सब सुख लहै तुम्हारी सरना। तुम रक्षक काहू को डर ना॥\"},\r\n    {\"verse_no\":25,\"text\":\"आपन तेज सम्हारो आपै। तीनों लोक हाँक तें काँपै॥\"},\r\n    {\"verse_no\":26,\"text\":\"भूत पिशाच निकट नहिं आवै। महावीर जब नाम सुनावै॥\"},\r\n    {\"verse_no\":27,\"text\":\"नासै रोग हरै सब पीरा। जपत निरंतर हनुमत बीरा॥\"},\r\n    {\"verse_no\":28,\"text\":\"संकट तें हनुमान छुड़ावै। मन क्रम बचन ध्यान जो लावै॥\"},\r\n    {\"verse_no\":29,\"text\":\"सब पर राम तपस्वी राजा। तिनके काज सकल तुम साजा॥\"},\r\n    {\"verse_no\":30,\"text\":\"और मनोरथ जो कोई लावै। सोइ अमित जीवन फल पावै॥\"},\r\n    {\"verse_no\":31,\"text\":\"चारों जुग परताप तुम्हारा। है परसिद्ध जगत उजियारा॥\"},\r\n    {\"verse_no\":32,\"text\":\"साधु संत के तुम रखवारे। असुर निकंदन राम दुलारे॥\"},\r\n    {\"verse_no\":33,\"text\":\"अष्ट सिद्धि नौ निधि के दाता। अस बर दीन जानकी माता॥\"},\r\n    {\"verse_no\":34,\"text\":\"राम रसायन तुम्हरे पासा। सदा रहो रघुपति के दासा॥\"},\r\n    {\"verse_no\":35,\"text\":\"तुम्हरे भजन राम को पावै। जनम जनम के दुख बिसरावै॥\"},\r\n    {\"verse_no\":36,\"text\":\"अंत काल रघुबर पुर जाई। जहाँ जन्म हरि भक्त कहाई॥\"},\r\n    {\"verse_no\":37,\"text\":\"और देवता चित्त न धरई। हनुमत सेइ सर्व सुख करई॥\"},\r\n    {\"verse_no\":38,\"text\":\"संकट कटै मिटै सब पीरा। जो सुमिरै हनुमत बलबीरा॥\"},\r\n    {\"verse_no\":39,\"text\":\"जय जय जय हनुमान गोसाईं। कृपा करहु गुरुदेव की नाईं॥\"},\r\n    {\"verse_no\":40,\"text\":\"जो सत बार पाठ कर कोई। छूटहि बंदि महा सुख होई॥\"},\r\n    {\"verse_no\":41,\"text\":\"जो यह पढ़ै हनुमान चालीसा। होय सिद्धि साखी गौरीसा॥\"},\r\n    {\"verse_no\":42,\"text\":\"तुलसीदास सदा हरि चेरा। कीजै नाथ हृदय महँ डेरा॥\"}\r\n]', NULL, NULL, 0, 0, 0, '2026-03-27 14:07:57', '2026-03-27 14:07:57'),
(2, 'Shri Ram Chalisa', 'Rama', 'Hindi', 40, 'Goswami Tulsidas', 'श्री राम चालीसा गोस्वामी तुलसीदास जी द्वारा रचित 40 चौपाइयों का स्तोत्र है। यह भगवान राम को समर्पित है और रामायण का सार है।', 'श्री राम चालीसा का पाठ जीवन में धर्म, अर्थ, काम और मोक्ष की प्राप्ति कराता है। यह सभी प्रकार के कष्टों से मुक्ति दिलाता है।', 'नियमित पाठ से मानसिक शांति, आत्मविश्वास, सभी कार्यों में सफलता, शत्रुओं पर विजय और मोक्ष की प्राप्ति होती है।', 'प्रातःकाल स्नान के बाद', 'गुरुवार, रामनवमी', '[\r\n    {\"verse_no\":1,\"text\":\"श्री गुरु चरन सरोज रज, निज मन मुकुर सुधारि। बरनउँ रघुबर बिमल जसु, जो दायक फल चारि॥\"},\r\n    {\"verse_no\":2,\"text\":\"बुद्धिहीन तनु जानिके, सुमिरौं पवन-कुमार। बल बुद्धि विद्या देहु मोहिं, हरहु कलेस बिकार॥\"},\r\n    {\"verse_no\":3,\"text\":\"जय हनुमान ज्ञान गुन सागर। जय कपीस तिहुँ लोक उजागर॥\"},\r\n    {\"verse_no\":4,\"text\":\"रामदूत अतुलित बल धामा। अंजनि-पुत्र पवनसुत नामा॥\"},\r\n    {\"verse_no\":5,\"text\":\"महाबीर बिक्रम बजरंगी। कुमति निवार सुमति के संगी॥\"},\r\n    {\"verse_no\":6,\"text\":\"कंचन बरन बिराज सुबेसा। कानन कुंडल कुंचित केसा॥\"},\r\n    {\"verse_no\":7,\"text\":\"हाथ बज्र औ ध्वजा बिराजै। काँधे मूँज जनेऊ साजै॥\"},\r\n    {\"verse_no\":8,\"text\":\"शंकर सुवन केसरी नंदन। तेज प्रताप महा जग बंदन॥\"},\r\n    {\"verse_no\":9,\"text\":\"विद्यावान गुनी अति चातुर। राम काज करिबे को आतुर॥\"},\r\n    {\"verse_no\":10,\"text\":\"प्रभु चरित्र सुनिबे को रसिया। राम लखन सीता मन बसिया॥\"},\r\n    {\"verse_no\":11,\"text\":\"सूक्ष्म रूप धरि सियहिं दिखावा। बिकट रूप धरि लंक जरावा॥\"},\r\n    {\"verse_no\":12,\"text\":\"भीम रूप धरि असुर संहारे। रामचंद्र के काज सवारे॥\"},\r\n    {\"verse_no\":13,\"text\":\"लाय सजीवन लखन जियाये। श्रीरघुबीर हरषि उर लाये॥\"},\r\n    {\"verse_no\":14,\"text\":\"रघुपति कीन्ही बहुत बड़ाई। तुम मम प्रिय भरतहि सम भाई॥\"},\r\n    {\"verse_no\":15,\"text\":\"सहस बदन तुम्हरो जस गावैं। अस कहि श्रीपति कंठ लगावैं॥\"},\r\n    {\"verse_no\":16,\"text\":\"सनकादिक ब्रह्मादि मुनीसा। नारद सारद सहित अहीसा॥\"},\r\n    {\"verse_no\":17,\"text\":\"जम कुबेर दिगपाल जहाँ ते। कबि कोबिद कहि सके कहाँ ते॥\"},\r\n    {\"verse_no\":18,\"text\":\"तुम उपकार सुग्रीवहिं कीन्हा। राम मिलाय राज पद दीन्हा॥\"},\r\n    {\"verse_no\":19,\"text\":\"तुम्हरो मंत्र बिभीषन माना। लंकेश्वर भए सब जग जाना॥\"},\r\n    {\"verse_no\":20,\"text\":\"जुग सहस्र जोजन पर भानू। लील्यो ताहि मधुर फल जानू॥\"},\r\n    {\"verse_no\":21,\"text\":\"प्रभु मुद्रिका मेलि मुख माहीं। जलधि लाँघि गये अचरज नाहीं॥\"},\r\n    {\"verse_no\":22,\"text\":\"दुर्गम काज जगत के जेते। सुगम अनुग्रह तुम्हरे तेते॥\"},\r\n    {\"verse_no\":23,\"text\":\"राम दुआरे तुम रखवारे। होत न आज्ञा बिनु पैसारे॥\"},\r\n    {\"verse_no\":24,\"text\":\"सब सुख लहै तुम्हारी सरना। तुम रक्षक काहू को डर ना॥\"},\r\n    {\"verse_no\":25,\"text\":\"आपन तेज सम्हारो आपै। तीनों लोक हाँक तें काँपै॥\"},\r\n    {\"verse_no\":26,\"text\":\"भूत पिशाच निकट नहिं आवै। महावीर जब नाम सुनावै॥\"},\r\n    {\"verse_no\":27,\"text\":\"नासै रोग हरै सब पीरा। जपत निरंतर हनुमत बीरा॥\"},\r\n    {\"verse_no\":28,\"text\":\"संकट तें हनुमान छुड़ावै। मन क्रम बचन ध्यान जो लावै॥\"},\r\n    {\"verse_no\":29,\"text\":\"सब पर राम तपस्वी राजा। तिनके काज सकल तुम साजा॥\"},\r\n    {\"verse_no\":30,\"text\":\"और मनोरथ जो कोई लावै। सोइ अमित जीवन फल पावै॥\"},\r\n    {\"verse_no\":31,\"text\":\"चारों जुग परताप तुम्हारा। है परसिद्ध जगत उजियारा॥\"},\r\n    {\"verse_no\":32,\"text\":\"साधु संत के तुम रखवारे। असुर निकंदन राम दुलारे॥\"},\r\n    {\"verse_no\":33,\"text\":\"अष्ट सिद्धि नौ निधि के दाता। अस बर दीन जानकी माता॥\"},\r\n    {\"verse_no\":34,\"text\":\"राम रसायन तुम्हरे पासा। सदा रहो रघुपति के दासा॥\"},\r\n    {\"verse_no\":35,\"text\":\"तुम्हरे भजन राम को पावै। जनम जनम के दुख बिसरावै॥\"},\r\n    {\"verse_no\":36,\"text\":\"अंत काल रघुबर पुर जाई। जहाँ जन्म हरि भक्त कहाई॥\"},\r\n    {\"verse_no\":37,\"text\":\"और देवता चित्त न धरई। हनुमत सेइ सर्व सुख करई॥\"},\r\n    {\"verse_no\":38,\"text\":\"संकट कटै मिटै सब पीरा। जो सुमिरै हनुमत बलबीरा॥\"},\r\n    {\"verse_no\":39,\"text\":\"जय जय जय हनुमान गोसाईं। कृपा करहु गुरुदेव की नाईं॥\"},\r\n    {\"verse_no\":40,\"text\":\"जो सत बार पाठ कर कोई। छूटहि बंदि महा सुख होई॥\"}\r\n]', NULL, NULL, 0, 0, 0, '2026-03-27 14:07:57', '2026-03-27 14:07:57'),
(3, 'Shri Shiva Chalisa', 'Shiva', 'Hindi', 40, 'Traditional', 'श्री शिव चालीसा भगवान शिव को समर्पित 40 चौपाइयों का स्तोत्र है। यह शिव भक्तों द्वारा सबसे अधिक पढ़ा जाने वाला स्तोत्र है।', 'शिव चालीसा का पाठ भगवान शिव की कृपा प्राप्ति, मोक्ष और सभी मनोकामनाओं की पूर्ति के लिए किया जाता है।', 'नियमित पाठ से मानसिक शांति, रोगों से मुक्ति, आयु में वृद्धि, मृत्यु के भय से मुक्ति और मोक्ष की प्राप्ति होती है।', 'प्रातःकाल स्नान के बाद या सायंकाल में', 'सोमवार, शिवरात्रि', '[\r\n    {\"verse_no\":1,\"text\":\"नमामि ईशमीशान निर्वाणरूपं, विभुं व्यापकं ब्रह्मवेदस्वरूपम्। निजं निर्गुणं निर्विकल्पं निरीहं, चिदाकाशमाकाशवासं भजेऽहम्॥\"},\r\n    {\"verse_no\":2,\"text\":\"नमो नमो जय शंकर भोले, सुख सागर सदा सुख दाता। दुखियन के दुख दूर करत हो, भक्तन के सब संकट हरता॥\"},\r\n    {\"verse_no\":3,\"text\":\"जय गिरिजा पति दीन दयाला, सदा करत सन्तन प्रतिपाला। भाल चन्द्र मस्तक शोभिता, गले कंठ माला विराजिता॥\"},\r\n    {\"verse_no\":4,\"text\":\"त्रिनयन धारी शूल पाणी, धरत सदा अभय को बानी। भस्म लपटित अंग भवानी, जटा मुकुट शिर सोहत भानी॥\"},\r\n    {\"verse_no\":5,\"text\":\"गंगा धारा धरत उर आनन, डमरू ध्वनि सुनत सुर जन मन। कैलाश पर्वत पर वासी, भक्तन के सदा सुख राशी॥\"},\r\n    {\"verse_no\":6,\"text\":\"वृषभ वाहन शंकर प्यारे, भक्तन के सदा सहायक हारे। नन्दी भृंगी और गण साथी, करहि सदा भक्तन की हाथी॥\"},\r\n    {\"verse_no\":7,\"text\":\"शिव रूपी यह जगत सवेरा, शिव बिना नहीं कहूं अंधेरा। शिव ही जल थल मेघ गगन हैं, शिव ही अग्नि पवन सम पन हैं॥\"},\r\n    {\"verse_no\":8,\"text\":\"शिव ही सोम सूर्य नक्षत्र, शिव ही व्याप्त यह विश्व पात्र। शिव ही ब्रह्मा विष्णु हरि रूप, शिव ही देव दनुज अनूप॥\"},\r\n    {\"verse_no\":9,\"text\":\"शिव ही बाल ब्रह्मचारी, शिव ही गृहस्थ अवतारी। शिव ही वानप्रथी संन्यासी, शिव ही योगी योगी रासी॥\"},\r\n    {\"verse_no\":10,\"text\":\"शिव ही ज्ञानी शिव ही ध्यानी, शिव ही स्वामी शिव ही रानी। शिव ही सृष्टि शिव ही संहार, शिव ही पालन करन विकार॥\"},\r\n    {\"verse_no\":11,\"text\":\"शिव ही निर्गुण शिव ही सगुण, शिव ही सकल जगत का गुण। शिव ही शक्ति शिव ही शिवा, शिव ही व्याप्त सब ठौर सदा॥\"},\r\n    {\"verse_no\":12,\"text\":\"शिव ही सत शिव ही रज तम, शिव ही वेद पुराण सब गम। शिव ही ब्रह्म शिव ही आत्मा, शिव ही परम पद है प्राता॥\"},\r\n    {\"verse_no\":13,\"text\":\"शिव के नाम जपत जग जन सब, शिव भजन बिनु होत न लब। शिव सुमिरन से मिटे जंजाल, शिव भजन से मिले निधान॥\"},\r\n    {\"verse_no\":14,\"text\":\"शिव की भक्ति सदा सुख दाई, शिव का नाम है सबसे भाई। शिव का नाम सदा मन राखो, सब विपदाओं से तुरत निकासो॥\"},\r\n    {\"verse_no\":15,\"text\":\"जय शिव शंकर भोले भंडारी, जय चन्द्रशेखर त्रिशूल धारी। जय गंगाधर जय जटाधारी, जय भूतनाथ जय भूत हारी॥\"},\r\n    {\"verse_no\":16,\"text\":\"जय जय शंकर जय जय भोले, जय सदाशिव पार्वती बोले। जय जय जय कैलाश के वासी, जय जय जय भोलेनाथ दासी॥\"},\r\n    {\"verse_no\":17,\"text\":\"जय जय शिव शम्भु महादेवा, जय जय गौरी प्राण प्रिय देवा। जय जय जय रुद्र अवतारी, जय जय जय शूल धारी भारी॥\"},\r\n    {\"verse_no\":18,\"text\":\"जय जय जय त्रिपुरारि सुजाना, जय जय जय भक्तन के प्राणा। जय जय जय विश्वनाथ भगवाना, जय जय जय भवभय नाशन हाना॥\"},\r\n    {\"verse_no\":19,\"text\":\"जय जय जय चन्द्रशेखर नाथा, जय जय जय पार्वती का नाथा। जय जय जय कैलाश निवासी, जय जय जय भोले सुख रासी॥\"},\r\n    {\"verse_no\":20,\"text\":\"जय जय जय पशुपति दयाला, जय जय जय भक्तन प्रतिपाला। जय जय जय दीनन के दाता, जय जय जय दुखियन के माता॥\"},\r\n    {\"verse_no\":21,\"text\":\"शिव चालीसा जो कोई गावे, सो सुख सम्पत्ति सब पावे। शिव का ध्यान जो नित नर करहीं, अवश्य शिव लोक परम पद लहहीं॥\"},\r\n    {\"verse_no\":22,\"text\":\"जो यह चालीसा शिव भक्त गावे, उसके सब दुख दूर हो जावे। शिव चालीसा जो नित पढ़िये, सब सुख भोग मोक्ष पद लहिये॥\"},\r\n    {\"verse_no\":23,\"text\":\"जो यह चालीसा पढ़े चित लाई, ताकी सदा शिव रक्षा करहीं। जो शिव भक्त यह चालीसा पढ़े, सब विघ्न दूर हो जाये घटे॥\"},\r\n    {\"verse_no\":24,\"text\":\"शिव चालीसा के पढ़ने मात्र, शिव भक्त होयें सब सुख पात्र। शिव चालीसा पढ़े नियम से, तो शिव कृपा उस पर हो सब से॥\"},\r\n    {\"verse_no\":25,\"text\":\"इति श्री शिव चालीसा सम्पूर्ण। जो पढ़े भक्ति सहित, ताके सब दुख पूर्ण। शिव भजन से मिले सुख, शिव भजन से मिले ज्ञान। शिव भजन से मिले मोक्ष, शिव भजन से मिले ध्यान॥\"}\r\n]', NULL, NULL, 0, 0, 0, '2026-03-27 14:07:57', '2026-03-27 14:07:57'),
(4, 'Shri Durga Chalisa', 'Durga', 'Hindi', 40, 'Traditional', 'श्री दुर्गा चालीसा माँ दुर्गा को समर्पित 40 चौपाइयों का स्तोत्र है। यह नवरात्रि में विशेष रूप से पढ़ा जाता है।', 'दुर्गा चालीसा का पाठ सभी प्रकार के संकटों से मुक्ति दिलाने वाला और शक्ति प्रदान करने वाला माना जाता है।', 'नियमित पाठ से शत्रुओं पर विजय, रोगों से मुक्ति, सभी प्रकार के भय का नाश और सुख-समृद्धि की प्राप्ति होती है।', 'प्रातःकाल स्नान के बाद या नवरात्रि में', 'मंगलवार, शुक्रवार, नवरात्रि', '[\r\n    {\"verse_no\":1,\"text\":\"नमो नमो दुर्गे सुख करनी, नमो नमो अम्बे दुख हरनी। निराकार है ज्योति तुम्हारी, तिहूं लोक फैली उजियारी॥\"},\r\n    {\"verse_no\":2,\"text\":\"शशि ललाट मुख महाविशाला, नेत्र लाल भृकुटी विकराला। रूप मातु को अधिक सुहावे, दरश करत जन अति सुख पावे॥\"},\r\n    {\"verse_no\":3,\"text\":\"तुम संसार शक्ति लै कीना, पालन हेतु अन्न धन दीना। अन्नपूर्णा हुई जग पाला, तुम ही आदि सुन्दरी बाला॥\"},\r\n    {\"verse_no\":4,\"text\":\"प्रलय काल सब नाशन हारी, तुम गौरी शिव शंकर प्यारी। शिव योगी तुम्हरे गुण गावें, ब्रह्मा विष्णु तुम्हें ध्यान लगावें॥\"},\r\n    {\"verse_no\":5,\"text\":\"रूप सरस्वती को तुम धारा, दे सुबुद्धि ऋषि मुनि उबारा। धरयो रूप नरसिंह को अम्बा, प्रगट भई फाड़कर खम्बा॥\"},\r\n    {\"verse_no\":6,\"text\":\"रक्षा करि प्रह्लाद बचायो, हिरण्याक्ष को स्वर्ग पठायो। लक्ष्मी रूप धरो जग माहीं, ब्रह्मा विष्णु प्रसन्न रहाहीं॥\"},\r\n    {\"verse_no\":7,\"text\":\"सावित्री रूप धरा माता, पापिण को दर्श भी न आता। सुर नर मुनि जन सेवा करते, संकट सब दूर होकर टरते॥\"},\r\n    {\"verse_no\":8,\"text\":\"रूप शक्ति का धारण कीनो, दुष्ट दलन संहारण लीनो। सहाय देव बना गुण अम्बा, देवन दुख दैत्य दल दम्भा॥\"},\r\n    {\"verse_no\":9,\"text\":\"शुम्भ निशुम्भ दैत्य असुर हरे, रक्तबीज संहारण डरे। महिषासुर से युद्ध रचायो, कालिका रूप सभय दिखलायो॥\"},\r\n    {\"verse_no\":10,\"text\":\"दुर्गम रूप धरा कपालिनी, असुर सेना पर घोर प्रचण्डिनी। भवानी ने दैत्य संहारा, देवतन हुलसि हर्ष पुकारा॥\"},\r\n    {\"verse_no\":11,\"text\":\"जय अम्बे जय जगदम्बे माता, तुम सब की हो रक्षा दाता। भक्तन के दुख दूर करो माता, सुख सम्पत्ति का घर भर दो माता॥\"},\r\n    {\"verse_no\":12,\"text\":\"जो मनसा बांचा फल पावे, दर्शन तुम्हारा मन भावे। दुर्गा चालीसा जो कोई गावे, सब सुख भोग परम पद पावे॥\"}\r\n]', NULL, NULL, 0, 0, 0, '2026-03-27 14:11:49', '2026-03-27 14:11:49'),
(5, 'Shri Lakshmi Chalisa', 'Lakshmi', 'Hindi', 40, 'Traditional', 'श्री लक्ष्मी चालीसा माँ लक्ष्मी को समर्पित 40 चौपाइयों का स्तोत्र है। यह धन, समृद्धि और ऐश्वर्य की प्राप्ति के लिए पढ़ा जाता है।', 'लक्ष्मी चालीसा का पाठ धन-धान्य, सुख-समृद्धि और वैभव की प्राप्ति के लिए किया जाता है।', 'नियमित पाठ से आर्थिक समृद्धि, घर में सुख-शांति, व्यापार में सफलता और सभी मनोकामनाओं की पूर्ति होती है।', 'प्रातःकाल या सायंकाल में', 'शुक्रवार, दीपावली', '[\r\n    {\"verse_no\":1,\"text\":\"जय लक्ष्मी माता, जय जय लक्ष्मी माता। तुमको निशिदिन सेवत, हरि विष्णु विधाता॥\"},\r\n    {\"verse_no\":2,\"text\":\"उमा रमा ब्रह्माणी, तुम ही जग माता। सूर्य चन्द्रमा ध्यावत, नारद ऋषि गाता॥\"},\r\n    {\"verse_no\":3,\"text\":\"दुर्गा रूप निरंजनी, सुख सम्पत्ति दाता। जो कोई तुमको ध्यावत, ऋद्धि-सिद्धि पाता॥\"},\r\n    {\"verse_no\":4,\"text\":\"तुम पाताल निवासिनी, तुम ही शुभ दाता। कर्म प्रभाव प्रकाशिनी, भवनिधि की त्राता॥\"},\r\n    {\"verse_no\":5,\"text\":\"ज्ञान प्रकाश विभावरी, मोहन रूप धारी। महिमा अति अपार है, कही नहीं बन आरी॥\"},\r\n    {\"verse_no\":6,\"text\":\"जय लक्ष्मी माता, जय जय लक्ष्मी माता। तुमको निशिदिन सेवत, हरि विष्णु विधाता॥\"},\r\n    {\"verse_no\":7,\"text\":\"लक्ष्मी चालीसा जो कोई, नित्य पढ़े चित लाई। सब सुख भोग सम्पत्ति, सुख सागर में जाई॥\"},\r\n    {\"verse_no\":8,\"text\":\"पुत्र मित्र सुख नाती, सब सुख ऐश्वर्य पावे। श्री लक्ष्मी चालीसा पढ़त, सब विपदा टर जावे॥\"}\r\n]', NULL, NULL, 0, 0, 0, '2026-03-27 14:11:49', '2026-03-27 14:11:49'),
(6, 'Shri Ganesh Chalisa', 'Ganesh', 'Hindi', 40, 'Traditional', 'श्री गणेश चालीसा भगवान गणेश को समर्पित 40 चौपाइयों का स्तोत्र है। यह किसी भी शुभ कार्य के आरंभ में पढ़ा जाता है।', 'गणेश चालीसा का पाठ विघ्नों का नाश करने वाला, बुद्धि और विवेक प्रदान करने वाला माना जाता है।', 'नियमित पाठ से सभी कार्यों में सफलता, विघ्नों का नाश, बुद्धि और विवेक की वृद्धि होती है।', 'प्रातःकाल स्नान के बाद', 'मंगलवार, बुधवार, गणेश चतुर्थी', '[\r\n    {\"verse_no\":1,\"text\":\"जय गणपति सद्गुण सदन, कविवर बदन कृपाल। विघ्न हरण मंगल करण, जय जय गिरिजालाल॥\"},\r\n    {\"verse_no\":2,\"text\":\"एक दंत बहु चित्र विचित्र, चार भुजा धारी। माथे सिंदूर सोहे, मूषक वाहन प्यारी॥\"},\r\n    {\"verse_no\":3,\"text\":\"सिंदूर लाल चढ़ायो, अच्छा गजमुख को। देखत ही रंग प्यारा, सब जन मन सुख को॥\"},\r\n    {\"verse_no\":4,\"text\":\"लड्डू का भोग लगायो, मोदक का भोग। पान सुपारी चढ़ायो, लायो हाथी के सोग॥\"},\r\n    {\"verse_no\":5,\"text\":\"मूषक वाहन राजे, खड़े हैं द्वारा। लंबोदर गणपति, सबका करें सहारा॥\"},\r\n    {\"verse_no\":6,\"text\":\"जय गणेश जय गणेश, जय गणेश देवा। माता जाकी पार्वती, पिता महादेवा॥\"}\r\n]', NULL, NULL, 0, 0, 0, '2026-03-27 14:11:49', '2026-03-27 14:11:49'),
(7, 'Shri Krishna Chalisa', 'Krishna', 'Hindi', 40, 'Traditional', 'श्री कृष्ण चालीसा भगवान श्रीकृष्ण को समर्पित ४० चौपाइयों का परम मधुर स्तोत्र है।', 'भगवान श्रीकृष्ण की कृपा, सन्तान प्राप्ति, गृहक्लेश निवारण और भक्ति-रस की प्राप्ति हेतु प्रसिद्ध।', 'पारिवारिक सौहार्द, सुख-समृद्धि, संकट-मुक्ति और अंतःकरण की पवित्रता।', 'प्रातःकाल अथवा सन्ध्याकाल', 'बुधवार, गुरुवार, जन्माष्टमी', '[{\"verse_no\":1,\"text\":\"दोहा: बंशी शोभित कर मधुर, नील जलद तन श्याम। अरुण अधर जनु बिम्बफल, नयन कमल अभिराम॥\"},{\"verse_no\":2,\"text\":\"पूर्ण इन्दु अरविन्द मुख, पीताम्बर शुभ साज। जय मनमोहन मदन छवि, कृष्णचन्द्र महाराज॥\"},{\"verse_no\":3,\"text\":\"चौपाई: जय यदुनन्दन जय जगवन्दन। जय वसुदेव देवकी नन्दन॥\"},{\"verse_no\":4,\"text\":\"जय यदुराज कंस अरि हन्ता। आनन्द घन सब भक्तन त्राता॥\"},{\"verse_no\":5,\"text\":\"भुवन चारु कर मुरली सोहै। सुर मुनि नर नागिन मन मोहै॥\"},{\"verse_no\":6,\"text\":\"मस्तक मुकुट कुण्डल कर कान। निरखि रूप मुनि तजत ध्यान॥\"},{\"verse_no\":7,\"text\":\"नटवर वेश मनोहर सोहै। देखत कोटि काम मन मोहै॥\"},{\"verse_no\":8,\"text\":\"कंसहि मारि असुर दल संहारा। उग्रसेन को राज सम्हारा॥\"},{\"verse_no\":9,\"text\":\"पाण्डव के तुम बने सहाई। अर्जुन को गीता बतलाई॥\"},{\"verse_no\":10,\"text\":\"जो यह पढ़े कृष्ण चालीसा। होय सिद्ध साक्षी जगदीशा॥\"}]', NULL, NULL, 0, 0, 0, '2026-10-24 18:45:53', '2026-10-24 18:46:49'),
(8, 'Shri Shani Chalisa', 'Shani', 'Hindi', 40, 'Traditional', 'श्री शनि चालीसा न्याय के देवता सूर्यपुत्र भगवान शनिदेव को समर्पित ४० चौपाइयों का स्तोत्र है।', 'शनि की साढ़ेसाती, ढैय्या एवं महादशा के कुप्रभावों को शांत कर शुभ फल प्रदान करता है।', 'अन्याय और संकटों से रक्षा, मानसिक संताप की शान्ति, रोगमुक्ति और कार्य में सफलता।', 'सायंकाल', 'शनिवार, शनि जयन्ती, अमावस्या', '[{\"verse_no\":1,\"text\":\"दोहा: जय गणेश गिरिजा सुवन, मंगल करण कृपाल। दीनन के दुख दूर करि, कीजै नाथ निहाल॥\"},{\"verse_no\":2,\"text\":\"जय जय श्री शनिदेव प्रभु, सुनहु विनय महाराज। कृपा करहु हे रवि सुवन, राखहु जन की लाज॥\"},{\"verse_no\":3,\"text\":\"चौपाई: जयति जयति शनिदेव दयाला। करत सदा भक्तन प्रतिपाला॥\"},{\"verse_no\":4,\"text\":\"चारि भुजा तनु श्याम विराहै। माथे रतन मुकुट छवि छाजै॥\"},{\"verse_no\":5,\"text\":\"परम विशाल मनोहर भाला। टेढ़ी दृष्टि भृकुटि विकराला॥\"},{\"verse_no\":6,\"text\":\"कुण्डल श्रवण चमाचम चमके। हिय माल मुक्तन मनि दमके॥\"},{\"verse_no\":7,\"text\":\"कर में गदा त्रिशूल कुठारा। पल बिच करैं अरिहिं संहारा॥\"},{\"verse_no\":8,\"text\":\"पिंगल मन्द रौद्र यम नामा। संवर्तक शुभ शनि सुख धामा॥\"},{\"verse_no\":9,\"text\":\"शनि चालीसा जो नित गावै। जाहि विपति सब दूर नसावै॥\"},{\"verse_no\":10,\"text\":\"दोहा: पाठ शनैश्चर देव को, कीन्हों विमल तैयार। करत पाठ चालीस दिन, हो भवसागर पार॥\"}]', NULL, NULL, 0, 0, 0, '2026-10-24 18:45:53', '2026-10-24 18:46:49'),
(9, 'Shri Saraswati Chalisa', 'Saraswati', 'Hindi', 40, 'Traditional', 'विद्या, बुद्धि, वाणी और संगीत की अधिष्ठात्री भगवती माँ सरस्वती की चालीसा।', 'अध्ययन में सफलता, एकाग्रता, अज्ञान-विनाश और वाक-सिद्धि हेतु अत्यंत फलदायी।', 'स्मृति शक्ति में वृद्धि, बौद्धिक विकास, परीक्षा में सफलता और कला-संगीत में निपुणता।', 'प्रातःकाल', 'बुधवार, गुरुवार, वसंत पंचमी', '[{\"verse_no\":1,\"text\":\"दोहा: जनक जननि पद कमल रज, निज मस्तक पर धारि। बन्दौं मातु सरस्वती, बुद्धि बल दे दातारि॥\"},{\"verse_no\":2,\"text\":\"पूर्ण जगत में व्याप्त तव, महिमा अमित अनन्तु। दुष्टजनों के पाप को, मातु सदा तुम हन्तु॥\"},{\"verse_no\":3,\"text\":\"चौपाई: जय श्री सकल बुद्धि बलरासी। जय सर्वज्ञ अमर अविनाशी॥\"},{\"verse_no\":4,\"text\":\"जय जय जय वीणाकर धारी। करती सदा सुहंस सवारी॥\"},{\"verse_no\":5,\"text\":\"रूप चतुर्भुज धारी माता। सकल विश्व अन्दर विख्याता॥\"},{\"verse_no\":6,\"text\":\"जग में पाप बुद्धि जो उपजे। माता तुरन्त हरत है लज के॥\"},{\"verse_no\":7,\"text\":\"विद्या बुद्धि देहु मोहि माता। तुम ही जग की भाग्य विधाता॥\"},{\"verse_no\":8,\"text\":\"जो यह पाठ करे मन लाई। ताके कष्ट दूर हो जाई॥\"}]', NULL, NULL, 0, 0, 0, '2026-10-24 18:45:53', '2026-10-24 18:46:49'),
(10, 'Shri Surya Chalisa', 'Surya', 'Hindi', 40, 'Traditional', 'प्रत्यक्ष देवता भगवान सूर्य नारायण को समर्पित ४० चौपाइयों का पावन स्तोत्र।', 'आरोग्य, दीर्घायु, आत्मबल और तेजस्विता की प्राप्ति हेतु नित्य पाठ योग्य।', 'नेत्र ज्योति, शारीरिक ओज, हृदय रोग निवारण और मान-सम्मान में वृद्धि।', 'प्रातःकाल सूर्योदय के समय', 'रविवार, सप्तमी', '[{\"verse_no\":1,\"text\":\"दोहा: कनक बदन कुण्डल मकर, मुकुट शीश पर सोह। करुणामय दीपक प्रभा, जग को डारत मोह॥\"},{\"verse_no\":2,\"text\":\"चौपाई: जय जय जय भास्कर अविनाशी। त्रिभुवन की हरते सब हाँसी॥\"},{\"verse_no\":3,\"text\":\"सप्त अश्व रथ पर असवारा। छिन महं करत जगत उजियारा॥\"},{\"verse_no\":4,\"text\":\"किरण मनोहर छवि सुखदायी। देखि छिनहिं सब विपति नसाई॥\"},{\"verse_no\":5,\"text\":\"अंग अंग पर कान्ति अनूपा। त्रिभुवन वन्दित दिव्य स्वरूपा॥\"},{\"verse_no\":6,\"text\":\"सूर्य चालीसा जो नित ध्यावै। सुख सम्पत्ति आरोग्य सुपावै॥\"}]', NULL, NULL, 0, 0, 0, '2026-10-24 18:45:53', '2026-10-24 18:46:49'),
(11, 'Shri Bhairav Chalisa', 'Shiva', 'Hindi', 40, 'Traditional', 'भगवान कालभैरव एवं बटुक भैरव को समर्पित ४० चौपाइयों का रक्षा स्तोत्र।', 'भूत-प्रेत, तंत्र-बाधा, शत्रु भय और आकस्मिक संकटों का समूल नाश करने वाला।', 'अखंड सुरक्षा, अदम्य साहस, ग्रह शांति और कार्यों में आने वाली रुकावटों का निवारण।', 'सायंकाल अथवा रात्रिकाल', 'रविवार, मंगलवार, कालाष्टमी', '[{\"verse_no\":1,\"text\":\"दोहा: श्री गणपति गुरु गौरिपद, प्रेम सहित धरि माथ। भैरव चालीसा कहत, कृपा करहु यदुनाथ॥\"},{\"verse_no\":2,\"text\":\"चौपाई: जय जय भैरव बटुक अनूपा। संकट हरण सुहवन स्वरूपा॥\"},{\"verse_no\":3,\"text\":\"झांझ झमीका बाजत आगे। कांपत असुर देखि भय जागे॥\"},{\"verse_no\":4,\"text\":\"कर त्रिशूल डमरू विराजै। नाद गगन पातालहिं गाजै॥\"},{\"verse_no\":5,\"text\":\"काल भैरव जो ध्यावै मन में। पावै सुख सम्पत्ति हर छिन में॥\"}]', NULL, NULL, 0, 0, 0, '2026-10-24 18:45:53', '2026-10-24 18:46:49');
INSERT INTO `festival_aartis` (`id`, `aarti_name`, `deity_name`, `festival`, `festival_category`, `month`, `tithi`, `day`, `occasion`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `chorus`, `significance`, `instructions`, `audio_url`, `video_url`, `is_premium`, `views_count`, `likes_count`, `created_at`) VALUES
(1, 'Sukhakarta Dukhaharta (Ganesh Chaturthi)', 'Ganesh', 'Ganesh Chaturthi', 'Hindu', 'Bhadrapada (Aug-Sep)', 'Shukla Chaturthi', NULL, 'गणेश जन्मोत्सव, 10 दिवसीय महोत्सव', 'सुखकर्ता दुःखहर्ता वार्ता विघ्नाची। नुरवे पुरवी प्रेमे कृपा जयाची॥\r\nसर्वांगी सुंदर उटी शेंदूराची। जय देव जय देव जय मंगलमूर्ती॥\r\nध्यानी आले मनामनी देहबुद्धी विसरा। मुखी तुझे नाम अक्षर तीनचि असरा॥\r\nदातारा दीनवरा तू सर्वां पालनकर्ता। जय देव जय देव जय मंगलमूर्ती॥\r\nआरती ओवाळू तुजला मोरया। म्हणोनिया आरती गातो मी आजा॥\r\nदास तुझा मी तुजला शरण माझा। जय देव जय देव जय मंगलमूर्ती॥', 'Sukhakarta Dukhharta Varta Vighnachi Nurave Purave Preme Kripa Jayachi Sarvangi Sundar Uti Shendurachi Jai Dev Jai Dev Jai Mangalmurti Dhyani Aale Manamani Dehabuddhi Visara Mukhi Tujhe Naam Akshar Tinchi Asara Datara Dinavara Tu Sarvan Palankarta Jai Dev Jai Dev Jai Mangalmurti Aarti Ovalu Tujala Moraya Mhononiya Aarti Gato Mi Aaja Das Tuza Mi Tujala Sharan Maza Jai Dev Jai Dev Jai Mangalmurti', 'सुख देने वाले, दुःख हरने वाले, विघ्नों की वार्ता। नुरवे (कमी) पूरी करते, प्रेम से कृपा जिनकी। सर्वांग सुंदर, शेंदूर की उटी। जय देव, जय देव, जय मंगलमूर्ति। ध्यान में आते, मन में देहबुद्धि भूल जाओ। मुख में तेरा नाम तीन अक्षर (ॐ गं) ही असर करता है। दातार, दीनवर, तू सबका पालन करता है। आरती ओवाळूं तुझे मोरया। कहकर आरती गाता हूं मैं आज। दास तेरा मैं, तेरी शरण मेरी।', 'Giver of happiness, remover of sorrows, remover of obstacles. He fulfills, with love and grace. Beautiful in every limb, adorned with vermillion. Victory to the Lord, victory to the auspicious form. When you come in meditation, forget the consciousness of the body. Your three-syllable name is effective. Giver to the poor, you sustain all. I wave the aarti before you, O Moraya. Singing this aarti today, I am your servant, I take refuge in you.', 'सुखकर्ता दुःखहर्ता वार्ता विघ्नाची', 'गणेश चतुर्थी के दिन गणेश जी की मूर्ति स्थापना कर आरती गाई जाती है। यह आरती संत समर्थ रामदास द्वारा रचित है।', 'शेंदूर, दुर्वा, मोदक, फुले अर्पण करें। आरती के बाद प्रसाद वितरण करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(2, 'Jai Ganesh Jai Ganesh Deva (Ganesh Chaturthi)', 'Ganesh', 'Ganesh Chaturthi', 'Hindu', 'Bhadrapada (Aug-Sep)', 'Shukla Chaturthi', NULL, 'गणेश जन्मोत्सव, 10 दिवसीय महोत्सव', 'जय गणेश जय गणेश जय गणेश देवा। माता जाकी पार्वती पिता महादेवा॥\r\nएक दंत दयावंत चार भुजा धारी। माथे सिंदूर सोहे मूसे की सवारी॥\r\nअंधन को आंख देते कोढ़न को काया। बांझन को पुत्र देते निर्धन को माया॥\r\nसूर्य शाम शरण आए फल पाए। दीनन की लाज रखो शंभु सुत वारी॥\r\nजय गणेश जय गणेश जय गणेश देवा॥', 'Jai Ganesh Jai Ganesh Jai Ganesh Deva Mata Jaki Parvati Pita Mahadeva Ek Dant Dayavant Char Bhuja Dhari Mathe Sindur Sohe Muse Ki Savari Andhan Ko Ankh Dete Kodhan Ko Kaya Banjhan Ko Putra Dete Nirdhan Ko Maya Surya Sham Sharan Aaye Fal Pave Dinan Ki Laj Rakho Shambhu Sut Vari Jai Ganesh Jai Ganesh Jai Ganesh Deva', 'जय गणेश जय गणेश जय गणेश देवा। माता पार्वती और पिता महादेव हैं। एक दंत, दयावंत, चार भुजाधारी। माथे पर सिंदूर सुशोभित, मूषक वाहन। अंधों को आंख देते, कोढ़ियों को स्वस्थ शरीर। बांझों को पुत्र देते, निर्धनों को धन। सूर्य और शाम को शरण आने से फल मिलता है। हे शंभुपुत्र, दीनों की लाज रखो।', 'Victory to Ganesh, victory to Ganesh, victory to Lord Ganesh. Mother Parvati and Father Mahadev. One-tusked, compassionate, four-armed. Vermillion adorns the forehead, mouse is the vehicle. You give sight to the blind, health to lepers. You grant children to the barren, wealth to the poor. Coming to your shelter at sunrise and sunset, one reaps the fruits. O son of Shambhu, protect the dignity of the humble.', 'जय गणेश जय गणेश जय गणेश देवा', 'गणेश चतुर्थी पर यह आरती प्रमुखता से गाई जाती है। यह सबसे लोकप्रिय हिंदी गणेश आरती है।', 'शेंदूर, दुर्वा, मोदक, फुले अर्पण करें। आरती के बाद गणेश चालीसा का पाठ करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(3, 'Morya Re Morya (Ganesh Visarjan)', 'Ganesh', 'Ganesh Chaturthi', 'Hindu', 'Bhadrapada (Aug-Sep)', 'Anant Chaturdashi', NULL, 'गणेश विसर्जन, 10वें दिन का महोत्सव', 'मोरया रे मोरया, गणपती मोरया। पुढच्या वर्षी लवकर या, गणपती मोरया॥\r\nएका दंता वंदू तुला, गणपती मोरया। शेंदूर लाल चढवितो, गणपती मोरया॥\r\nमोदकांचा भोग लागे, गणपती मोरया। आरती ओवाळितो मी, गणपती मोरया॥\r\nविघ्नहर्ता सुखकर्ता, गणपती मोरया। भक्तांच्या रक्षणाला, गणपती मोरया॥', 'Morya Re Morya Ganapati Morya Pudhchya Varshi Lavkar Ya Ganapati Morya Eka Danta Vandu Tula Ganapati Morya Shendur Lal Chadhavito Ganapati Morya Modakancha Bhog Lage Ganapati Morya Aarti Ovalito Mi Ganapati Morya Vighnaharta Sukhakarta Ganapati Morya Bhaktancha Rakshanala Ganapati Morya', 'मोरया रे मोरया, गणपती मोरया। पुढच्या वर्षी लवकर या, गणपती मोरया। एका दंता वंदू तुला, गणपती मोरया। शेंदूर लाल चढवितो, गणपती मोरया। मोदकांचा भोग लागे, गणपती मोरया। आरती ओवाळितो मी, गणपती मोरया। विघ्नहर्ता सुखकर्ता, गणपती मोरया। भक्तांच्या रक्षणाला, गणपती मोरया।', 'Morya Re Morya, Ganapati Morya. Come early next year, Ganapati Morya. I bow to the one-tusked one, Ganapati Morya. I offer red vermillion, Ganapati Morya. Modak offerings are made, Ganapati Morya. I wave the aarti, Ganapati Morya. Remover of obstacles, giver of happiness, Ganapati Morya. To protect devotees, Ganapati Morya.', 'मोरया रे मोरया, गणपती मोरया', 'गणेश विसर्जन के समय यह आरती गाई जाती है। यह आरती अगले वर्ष गणेश जी को जल्दी लौटने का आग्रह करती है।', 'विसर्जन से पहले अंतिम आरती करें, गुलाल उधेड़ें, फिर विसर्जन के लिए प्रस्थान करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(4, 'Jai Ambe Gauri (Navratri Aarti)', 'Durga', 'Navratri', 'Hindu', 'Ashwin (Sep-Oct), Chaitra (Mar-Apr)', 'Pratipada to Navami', NULL, 'नवरात्रि के 9 दिन, दुर्गा पूजा, शक्ति उपासना', 'जय अम्बे गौरी, मैया जय श्यामा गौरी। तुमको निशिदिन ध्यावत, हरि ब्रह्म शिवरी॥\r\nमांगलिक कार्यों में, सब सिद्धि दाता। सभी मनोरथ पूर्ण कर, सब विघ्न हरता॥\r\nशेर पर सवार है, सब पर भारी है। दानव दल संहारक, माता दुर्गा भारी॥\r\nआरती ओवाळूं मैया, तुझी माता। सभी सुख संपत्ति, दो माता॥', 'Jai Ambe Gauri Maiya Jai Shyama Gauri Tumko Nishidin Dhyavat Hari Brahma Shivari Mangalik Karyon Mein Sab Siddhi Data Sabhi Manorath Purna Kar Sab Vighn Harta Sher Par Sawar Hai Sab Par Bhari Hai Danav Dal Sanharak Mata Durga Bhari Aarti Ovalu Maiya Tuzhi Mata Sabhi Sukh Sampatti Do Mata', 'जय अम्बे गौरी, मैया जय श्यामा गौरी। तुमको निशिदिन ध्यावत, हरि, ब्रह्म, शिवरी। मांगलिक कार्यों में, सब सिद्धि दाता। सभी मनोरथ पूर्ण कर, सब विघ्न हरता। शेर पर सवार है, सब पर भारी है। दानव दल संहारक, माता दुर्गा भारी। आरती ओवाळूं मैया, तुझी माता। सभी सुख संपत्ति, दो माता।', 'Victory to Mother Ambe Gauri, Mother Shyama Gauri. You are meditated upon day and night by Hari, Brahma, and Shiva. In auspicious ceremonies, you bestow all powers. You fulfill all desires, remove all obstacles. Seated on a lion, you are mighty over all. Destroyer of demon armies, Mother Durga is powerful. I wave the aarti before you, O Mother. Grant all happiness and prosperity, O Mother.', 'जय अम्बे गौरी मैया, जय श्यामा गौरी', 'नवरात्रि के नौ दिनों में प्रतिदिन यह आरती गाई जाती है। इससे सभी विघ्नों का नाश होता है और शक्ति की प्राप्ति होती है।', 'लाल फूल, लाल चुनरी, दीपक, धूप, नैवेद्य अर्पण करें। नवरात्रि में विशेष आयोजन करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(5, 'Durga Aarti - Ambe Tu Hai Jagdambe', 'Durga', 'Navratri', 'Hindu', 'Ashwin (Sep-Oct), Chaitra (Mar-Apr)', 'Pratipada to Navami', NULL, 'नवरात्रि, दुर्गा पूजा', 'अम्बे तू है जगदम्बे, माता तू है जगदम्बे। सुखियों के दुख दूर कर, दुखियों के दुख हर॥\r\nतेरे हाथों में त्रिशूल, तेरे हाथों में शूल। तेरे हाथों में खप्पर, तेरे हाथों में शंख॥\r\nशेर पर सवार है, सब पर भारी है। दानव दल संहारक, माता दुर्गा भारी॥\r\nअम्बे तू है जगदम्बे, माता तू है जगदम्बे॥', 'Ambe Tu Hai Jagdambe Mata Tu Hai Jagdambe Sukhiyon Ke Dukh Door Kar Dukhiyon Ke Dukh Har Tere Hathon Mein Trishool Tere Hathon Mein Shool Tere Hathon Mein Khappar Tere Hathon Mein Shankh Sher Par Sawar Hai Sab Par Bhari Hai Danav Dal Sanharak Mata Durga Bhari Ambe Tu Hai Jagdambe Mata Tu Hai Jagdambe', 'अम्बे तू है जगदम्बे, माता तू है जगदम्बे। सुखियों के दुख दूर कर, दुखियों के दुख हर। तेरे हाथों में त्रिशूल, तेरे हाथों में शूल। तेरे हाथों में खप्पर, तेरे हाथों में शंख। शेर पर सवार है, सब पर भारी है। दानव दल संहारक, माता दुर्गा भारी।', 'O Mother Ambe, you are the mother of the universe. Remove the sorrows of the happy, remove the sorrows of the sorrowful. In your hands are the trident, in your hands are the spear. In your hands are the skull cup, in your hands are the conch. Seated on a lion, you are mighty over all. Destroyer of demon armies, Mother Durga is powerful.', 'अम्बे तू है जगदम्बे', 'यह आरती नवरात्रि के दौरान प्रसिद्ध है और दुर्गा पूजा के समय गाई जाती है। इससे सभी मनोकामनाएं पूर्ण होती हैं।', 'लाल फूल, चुनरी, दीपक, धूप, भोग अर्पण करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(6, 'Om Jai Lakshmi Mata (Diwali Aarti)', 'Lakshmi', 'Diwali', 'Hindu', 'Kartik (Oct-Nov)', 'Amavasya', NULL, 'लक्ष्मी पूजन, धनतेरस, नरक चतुर्दशी, बलिप्रतिपदा', 'ॐ जय लक्ष्मी माता, स्वामी जय लक्ष्मी माता। विष्णु प्रिया सुखदाता, मोक्ष प्रदाता॥\r\nदीपावली आई, लक्ष्मी पूजा की रात। धन-धान्य से भर दो, माता मेरा हाथ॥\r\nलक्ष्मी पूजन करते, सब जन सुख पाते। दीपक जलते घर-घर, अंधकार मिट जाते॥\r\nॐ जय लक्ष्मी माता, स्वामी जय लक्ष्मी माता॥', 'Om Jai Lakshmi Mata Swami Jai Lakshmi Mata Vishnu Priya Sukhdata Moksha Pradata Dipavali Aai Lakshmi Puja Ki Raat Dhana Dhanya Se Bhar Do Mata Mera Hath Lakshmi Pujan Karte Sab Jan Sukh Pate Dipak Jalte Ghar Ghar Andhakar Mit Jate Om Jai Lakshmi Mata Swami Jai Lakshmi Mata', 'ॐ जय लक्ष्मी माता, स्वामी जय लक्ष्मी माता। विष्णु प्रिया सुखदाता, मोक्ष प्रदाता। दीपावली आई, लक्ष्मी पूजा की रात। धन-धान्य से भर दो, माता मेरा हाथ। लक्ष्मी पूजन करते, सब जन सुख पाते। दीपक जलते घर-घर, अंधकार मिट जाते।', 'Om, Victory to Mother Lakshmi, victory to Mother Lakshmi. Beloved of Vishnu, giver of happiness, bestower of liberation. Diwali has arrived, the night of Lakshmi Puja. Fill my hands with wealth and grain, O Mother. By performing Lakshmi Puja, all people attain happiness. Lamps light up every home, darkness is dispelled.', 'ॐ जय लक्ष्मी माता', 'दिवाली के दिन लक्ष्मी पूजन का विशेष महत्व है। यह आरती धन, समृद्धि और सुख-शांति की प्राप्ति के लिए गाई जाती है।', 'लाल फूल, लाल चुनरी, गुड़, चावल, दीपक, धूप अर्पण करें। दीपावली की रात विशेष पूजा करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(7, 'Jai Ganesh Deva (Diwali Ganesh Puja)', 'Ganesh', 'Diwali', 'Hindu', 'Kartik (Oct-Nov)', 'Amavasya', NULL, 'दिवाली पर गणेश-लक्ष्मी पूजन', 'जय गणेश जय गणेश जय गणेश देवा। माता जाकी पार्वती पिता महादेवा॥\r\nदीपावली की रात, तुम्हारी पूजा करते। विघ्नहर्ता गणपति, सुख-समृद्धि भरते॥\r\nलक्ष्मी संग आओ, घर-घर में बसो। सुख-शांति का वास, सदा यहां रहो॥\r\nजय गणेश जय गणेश जय गणेश देवा॥', 'Jai Ganesh Jai Ganesh Jai Ganesh Deva Mata Jaki Parvati Pita Mahadeva Dipavali Ki Raat Tumhari Pooja Karte Vighnaharta Ganapati Sukh Samriddhi Bharte Lakshmi Sang Aao Ghar Ghar Mein Baso Sukh Shanti Ka Vas Sada Yahan Raho Jai Ganesh Jai Ganesh Jai Ganesh Deva', 'जय गणेश जय गणेश जय गणेश देवा। माता पार्वती और पिता महादेव। दीपावली की रात, तुम्हारी पूजा करते। विघ्नहर्ता गणपति, सुख-समृद्धि भरते। लक्ष्मी संग आओ, घर-घर में बसो। सुख-शांति का वास, सदा यहां रहो।', 'Victory to Ganesh, victory to Ganesh, victory to Lord Ganesh. Mother Parvati and Father Mahadev. On the night of Diwali, we worship you. O remover of obstacles, fill with happiness and prosperity. Come with Lakshmi, reside in every home. May happiness and peace always dwell here.', 'जय गणेश जय गणेश जय गणेश देवा', 'दिवाली पर गणेश-लक्ष्मी पूजन किया जाता है। गणेश जी की पूजा सबसे पहले की जाती है।', 'शेंदूर, दुर्वा, मोदक, फुले अर्पण करें। सबसे पहले गणेश पूजन करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(8, 'Goverdhan Aarti (Annakut)', 'Govardhan', 'Diwali', 'Hindu', 'Kartik (Oct-Nov)', 'Pratipada', NULL, 'गोवर्धन पूजा, अन्नकूट, बलि प्रतिपदा', 'जय गिरिराज गोवर्धन, जय गिरिराज गोवर्धन। कृष्ण ने उठाया, गोपियों संग गावे॥\r\nअन्नकूट का पर्व, गोवर्धन की पूजा। गो-ग्राम की रक्षा, कृष्ण की यह लीला॥\r\nगोवर्धन पर्वत, भक्तों के सहारे। श्री हरि के चरण, सबके दुख टारे॥\r\nजय गिरिराज गोवर्धन, जय गिरिराज गोवर्धन॥', 'Jai Giriraj Govardhan Jai Giriraj Govardhan Krishna Ne Uthaya Gopiyon Sang Gaave Annakut Ka Parv Govardhan Ki Puja Go Gram Ki Raksha Krishna Ki Yeh Leela Govardhan Parvat Bhakton Ke Sahare Shri Hari Ke Charan Sabke Dukh Tare Jai Giriraj Govardhan Jai Giriraj Govardhan', 'जय गिरिराज गोवर्धन, जय गिरिराज गोवर्धन। कृष्ण ने उठाया, गोपियों संग गावे। अन्नकूट का पर्व, गोवर्धन की पूजा। गो-ग्राम की रक्षा, कृष्ण की यह लीला। गोवर्धन पर्वत, भक्तों के सहारे। श्री हरि के चरण, सबके दुख टारे।', 'Victory to Giriraj Govardhan, victory to Giriraj Govardhan. Krishna lifted it, sing with the Gopis. The festival of Annakut, the worship of Govardhan. Protection of cows and villages, this is Krishna\'s divine play. Govardhan mountain, the support of devotees. The feet of Shri Hari remove everyone\'s sorrows.', 'जय गिरिराज गोवर्धन', 'दिवाली के अगले दिन गोवर्धन पूजा की जाती है। भगवान कृष्ण ने गोवर्धन पर्वत उठाकर गोकुलवासियों की रक्षा की थी।', 'अन्नकूट (56 भोग) लगाएं, गोवर्धन पर्वत का चित्र बनाकर पूजा करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(9, 'Bhai Dooj Aarti', 'Yama', 'Diwali', 'Hindu', 'Kartik (Oct-Nov)', 'Dwitiya', NULL, 'भाई दूज, यम द्वितीया, भाई-बहन का पर्व', 'जय यम देवता, स्वामी जय यम देवता। भाई दूज का पर्व, सुख-समृद्धि दाता॥\r\nबहन ने तिलक लगाया, भाई की रक्षा की। यमुना में स्नान किया, दीपक जलाया॥\r\nयमराज ने यमुना से, भोजन किया स्वीकार। तभी से यह पर्व, हुआ प्रचलित अपार॥\r\nजय यम देवता, स्वामी जय यम देवता॥', 'Jai Yam Devata Swami Jai Yam Devata Bhai Dooj Ka Parv Sukh Samriddhi Data Bahan Ne Tilak Lagaya Bhai Ki Raksha Ki Yamuna Mein Snan Kiya Dipak Jalaya Yamraj Ne Yamuna Se Bhojan Kiya Svikar Tabhi Se Yeh Parv Hua Prachalit Apar Jai Yam Devata Swami Jai Yam Devata', 'जय यम देवता, स्वामी जय यम देवता। भाई दूज का पर्व, सुख-समृद्धि दाता। बहन ने तिलक लगाया, भाई की रक्षा की। यमुना में स्नान किया, दीपक जलाया। यमराज ने यमुना से, भोजन किया स्वीकार। तभी से यह पर्व, हुआ प्रचलित अपार।', 'Victory to Lord Yama, victory to Lord Yama. The festival of Bhai Dooj, bestower of happiness and prosperity. Sister applied tilak, protected her brother. Bathed in Yamuna, lit a lamp. Yama accepted food from Yamuna. Since then, this festival has become widely celebrated.', 'जय यम देवता', 'भाई दूज के दिन बहनें भाइयों के माथे पर तिलक लगाती हैं और उनकी लंबी आयु की कामना करती हैं।', 'बहन भाई के माथे पर तिलक लगाएं, आरती करें, मिठाई खिलाएं।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(10, 'Om Jai Shiv Omkara (Mahashivratri)', 'Shiva', 'Mahashivratri', 'Hindu', 'Phalgun (Feb-Mar)', 'Krishna Chaturdashi', NULL, 'शिवरात्रि, जागरण, रुद्राभिषेक', 'ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा। ब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा॥\r\nशिवरात्रि का पर्व, जागरण करते। बेलपत्र चढ़ाकर, शिवलिंग पूजते॥\r\nत्र्यंबक त्रिनेत्रा, चंद्रशेखरा। गंगाधर शूलपाणी, भक्तांच्या रक्षणा॥\r\nॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा॥', 'Om Jai Shiv Omkara Swami Jai Shiv Omkara Brahma Vishnu Sadashiv Ardhangidhara Shivaratri Ka Parv Jagram Karte Belpatra Chadha Kar Shivaling Pujate Tryambak Trinetra Chandrashekhara Gangadhar Shulapani Bhaktancha Rakshana Om Jai Shiv Omkara Swami Jai Shiv Omkara', 'ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा। ब्रह्मा, विष्णु और सदाशिव, अर्धांगिनी धारण करने वाले। शिवरात्रि का पर्व, जागरण करते। बेलपत्र चढ़ाकर, शिवलिंग पूजते। त्र्यंबक, त्रिनेत्रा, चंद्रशेखरा। गंगाधर, शूलपाणी, भक्तांच्या रक्षणा।', 'Om, Victory to Shiva, the embodiment of Om. Brahma, Vishnu, and Sadashiva, with the consort by their side. The festival of Shivratri, we stay awake. Offering bilva leaves, we worship the Shivalinga. The three-eyed one, the moon-crested one. Bearer of Ganga, holder of the trident, protector of devotees.', 'ॐ जय शिव ओंकारा', 'महाशिवरात्रि पर शिवलिंग का अभिषेक और जागरण किया जाता है। यह रात्रि शिव-शक्ति के मिलन की रात है।', 'बेलपत्र, धतुरा, भांग, फुले, दीपक अर्पण करें। रात्रि जागरण करें, शिव पंचाक्षरी मंत्र का जप करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(11, 'Shri Ram Chandra Kripalu (Ram Navami)', 'Rama', 'Ram Navami', 'Hindu', 'Chaitra (Mar-Apr)', 'Shukla Navami', NULL, 'राम जन्मोत्सव, रामायण पाठ', 'श्री राम चन्द्र कृपालु भजमन, हरण भव भय दारुणम्। नवकंज लोचन, कंज मुख, कर कंज पद कंजारुणम्॥\r\nराम नवमी आई, रघुवर का जन्म। अयोध्या नगरी में, हुआ यह पर्व धन्य॥\r\nसीता राम के चरण, भक्तों के सहारे। सब विधि रखना माया, देना फल पाया॥\r\nआरती श्री रामचन्द्र जी की॥', 'Shri Ram Chandra Kripalu Bhajman Haran Bhav Bhaya Darunam Navkanj Lochan Kanj Mukh Kar Kanj Pad Kanjarunam Ram Navami Aai Raghubar Ka Janm Ayodhya Nagari Mein Hua Yeh Parv Dhanya Sita Ram Ke Charan Bhakton Ke Sahare Sab Vidhi Rakhna Maya Dena Fal Paya Aarti Shri Ramchandra Ji Ki', 'श्री राम चन्द्र कृपालु भजमन, हरण भव भय दारुणम्। नवकंज लोचन, कंज मुख, कर कंज पद कंजारुणम्। राम नवमी आई, रघुवर का जन्म। अयोध्या नगरी में, हुआ यह पर्व धन्य। सीता राम के चरण, भक्तों के सहारे। सब विधि रखना माया, देना फल पाया।', 'O mind, sing of the merciful Shri Ramachandra, who removes the terrible fear of worldly existence. He has lotus-like eyes, a lotus-like face, and hands and feet that are like red lotuses. Ram Navami has arrived, the birth of the best of Raghu. In the city of Ayodhya, this festival has become blessed. The feet of Sita and Ram are the support of devotees. Protect us in all ways, grant us the fruits.', 'आरती श्री रामचन्द्र जी की', 'राम नवमी के दिन भगवान राम का जन्मोत्सव मनाया जाता है। इस दिन रामायण का पाठ और भजन-कीर्तन किया जाता है।', 'फूल, फल, दीपक, धूप, रोली, चावल अर्पण करें। रामायण पाठ करें, राम नाम का जप करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(12, 'Aarti Krishna Govind (Janmashtami)', 'Krishna', 'Janmashtami', 'Hindu', 'Bhadrapada (Aug-Sep)', 'Krishna Ashtami', NULL, 'कृष्ण जन्मोत्सव, मध्यरात्रि पूजा', 'आरती कृष्णा गोविन्दा, स्वामी आरती कृष्णा गोविन्दा। जगत गुरु दयालु, पूर्ण काम दाता॥\r\nजन्माष्टमी आई, नंदलाल का जन्म। मथुरा नगरी में, हुआ यह पर्व धन्य॥\r\nमाखन चोर कहलाये, ब्रज की नारिन के। कालिया नाग मर्दन, गोवर्धन धारी॥\r\nआरती कृष्णा गोविन्दा, स्वामी आरती कृष्णा गोविन्दा॥', 'Aarti Krishna Govinda Swami Aarti Krishna Govinda Jagat Guru Dayalu Purna Kam Data Janmashtami Aai Nandalal Ka Janm Mathura Nagari Mein Hua Yeh Parv Dhanya Makhan Chor Kehlaye Braj Ki Narin Ke Kaliya Nag Mardan Govardhan Dhari Aarti Krishna Govinda Swami Aarti Krishna Govinda', 'आरती कृष्णा गोविन्दा, स्वामी आरती कृष्णा गोविन्दा। जगत गुरु दयालु, पूर्ण काम दाता। जन्माष्टमी आई, नंदलाल का जन्म। मथुरा नगरी में, हुआ यह पर्व धन्य। माखन चोर कहलाये, ब्रज की नारिन के। कालिया नाग मर्दन, गोवर्धन धारी।', 'Aarti to Krishna Govinda, aarti to Krishna Govinda. The Guru of the world, the compassionate, the fulfiller of all desires. Janmashtami has arrived, the birth of Nandalal. In the city of Mathura, this festival has become blessed. Known as the butter thief, loved by the women of Braj. Tamer of the Kaliya serpent, lifter of Govardhan.', 'आरती कृष्णा गोविन्दा', 'जन्माष्टमी के दिन मध्यरात्रि में भगवान कृष्ण का जन्मोत्सव मनाया जाता है। इस दिन जागरण, भजन-कीर्तन और झांकियां की जाती हैं।', 'फूल, पंचामृत, माखन-मिश्री, दीपक, धूप अर्पण करें। मध्यरात्रि में जन्मोत्सव मनाएं।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(13, 'Aarti Keeje Hanuman Lala Ki (Hanuman Jayanti)', 'Hanuman', 'Hanuman Jayanti', 'Hindu', 'Chaitra (Mar-Apr)', 'Shukla Purnima', NULL, 'हनुमान जन्मोत्सव, मंगलवार विशेष', 'आरती कीजै हनुमान लला की। दुष्ट दलन रघुनाथ कला की॥\r\nहनुमान जयंती आई, बजरंग बली का जन्म। अंजनी माता के, गर्भ से हुआ प्रकट॥\r\nजा को देहु बुद्धि बल, पाए। सहज दर्शन रघुनंदन आए॥\r\nराम रूप धरि जगत पिता, संकट हरत भक्तन सुख दाता॥\r\nआरती कीजै हनुमान लला की॥', 'Aarti Kije Hanuman Lala Ki Dusht Dalana Raghunatha Kala Ki Hanuman Jayanti Aai Bajrang Bali Ka Janm Anjani Mata Ke Garbh Se Hua Prakat Ja Ko Dehu Buddhi Bal Pave Sahaj Darshan Raghunandan Aave Ram Roop Dhari Jagat Pita Sankat Harat Bhaktan Sukh Data Aarti Kije Hanuman Lala Ki', 'आरती कीजै हनुमान लला की। दुष्ट दलन रघुनाथ कला की। हनुमान जयंती आई, बजरंग बली का जन्म। अंजनी माता के, गर्भ से हुआ प्रकट। जाको देहु बुद्धि-बल, पावै। सहज दर्शन रघुनंदन आवै। राम रूप धरि जगत पिता, संकट हरत भक्तन सुख दाता।', 'Perform aarti of dear Hanuman. The destroyer of evil, the embodiment of Rama\'s power. Hanuman Jayanti has arrived, the birth of Bajrang Bali. He was manifested from the womb of Mother Anjani. Whom you give wisdom and strength, they effortlessly attain the vision of Rama. Taking the form of Rama, the father of the universe, remover of troubles, giver of happiness to devotees.', 'आरती कीजै हनुमान लला की', 'हनुमान जयंती के दिन हनुमान जी का जन्मोत्सव मनाया जाता है। यह दिन मंगलवार को विशेष महत्व रखता है।', 'सिंदूर, लाल फूल, चोला, दीपक अर्पण करें। हनुमान चालीसा का पाठ करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(14, 'Jai Surya Dev Bhagwan (Makar Sankranti)', 'Surya', 'Makar Sankranti', 'Harvest Festival', 'Magh (Jan)', 'Sankranti', NULL, 'सूर्य उपासना, तिल-गुड़ का दान, खिचड़ी पर्व', 'जय सूर्य देव भगवान, स्वामी जय सूर्य देव भगवान। सात घोड़े का रथ है, रथी भगवान॥\r\nमकर संक्रांति आई, सूर्य देव का पर्व। तिल-गुड़ खाकर, मीठा करो जीवन॥\r\nउत्तरायण आया, देवताओं का दिन। पुण्य का है पर्व, सबके मन हर्षित॥\r\nजय सूर्य देव भगवान, स्वामी जय सूर्य देव भगवान॥', 'Jai Surya Dev Bhagwan Swami Jai Surya Dev Bhagwan Saat Ghode Ka Rath Hai Rathi Bhagwan Makar Sankranti Aai Surya Dev Ka Parv Til Gud Khakar Mitha Karo Jivan Uttarayan Aaya Devataon Ka Din Punya Ka Hai Parv Sabke Man Harshit Jai Surya Dev Bhagwan Swami Jai Surya Dev Bhagwan', 'जय सूर्य देव भगवान, स्वामी जय सूर्य देव भगवान। सात घोड़े का रथ है, रथी भगवान। मकर संक्रांति आई, सूर्य देव का पर्व। तिल-गुड़ खाकर, मीठा करो जीवन। उत्तरायण आया, देवताओं का दिन। पुण्य का है पर्व, सबके मन हर्षित।', 'Victory to Lord Surya Dev, victory to Lord Surya Dev. He rides a chariot drawn by seven horses. Makar Sankranti has arrived, the festival of the Sun God. Eating sesame and jaggery, sweeten your life. Uttarayan has come, the day of the gods. It is a festival of merit, everyone\'s mind rejoices.', 'जय सूर्य देव भगवान', 'मकर संक्रांति पर सूर्य देव की पूजा की जाती है। यह उत्तरायण का आरंभ है, जो देवताओं का दिन माना जाता है।', 'जल, लाल फूल, चावल, गुड़, तिल अर्पण करें। सूर्य को अर्घ्य दें, तिल-गुड़ का दान करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(15, 'Raksha Bandhan Aarti', 'Raksha', 'Raksha Bandhan', 'Hindu', 'Shravan (Aug)', 'Shukla Purnima', NULL, 'भाई-बहन का पर्व, रक्षा सूत्र बंधन', 'रक्षा बंधन का पर्व, भाई-बहन का प्यार। राखी बांध बहन ने, भाई का उपकार॥\r\nसुरक्षा का वचन ले, भाई ने माना। सात जन्मों का यह, रिश्ता है सुहाना॥\r\nदेवताओं ने भी, राखी बांधी थी। इंद्राणी ने इंद्र को, सुरक्षा दी थी॥\r\nजय राखी माता, जय राखी माता॥', 'Raksha Bandhan Ka Parv Bhai Bahan Ka Pyar Rakhi Bandh Bahan Ne Bhai Ka Upkar Suraksha Ka Vachan Le Bhai Ne Mana Saat Janmon Ka Yeh Rishta Hai Suhana Devataon Ne Bhi Rakhi Bandhi Thi Indrani Ne Indra Ko Suraksha Di Thi Jai Rakhi Mata Jai Rakhi Mata', 'रक्षा बंधन का पर्व, भाई-बहन का प्यार। राखी बांध बहन ने, भाई का उपकार। सुरक्षा का वचन ले, भाई ने माना। सात जन्मों का यह, रिश्ता है सुहाना। देवताओं ने भी, राखी बांधी थी। इंद्राणी ने इंद्र को, सुरक्षा दी थी।', 'The festival of Raksha Bandhan, the love of brother and sister. Sister ties the rakhi, doing a favor for her brother. Brother accepts the vow of protection. This bond is beautiful for seven births. Even the gods tied rakhi. Indrani gave protection to Indra.', 'जय राखी माता', 'रक्षा बंधन के दिन बहनें भाइयों के कलाई पर राखी बांधती हैं और उनकी सुरक्षा की कामना करती हैं।', 'बहन भाई की कलाई पर राखी बांधे, आरती करे, मिठाई खिलाए।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(16, 'Jai Vishnu Bhagwan (Ekadashi Aarti)', 'Vishnu', 'Ekadashi', 'Hindu', 'Throughout Year', 'Ekadashi', NULL, 'विष्णु पूजा, व्रत, निराहार', 'जय विष्णु भगवान, स्वामी जय विष्णु भगवान। शंख चक्र गदा पद्म, धारी सनातन॥\r\nएकादशी का पर्व, विष्णु जी का दिन। व्रत-उपवास करे, पावे मोक्ष धन॥\r\nकमल नयन विश्वंभर, करुणा के सागर। भक्तों के दुख हरते, कष्ट निवारण करते॥\r\nजय विष्णु भगवान, स्वामी जय विष्णु भगवान॥', 'Jai Vishnu Bhagwan Swami Jai Vishnu Bhagwan Shankha Chakra Gada Padma Dhari Sanatan Ekadashi Ka Parv Vishnu Ji Ka Din Vrat Upvas Kare Pave Moksh Dhan Kamal Nayan Vishwambar Karuna Ke Sagar Bhakton Ke Dukh Harte Kasht Nivaran Karte Jai Vishnu Bhagwan Swami Jai Vishnu Bhagwan', 'जय विष्णु भगवान, स्वामी जय विष्णु भगवान। शंख, चक्र, गदा, पद्म धारण करने वाले, सनातन। एकादशी का पर्व, विष्णु जी का दिन। व्रत-उपवास करे, पावे मोक्ष धन। कमल नयन, विश्वंभर, करुणा के सागर। भक्तों के दुख हरते हैं, कष्ट निवारण करते हैं।', 'Victory to Lord Vishnu, victory to Lord Vishnu. Holder of conch, discus, mace, and lotus, the eternal one. The festival of Ekadashi, the day of Lord Vishnu. By observing fast, one attains the wealth of liberation. Lotus-eyed, sustainer of the world, ocean of compassion. He removes the sorrows of devotees, alleviates their troubles.', 'जय विष्णु भगवान', 'एकादशी व्रत भगवान विष्णु को समर्पित है। यह व्रत आध्यात्मिक उन्नति और पापों से मुक्ति के लिए किया जाता है।', 'तुलसी दल, फूल, दीपक, धूप अर्पण करें। विष्णु सहस्रनाम का पाठ करें, व्रत करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(17, 'Holi Aarti (Phagun Purnima)', 'Krishna', 'Holi', 'Hindu', 'Phalgun (Mar)', 'Purnima', NULL, 'रंगों का त्योहार, होलिका दहन, वसंत उत्सव', 'जय जय होली माता, जय जय होली माता। रंगों की देवी, सुख की दाता॥\r\nफागुन महीना आया, रंग बरसने लागे। होली की आरती, सब मिलकर गावे॥\r\nराधा कृष्ण की लीला, बृज में रंग भरी। गोपियों संग राधा, होली खेले श्याम॥\r\nजय जय होली माता, जय जय होली माता॥', 'Jai Jai Holi Mata Jai Jai Holi Mata Rangon Ki Devi Sukh Ki Data Phagun Mahina Aaya Rang Barasne Lage Holi Ki Aarti Sab Milkar Gaave Radha Krishna Ki Leela Braj Mein Rang Bhari Gopiyon Sang Radha Holi Khele Shyam Jai Jai Holi Mata Jai Jai Holi Mata', 'जय जय होली माता, जय जय होली माता। रंगों की देवी, सुख की दाता। फागुन महीना आया, रंग बरसने लागे। होली की आरती, सब मिलकर गावे। राधा कृष्ण की लीला, बृज में रंग भरी। गोपियों संग राधा, होली खेले श्याम।', 'Victory to Mother Holi, victory to Mother Holi. Goddess of colors, bestower of happiness. The month of Phalgun has arrived, colors start to shower. Let us all sing the aarti of Holi together. The divine play of Radha and Krishna, colors fill Braj. Radha plays Holi with the Gopis and Shyam.', 'जय जय होली माता', 'होली रंगों और खुशियों का त्योहार है। होलिका दहन बुराई पर अच्छाई की जीत का प्रतीक है।', 'रंग, गुलाल, फूल, दीपक, धूप अर्पण करें। होलिका दहन के बाद आरती करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(18, 'Jai Guru Dev (Guru Purnima)', 'Guru', 'Guru Purnima', 'Hindu', 'Ashadha (Jul)', 'Purnima', NULL, 'व्यास पूर्णिमा, गुरु पूजन, सद्गुरु की आराधना', 'जय जय गुरु देवा, स्वामी जय जय गुरु देवा। ज्ञान की ज्योति जलाओ, अज्ञान मिटाओ॥\r\nगुरु पूर्णिमा आई, गुरु चरण वंदन। व्यास जी का जन्मदिन, पूजन का कारण॥\r\nगुरुर्ब्रह्मा गुरुर्विष्णुः, गुरुर्देवो महेश्वरः। गुरुः साक्षात् परं ब्रह्म, तस्मै श्री गुरवे नमः॥\r\nजय जय गुरु देवा, स्वामी जय जय गुरु देवा॥', 'Jai Jai Guru Deva Swami Jai Jai Guru Deva Gyan Ki Jyoti Jalao Agyan Mitao Guru Purnima Aai Guru Charan Vandan Vyas Ji Ka Janmdin Poojan Ka Karan Gurur Brahma Gurur Vishnuh Gurur Devo Maheshwarah Guru Sakshaat Param Brahma Tasmai Shri Gurave Namah Jai Jai Guru Deva Swami Jai Jai Guru Deva', 'जय जय गुरु देवा, स्वामी जय जय गुरु देवा। ज्ञान की ज्योति जलाओ, अज्ञान मिटाओ। गुरु पूर्णिमा आई, गुरु चरण वंदन। व्यास जी का जन्मदिन, पूजन का कारण। गुरुर्ब्रह्मा गुरुर्विष्णुः, गुरुर्देवो महेश्वरः। गुरुः साक्षात् परं ब्रह्म, तस्मै श्री गुरवे नमः।', 'Victory to the divine Guru, victory to the divine Guru. Light the flame of knowledge, remove ignorance. Guru Purnima has arrived, salutations to the Guru\'s feet. The birthday of Sage Vyasa, the reason for worship. Guru is Brahma, Guru is Vishnu, Guru is the Lord Maheshwara. Guru is indeed the Supreme Brahman, Salutations to that Guru.', 'जय जय गुरु देवा', 'गुरु पूर्णिमा के दिन गुरुओं का पूजन किया जाता है। यह दिन महर्षि वेदव्यास का जन्मदिन है, जिन्होंने वेदों का विभाजन किया।', 'फूल, फल, दीपक, धूप अर्पण करें। गुरु वंदना करें, गुरु गीता का पाठ करें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22'),
(19, 'Karva Chauth Aarti', 'Gauri', 'Karva Chauth', 'Hindu', 'Kartik (Oct-Nov)', 'Chaturthi', NULL, 'सुहागिनों का व्रत, चंद्रोदय पूजा', 'जय गौरी मैया, जय गौरी मैया। सुहागिनों का व्रत, पूरा करो मैया॥\r\nचंद्र देव उदय हुए, करवा चौथ आई। सुहागिनों की रक्षा, माता तुम करो॥\r\nगौरी शंकर का व्रत, सुहाग का आधार। अखंड सौभाग्य दो, माता हमें अपार॥\r\nजय गौरी मैया, जय गौरी मैया॥', 'Jai Gauri Maiya Jai Gauri Maiya Suhaginon Ka Vrat Pura Karo Maiya Chandra Dev Uday Hue Karva Chauth Aai Suhaginon Ki Raksha Mata Tum Karo Gauri Shankar Ka Vrat Suhag Ka Aadhar Akhand Saubhagya Do Mata Hamen Apar Jai Gauri Maiya Jai Gauri Maiya', 'जय गौरी मैया, जय गौरी मैया। सुहागिनों का व्रत, पूरा करो मैया। चंद्र देव उदय हुए, करवा चौथ आई। सुहागिनों की रक्षा, माता तुम करो। गौरी शंकर का व्रत, सुहाग का आधार। अखंड सौभाग्य दो, माता हमें अपार।', 'Victory to Mother Gauri, victory to Mother Gauri. Fulfill the fast of married women. The moon has risen, Karva Chauth has arrived. Protect the married women, O Mother. The fast of Gauri-Shankar is the foundation of marital happiness. Grant us eternal good fortune, O Mother.', 'जय गौरी मैया', 'करवा चौथ के दिन सुहागिन महिलाएं अपने पति की लंबी आयु के लिए निर्जला व्रत रखती हैं। चंद्रोदय के समय आरती कर व्रत खोला जाता है।', 'चंद्रोदय पर छलनी से चंद्रमा देखें, आरती करें, पति के हाथ से जल पीकर व्रत खोलें।', NULL, NULL, 0, 0, 0, '2026-03-23 18:26:22');
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1, 'Ganesh Mool Mantra', 'ॐ गं गणपतये नमः', 'Om Gam Ganapataye Namah', 'ॐ गणेश जी को नमन', 'Salutations to Lord Ganesha', 1, '/audio/ganesh/ganesh_mool.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(2, 'Ganesh Panchakshari', 'ॐ गणेशाय नमः', 'Om Ganeshaya Namah', 'ॐ गणेश भगवान को नमन', 'Salutations to Lord Ganesha', 1, '/audio/ganesh/panchakshari.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'Ganesh Shadakshari', 'ॐ श्री गणेशाय नमः', 'Om Shri Ganeshaya Namah', 'ॐ श्री गणेश भगवान को नमन', 'Salutations to Lord Ganesha', 1, '/audio/ganesh/shadakshari.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Ganesh Ashtakshari', 'ॐ नमो श्री गणेशाय', 'Om Namo Shri Ganeshaya', 'ॐ श्री गणेश को प्रणाम', 'Salutations to Lord Ganesha', 1, '/audio/ganesh/ashtakshari.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Ganesh Dwadashakshari', 'ॐ नमो भगवते गणेशाय', 'Om Namo Bhagavate Ganeshaya', 'ॐ भगवान गणेश को नमन', 'Salutations to Lord Ganesha', 1, '/audio/ganesh/dwadashakshari.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Vakratunda Mantra', 'वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ। निर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥', 'Vakratunda Mahakaya Suryakoti Samaprabha Nirvighnam Kuru Me Deva Sarvakaryeshu Sarvada', 'हे वक्रतुण्ड महाकाय, करोड़ों सूर्य के समान तेजस्वी, मेरे सभी कार्यों में सदा विघ्नों को दूर करो', 'O Lord with curved trunk and massive body, with the luster of million suns, always remove obstacles from my endeavors', 1, '/audio/ganesh/vakratunda.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Ekadanta Mantra', 'एकदन्ताय विद्महे वक्रतुण्डाय धीमहि तन्नो दन्ती प्रचोदयात्॥', 'Ekadantaya Vidmahe Vakratundaya Dhimahi Tanno Danti Prachodayat', 'एकदंत भगवान को जानें, वक्रतुंड का ध्यान करें, वे हमें प्रेरित करें', 'We meditate on the one-tusked Lord, may that curved-trunk God illuminate our minds', 1, '/audio/ganesh/ekadanta.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Lambodara Mantra', 'लम्बोदराय विद्महे महोदराय धीमहि तन्नो दन्ती प्रचोदयात्॥', 'Lambodaraya Vidmahe Mahodaraya Dhimahi Tanno Danti Prachodayat', 'लम्बोदर भगवान को जानें, महोदर का ध्यान करें, वे हमें प्रेरित करें', 'We meditate on the pot-bellied Lord, may that large-bellied God illuminate our minds', 1, '/audio/ganesh/lambodara.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(9, 'Gajanan Mantra', 'गजाननाय विद्महे वक्रतुण्डाय धीमहि तन्नो दन्ती प्रचोदयात्॥', 'Gajananaya Vidmahe Vakratundaya Dhimahi Tanno Danti Prachodayat', 'गजानन भगवान को जानें, वक्रतुंड का ध्यान करें, वे हमें प्रेरित करें', 'We meditate on the elephant-faced Lord, may that curved-trunk God illuminate our minds', 1, '/audio/ganesh/gajanan.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(10, 'Vighneshwara Mantra', 'विघ्नेश्वराय विद्महे विघ्नराजाय धीमहि तन्नो विघ्नहर्ता प्रचोदयात्॥', 'Vighneshwaraya Vidmahe Vighnarajaya Dhimahi Tanno Vighnaharta Prachodayat', 'विघ्नेश्वर भगवान को जानें, विघ्नराज का ध्यान करें, वे विघ्नहर्ता हमें प्रेरित करें', 'We meditate on the Lord of obstacles, may that King of obstacles who removes all hurdles illuminate our minds', 1, '/audio/ganesh/vighneshwara.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(11, 'Ganesh Beej Mantra 1', 'ॐ ग्लौं गं गणपतये नमः', 'Om Glaum Gam Ganapataye Namah', 'ॐ ग्लौं गं गणपति को नमन', 'Salutations to Lord Ganapati', 1, '/audio/ganesh/beej1.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(12, 'Ganesh Beej Mantra 2', 'ॐ ह्रीं गं ह्रीं', 'Om Hreem Gam Hreem', 'ॐ ह्रीं गं ह्रीं', 'The seed mantra of Lord Ganesha', 1, '/audio/ganesh/beej2.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(13, 'Ganesh Beej Mantra 3', 'ॐ क्लीं गं क्लीं', 'Om Kleem Gam Kleem', 'ॐ क्लीं गं क्लीं', 'The seed mantra for attraction and wisdom', 1, '/audio/ganesh/beej3.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(14, 'Ganesh Beej Mantra 4', 'ॐ ऐं गं ऐं', 'Om Aim Gam Aim', 'ॐ ऐं गं ऐं', 'The seed mantra for knowledge and wisdom', 1, '/audio/ganesh/beej4.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(15, 'Ganesh Beej Mantra 5', 'ॐ सौः गं सौः', 'Om Sauh Gam Sauh', 'ॐ सौः गं सौः', 'The seed mantra for protection', 1, '/audio/ganesh/beej5.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(16, 'Ganesh Beej Mantra 6', 'ॐ ह्रीं क्लीं ग्लौं गं', 'Om Hreem Kleem Glaum Gam', 'ॐ ह्रीं क्लीं ग्लौं गं', 'The combined seed mantra of Ganesha', 1, '/audio/ganesh/beej6.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(17, 'Ganesh Beej Mantra 7', 'ॐ गं गणेश्वराय नमः', 'Om Gam Ganeshwaraya Namah', 'ॐ गं गणेश्वर को नमन', 'Salutations to the Lord of Ganas', 1, '/audio/ganesh/beej7.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(18, 'Ganesh Beej Mantra 8', 'ॐ गं गणाध्यक्षाय नमः', 'Om Gam Ganadhyakshaya Namah', 'ॐ गं गणों के अध्यक्ष को नमन', 'Salutations to the Chief of Ganas', 1, '/audio/ganesh/beej8.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(19, 'Ganesh Beej Mantra 9', 'ॐ गं गणनाथाय नमः', 'Om Gam Ganathaya Namah', 'ॐ गं गणों के नाथ को नमन', 'Salutations to the Lord of Ganas', 1, '/audio/ganesh/beej9.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(20, 'Ganesh Beej Mantra 10', 'ॐ गं गणपतये स्वाहा', 'Om Gam Ganapataye Swaha', 'ॐ गं गणपति को स्वाहा', 'Offering to Lord Ganapati', 1, '/audio/ganesh/beej10.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(21, 'Ganesh Gayatri 1', 'ॐ एकदन्ताय विद्महे वक्रतुण्डाय धीमहि तन्नो दन्ती प्रचोदयात्॥', 'Om Ekadantaya Vidmahe Vakratundaya Dhimahi Tanno Danti Prachodayat', 'ॐ एकदंत भगवान को जानें, वक्रतुंड का ध्यान करें, वे हमें प्रेरित करें', 'Om, Let me meditate on the one-tusked Lord, Give me higher intellect, Let the curved-trunk God illuminate my mind', 1, '/audio/ganesh/gayatri1.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(22, 'Ganesh Gayatri 2', 'ॐ गणपतये विद्महे वक्रतुण्डाय धीमहि तन्नो दन्ती प्रचोदयात्॥', 'Om Ganapataye Vidmahe Vakratundaya Dhimahi Tanno Danti Prachodayat', 'ॐ गणपति भगवान को जानें, वक्रतुंड का ध्यान करें, वे हमें प्रेरित करें', 'Om, Let me meditate on Lord Ganapati, Give me higher intellect, Let the curved-trunk God illuminate my mind', 1, '/audio/ganesh/gayatri2.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(23, 'Ganesh Gayatri 3', 'ॐ तत्पुरुषाय विद्महे वक्रतुण्डाय धीमहि तन्नो दन्ती प्रचोदयात्॥', 'Om Tatpurushaya Vidmahe Vakratundaya Dhimahi Tanno Danti Prachodayat', 'ॐ तत्पुरुष भगवान को जानें, वक्रतुंड का ध्यान करें, वे हमें प्रेरित करें', 'Om, Let me meditate on the Supreme Being, Give me higher intellect, Let the curved-trunk God illuminate my mind', 1, '/audio/ganesh/gayatri3.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(24, 'Ganesh Gayatri 4', 'ॐ वक्रतुण्डाय विद्महे लम्बोदराय धीमहि तन्नो गणपति प्रचोदयात्॥', 'Om Vakratundaya Vidmahe Lambodaraya Dhimahi Tanno Ganapati Prachodayat', 'ॐ वक्रतुंड भगवान को जानें, लम्बोदर का ध्यान करें, वे गणपति हमें प्रेरित करें', 'Om, Let me meditate on the curved-trunk Lord, Give me higher intellect, Let the pot-bellied Ganapati illuminate my mind', 1, '/audio/ganesh/gayatri4.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(25, 'Ganesh Gayatri 5', 'ॐ गजाननाय विद्महे गणाधिपाय धीमहि तन्नो गणेश प्रचोदयात्॥', 'Om Gajananaya Vidmahe Ganadhipaya Dhimahi Tanno Ganesha Prachodayat', 'ॐ गजानन भगवान को जानें, गणाधिप का ध्यान करें, वे गणेश हमें प्रेरित करें', 'Om, Let me meditate on the elephant-faced Lord, Give me higher intellect, Let the Lord of Ganas illuminate my mind', 1, '/audio/ganesh/gayatri5.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(26, 'Ganesh for Success', 'ॐ श्रीं ह्रीं क्लीं ग्लौं गं गणपतये वरवरद सर्वजनं मे वशमानय स्वाहा', 'Om Shreem Hreem Kleem Glaum Gam Ganapataye Varavarada Sarvajanam Me Vasamanaya Swaha', 'ॐ श्रीं ह्रीं क्लीं ग्लौं गं गणपति को समर्पित, सबको मेरे वश में करो स्वाहा', 'Om and salutations to Ganapati, who bestows boons, may all beings come under my influence', 1, '/audio/ganesh/success.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(27, 'Ganesh for Wealth', 'ॐ ह्रीं ग्रीं ह्रीं', 'Om Hreem Greem Hreem', 'ॐ ह्रीं ग्रीं ह्रीं', 'Ganesh mantra for wealth and prosperity', 1, '/audio/ganesh/wealth.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(28, 'Ganesh for Knowledge', 'ॐ ऐं ग्लौं गं', 'Om Aim Glaum Gam', 'ॐ ऐं ग्लौं गं', 'Ganesh mantra for knowledge and wisdom', 1, '/audio/ganesh/knowledge.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(29, 'Ganesh for Protection', 'ॐ ह्रीं गं ह्रीं नमः', 'Om Hreem Gam Hreem Namah', 'ॐ ह्रीं गं ह्रीं नमः', 'Ganesh mantra for protection from negativity', 1, '/audio/ganesh/protection.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(30, 'Ganesh for Marriage', 'ॐ श्रीं गं सौः', 'Om Shreem Gam Sauh', 'ॐ श्रीं गं सौः', 'Ganesh mantra for removing marriage obstacles', 1, '/audio/ganesh/marriage.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(31, 'Ganesh for Business', 'ॐ गं गणपतये फट्', 'Om Gam Ganapataye Phat', 'ॐ गं गणपतये फट्', 'Ganesh mantra for business success', 1, '/audio/ganesh/business.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(32, 'Ganesh for Health', 'ॐ गं ग्लौं गं', 'Om Gam Glaum Gam', 'ॐ गं ग्लौं गं', 'Ganesh mantra for good health', 1, '/audio/ganesh/health.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(33, 'Ganesh Stotra 1', 'प्रणम्य शिरसा देवं गौरीपुत्रं विनायकम्। एकदन्तं द्विजं शुद्धं नमामि गणनायकम्॥', 'Pranamya Shirasa Devam Gauriputram Vinayakam Ekadantam Dvijam Shuddham Namami Gananyakam', 'सिर झुकाकर प्रणाम करूं गौरीपुत्र विनायक को, एकदंत, द्विज, शुद्ध, गणनायक को नमन', 'Bowing my head, I salute the Lord, son of Gauri, Vinayaka, the one-tusked, pure, salutations to the Lord of Ganas', 1, '/audio/ganesh/stotra1.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(34, 'Ganesh Stotra 2', 'गणानां त्वा गणपतिं हवामहे कविं कवीनामुपमश्रवस्तमम्। ज्येष्ठराजं ब्रह्मणां ब्रह्मणस्पत आ नः शृण्वन्नूतिभिः सीद सादनम्॥', 'Gananam Tva Ganapatim Havamahe Kavim Kavinamupamashravastamam Jyeshtharajam Brahmanam Brahmanaspata A Nah Shrivannutibhih Sida Sadanam', 'गणों के स्वामी गणपति को हम पुकारते हैं, कवियों के कवि, अत्यधिक कीर्ति वाले, ब्रह्मज्ञानियों में श्रेष्ठ, ब्रह्मणस्पति, हमारी पुकार सुनकर रक्षा करें', 'We invoke you, Lord of hosts, the sage among sages, the most famous, the eldest king of Brahma-knowers, hear us and come to our abode', 1, '/audio/ganesh/stotra2.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
(35, 'Ganesh Ashtottara 1', 'ॐ गणेश्वराय नमः', 'Om Ganeshwaraya Namah', 'ॐ गणेश्वर को नमन', 'Salutations to the Lord of Ganas', 1, '/audio/ganesh/ashtottara1.mp3', 0, 0, '2026-03-18 02:17:34', NULL, NULL, NULL, NULL, NULL, NULL),
