(220, 'Shiva for Liberation', 'ॐ नमः शिवाय हौं', 'Om Namah Shivaya Haum', 'ॐ नमः शिवाय हौं', 'Shiva mantra for moksha', 2, '/audio/shiva/liberation.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
(221, 'Shiva for Peace', 'ॐ शान्ताय शिवाय नमः', 'Om Shantaya Shivaya Namah', 'ॐ शांत शिव को नमन', 'Salutations to the peaceful Shiva', 2, '/audio/shiva/peace.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
(222, 'Shiva for Courage', 'ॐ वीरभद्राय नमः', 'Om Veerabhadraya Namah', 'ॐ वीरभद्र को नमन', 'Salutations to Veerabhadra for courage', 2, '/audio/shiva/courage.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
