(224, 'Shiva for Concentration', 'ॐ एकाग्रचित्ताय नमः', 'Om Ekagrachittaya Namah', 'ॐ एकाग्रचित्त को नमन', 'Salutations to the one with concentrated mind', 2, '/audio/shiva/concentration.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
(225, 'Shiva for Spiritual Growth', 'ॐ आदियोगाय नमः', 'Om Adiyogaya Namah', 'ॐ आदियोगी को नमन', 'Salutations to the primal yogi', 2, '/audio/shiva/spiritual_growth.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
(226, 'Shiva for Removing Fear', 'ॐ अभयप्रदाय नमः', 'Om Abhayapradaya Namah', 'ॐ अभयप्रद को नमन', 'Salutations to the bestower of fearlessness', 2, '/audio/shiva/remove_fear.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
(227, 'Shiva for Healing', 'ॐ वैद्यनाथाय नमः', 'Om Vaidyanathaya Namah', 'ॐ वैद्यनाथ को नमन', 'Salutations to the Lord of physicians', 2, '/audio/shiva/healing.mp3', 0, 0, '2026-03-18 02:18:20', NULL, NULL, NULL, NULL, NULL, NULL),
