(245, 'Narayana Mantra', 'ॐ नारायणाय नमः', 'Om Narayanaya Namah', 'ॐ नारायण को नमन', 'Om, Salutations to Narayana', 3, '/audio/vishnu/narayana.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(246, 'Hari Mantra', 'ॐ हरये नमः', 'Om Haraye Namah', 'ॐ हरि को नमन', 'Om, Salutations to Hari', 3, '/audio/vishnu/hari.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(247, 'Vishnu Gayatri', 'ॐ नारायणाय विद्महे वासुदेवाय धीमहि तन्नो विष्णुः प्रचोदयात्॥', 'Om Narayanaya Vidmahe Vasudevaya Dhimahi Tanno Vishnuh Prachodayat', 'ॐ नारायण को जानें, वासुदेव का ध्यान करें, वे विष्णु हमें प्रेरित करें', 'Om, Let me meditate on Narayana, Give me higher intellect, Let Lord Vishnu illuminate my mind', 3, '/audio/vishnu/gayatri1.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(248, 'Vishnu Gayatri 2', 'ॐ वासुदेवाय विद्महे वैकुण्ठाय धीमहि तन्नो विष्णुः प्रचोदयात्॥', 'Om Vasudevaya Vidmahe Vaikunthaya Dhimahi Tanno Vishnuh Prachodayat', 'ॐ वासुदेव को जानें, वैकुण्ठ का ध्यान करें, वे विष्णु हमें प्रेरित करें', 'Om, Let me meditate on Vasudeva, Give me higher intellect, Let Lord Vishnu illuminate my mind', 3, '/audio/vishnu/gayatri2.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(249, 'Vishnu Gayatri 3', 'ॐ त्रिविक्रमाय विद्महे वामनाय धीमहि तन्नो विष्णुः प्रचोदयात्॥', 'Om Trivikramaya Vidmahe Vamanaya Dhimahi Tanno Vishnuh Prachodayat', 'ॐ त्रिविक्रम को जानें, वामन का ध्यान करें, वे विष्णु हमें प्रेरित करें', 'Om, Let me meditate on Trivikrama, Give me higher intellect, Let Lord Vishnu illuminate my mind', 3, '/audio/vishnu/gayatri3.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(250, 'Vishnu Gayatri 4', 'ॐ श्रीधराय विद्महे वैकुण्ठाय धीमहि तन्नो विष्णुः प्रचोदयात्॥', 'Om Shridharaya Vidmahe Vaikunthaya Dhimahi Tanno Vishnuh Prachodayat', 'ॐ श्रीधर को जानें, वैकुण्ठ का ध्यान करें, वे विष्णु हमें प्रेरित करें', 'Om, Let me meditate on Shridhara, Give me higher intellect, Let Lord Vishnu illuminate my mind', 3, '/audio/vishnu/gayatri4.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL);
