(258, 'Vishnu Beej Mantra 7', 'ॐ क्लीं नारायणाय नमः', 'Om Kleem Narayanaya Namah', 'ॐ क्लीं नारायण को नमन', 'Om Kleem, Salutations to Narayana', 3, '/audio/vishnu/beej7.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(259, 'Vishnu Beej Mantra 8', 'ॐ श्रीं विष्णवे नमः', 'Om Shreem Vishnave Namah', 'ॐ श्रीं विष्णु को नमन', 'Om Shreem, Salutations to Vishnu', 3, '/audio/vishnu/beej8.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(260, 'Vishnu Beej Mantra 9', 'ॐ ह्रीं वासुदेवाय नमः', 'Om Hreem Vasudevaya Namah', 'ॐ ह्रीं वासुदेव को नमन', 'Om Hreem, Salutations to Vasudeva', 3, '/audio/vishnu/beej9.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(261, 'Vishnu Beej Mantra 10', 'ॐ क्लीं ह्रीं श्रीं विष्णवे नमः', 'Om Kleem Hreem Shreem Vishnave Namah', 'ॐ क्लीं ह्रीं श्रीं विष्णु को नमन', 'Om Kleem Hreem Shreem, Salutations to Vishnu', 3, '/audio/vishnu/beej10.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
