(389, 'Vishnu for Family', 'ॐ कुटुम्बरक्षकाय विष्णवे नमः', 'Om Kutumbarakshakaya Vishnave Namah', 'ॐ कुटुम्बरक्षक विष्णु को नमन', 'Om, Salutations to Vishnu, the protector of family', 3, '/audio/vishnu/family.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(390, 'Vishnu for Children', 'ॐ सन्तानप्रदाय विष्णवे नमः', 'Om Santanapradaya Vishnave Namah', 'ॐ सन्तानप्रद विष्णु को नमन', 'Om, Salutations to Vishnu, the bestower of children', 3, '/audio/vishnu/children.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
(391, 'Vishnu for Marriage', 'ॐ वैवाहिकप्रदाय विष्णवे नमः', 'Om Vaivahikapradaya Vishnave Namah', 'ॐ वैवाहिकप्रद विष्णु को नमन', 'Om, Salutations to Vishnu, the bestower of marriage', 3, '/audio/vishnu/marriage.mp3', 0, 0, '2026-03-18 02:25:50', NULL, NULL, NULL, NULL, NULL, NULL),
