(798, 'Hanuman Moola Mantra', 'ॐ हनुमते नमः', 'Om Hanumate Namah', 'ॐ हनुमान जी को नमन', 'Om, Salutations to Lord Hanuman', 7, '/audio/hanuman/mool_mantra.mp3', 0, 0, '2026-03-18 11:47:40', NULL, NULL, NULL, NULL, NULL, NULL),
(799, 'Hanuman Moola Mantra Extended', 'ॐ ह्रां ह्रीं ह्रौं हनुमते नमः', 'Om Hraam Hreem Hraum Hanumate Namah', 'ॐ ह्रां ह्रीं ह्रौं हनुमान जी को नमन', 'Om Hraam Hreem Hraum, Salutations to Lord Hanuman', 7, '/audio/hanuman/mool_mantra_extended.mp3', 0, 0, '2026-03-18 11:47:40', NULL, NULL, NULL, NULL, NULL, NULL),
(800, 'Shri Hanuman Mantra', 'ॐ श्री हनुमते नमः', 'Om Shri Hanumate Namah', 'ॐ श्री हनुमान जी को नमन', 'Om, Salutations to Shri Hanuman', 7, '/audio/hanuman/shri_hanuman.mp3', 0, 0, '2026-03-18 11:47:40', NULL, NULL, NULL, NULL, NULL, NULL);
