(1140, 'Lakshmi Ashtottara 68', 'ॐ श्रीपद्ममुख्यै नमः', 'Om Shipadmamukhyai Namah', 'ॐ श्रीपद्ममुखी को नमन', 'Om, Salutations to the Lotus-Faced One', 9, '/audio/lakshmi/ashtottara68.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1141, 'Lakshmi Ashtottara 69', 'ॐ श्रीपद्महृदयायै नमः', 'Om Shipadmahridayayai Namah', 'ॐ श्रीपद्महृदया को नमन', 'Om, Salutations to the Lotus-Hearted One', 9, '/audio/lakshmi/ashtottara69.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1142, 'Lakshmi Ashtottara 70', 'ॐ श्रीपद्मनाभप्रियायै नमः', 'Om Shipadmanabhapriyayai Namah', 'ॐ श्रीपद्मनाभप्रिया को नमन', 'Om, Salutations to the Beloved of Padmanabha', 9, '/audio/lakshmi/ashtottara70.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1143, 'Lakshmi Ashtottara 71', 'ॐ श्रीपद्माकरप्रियायै नमः', 'Om Shipadmakara priyayai Namah', 'ॐ श्रीपद्माकरप्रिया को नमन', 'Om, Salutations to the Beloved of the Lotus-Handed', 9, '/audio/lakshmi/ashtottara71.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1144, 'Lakshmi Ashtottara 72', 'ॐ श्रीपद्माक्षप्रियायै नमः', 'Om Shipadmakshapriyayai Namah', 'ॐ श्रीपद्माक्षप्रिया को नमन', 'Om, Salutations to the Beloved of the Lotus-Eyed', 9, '/audio/lakshmi/ashtottara72.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1145, 'Lakshmi Ashtottara 73', 'ॐ श्रीपद्मोद्भवायै नमः', 'Om Shipadmodbhavayai Namah', 'ॐ श्रीपद्मोद्भवा को नमन', 'Om, Salutations to the One Born from Lotuses', 9, '/audio/lakshmi/ashtottara73.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1146, 'Lakshmi Ashtottara 74', 'ॐ श्रीपद्मावत्यै नमः', 'Om Shipadmavatyai Namah', 'ॐ श्रीपद्मावती को नमन', 'Om, Salutations to the Goddess Padmavati', 9, '/audio/lakshmi/ashtottara74.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1147, 'Lakshmi Ashtottara 75', 'ॐ श्रीपद्मिनीवल्लभायै नमः', 'Om Shipadminivallabhayai Namah', 'ॐ श्रीपद्मिनीवल्लभा को नमन', 'Om, Salutations to the Beloved of Padmini', 9, '/audio/lakshmi/ashtottara75.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1148, 'Lakshmi Ashtottara 76', 'ॐ श्रीपद्मकरायै नमः', 'Om Shipadmakaraayai Namah', 'ॐ श्रीपद्मकरा को नमन', 'Om, Salutations to the Lotus-Handed One', 9, '/audio/lakshmi/ashtottara76.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1149, 'Lakshmi Ashtottara 77', 'ॐ श्रीपद्माङ्घ्र्यै नमः', 'Om Shipadmanaghryai Namah', 'ॐ श्रीपद्माङ्घ्री को नमन', 'Om, Salutations to the Lotus-Footed One', 9, '/audio/lakshmi/ashtottara77.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1150, 'Lakshmi Ashtottara 78', 'ॐ श्रीपद्मनाभसोदर्यै नमः', 'Om Shipadmanabhasodaryai Namah', 'ॐ श्रीपद्मनाभसोदरी को नमन', 'Om, Salutations to the Sister of Padmanabha', 9, '/audio/lakshmi/ashtottara78.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1151, 'Lakshmi Ashtottara 79', 'ॐ श्रीपद्मनाभस्वसृए नमः', 'Om Shipadmanabhasvasre Namah', 'ॐ श्रीपद्मनाभस्वसृ को नमन', 'Om, Salutations to the Sister of Padmanabha', 9, '/audio/lakshmi/ashtottara79.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1152, 'Lakshmi Ashtottara 80', 'ॐ श्रीपद्मनाभसहोदर्यै नमः', 'Om Shipadmanabhasahodaryai Namah', 'ॐ श्रीपद्मनाभसहोदरी को नमन', 'Om, Salutations to the Sister of Padmanabha', 9, '/audio/lakshmi/ashtottara80.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1153, 'Sri Suktam - Verse 1', 'ॐ हिरण्यवर्णां हरिणीं सुवर्णरजतस्रजाम्। चन्द्रां हिरण्मयीं लक्ष्मीं जातवेदो म आवह॥', 'Om Hiranyavarnam Harinim Suvarnarajatasrajam Chandram Hiranmayim Lakshmim Jatavedo Ma Avaha', 'ॐ स्वर्णवर्णा, हरिणी, सुवर्ण और रजत की माला धारण करने वाली, चन्द्र के समान, स्वर्णमयी लक्ष्मी को, हे जातवेदः (अग्नि), मेरे लिए लाओ', 'Om, O Agni, bring to me Lakshmi, who is golden in color, beautiful, adorned with gold and silver garlands, radiant like the moon, and resplendent with gold', 9, '/audio/lakshmi/sri_suktam1.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1154, 'Sri Suktam - Verse 2', 'तां म आवह जातवेदो लक्ष्मीमनपगामिनीम्। यस्यां हिरण्यं विन्देयं गामश्वं पुरुषानहम्॥', 'Tam Ma Avaha Jatavedo Lakshmimanapagaminim Yasyam Hiranyam Vindeyam Gamashvam Purushanaham', 'उस अनपगामिनी (कभी न टलने वाली) लक्ष्मी को, हे जातवेदः, मेरे लिए लाओ, जिससे मैं सुवर्ण, गौ, अश्व और पुरुष (सेवक) प्राप्त करूं', 'O Jataveda, bring to me that unfailing Lakshmi, by whom I may obtain gold, cows, horses, and servants', 9, '/audio/lakshmi/sri_suktam2.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1155, 'Sri Suktam - Verse 3', 'अश्वपूर्वां रथमध्यां हस्तिनादप्रबोधिनीम्। श्रियं देवीमुपह्वये श्रीर्मा देवी जुषताम्॥', 'Ashvapurvam Rathamadhyam Hastinadaprabodhinim Shriyam Devimupahvaye Shrirma Devi Jushatam', 'अश्वों से अग्रगामिनी, रथों के मध्य में स्थित, हाथियों की गर्जना से जाग्रत, उस श्री देवी को मैं पुकारता हूं, वह श्री देवी मुझसे प्रसन्न हों', 'I invoke Goddess Shri, who is preceded by horses, seated in the middle of chariots, awakened by the trumpeting of elephants, may that Goddess Shri be pleased with me', 9, '/audio/lakshmi/sri_suktam3.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1156, 'Sri Suktam - Verse 4', 'कां सोस्मितां हिरण्यप्राकारामार्द्रां ज्वलन्तीं तृप्तां तर्पयन्तीम्। पद्मे स्थितां पद्मवर्णां तामिहोपह्वये श्रियम्॥', 'Kam Sosmitam Hiranyaprakaramardram Jvalantim Triptam Tarpayantim Padme Sthitam Padmavarnam Tamihopahvaye Shriyam', 'उन्हें, जो काम और स्मिता से युक्त हैं, सुवर्ण प्राकार वाली, आर्द्र, दीप्तिमान, तृप्त और तर्पयन्ती, पद्म में स्थित, पद्मवर्णा, उन श्री को मैं यहां पुकारता हूं', 'I invoke that Shri here, who is desired and smiling, having golden walls, moist, radiant, content, and satisfying others, seated on a lotus, lotus-hued', 9, '/audio/lakshmi/sri_suktam4.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1157, 'Sri Suktam - Verse 5', 'चन्द्रां प्रभासां यशसा ज्वलन्तीं श्रियं लोके देवजुष्टामुदाराम्। तां पद्मिनीमीं शरणमहं प्रपद्ये अलक्ष्मीर्मे नश्यतां त्वां वृणे॥', 'Chandram Prabhasam Yashasa Jwalantim Shriyam Loke Devajushtamudaram Tam Padminimim Sharanamaham Prapadye Alakshmirme Nashyatam Tvam Vrine', 'चन्द्र के समान प्रभासित, यश से ज्वलन्ती, लोक में देवताओं द्वारा सेवित, उदार, उस पद्मिनी श्री की मैं शरण ग्रहण करता हूं। मेरी अलक्ष्मी (दरिद्रता) नष्ट हो, मैं आपको चुनता हूं', 'I take refuge in that Padmini Shri, who is radiant like the moon, blazing with glory, worshipped by gods in the world, and generous. May my misfortune be destroyed, I choose you', 9, '/audio/lakshmi/sri_suktam5.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1158, 'Sri Suktam - Phala Sruti', 'श्रीः स्वर्णपद्मा विमलाननांशा हिरण्यवर्णा हरिणीसुवेषा। सदाऽऽश्रितानामवलोकयन्ती भक्तानुकम्पा कुरुषे प्रसादम्॥', 'Shrih Svarnapadma Vimalananamsha Hiranyavarna Harinisuvesha Sada Ashritanamavalokayanti Bhaktanukampa Kurushe Prasadam', 'श्री, स्वर्ण पद्म वाली, विमल मुख वाली, हिरण्यवर्णा, हरिणी, सुवेषा, सदा आश्रितों की ओर देखने वाली, भक्तों पर अनुकंपा करने वाली, कृपा करें', 'Shri, who sits on a golden lotus, whose face is pure, who is golden-colored, beautiful, well-adorned, always looking at those who seek refuge, compassionate to devotees, bestow your grace', 9, '/audio/lakshmi/sri_suktam6.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1159, 'Kanakadhara Stotram - Verse 1', 'अङ्गं हरेः पुलकभूषणमाश्रयन्ती भृङ्गाङ्गनेव मुकुलाभरणं तमालम्। अङ्गीकृताखिलविभूतिरपाङ्गलीला माङ्गल्यदाऽस्तु मम मङ्गलदेवतायाः॥', 'Angam Hareh Pulakabhushanamashrayanti Bhranganganeva Mukulabharanam Tamalam Angikritakhilavibhutirapangalila Mangalyadastu Mama Mangaladevatah', 'भगवान विष्णु के अंग को जो सुशोभित करती हैं, जैसे भ्रमरी तमाल वृक्ष का आश्रय लेती है, उनकी कटाक्ष लीला से समस्त ऐश्वर्य प्राप्त होता है, वह मंगलदायिनी देवी मुझे मंगल प्रदान करें', 'She who adorns the body of Hari like a female bee adorns a young tamala tree, whose sidelong glance bestows all prosperity, may that bestower of auspiciousness grant me auspiciousness', 9, '/audio/lakshmi/kanakadhara1.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1160, 'Kanakadhara Stotram - Verse 2', 'भवन्ति यत्रौषधयो रजन्यां अवर्धमानास्तमसा न रात्र्याम्। फलन्ति यत्रौषधयः प्रभाते तत्रैव लक्ष्मीः प्रतिवासरं नः॥', 'Bhavanti Yatroshadayo Rajanyam Avardhamanastamasa Na Ratryam Falanti Yatroshadayah Prabhate Tatraiva Lakshmih Prativasaram Nah', 'जहां रात्रि में भी औषधियां बढ़ती हैं और अंधकार से प्रभावित नहीं होतीं, जहां औषधियां प्रभात में फलती हैं, वहां हमारी लक्ष्मी प्रतिदिन निवास करती हैं', 'Where herbs grow even at night and are not affected by darkness, where herbs bear fruit in the morning, there Lakshmi resides for us daily', 9, '/audio/lakshmi/kanakadhara2.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1161, 'Kanakadhara Stotram - Verse 3', 'श्रीयः प्रिया श्रीय इव प्रियाणि श्रियः प्रदानैः प्रियदानशीलाः। श्रियः प्रियः श्रीपतयः प्रियायाः श्रीदेवतायाः प्रियदेवतायाः॥', 'Shriyah Priya Shriya Iva Priyani Shriyah Pradanaih Priyadanashilah Shriyah Priyah Shripatayah Priyayah Shridevatayah Priyadevatayah', 'लक्ष्मी के प्रिय, लक्ष्मी के समान प्रिय, लक्ष्मी के दान से प्रियदानशील, लक्ष्मी के प्रिय श्रीपति (विष्णु) उन प्रिया की, उन श्रीदेवता की, उन प्रियदेवता की', 'The beloved of Shri, the beloved ones like Shri, those who are generous with the gifts of Shri, the beloved of Shri, the consort of Shri, of that beloved Goddess Shri, the beloved deity', 9, '/audio/lakshmi/kanakadhara3.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1162, 'Lakshmi Stotram', 'नमस्तेऽस्तु महामाये श्रीपीठे सुरपूजिते। शङ्खचक्रगदाहस्ते महालक्ष्मि नमोऽस्तु ते॥', 'Namaste\'stu Mahamaye Shripithe Surapujite Shankhachakragadahaste Mahalakshmi Namo\'stu Te', 'हे महामाया, श्रीपीठ में निवास करने वाली, देवताओं द्वारा पूजित, शंख, चक्र, गदा धारण करने वाली, हे महालक्ष्मी, आपको नमन', 'Salutations to you, O Mahamaya, residing in the seat of Shri, worshipped by gods, holding conch, discus, and mace, O Mahalakshmi, salutations to you', 9, '/audio/lakshmi/lakshmi_stotram.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1163, 'Lakshmi for Wealth', 'ॐ श्रीं ह्रीं क्लीं महालक्ष्म्यै नमः', 'Om Shreem Hreem Kleem Mahalakshmyai Namah', 'ॐ श्रीं ह्रीं क्लीं महालक्ष्मी को नमन - धन प्राप्ति के लिए', 'Om Shreem Hreem Kleem, Salutations to Mahalakshmi for wealth', 9, '/audio/lakshmi/wealth.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1164, 'Lakshmi for Prosperity', 'ॐ श्रीं श्रीं श्रीं महालक्ष्म्यै नमः', 'Om Shreem Shreem Shreem Mahalakshmyai Namah', 'ॐ श्रीं श्रीं श्रीं महालक्ष्मी को नमन - समृद्धि के लिए', 'Om Shreem Shreem Shreem, Salutations to Mahalakshmi for prosperity', 9, '/audio/lakshmi/prosperity.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1165, 'Lakshmi for Success', 'ॐ ह्रीं श्रीं क्लीं महालक्ष्म्यै स्वाहा', 'Om Hreem Shreem Kleem Mahalakshmyai Swaha', 'ॐ ह्रीं श्रीं क्लीं महालक्ष्मी को स्वाहा - सफलता के लिए', 'Om Hreem Shreem Kleem, Offering to Mahalakshmi for success', 9, '/audio/lakshmi/success.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1166, 'Lakshmi for Business', 'ॐ श्रीं ह्रीं क्लीं ऐं महालक्ष्म्यै नमः', 'Om Shreem Hreem Kleem Aim Mahalakshmyai Namah', 'ॐ श्रीं ह्रीं क्लीं ऐं महालक्ष्मी को नमन - व्यापार वृद्धि के लिए', 'Om Shreem Hreem Kleem Aim, Salutations to Mahalakshmi for business growth', 9, '/audio/lakshmi/business.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1167, 'Lakshmi for Family', 'ॐ श्रीं महालक्ष्म्यै कुटुम्बरक्षणाय नमः', 'Om Shreem Mahalakshmyai Kutumbarakshanaya Namah', 'ॐ श्रीं महालक्ष्मी, परिवार की रक्षा के लिए नमन', 'Om Shreem, Salutations to Mahalakshmi for family protection', 9, '/audio/lakshmi/family.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1168, 'Lakshmi for Children', 'ॐ श्रीं महालक्ष्म्यै सन्तानप्रदायै नमः', 'Om Shreem Mahalakshmyai Santanapradayai Namah', 'ॐ श्रीं महालक्ष्मी, संतान प्रदान करने वाली को नमन', 'Om Shreem, Salutations to Mahalakshmi, the giver of children', 9, '/audio/lakshmi/children.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1169, 'Lakshmi for Education', 'ॐ श्रीं विद्यालक्ष्म्यै नमः', 'Om Shreem Vidyalakshmyai Namah', 'ॐ श्रीं विद्या लक्ष्मी को नमन - शिक्षा के लिए', 'Om Shreem, Salutations to Vidya Lakshmi for education', 9, '/audio/lakshmi/education.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1170, 'Lakshmi for Courage', 'ॐ श्रीं वीरलक्ष्म्यै नमः', 'Om Shreem Veeralakshmyai Namah', 'ॐ श्रीं वीर लक्ष्मी को नमन - साहस के लिए', 'Om Shreem, Salutations to Veera Lakshmi for courage', 9, '/audio/lakshmi/courage.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
(1171, 'Lakshmi for Victory', 'ॐ श्रीं जयलक्ष्म्यै नमः', 'Om Shreem Jayalakshmyai Namah', 'ॐ श्रीं जय लक्ष्मी को नमन - विजय के लिए', 'Om Shreem, Salutations to Jaya Lakshmi for victory', 9, '/audio/lakshmi/victory.mp3', 0, 0, '2026-03-23 03:08:50', NULL, NULL, NULL, NULL, NULL, NULL),
