(1394, 'Brahma Ashtottara 47', 'ॐ चतुर्विधजीवरक्षकाय नमः', 'Om Chaturvidhajivarakshakaya Namah', 'ॐ चारों प्रकार के जीवों के रक्षक को नमन', 'Om, Salutations to the Protector of Four Kinds of Beings', 11, '/audio/brahma/ashtottara47.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1395, 'Brahma Ashtottara 48', 'ॐ चतुर्विधप्राणिधराय नमः', 'Om Chaturvidhapranidharaya Namah', 'ॐ चारों प्रकार के प्राणियों को धारण करने वाले को नमन', 'Om, Salutations to the Sustainer of Four Kinds of Creatures', 11, '/audio/brahma/ashtottara48.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1396, 'Brahma Ashtottara 49', 'ॐ चतुर्विधवेदप्रतिपाद्याय नमः', 'Om Chaturvidhavedapratipadyaya Namah', 'ॐ चारों प्रकार के वेदों द्वारा प्रतिपादित को नमन', 'Om, Salutations to the One Expounded by Four Vedas', 11, '/audio/brahma/ashtottara49.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1397, 'Brahma Ashtottara 50', 'ॐ चतुर्विधयज्ञफलप्रदाय नमः', 'Om Chaturvidhayajnaphalapradaya Namah', 'ॐ चारों प्रकार के यज्ञों का फल देने वाले को नमन', 'Om, Salutations to the Giver of Fruits of Four Kinds of Sacrifices', 11, '/audio/brahma/ashtottara50.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1398, 'Brahma Garbhadhana Mantra', 'विष्णुर्योनिं कल्पयतु त्वष्टा रूपाणि पिंशतु। आसिञ्चतु प्रजापतिः धाता गर्भं दधातु ते॥', 'Vishnuryonim Kalpayatu Tvashta Rupani Pimshatu Asincatu Prajapatih Dhata Garbham Dadhatu Te', 'विष्णु योनि को तैयार करें, त्वष्टा रूपों को गढ़ें, प्रजापति सिंचन करें, धाता तुम्हारे लिए गर्भ धारण करें', 'May Vishnu prepare the womb, may Tvashta shape the forms, may Prajapati inseminate, may Dhata sustain the embryo for you', 11, '/audio/brahma/brahma_garbhadhana.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1399, 'Brahma for Knowledge', 'ॐ ब्रह्मणे विद्याप्रदाय नमः', 'Om Brahmane Vidyapradaya Namah', 'ॐ ब्रह्मा, विद्या प्रदान करने वाले को नमन', 'Om, Salutations to Brahma, the giver of knowledge', 11, '/audio/brahma/brahma_knowledge.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1400, 'Brahma for Wisdom', 'ॐ ब्रह्मणे ज्ञानप्रदाय नमः', 'Om Brahmane Jnanapradaya Namah', 'ॐ ब्रह्मा, ज्ञान प्रदान करने वाले को नमन', 'Om, Salutations to Brahma, the giver of wisdom', 11, '/audio/brahma/brahma_wisdom.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1401, 'Brahma for Creativity', 'ॐ ब्रह्मणे सृजनशक्तिप्रदाय नमः', 'Om Brahmane Srijanashaktipradaya Namah', 'ॐ ब्रह्मा, सृजनशक्ति प्रदान करने वाले को नमन', 'Om, Salutations to Brahma, the giver of creative power', 11, '/audio/brahma/brahma_creativity.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1402, 'Brahma Prarthana', 'ॐ नमो ब्रह्मणे महते पुरुषाय चिदात्मने। सृष्टिस्थितिविनाशानां एकाय परमात्मने॥', 'Om Namo Brahmane Mahate Purushaya Chidatmane Srishtisthitivinashanam Ekaya Paramatmane', 'ॐ नमन ब्रह्मा को, महान पुरुष को, चिदात्मा को, सृष्टि, स्थिति और विनाश के एकमात्र परमात्मा को', 'Om, Salutations to Brahma, the great Purusha, the consciousness-self, the one Supreme Self who is the cause of creation, preservation, and destruction', 11, '/audio/brahma/brahma_prarthana.mp3', 0, 0, '2026-03-23 03:11:35', NULL, NULL, NULL, NULL, NULL, NULL),
(1403, 'Indra Mool Mantra', 'ॐ इन्द्राय नमः', 'Om Indraya Namah', 'ॐ इन्द्र देव को नमन', 'Om, Salutations to Lord Indra', 12, '/audio/vedic/indra_mool.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1404, 'Indra Pranam Mantra', 'ॐ नमो इन्द्राय', 'Om Namo Indraya', 'ॐ इन्द्र देव को प्रणाम', 'Om, Salutations and prostrations to Indra', 12, '/audio/vedic/indra_pranam.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1405, 'Indra Panchakshari', 'ॐ इन्द्राय नमः', 'Om Indraya Namah', 'ॐ इन्द्र को नमन', 'Om, Salutations to Indra', 12, '/audio/vedic/indra_panchakshari.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1406, 'Indra Gayatri', 'ॐ महेन्द्राय विद्महे वज्रहस्ताय धीमहि तन्नो इन्द्रः प्रचोदयात्॥', 'Om Mahendraya Vidmahe Vajrahastaya Dhimahi Tanno Indrah Prachodayat', 'ॐ महेन्द्र को जानें, वज्रहस्त का ध्यान करें, वे इन्द्र हमें प्रेरित करें', 'Om, Let me meditate on the great Indra, Give me higher intellect, Let Lord Indra illuminate my mind', 12, '/audio/vedic/indra_gayatri.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1407, 'Indra Beej Mantra', 'ॐ इं इन्द्राय नमः', 'Om Im Indraya Namah', 'ॐ इं इन्द्र को नमन', 'Om Im, Salutations to Indra', 12, '/audio/vedic/indra_beej.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1408, 'Indra Vajra Mantra', 'ॐ वज्रहस्ताय नमः', 'Om Vajrahastaya Namah', 'ॐ वज्रधारी (इन्द्र) को नमन', 'Om, Salutations to the Thunderbolt-Holder', 12, '/audio/vedic/indra_vajra.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1409, 'Indra Vajra Beej', 'ॐ वज्राय नमः', 'Om Vajraya Namah', 'ॐ वज्र को नमन', 'Om, Salutations to the Thunderbolt', 12, '/audio/vedic/indra_vajra_beej.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1410, 'Indra Shachi Pati Mantra', 'ॐ शचीपतये नमः', 'Om Shachipataye Namah', 'ॐ शची के पति (इन्द्र) को नमन', 'Om, Salutations to the Consort of Shachi', 12, '/audio/vedic/indra_shachi.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1411, 'Rigvedic Indra Sukta', 'इन्द्रं वो विश्वतस्परि हवामहे जनेभ्यः। अस्माकमस्तु केवलः॥', 'Indram Vo Vishvatas Pari Havamahe Janebhyah Asmakam Astu Kevalah', 'हे इन्द्र, हम आपको सभी दिशाओं से, सभी लोगों के लिए पुकारते हैं। आप केवल हमारे ही हों', 'We invoke Indra from all directions for all people. May he be exclusively ours', 12, '/audio/vedic/indra_rigveda1.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1412, 'Indra Vritraghna Mantra', 'ॐ इन्द्रो वृत्रं जघान', 'Om Indro Vritram Jaghana', 'ॐ इन्द्र ने वृत्रासुर का वध किया', 'Om, Indra slew Vritra', 12, '/audio/vedic/indra_vritraghna.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1413, 'Indra Purandara Mantra', 'ॐ पुरन्दराय नमः', 'Om Purandaraya Namah', 'ॐ पुरन्दर (इन्द्र) को नमन', 'Om, Salutations to the Destroyer of Forts', 12, '/audio/vedic/indra_purandara.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1414, 'Indra Varsha Mantra', 'ॐ इन्द्रो वर्षतु', 'Om Indro Varshatu', 'ॐ इन्द्र वर्षा करें', 'Om, May Indra shower rain', 12, '/audio/vedic/indra_varsha.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1415, 'Indra Megha Mantra', 'ॐ मेघराजाय नमः', 'Om Megharajaya Namah', 'ॐ मेघराज (इन्द्र) को नमन', 'Om, Salutations to the King of Clouds', 12, '/audio/vedic/indra_megha.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1416, 'Indra Krishi Mantra', 'ॐ इन्द्राय कृषिफलप्रदाय नमः', 'Om Indraya Krishiphalapradaya Namah', 'ॐ इन्द्र, कृषि फल प्रदान करने वाले को नमन', 'Om, Salutations to Indra, the giver of agricultural harvest', 12, '/audio/vedic/indra_krishi.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1417, 'Agni Mool Mantra', 'ॐ अग्नये नमः', 'Om Agnaye Namah', 'ॐ अग्नि देव को नमन', 'Om, Salutations to Lord Agni', 12, '/audio/vedic/agni_mool.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1418, 'Agni Pranam Mantra', 'ॐ नमो अग्नये', 'Om Namo Agnaye', 'ॐ अग्नि देव को प्रणाम', 'Om, Salutations and prostrations to Agni', 12, '/audio/vedic/agni_pranam.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1419, 'Agni Gayatri', 'ॐ महाज्वालाय विद्महे अग्निदेवाय धीमहि तन्नो अग्निः प्रचोदयात्॥', 'Om Mahajwalaya Vidmahe Agnidevaya Dhimahi Tanno Agnih Prachodayat', 'ॐ महाज्वाला को जानें, अग्निदेव का ध्यान करें, वे अग्नि हमें प्रेरित करें', 'Om, Let me meditate on the great flame, Give me higher intellect, Let Lord Agni illuminate my mind', 12, '/audio/vedic/agni_gayatri.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1420, 'Agni Beej Mantra', 'ॐ रां अग्नये नमः', 'Om Raam Agnaye Namah', 'ॐ रां अग्नि को नमन', 'Om Raam, Salutations to Agni', 12, '/audio/vedic/agni_beej.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1421, 'Rigvedic Agni Sukta', 'अग्निमीळे पुरोहितं यज्ञस्य देवमृत्विजम्। होतारं रत्नधातमम्॥', 'Agnim Iele Purohitam Yajnasya Devamritvijam Hotaram Ratnadhatamam', 'अग्नि की स्तुति करता हूं, जो पुरोहित हैं, यज्ञ के देवता, ऋत्विज, होता, और सबसे अधिक रत्नों को देने वाले हैं', 'I praise Agni, the household priest, the divine minister of the sacrifice, the invoker, the bestower of treasures', 12, '/audio/vedic/agni_rigveda1.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1422, 'Agni Duta Mantra', 'ॐ अग्निर्दूतः', 'Om Agnirdutah', 'ॐ अग्नि दूत हैं', 'Om, Agni is the messenger', 12, '/audio/vedic/agni_duta.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1423, 'Agni Jataveda Mantra', 'ॐ जातवेदसे नमः', 'Om Jatavedase Namah', 'ॐ जातवेदा (अग्नि) को नमन', 'Om, Salutations to Jataveda (Agni)', 12, '/audio/vedic/agni_jataveda.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1424, 'Agni Homa Mantra', 'ॐ अग्नये स्वाहा', 'Om Agnaye Swaha', 'ॐ अग्नि को स्वाहा', 'Om, Offering to Agni', 12, '/audio/vedic/agni_homa.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1425, 'Agni Prajvalana Mantra', 'ॐ अग्निं प्रज्वालयामि', 'Om Agnim Prajvalayami', 'ॐ अग्नि प्रज्वलित करता हूं', 'Om, I kindle the sacred fire', 12, '/audio/vedic/agni_prajvalana.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1426, 'Agni Raksha Mantra', 'ॐ अग्ने रक्ष रक्ष', 'Om Agne Raksha Raksha', 'ॐ अग्नि, रक्षा करो, रक्षा करो', 'Om, O Agni, protect, protect', 12, '/audio/vedic/agni_raksha.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1427, 'Agni Diksha Mantra', 'ॐ अग्ने व्रतपते व्रतं चरिष्यामि', 'Om Agne Vratapate Vratam Charishyami', 'ॐ अग्नि, व्रत के स्वामी, मैं व्रत का पालन करूंगा', 'Om, O Agni, Lord of vows, I shall observe the vow', 12, '/audio/vedic/agni_diksha.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1428, 'Agni Pavaka Mantra', 'ॐ पावकाय नमः', 'Om Pavakaya Namah', 'ॐ पावक (शुद्धिकारक अग्नि) को नमन', 'Om, Salutations to the Purifier (Agni)', 12, '/audio/vedic/agni_pavaka.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1429, 'Agni Pavamana Mantra', 'ॐ अग्ने पवमान', 'Om Agne Pavamana', 'ॐ अग्नि, पवित्र करने वाले', 'Om, O Agni, the purifier', 12, '/audio/vedic/agni_pavamana.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1430, 'Vayu Mool Mantra', 'ॐ वायवे नमः', 'Om Vayave Namah', 'ॐ वायु देव को नमन', 'Om, Salutations to Lord Vayu', 12, '/audio/vedic/vayu_mool.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1431, 'Vayu Pranam Mantra', 'ॐ नमो वायवे', 'Om Namo Vayave', 'ॐ वायु देव को प्रणाम', 'Om, Salutations to Lord Vayu', 12, '/audio/vedic/vayu_pranam.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1432, 'Vayu Gayatri', 'ॐ वायवे विद्महे वातरूपाय धीमहि तन्नो वायुः प्रचोदयात्॥', 'Om Vayave Vidmahe Vatarupaya Dhimahi Tanno Vayuh Prachodayat', 'ॐ वायु देव को जानें, वातरूप का ध्यान करें, वे वायु हमें प्रेरित करें', 'Om, Let me meditate on Vayu, Give me higher intellect, Let Lord Vayu illuminate my mind', 12, '/audio/vedic/vayu_gayatri.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1433, 'Vayu Beej Mantra', 'ॐ यं वायवे नमः', 'Om Yam Vayave Namah', 'ॐ यं वायु को नमन', 'Om Yam, Salutations to Vayu', 12, '/audio/vedic/vayu_beej.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1434, 'Rigvedic Vayu Sukta', 'वायो याहि दर्शतेमे सोमा अरंकृताः। तेषां पाहि श्रुधी हवम्॥', 'Vayo Yahi Darshateme Soma Arankritah Tesham Pahi Shrudhi Havam', 'हे वायु, आओ, ये सोम सुंदर रूप से सज्जित हैं। उनका पान करो और हमारी पुकार सुनो', 'O Vayu, come, these Soma juices are beautifully prepared. Drink them and listen to our call', 12, '/audio/vedic/vayu_rigveda1.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1435, 'Vayu Pranah Mantra', 'ॐ प्राणाय नमः', 'Om Pranaya Namah', 'ॐ प्राण (वायु) को नमन', 'Om, Salutations to the Life Force (Vayu)', 12, '/audio/vedic/vayu_prana.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1436, 'Vayu Prana Shakti Mantra', 'ॐ प्राणस्य प्राणाय नमः', 'Om Pranasya Pranaya Namah', 'ॐ प्राणों के प्राण (वायु) को नमन', 'Om, Salutations to the Life of Life (Vayu)', 12, '/audio/vedic/vayu_prana_shakti.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1437, 'Vayu Arogya Mantra', 'ॐ वायवे आरोग्यप्रदाय नमः', 'Om Vayave Arogyapradaya Namah', 'ॐ वायु, आरोग्य प्रदान करने वाले को नमन', 'Om, Salutations to Vayu, the giver of health', 12, '/audio/vedic/vayu_arogya.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1438, 'Vayu Bala Mantra', 'ॐ वायवे बलप्रदाय नमः', 'Om Vayave Balapradaya Namah', 'ॐ वायु, बल प्रदान करने वाले को नमन', 'Om, Salutations to Vayu, the giver of strength', 12, '/audio/vedic/vayu_bala.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1439, 'Vayu Diggaja Mantra', 'ॐ वायो दिशां पते', 'Om Vayo Disham Pate', 'ॐ वायु, दिशाओं के स्वामी', 'Om, O Vayu, Lord of the Directions', 12, '/audio/vedic/vayu_disha.mp3', 0, 0, '2026-03-23 03:15:20', NULL, NULL, NULL, NULL, NULL, NULL),
(1440, 'Varuna Mool Mantra', 'ॐ वरुणाय नमः', 'Om Varunaya Namah', 'ॐ वरुण देव को नमन', 'Om, Salutations to Lord Varuna', 12, '/audio/vedic/varuna_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1441, 'Varuna Pranam Mantra', 'ॐ नमो वरुणाय', 'Om Namo Varunaya', 'ॐ वरुण देव को प्रणाम', 'Om, Salutations to Lord Varuna', 12, '/audio/vedic/varuna_pranam.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1442, 'Varuna Gayatri', 'ॐ जलाधिपतये विद्महे वरुणाय धीमहि तन्नो वरुणः प्रचोदयात्॥', 'Om Jaladhipataye Vidmahe Varunaya Dhimahi Tanno Varunah Prachodayat', 'ॐ जलाधिपति को जानें, वरुण का ध्यान करें, वे वरुण हमें प्रेरित करें', 'Om, Let me meditate on the Lord of Waters, Give me higher intellect, Let Lord Varuna illuminate my mind', 12, '/audio/vedic/varuna_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1443, 'Varuna Beej Mantra', 'ॐ वं वरुणाय नमः', 'Om Vam Varunaya Namah', 'ॐ वं वरुण को नमन', 'Om Vam, Salutations to Varuna', 12, '/audio/vedic/varuna_beej.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1444, 'Rigvedic Varuna Sukta', 'वरुणो राजा वरुणो दिवो वरुणो मही। वरुणो राजा पृथिव्याः स्यन्दते वरुणः॥', 'Varuno Raja Varuno Divo Varuno Mahi Varuno Raja Prithivyah Syandate Varunah', 'वरुण राजा हैं, वरुण द्युलोक के हैं, वरुण मही के हैं। वरुण पृथ्वी के राजा हैं, वरुण प्रवाहित होते हैं', 'Varuna is the king, Varuna is of the sky, Varuna is of the earth. Varuna is the king of the earth, Varuna flows', 12, '/audio/vedic/varuna_rigveda1.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1445, 'Varuna Jalapati Mantra', 'ॐ जलपतये नमः', 'Om Jalapataye Namah', 'ॐ जलपति (वरुण) को नमन', 'Om, Salutations to the Lord of Waters', 12, '/audio/vedic/varuna_jalapati.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1446, 'Varuna Apah Mantra', 'ॐ अपां पतये नमः', 'Om Apam Pataye Namah', 'ॐ जलों के स्वामी (वरुण) को नमन', 'Om, Salutations to the Lord of Waters', 12, '/audio/vedic/varuna_apah.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1447, 'Varuna Pavana Mantra', 'ॐ वरुण पावय', 'Om Varuna Pavaya', 'ॐ वरुण, पवित्र करें', 'Om, O Varuna, purify', 12, '/audio/vedic/varuna_pavana.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1448, 'Varuna Abhisheka Mantra', 'ॐ वरुणाय अभिषिञ्चामि', 'Om Varunaya Abhishinchami', 'ॐ वरुण का अभिषेक करता हूं', 'Om, I perform abhisheka to Varuna', 12, '/audio/vedic/varuna_abhisheka.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1449, 'Varuna Shanti Mantra', 'ॐ शं नो वरुणः', 'Om Sham No Varunah', 'ॐ हमारे लिए वरुण कल्याणकारी हों', 'Om, May Varuna be auspicious for us', 12, '/audio/vedic/varuna_shanti.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1450, 'Varuna Rta Mantra', 'ॐ ऋतस्य वरुणः', 'Om Ritasya Varunah', 'ॐ ऋत (ब्रह्मांडीय व्यवस्था) के वरुण', 'Om, Varuna of Cosmic Order', 12, '/audio/vedic/varuna_rta.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1451, 'Yama Mool Mantra', 'ॐ यमाय नमः', 'Om Yamaya Namah', 'ॐ यम देव को नमन', 'Om, Salutations to Lord Yama', 12, '/audio/vedic/yama_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1452, 'Yama Pranam Mantra', 'ॐ नमो यमाय', 'Om Namo Yamaya', 'ॐ यम देव को प्रणाम', 'Om, Salutations to Lord Yama', 12, '/audio/vedic/yama_pranam.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1453, 'Yama Gayatri', 'ॐ सूर्यपुत्राय विद्महे महाकालाय धीमहि तन्नो यमः प्रचोदयात्॥', 'Om Suryaputraya Vidmahe Mahakalaya Dhimahi Tanno Yamah Prachodayat', 'ॐ सूर्यपुत्र को जानें, महाकाल का ध्यान करें, वे यम हमें प्रेरित करें', 'Om, Let me meditate on the Son of the Sun, Give me higher intellect, Let Lord Yama illuminate my mind', 12, '/audio/vedic/yama_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1454, 'Yama Beej Mantra', 'ॐ यं यमाय नमः', 'Om Yam Yamaya Namah', 'ॐ यं यम को नमन', 'Om Yam, Salutations to Yama', 12, '/audio/vedic/yama_beej.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1455, 'Rigvedic Yama Sukta', 'यमो राजा यमो दिवो यमः पृथिव्याः। यमो विश्वस्माद्धावते', 'Yamo Raja Yamo Divo Yamah Prithivyah Yamo Vishvasmadhavate', 'यम राजा हैं, यम द्युलोक के हैं, यम पृथ्वी के हैं। यम सभी से दूर भागते हैं', 'Yama is the king, Yama is of the sky, Yama is of the earth. Yama runs from all', 12, '/audio/vedic/yama_rigveda1.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1456, 'Yama Dharmaraja Mantra', 'ॐ धर्मराजाय नमः', 'Om Dharmarajaya Namah', 'ॐ धर्मराज (यम) को नमन', 'Om, Salutations to the King of Dharma', 12, '/audio/vedic/yama_dharmaraja.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1457, 'Yama Antaka Mantra', 'ॐ अन्तकाय नमः', 'Om Antakaya Namah', 'ॐ अन्तक (यम) को नमन', 'Om, Salutations to the Destroyer (Yama)', 12, '/audio/vedic/yama_antaka.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1458, 'Yama Mrityunjaya', 'ॐ यमाय मृत्युंजयाय नमः', 'Om Yamaya Mrityunjayaya Namah', 'ॐ यम, मृत्युंजय को नमन', 'Om, Salutations to Yama, the Conqueror of Death', 12, '/audio/vedic/yama_mrityunjaya.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1459, 'Yama Shanti Mantra', 'ॐ शं नो यमः', 'Om Sham No Yamah', 'ॐ हमारे लिए यम कल्याणकारी हों', 'Om, May Yama be auspicious for us', 12, '/audio/vedic/yama_shanti.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1460, 'Yama Pitri Mantra', 'ॐ पितृभ्यो यमाय नमः', 'Om Pitribhyo Yamaya Namah', 'ॐ पितरों और यम को नमन', 'Om, Salutations to the Ancestors and Yama', 12, '/audio/vedic/yama_pitri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1461, 'Kubera Mool Mantra', 'ॐ कुबेराय नमः', 'Om Kuberaya Namah', 'ॐ कुबेर देव को नमन', 'Om, Salutations to Lord Kubera', 12, '/audio/vedic/kubera_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1462, 'Kubera Pranam Mantra', 'ॐ नमो कुबेराय', 'Om Namo Kuberaya', 'ॐ कुबेर देव को प्रणाम', 'Om, Salutations to Lord Kubera', 12, '/audio/vedic/kubera_pranam.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1463, 'Kubera Gayatri', 'ॐ यक्षराजाय विद्महे धनाधिपतये धीमहि तन्नो कुबेरः प्रचोदयात्॥', 'Om Yaksharajaya Vidmahe Dhanadhipataye Dhimahi Tanno Kuberah Prachodayat', 'ॐ यक्षराज को जानें, धनाधिपति का ध्यान करें, वे कुबेर हमें प्रेरित करें', 'Om, Let me meditate on the King of Yakshas, Give me higher intellect, Let Lord Kubera illuminate my mind', 12, '/audio/vedic/kubera_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1464, 'Kubera Beej Mantra', 'ॐ कुं कुबेराय नमः', 'Om Kum Kuberaya Namah', 'ॐ कुं कुबेर को नमन', 'Om Kum, Salutations to Kubera', 12, '/audio/vedic/kubera_beej.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1465, 'Kubera Dhana Mantra', 'ॐ श्रीं ह्रीं कुबेराय नमः', 'Om Shreem Hreem Kuberaya Namah', 'ॐ श्रीं ह्रीं कुबेर को नमन - धन प्राप्ति के लिए', 'Om Shreem Hreem, Salutations to Kubera for wealth', 12, '/audio/vedic/kubera_dhana.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1466, 'Kubera Lakshmi Mantra', 'ॐ कुबेराय विद्महे धनधान्याधिपतये धीमहि तन्नो कुबेरः प्रचोदयात्॥', 'Om Kuberaya Vidmahe Dhanadhyadhipataye Dhimahi Tanno Kuberah Prachodayat', 'ॐ कुबेर को जानें, धन-धान्य के अधिपति का ध्यान करें, वे कुबेर हमें प्रेरित करें', 'Om, Let me meditate on Kubera, Give me higher intellect, Let Lord Kubera illuminate my mind', 12, '/audio/vedic/kubera_lakshmi.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1467, 'Kubera Nidhi Mantra', 'ॐ कुबेराय निधिपतये नमः', 'Om Kuberaya Nidhipataye Namah', 'ॐ कुबेर, निधियों के स्वामी को नमन', 'Om, Salutations to Kubera, the Lord of Treasures', 12, '/audio/vedic/kubera_nidhi.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1468, 'Kubera Samriddhi Mantra', 'ॐ कुबेराय समृद्धिप्रदाय नमः', 'Om Kuberaya Samriddhipradaya Namah', 'ॐ कुबेर, समृद्धि प्रदान करने वाले को नमन', 'Om, Salutations to Kubera, the giver of prosperity', 12, '/audio/vedic/kubera_samriddhi.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1469, 'Kubera Aishwarya Mantra', 'ॐ कुबेराय ऐश्वर्यप्रदाय नमः', 'Om Kuberaya Aishwaryapradaya Namah', 'ॐ कुबेर, ऐश्वर्य प्रदान करने वाले को नमन', 'Om, Salutations to Kubera, the giver of opulence', 12, '/audio/vedic/kubera_aishwarya.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1470, 'Soma Mool Mantra', 'ॐ सोमाय नमः', 'Om Somaya Namah', 'ॐ सोम देव को नमन', 'Om, Salutations to Lord Soma', 12, '/audio/vedic/soma_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1471, 'Soma Gayatri', 'ॐ सोमाय विद्महे अमृतत्वाय धीमहि तन्नो चन्द्रः प्रचोदयात्॥', 'Om Somaya Vidmahe Amritatvaya Dhimahi Tanno Chandrah Prachodayat', 'ॐ सोम को जानें, अमृतत्व का ध्यान करें, वे चन्द्र हमें प्रेरित करें', 'Om, Let me meditate on Soma, Give me higher intellect, Let Lord Chandra illuminate my mind', 12, '/audio/vedic/soma_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1472, 'Pushan Mool Mantra', 'ॐ पूष्णे नमः', 'Om Pushne Namah', 'ॐ पूषण देव को नमन', 'Om, Salutations to Lord Pushan', 12, '/audio/vedic/pushan_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1473, 'Pushan Gayatri', 'ॐ पूष्णे विद्महे पथिकृते धीमहि तन्नो पूषा प्रचोदयात्॥', 'Om Pushne Vidmahe Pathikrite Dhimahi Tanno Pusha Prachodayat', 'ॐ पूषण को जानें, पथिकृत का ध्यान करें, वे पूषा हमें प्रेरित करें', 'Om, Let me meditate on Pushan, Give me higher intellect, Let Lord Pushan illuminate my mind', 12, '/audio/vedic/pushan_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1474, 'Ashwini Kumara Mantra', 'ॐ अश्विभ्यां नमः', 'Om Ashvibhyam Namah', 'ॐ अश्विनी कुमारों को नमन', 'Om, Salutations to the Ashwini Twins', 12, '/audio/vedic/ashwini_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1475, 'Ashwini Gayatri', 'ॐ अश्विनोः विद्महे नासत्योः धीमहि तन्नो अश्विनौ प्रचोदयाताम्॥', 'Om Ashvinoh Vidmahe Nasatyoh Dhimahi Tanno Ashvinau Prachodayatam', 'ॐ अश्विनी कुमारों को जानें, नासत्यों का ध्यान करें, वे अश्विनी हमें प्रेरित करें', 'Om, Let me meditate on the Ashwini Twins, Give me higher intellect, Let the Ashwini Kumaras illuminate my minds', 12, '/audio/vedic/ashwini_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1476, 'Mitra Mool Mantra', 'ॐ मित्राय नमः', 'Om Mitraya Namah', 'ॐ मित्र देव को नमन', 'Om, Salutations to Lord Mitra', 12, '/audio/vedic/mitra_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1477, 'Mitra Gayatri', 'ॐ मित्राय विद्महे प्रियाय धीमहि तन्नो मित्रः प्रचोदयात्॥', 'Om Mitraya Vidmahe Priyaya Dhimahi Tanno Mitrah Prachodayat', 'ॐ मित्र को जानें, प्रिय का ध्यान करें, वे मित्र हमें प्रेरित करें', 'Om, Let me meditate on Mitra, Give me higher intellect, Let Lord Mitra illuminate my mind', 12, '/audio/vedic/mitra_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1478, 'Vishvedeva Mantra', 'ॐ विश्वेभ्यो देवेभ्यो नमः', 'Om Vishvebhyo Devebhyo Namah', 'ॐ सभी देवताओं को नमन', 'Om, Salutations to All the Gods', 12, '/audio/vedic/vishvedeva_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1479, 'Vishvedeva Gayatri', 'ॐ विश्वेभ्यो देवेभ्यो विद्महे सर्वदेवाय धीमहि तन्नो देवाः प्रचोदयान्॥', 'Om Vishvebhyo Devebhyo Vidmahe Sarvadevaya Dhimahi Tanno Devah Prachodayan', 'ॐ सभी देवताओं को जानें, सर्वदेव का ध्यान करें, सभी देव हमें प्रेरित करें', 'Om, Let me meditate on all the Gods, Give me higher intellect, Let all the Gods illuminate my mind', 12, '/audio/vedic/vishvedeva_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1480, 'Savita Mool Mantra', 'ॐ सवित्रे नमः', 'Om Savitre Namah', 'ॐ सविता देव को नमन', 'Om, Salutations to Lord Savita', 12, '/audio/vedic/savita_mool.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1481, 'Savita Gayatri', 'ॐ सवित्रे विद्महे सहस्रकिरणाय धीमहि तन्नो सविता प्रचोदयात्॥', 'Om Savitre Vidmahe Sahasrakiranaya Dhimahi Tanno Savita Prachodayat', 'ॐ सविता को जानें, सहस्रकिरण का ध्यान करें, वे सविता हमें प्रेरित करें', 'Om, Let me meditate on Savita, Give me higher intellect, Let Lord Savita illuminate my mind', 12, '/audio/vedic/savita_gayatri.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1482, 'Sarva Deva Pranam', 'ॐ नमो देवेभ्यः', 'Om Namo Devebhya', 'ॐ सभी देवताओं को नमन', 'Om, Salutations to All the Gods', 12, '/audio/vedic/sarva_deva_pranam.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1483, 'Gayatri Mantra', 'ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि धियो यो नः प्रचोदयात्॥', 'Om Bhur Bhuvah Svah Tat Savitur Varenyam Bhargo Devasya Dhimahi Dhiyo Yo Nah Prachodayat', 'ॐ भूः, भुवः, स्वः, उस प्राणस्वरूप देव के वरणीय तेज का हम ध्यान करते हैं, वे हमारी बुद्धि को प्रेरित करें', 'Om, We meditate on the glory of the Creator, who has created the universe, who is worthy of worship, who is the embodiment of knowledge and light, who removes all sins and ignorance, may he enlighten our intellect', 12, '/audio/vedic/gayatri_mantra.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1484, 'Shanti Mantra - Om Shanti', 'ॐ शान्तिः शान्तिः शान्तिः', 'Om Shantih Shantih Shantih', 'ॐ शांति, शांति, शांति', 'Om, Peace, Peace, Peace', 12, '/audio/vedic/shanti_mantra1.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1485, 'Shanti Mantra - Dyau Shanti', 'द्यौः शान्तिरन्तरिक्षं शान्तिः पृथिवी शान्तिरापः शान्तिरोषधयः शान्तिः। वनस्पतयः शान्तिर्विश्वे देवाः शान्तिर्ब्रह्म शान्तिः सर्वं शान्तिः शान्तिरेव शान्तिः सा मा शान्तिरेधि॥', 'Dyauh Shantirantariksham Shantih Prithivi Shantir Apah Shantir Oshadhayah Shantih Vanaspatayah Shantir Vishve Devah Shantir Brahma Shantih Sarvam Shantih Shantireva Shantih Sa Ma Shantiredhi', 'आकाश शांत हो, अंतरिक्ष शांत हो, पृथ्वी शांत हो, जल शांत हो, औषधियां शांत हों, वनस्पतियां शांत हों, सभी देवता शांत हों, ब्रह्म शांत हो, सब कुछ शांत हो, केवल शांति ही शांति हो, वह शांति मुझे प्राप्त हो', 'May the sky be peaceful, may the space be peaceful, may the earth be peaceful, may the waters be peaceful, may the herbs be peaceful, may the plants be peaceful, may all gods be peaceful, may Brahman be peaceful, may everything be peaceful, peace alone is peace, may that peace come to me', 12, '/audio/vedic/shanti_mantra2.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1486, 'Vedic Invocation - Agni', 'ॐ अग्निर्मूर्धा दिवः', 'Om Agnirmurdha Divah', 'ॐ अग्नि दिव्य शिरा हैं', 'Om, Agni is the head of the sky', 12, '/audio/vedic/vedic_invocation1.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1487, 'Vedic Invocation - Surya', 'ॐ आप्यायस्व समेतु ते', 'Om Apyayasva Sametu Te', 'ॐ आप पुष्ट हों, आप सब एकत्र हों', 'Om, May you be nourished, may all come together for you', 12, '/audio/vedic/vedic_invocation2.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1488, 'Vedic Ashirvad', 'ॐ स्वस्ति न इन्द्रो वृद्धश्रवाः स्वस्ति नः पूषा विश्ववेदाः। स्वस्ति नस्तार्क्ष्यो अरिष्टनेमिः स्वस्ति नो बृहस्पतिर्दधातु॥', 'Om Svasti Na Indro Vriddhashravah Svasti Nah Pusha Vishvavedah Svasti Nastarkshyo Arishtanemih Svasti No Brihaspatirdadhatu', 'ॐ इन्द्र, जिनकी कीर्ति वृद्ध है, हमारा कल्याण करें। पूषा, जो सर्वज्ञ हैं, हमारा कल्याण करें। तार्क्ष्य (गरुड़), जिनकी गति अरिष्ट (अनिष्ट) से रहित है, हमारा कल्याण करें। बृहस्पति हमारा कल्याण करें', 'Om, May Indra of widespread fame grant us well-being. May Pushan, the all-knower, grant us well-being. May Tarkshya (Garuda), who moves without harm, grant us well-being. May Brihaspati grant us well-being', 12, '/audio/vedic/vedic_ashirvad.mp3', 0, 0, '2026-03-23 03:15:21', NULL, NULL, NULL, NULL, NULL, NULL),
(1489, 'Ayyappa Mool Mantra', 'ॐ स्वामी अय्यप्पाय नमः', 'Om Swami Ayyappaya Namah', 'ॐ स्वामी अय्यप्पा को नमन', 'Om, Salutations to Lord Ayyappa', 13, '/audio/regional/ayyappa_mool.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1490, 'Ayyappa Pranam Mantra', 'ॐ नमो अय्यप्पाय', 'Om Namo Ayyappaya', 'ॐ अय्यप्पा को प्रणाम', 'Om, Salutations to Lord Ayyappa', 13, '/audio/regional/ayyappa_pranam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1491, 'Ayyappa Beej Mantra', 'ॐ स्वामिये शरणमय्यप्पा', 'Om Swamiye Sharanam Ayyappa', 'ॐ स्वामिये शरणम अय्यप्पा', 'Om, I take refuge in Lord Ayyappa', 13, '/audio/regional/ayyappa_beej.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1492, 'Ayyappa Gayatri', 'ॐ धर्मशास्त्रे विद्महे हरिहरपुत्राय धीमहि तन्नो अय्यप्पः प्रचोदयात्॥', 'Om Dharmashastre Vidmahe Hariharaputraya Dhimahi Tanno Ayyappah Prachodayat', 'ॐ धर्मशास्त्र स्वरूप को जानें, हरिहर पुत्र का ध्यान करें, वे अय्यप्पा हमें प्रेरित करें', 'Om, Let me meditate on the embodiment of Dharma, Give me higher intellect, Let Lord Ayyappa illuminate my mind', 13, '/audio/regional/ayyappa_gayatri.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1493, 'Sharanam Ayyappa', 'स्वामिये शरणमय्यप्पा', 'Swamiye Sharanam Ayyappa', 'स्वामिये शरणम अय्यप्पा', 'O Lord, I take refuge in you, Ayyappa', 13, '/audio/regional/sharanam_ayyappa.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1494, 'Ayyappa Sharanam Mantra', 'ॐ अय्यप्प शरणं', 'Om Ayyappa Sharanam', 'ॐ अय्यप्पा शरणं', 'Om, Refuge in Ayyappa', 13, '/audio/regional/ayyappa_sharanam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1495, 'Ayyappa Ashtakshari', 'ॐ स्वामी अय्यप्पा', 'Om Swami Ayyappa', 'ॐ स्वामी अय्यप्पा', 'Om, Lord Ayyappa', 13, '/audio/regional/ayyappa_ashtakshari.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1496, 'Ayyappa Kavacham', 'ॐ अय्यप्पाय कवचं', 'Om Ayyappaya Kavacham', 'ॐ अय्यप्पा का कवच', 'Om, The armor of Ayyappa', 13, '/audio/regional/ayyappa_kavacham.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1497, 'Ayyappa Raksha Mantra', 'ॐ अय्यप्पाय रक्ष रक्ष', 'Om Ayyappaya Raksha Raksha', 'ॐ अय्यप्पा, रक्षा करो, रक्षा करो', 'Om, O Ayyappa, protect, protect', 13, '/audio/regional/ayyappa_raksha.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1498, 'Ayyappa Stotram', 'श्रीमहाशास्त्रे नमस्तुभ्यं हरिहरप्रियाय च। सत्यव्रताय शुद्धाय शरणं ते सदा गतः॥', 'Shrimahashastre Namastubhyam Hariharapriyaya Cha Satyavrataya Shuddhaya Sharanam Te Sada Gatah', 'श्री महाशास्त्र स्वरूप, आपको नमन, हरिहरप्रिय, सत्यव्रत, शुद्ध, आपकी शरण में सदा हूं', 'Salutations to the great Shastra, beloved of Hari and Hara, the truth-vowed, the pure one, I have always taken refuge in you', 13, '/audio/regional/ayyappa_stotram.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1499, 'Ayyappa Dhyana Mantra', 'ॐ हरिहरपुत्रं महाशास्तारं सत्यव्रतं शुद्धचरित्रं। ध्यायेत् सदा मानससरोजे नीलाम्बरं शंखचक्रधरम्॥', 'Om Hariharaputram Mahashastaram Satyavratam Shuddhacharitram Dhyayet Sada Manasasaroje Nilambaram Shankhachakradharam', 'ॐ हरिहरपुत्र, महाशास्ता, सत्यव्रत, शुद्धचरित्र, नीलांबर, शंख-चक्र धारी का सदा ध्यान करें', 'Om, Meditate always on the son of Hari and Hara, the great Shasta, the truth-vowed, the pure-charactered, the blue-robed one, holding conch and discus', 13, '/audio/regional/ayyappa_dhyana.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1500, 'Venkateshwara Mool Mantra', 'ॐ नमो वेंकटेशाय', 'Om Namo Venkateshaya', 'ॐ वेंकटेश्वर को नमन', 'Om, Salutations to Lord Venkateshwara', 13, '/audio/regional/venkateshwara_mool.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1501, 'Venkateshwara Pranam', 'ॐ वेंकटेशाय नमः', 'Om Venkateshaya Namah', 'ॐ वेंकटेश्वर को नमन', 'Om, Salutations to Lord Venkateshwara', 13, '/audio/regional/venkateshwara_pranam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1502, 'Venkateshwara Beej Mantra', 'ॐ श्रीं वेंकटेशाय नमः', 'Om Shreem Venkateshaya Namah', 'ॐ श्रीं वेंकटेश्वर को नमन', 'Om Shreem, Salutations to Venkateshwara', 13, '/audio/regional/venkateshwara_beej.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1503, 'Venkateshwara Gayatri', 'ॐ नारायणाय विद्महे वेंकटेशाय धीमहि तन्नो वेंकटेशः प्रचोदयात्॥', 'Om Narayanaya Vidmahe Venkateshaya Dhimahi Tanno Venkateshah Prachodayat', 'ॐ नारायण को जानें, वेंकटेश का ध्यान करें, वे वेंकटेश हमें प्रेरित करें', 'Om, Let me meditate on Narayana, Give me higher intellect, Let Lord Venkateshwara illuminate my mind', 13, '/audio/regional/venkateshwara_gayatri.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1504, 'Govinda Mantra', 'ॐ गोविन्दाय नमः', 'Om Govindaya Namah', 'ॐ गोविंद को नमन', 'Om, Salutations to Govinda', 13, '/audio/regional/govinda_mantra.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1505, 'Venkateshwara Govinda', 'गोविंदा वेंकटेश्वरा', 'Govinda Venkateshwara', 'गोविंदा वेंकटेश्वरा', 'Govinda Venkateshwara', 13, '/audio/regional/venkateshwara_govinda.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1506, 'Venkateshwara Stotram', 'नमो वेंकटनाथाय नमो वेंकटवासिने। नमो वेंकटगिरिशे नमो वेंकटशायिने॥', 'Namo Venkatanathaya Namo Venkatavasine Namo Venkatagirisha Namo Venkatashayine', 'वेंकटनाथ को नमन, वेंकटवासी को नमन, वेंकटगिरीश को नमन, वेंकटशायी को नमन', 'Salutations to the Lord of Venkata, salutations to the dweller of Venkata, salutations to the Lord of Venkata Hill, salutations to the one who rests on Venkata', 13, '/audio/regional/venkateshwara_stotram.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1507, 'Venkateshwara Ashtakam', 'वेंकटाद्रिसमं स्थानं ब्रह्माण्डे नास्ति किञ्चन। वेंकटेशसमो देवो न भूतो न भविष्यति॥', 'Venkatadrisamam Sthanam Brahmande Nastikincana Venkateshasamo Devo Na Bhuto Na Bhavishyati', 'वेंकटाद्रि के समान स्थान ब्रह्मांड में नहीं है। वेंकटेश के समान देव न भूतो न भविष्यति', 'There is no place like Venkatadri in the entire universe. There was no god like Venkatesha in the past, nor will there be in the future', 13, '/audio/regional/venkateshwara_ashtakam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1508, 'Venkateshwara Dhana Mantra', 'ॐ श्रीं ह्रीं वेंकटेशाय नमः', 'Om Shreem Hreem Venkateshaya Namah', 'ॐ श्रीं ह्रीं वेंकटेश्वर को नमन', 'Om Shreem Hreem, Salutations to Venkateshwara for wealth', 13, '/audio/regional/venkateshwara_dhana.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1509, 'Vithoba Mool Mantra', 'ॐ नमो विठ्ठलाय', 'Om Namo Vitthalaya', 'ॐ विठ्ठल को नमन', 'Om, Salutations to Lord Vithoba', 13, '/audio/regional/vithoba_mool.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1510, 'Vithoba Pranam', 'ॐ विठ्ठलाय नमः', 'Om Vitthalaya Namah', 'ॐ विठ्ठल को नमन', 'Om, Salutations to Vithoba', 13, '/audio/regional/vithoba_pranam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1511, 'Vithoba Beej Mantra', 'ॐ विठ्ठल', 'Om Vitthala', 'ॐ विठ्ठल', 'Om, Vithala', 13, '/audio/regional/vithoba_beej.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1512, 'Vithoba Gayatri', 'ॐ विठ्ठलाय विद्महे पांडुरंगाय धीमहि तन्नो विठ्ठलः प्रचोदयात्॥', 'Om Vitthalaya Vidmahe Pandurangaya Dhimahi Tanno Vitthalah Prachodayat', 'ॐ विठ्ठल को जानें, पांडुरंग का ध्यान करें, वे विठ्ठल हमें प्रेरित करें', 'Om, Let me meditate on Vithoba, Give me higher intellect, Let Lord Vithoba illuminate my mind', 13, '/audio/regional/vithoba_gayatri.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1513, 'Panduranga Mantra', 'ॐ पांडुरंगाय नमः', 'Om Pandurangaya Namah', 'ॐ पांडुरंग को नमन', 'Om, Salutations to Panduranga', 13, '/audio/regional/panduranga_mantra.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1514, 'Panduranga Ashtakshari', 'ॐ नमो पांडुरंगाय', 'Om Namo Pandurangaya', 'ॐ पांडुरंग को नमन', 'Om, Salutations to Panduranga', 13, '/audio/regional/panduranga_ashtakshari.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1515, 'Vithoba Stotram', 'विठ्ठल विठ्ठल जय विठ्ठल। पांडुरंग रखुमाई वल्लभ॥', 'Vitthala Vitthala Jaya Vitthala Panduranga Rakhumai Vallabha', 'विठ्ठल विठ्ठल जय विठ्ठल। पांडुरंग रखुमाई वल्लभ', 'Vitthala Vitthala Victory to Vitthala, Panduranga, beloved of Rakhumai', 13, '/audio/regional/vithoba_stotram.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1516, 'Vithoba Dhyana', 'ॐ पांडुरंगाय विद्महे रखुमाईप्रियाय धीमहि तन्नो विठ्ठलः प्रचोदयात्॥', 'Om Pandurangaya Vidmahe Rakhumaipriyaya Dhimahi Tanno Vitthalah Prachodayat', 'ॐ पांडुरंग को जानें, रखुमाईप्रिय का ध्यान करें, वे विठ्ठल हमें प्रेरित करें', 'Om, Let me meditate on Panduranga, Give me higher intellect, Let Lord Vithoba illuminate my mind', 13, '/audio/regional/vithoba_dhyana.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1517, 'Vithoba Bhakti Mantra', 'ॐ विठ्ठल भक्तिप्रदाय नमः', 'Om Vitthala Bhaktipradaya Namah', 'ॐ विठ्ठल, भक्ति प्रदान करने वाले को नमन', 'Om, Salutations to Vithoba, the giver of devotion', 13, '/audio/regional/vithoba_bhakti.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1518, 'Jagannath Mool Mantra', 'ॐ जगन्नाथाय नमः', 'Om Jagannathaya Namah', 'ॐ जगन्नाथ को नमन', 'Om, Salutations to Lord Jagannath', 13, '/audio/regional/jagannath_mool.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1519, 'Jagannath Pranam', 'ॐ नमो जगन्नाथाय', 'Om Namo Jagannathaya', 'ॐ जगन्नाथ को प्रणाम', 'Om, Salutations to Lord Jagannath', 13, '/audio/regional/jagannath_pranam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1520, 'Jagannath Beej Mantra', 'ॐ जगन्नाथ', 'Om Jagannatha', 'ॐ जगन्नाथ', 'Om, Lord of the Universe', 13, '/audio/regional/jagannath_beej.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1521, 'Jagannath Gayatri', 'ॐ जगन्नाथाय विद्महे नीलचक्राय धीमहि तन्नो जगन्नाथः प्रचोदयात्॥', 'Om Jagannathaya Vidmahe Nilachakraya Dhimahi Tanno Jagannathah Prachodayat', 'ॐ जगन्नाथ को जानें, नीलचक्र का ध्यान करें, वे जगन्नाथ हमें प्रेरित करें', 'Om, Let me meditate on the Lord of the Universe, Give me higher intellect, Let Lord Jagannath illuminate my mind', 13, '/audio/regional/jagannath_gayatri.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1522, 'Jagannath Trio Mantra', 'ॐ जगन्नाथ बलभद्र सुभद्रायै नमः', 'Om Jagannatha Balabhadra Subhadrayai Namah', 'ॐ जगन्नाथ, बलभद्र, सुभद्रा को नमन', 'Om, Salutations to Jagannath, Balabhadra, and Subhadra', 13, '/audio/regional/jagannath_trio.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1523, 'Balabhadra Mantra', 'ॐ बलभद्राय नमः', 'Om Balabhadraya Namah', 'ॐ बलभद्र को नमन', 'Om, Salutations to Balabhadra', 13, '/audio/regional/balabhadra.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1524, 'Subhadra Mantra', 'ॐ सुभद्रायै नमः', 'Om Subhadrayai Namah', 'ॐ सुभद्रा को नमन', 'Om, Salutations to Subhadra', 13, '/audio/regional/subhadra.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1525, 'Jagannath Stotram', 'जगन्नाथ स्वयं रामो जगन्नाथो हरिः स्वयम्। जगन्नाथो गदापाणिः जगन्नाथः सनातनः॥', 'Jagannatha Svayam Ramo Jagannatho Harih Svayam Jagannatho Gadapanih Jagannathah Sanatanah', 'जगन्नाथ स्वयं राम हैं, जगन्नाथ हरि स्वयं हैं। जगन्नाथ गदाधारी हैं, जगन्नाथ सनातन हैं', 'Jagannath is Rama himself, Jagannath is Hari himself. Jagannath is the wielder of the mace, Jagannath is eternal', 13, '/audio/regional/jagannath_stotram.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1526, 'Jagannath Dhyana', 'ॐ नीलांजनसमाभासं रत्नसिंहासनस्थितम्। जगन्नाथं चतुर्बाहुं भक्तानुग्रहकारकम्॥', 'Om Neelanjana Samabhasam Ratnasinghasanasthitam Jagannatham Chaturbahum Bhaktanugrahakarakam', 'ॐ नीलांजन के समान कांति वाले, रत्न सिंहासन पर स्थित, चतुर्भुज, भक्तों पर अनुग्रह करने वाले जगन्नाथ का ध्यान करें', 'Om, Meditate on Jagannath, who shines like blue collyrium, seated on a jeweled throne, four-armed, who bestows grace upon devotees', 13, '/audio/regional/jagannath_dhyana.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1527, 'Murugan Mool Mantra', 'ॐ सुब्रह्मण्याय नमः', 'Om Subrahmanyaya Namah', 'ॐ सुब्रह्मण्य (मुरुगन) को नमन', 'Om, Salutations to Lord Subrahmanya (Murugan)', 13, '/audio/regional/murugan_mool.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1528, 'Murugan Pranam', 'ॐ नमो सुब्रह्मण्याय', 'Om Namo Subrahmanyaya', 'ॐ सुब्रह्मण्य को प्रणाम', 'Om, Salutations to Subrahmanya', 13, '/audio/regional/murugan_pranam.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1529, 'Murugan Beej Mantra', 'ॐ सरवणभवाय नमः', 'Om Saravanabhavaya Namah', 'ॐ सरवणभव (मुरुगन) को नमन', 'Om, Salutations to Saravanabhava (Murugan)', 13, '/audio/regional/murugan_beej.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1530, 'Murugan Gayatri', 'ॐ तत्पुरुषाय विद्महे सुब्रह्मण्याय धीमहि तन्नो मुरुगन् प्रचोदयात्॥', 'Om Tatpurushaya Vidmahe Subrahmanyaya Dhimahi Tanno Murugan Prachodayat', 'ॐ तत्पुरुष को जानें, सुब्रह्मण्य का ध्यान करें, वे मुरुगन हमें प्रेरित करें', 'Om, Let me meditate on the Supreme Person, Give me higher intellect, Let Lord Murugan illuminate my mind', 13, '/audio/regional/murugan_gayatri.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1531, 'Vel Mantra', 'ॐ वेलाय नमः', 'Om Velaya Namah', 'ॐ वेल (मुरुगन के भाले) को नमन', 'Om, Salutations to the Vel (Murugan\'s spear)', 13, '/audio/regional/vel_mantra.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1532, 'Vel Mayil Mantra', 'ॐ वेल् मयिल् वाहनाय नमः', 'Om Vel Mayil Vahanaya Namah', 'ॐ वेल, मयिल (मोर) वाहन को नमन', 'Om, Salutations to the one with Vel and Peacock vehicle', 13, '/audio/regional/vel_mayil.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1533, 'Kanda Sashti Kavasam', 'कन्दं कन्दं कन्दं कन्दं कन्दं कन्दं कन्दमेन। कन्दं कन्दं कन्दं कन्दं कन्दमेन कन्दमेन॥', 'Kandam Kandam Kandam Kandam Kandam Kandam Kandamena Kandam Kandam Kandam Kandam Kandamena Kandamena', 'कन्दं कन्दं कन्दं कन्दं कन्दं कन्दं कन्दमेन। कन्दं कन्दं कन्दं कन्दं कन्दमेन कन्दमेन॥', 'The powerful armor of Lord Murugan - chanting his name for protection', 13, '/audio/regional/kanda_sashti.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1534, 'Murugan Stotram', 'सुब्रह्मण्यं सुब्रह्मण्यं सुब्रह्मण्यं नमाम्यहम्। सुब्रह्मण्यं सुब्रह्मण्यं सुब्रह्मण्यं नमाम्यहम्॥', 'Subrahmanyam Subrahmanyam Subrahmanyam Namamyaham Subrahmanyam Subrahmanyam Subrahmanyam Namamyaham', 'सुब्रह्मण्य, सुब्रह्मण्य, सुब्रह्मण्य को मैं नमन करता हूं', 'Subrahmanya, Subrahmanya, Subrahmanya I bow to you', 13, '/audio/regional/murugan_stotram.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1535, 'Murugan Dhyana', 'ॐ षडाननं कुंकुमरंजितांगं महामुनिं दिव्यमयूरवाहनम्। रुद्रस्य सूनुं सुरसैन्यनाथं गुहं सदा शरणमहं प्रपद्ये॥', 'Om Shadananam Kumkumarajitangam Mahamunim Divyamayuravahanam Rudrasya Sunum Surasainyanatham Guham Sada Sharanamaham Prapadye', 'ॐ षडानन, कुंकुम से रंजित अंग, महामुनि, दिव्य मोर वाहन, रुद्र के पुत्र, देवसेनापति, गुह की मैं शरण ग्रहण करता हूं', 'Om, I take refuge in the six-faced one, whose body is adorned with kumkum, the great sage, with the divine peacock as vehicle, the son of Rudra, commander of the celestial army, Guha', 13, '/audio/regional/murugan_dhyana.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1536, 'Siddhivinayak Mantra', 'ॐ सिद्धिविनायकाय नमः', 'Om Siddhivinayakaya Namah', 'ॐ सिद्धिविनायक को नमन', 'Om, Salutations to Siddhivinayak', 13, '/audio/regional/siddhivinayak.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1537, 'Kholeshwar Ganesh Mantra', 'ॐ खोलेश्वराय नमः', 'Om Kholeshvaraya Namah', 'ॐ खोलेश्वर गणेश को नमन', 'Om, Salutations to Kholeshwar Ganesh', 13, '/audio/regional/kholeshwar.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1538, 'Ucchi Pillayar Mantra', 'ॐ उच्चि पिल्लैयाराय नमः', 'Om Ucchi Pillaiyaraya Namah', 'ॐ उच्चि पिल्लैयार गणेश को नमन', 'Om, Salutations to Ucchi Pillaiyar', 13, '/audio/regional/ucchi_pillaiyar.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1539, 'Vatapi Ganapati Mantra', 'ॐ वातापि गणपतये नमः', 'Om Vatapi Ganapataye Namah', 'ॐ वातापि गणपति को नमन', 'Om, Salutations to Vatapi Ganapati', 13, '/audio/regional/vatapi_ganapati.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1540, 'Heramba Ganapati Mantra', 'ॐ हेरम्बाय नमः', 'Om Herambaya Namah', 'ॐ हेरम्ब गणेश को नमन', 'Om, Salutations to Heramba Ganapati', 13, '/audio/regional/heramba.mp3', 0, 0, '2026-03-23 03:15:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1541, 'Mariamman Mool Mantra', 'ॐ मरियम्मन् नमः', 'Om Mariamman Namah', 'ॐ मरियम्मन को नमन', 'Om, Salutations to Goddess Mariamman', 13, '/audio/regional/mariamman_mool.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1542, 'Mariamman Gayatri', 'ॐ मरियम्मायै विद्महे रोगहारिण्यै धीमहि तन्नो मरियम्मन् प्रचोदयात्॥', 'Om Mariammayai Vidmahe Rogaharinyai Dhimahi Tanno Mariamman Prachodayat', 'ॐ मरियम्मन को जानें, रोगहारिणी का ध्यान करें, वे मरियम्मन हमें प्रेरित करें', 'Om, Let me meditate on Mariamman, Give me higher intellect, Let Goddess Mariamman illuminate my mind', 13, '/audio/regional/mariamman_gayatri.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1543, 'Yellamma Mantra', 'ॐ येल्लम्मा नमः', 'Om Yellamma Namah', 'ॐ येल्लम्मा को नमन', 'Om, Salutations to Yellamma', 13, '/audio/regional/yellamma.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1544, 'Mhasoba Mantra', 'ॐ म्हसोबाय नमः', 'Om Mhasobaya Namah', 'ॐ म्हसोबा को नमन', 'Om, Salutations to Mhasoba', 13, '/audio/regional/mhasoba.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1545, 'Khandoba Mantra', 'ॐ खण्डोबाय नमः', 'Om Khandobaya Namah', 'ॐ खंडोबा को नमन', 'Om, Salutations to Khandoba', 13, '/audio/regional/khandoba.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1546, 'Ranganatha Mantra', 'ॐ रंगनाथाय नमः', 'Om Ranganathaya Namah', 'ॐ रंगनाथ को नमन', 'Om, Salutations to Lord Ranganatha', 13, '/audio/regional/ranganatha.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1547, 'Padmanabhaswamy Mantra', 'ॐ पद्मनाभस्वामिने नमः', 'Om Padmanabhaswamine Namah', 'ॐ पद्मनाभस्वामी को नमन', 'Om, Salutations to Lord Padmanabhaswamy', 13, '/audio/regional/padmanabhaswamy.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1548, 'Guruvayurappan Mantra', 'ॐ गुरुवायुरप्पन नमः', 'Om Guruvayurappana Namah', 'ॐ गुरुवायुरप्पन को नमन', 'Om, Salutations to Guruvayurappan', 13, '/audio/regional/guruvayurappan.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1549, 'Dwarakadhisha Mantra', 'ॐ द्वारकाधीशाय नमः', 'Om Dwarakadhishaya Namah', 'ॐ द्वारकाधीश को नमन', 'Om, Salutations to the Lord of Dwarka', 13, '/audio/regional/dwarakadhisha.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1550, 'Kamakhya Mantra', 'ॐ कामाख्यायै नमः', 'Om Kamakhyayai Namah', 'ॐ कामाख्या देवी को नमन', 'Om, Salutations to Goddess Kamakhya', 13, '/audio/regional/kamakhya.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1551, 'Kamakhya Beej Mantra', 'ॐ ऐं ह्रीं क्लीं कामाख्यायै नमः', 'Om Aim Hreem Kleem Kamakhyayai Namah', 'ॐ ऐं ह्रीं क्लीं कामाख्या देवी को नमन', 'Om Aim Hreem Kleem, Salutations to Goddess Kamakhya', 13, '/audio/regional/kamakhya_beej.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1552, 'Vaishno Devi Mantra', 'ॐ वैष्णव्यै नमः', 'Om Vaishnavyai Namah', 'ॐ वैष्णो देवी को नमन', 'Om, Salutations to Vaishno Devi', 13, '/audio/regional/vaishno_devi.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1553, 'Meenakshi Mantra', 'ॐ मीनाक्ष्यै नमः', 'Om Meenakshyai Namah', 'ॐ मीनाक्षी देवी को नमन', 'Om, Salutations to Goddess Meenakshi', 13, '/audio/regional/meenakshi.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1554, 'Meenakshi Gayatri', 'ॐ मीनाक्ष्यै विद्महे कन्याकुमार्यै धीमहि तन्नो मीनाक्षी प्रचोदयात्॥', 'Om Meenakshyai Vidmahe Kanyakumaryai Dhimahi Tanno Meenakshi Prachodayat', 'ॐ मीनाक्षी को जानें, कन्याकुमारी का ध्यान करें, वे मीनाक्षी हमें प्रेरित करें', 'Om, Let me meditate on Meenakshi, Give me higher intellect, Let Goddess Meenakshi illuminate my mind', 13, '/audio/regional/meenakshi_gayatri.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1555, 'Sai Baba Mantra', 'ॐ साईं नाथाय नमः', 'Om Sai Nathaya Namah', 'ॐ साईं नाथ को नमन', 'Om, Salutations to Sai Nath', 13, '/audio/regional/sai_baba.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1556, 'Sai Baba Gayatri', 'ॐ साईं नाथाय विद्महे सच्चिदानन्दाय धीमहि तन्नो साईं प्रचोदयात्॥', 'Om Sai Nathaya Vidmahe Satchidanandaya Dhimahi Tanno Sai Prachodayat', 'ॐ साईं नाथ को जानें, सच्चिदानंद का ध्यान करें, वे साईं हमें प्रेरित करें', 'Om, Let me meditate on Sai Nath, Give me higher intellect, Let Sai Baba illuminate my mind', 13, '/audio/regional/sai_baba_gayatri.mp3', 0, 0, '2026-03-23 03:15:40', NULL, NULL, NULL, NULL, NULL, NULL),
(1557, 'Purusha Sukta - Verse 1', 'सहस्रशीर्षा पुरुषः सहस्राक्षः सहस्रपात्। स भूमिं विश्वतो वृत्वा अत्यतिष्ठद्दशाङ्गुलम्॥', 'Sahasrashirsha Purushah Sahasrakshah Sahasrapat Sa Bhumim Vishvato Vritva Atatishthad Dashangulam', 'सहस्र शीर्ष वाले, सहस्र नेत्र वाले, सहस्र चरण वाले पुरुष ने पृथ्वी को सभी ओर से आच्छादित कर दस अंगुल (मात्र) से अधिक शेष रह गए', 'The Purusha has a thousand heads, a thousand eyes, a thousand feet. He pervades the earth from all sides and extends beyond it by ten fingers', 14, '/audio/vedic_suktas/purusha_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1558, 'Purusha Sukta - Verse 2', 'पुरुष एवेदं सर्वं यद्भूतं यच्च भव्यम्। उतामृतत्वस्येशानो यदन्नेनातिरोहति॥', 'Purusha Eva Idam Sarvam Yadbhutam Yaccha Bhavyam Utamritatvasyeshanah Yadannenatirohati', 'पुरुष ही यह सब है - जो भूत (अतीत) है और जो भव्य (भविष्य) है। वह अमृतत्व का भी स्वामी है और अन्न (भोजन) के रूप में विस्तृत होता है', 'Purusha is all this - whatever has been and whatever will be. He is the lord of immortality and also grows through food', 14, '/audio/vedic_suktas/purusha_sukta2.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1559, 'Purusha Sukta - Verse 3', 'एतावानस्य महिमा अतो ज्यायाँश्च पूरुषः। पादोऽस्य विश्वा भूतानि त्रिपादस्यामृतं दिवि॥', 'Etavanasya Mahima Ato Jyayanshcha Purushah Padovyasya Vishva Bhutani Tripadasyamritam Divi', 'इतना ही उसका महिमा है, किन्तु पुरुष इससे भी बड़ा है। उसका एक चरण समस्त भूत हैं, तीन चरण अमृत (स्वर्ग) में हैं', 'Such is his greatness, yet the Purusha is greater than this. All beings are but one quarter of him, his three quarters are immortal in heaven', 14, '/audio/vedic_suktas/purusha_sukta3.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1560, 'Purusha Sukta - Verse 4', 'त्रिपादूर्ध्व उदैत्पुरुषः पादोऽस्येहाभवत्पुनः। ततो विष्वङ्व्यक्रामत्साशनानशने अभि॥', 'Tripadurdhva Udait Purushah Padovyasyehabhavat Punah Tato Vishvangvyakramat Sashananashane Abhi', 'तीन चरण वाला पुरुष ऊपर उठ गया, उसका एक चरण फिर यहाँ (पृथ्वी पर) हो गया। तत्पश्चात वह सभी दिशाओं में विस्तृत हुआ, भोजन करने वाले और बिना भोजन वाले में', 'The Purusha with three quarters rose upward, his one quarter became manifest here again. Then he spread out in all directions, among those who eat and those who do not eat', 14, '/audio/vedic_suktas/purusha_sukta4.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1561, 'Purusha Sukta - Verse 5', 'तस्माद्विराळजायत विराजो अधि पूरुषः। स जातो अत्यरिच्यत पश्चाद्भूमिमथो पुरः॥', 'Tasmad Viratajayata Virajo Adhi Purushah Sa Jato Ataryachyata Pashchadbhumimatho Purah', 'उससे विराट् उत्पन्न हुआ, विराट् से पुरुष उत्पन्न हुआ। वह उत्पन्न होकर पीछे से भूमि को और आगे से (देवताओं को) अतिक्रम कर गया', 'From him Virat was born, and from Virat arose Purusha. Being born, he surpassed the earth behind and the gods ahead', 14, '/audio/vedic_suktas/purusha_sukta5.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1562, 'Purusha Sukta - Verse 6', 'यत्पुरुषेण हविषा देवा यज्ञमतन्वत। वसन्तो अस्यासीदाज्यं ग्रीष्म इध्मः शरद्धविः॥', 'Yatpurushena Havisha Deva Yajnamatanvata Vasanto Asyasadajyam Grishma Idhmah Sharaddhavih', 'जब देवताओं ने पुरुष को हवि के रूप में यज्ञ का विस्तार किया, तब वसन्त उसका घी (आज्य) हुआ, ग्रीष्म समिधा (ईंधन) हुआ और शरद हवि (आहुति) हुई', 'When the gods performed the sacrifice with Purusha as the offering, Spring became the ghee, Summer the fuel, and Autumn the offering', 14, '/audio/vedic_suktas/purusha_sukta6.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1563, 'Purusha Sukta - Verse 7', 'तं यज्ञं बर्हिषि प्रौक्षन्पुरुषं जातमग्रतः। तेन देवा अयजन्त साध्या ऋषयश्च ये॥', 'Tam Yajnam Barhishi Praukshan Purusham Jatamagratah Tena Deva Ayajanta Sadhya Rishayashcha Ye', 'उस अग्रजात पुरुष का यज्ञ (देवताओं ने) बर्हि (कुश) पर अभिषेक किया। उस यज्ञ से देवता, साध्य और ऋषि लोग यजन करते थे', 'They sprinkled the Purusha, born at the beginning, on the sacred grass as the sacrifice. With him the gods, the Sadhyas, and the sages performed the sacrifice', 14, '/audio/vedic_suktas/purusha_sukta7.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1564, 'Purusha Sukta - Verse 8', 'तस्माद्यज्ञात्सर्वहुत ऋचः सामानि जज्ञिरे। छन्दांसि जज्ञिरे तस्माद्यजुस्तस्मादजायत॥', 'Tasmadyajnat Sarvahuta Richah Samani Jajñire Chandamsi Jajñire Tasmad Yajustasmadajayata', 'उस सर्वाहुत यज्ञ से ऋचाएं और सामानि उत्पन्न हुए। उससे छन्द उत्पन्न हुए, उससे यजुः (यजुर्वेद) उत्पन्न हुआ', 'From that sacrifice, completely offered, the Rig and Sama hymns were born. The meters were born from him, the Yajus was born from him', 14, '/audio/vedic_suktas/purusha_sukta8.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1565, 'Purusha Sukta - Verse 9', 'तस्मादश्वा अजायन्त ये के चोभयादतः। गावो ह जज्ञिरे तस्मात्तस्माज्जाता अजावयः॥', 'Tasmadashva Ajayanta Ye Ke Chobhayadatah Gavoha Jajñire Tasmattasmajjata Ajavayah', 'उससे घोड़े उत्पन्न हुए, और जो भी दोनों पंक्तियों के दाँत वाले (जानवर) हैं। गायें उससे उत्पन्न हुईं, उससे बकरी-भेड़ उत्पन्न हुईं', 'From him horses were born, and all creatures with two rows of teeth. Cattle were born from him, from him were born goats and sheep', 14, '/audio/vedic_suktas/purusha_sukta9.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1566, 'Purusha Sukta - Verse 10', 'यत्पुरुषं व्यदधुः कतिधा व्यकल्पयन्। मुखं किमस्य कौ बाहू का ऊरू पादा उच्येते॥', 'Yatpurusham Vyadadhuh Katidha Vyakalpayan Mukham Kimasya Kau Bahu Ka Uru Pada Uchyete', 'जब उन्होंने पुरुष को विभक्त किया, तो उन्होंने उसे कितने भागों में विभाजित किया? उसका मुख क्या हुआ, उसकी भुजाएँ क्या हुईं, उसकी जंघाएँ और पैर क्या कहलाए?', 'When they divided Purusha, in how many parts did they arrange him? What became of his mouth? What of his arms? What of his thighs and feet?', 14, '/audio/vedic_suktas/purusha_sukta10.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1567, 'Purusha Sukta - Verse 11', 'ब्राह्मणोऽस्य मुखमासीद् बाहू राजन्यः कृतः। ऊरूतदस्य यद्वैश्यः पद्भ्यां शूद्रो अजायत॥', 'Brahmanoasya Mukhamasid Bahu Rajanyah Kritah Uru Tadasya Yadvaishyah Padbhyam Shudro Ajayata', 'उसका मुख ब्राह्मण हुआ, भुजाएँ राजन्य (क्षत्रिय) बनाई गईं। उसकी जंघाएँ वैश्य हुईं, चरणों से शूद्र उत्पन्न हुआ', 'His mouth became the Brahmin, his arms became the Kshatriya, his thighs became the Vaishya, from his feet the Shudra was born', 14, '/audio/vedic_suktas/purusha_sukta11.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1568, 'Purusha Sukta - Verse 12', 'चन्द्रमा मनसो जातश्चक्षोः सूर्यो अजायत। मुखादिन्द्रश्चाग्निश्च प्राणाद्वायुरजायत॥', 'Chandrama Manaso Jatashchakshoh Suryo Ajayata Mukhadindrashchagnishcha Pranadvayurajayata', 'मन से चन्द्रमा उत्पन्न हुआ, नेत्रों से सूर्य उत्पन्न हुआ। मुख से इन्द्र और अग्नि उत्पन्न हुए, प्राण से वायु उत्पन्न हुआ', 'The moon was born from his mind, the sun was born from his eyes. From his mouth came Indra and Agni, from his breath Vayu was born', 14, '/audio/vedic_suktas/purusha_sukta12.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1569, 'Purusha Sukta - Verse 13', 'नाभ्या आसीदन्तरिक्षं शीर्ष्णो द्यौः समवर्तत। पद्भ्यां भूमिर्दिशः श्रोत्रात्तथा लोकाँ अकल्पयन्॥', 'Nabhya Asidantariksham Shirshno Dyauh Samavartata Padbhyam Bhumir Dishah Shrotattatha Lokan Akalpayan', 'नाभि से अंतरिक्ष उत्पन्न हुआ, शीर्ष से द्युलोक प्रकट हुआ। चरणों से भूमि, कानों से दिशाएँ - इस प्रकार उन्होंने लोकों की रचना की', 'From his navel came the space, from his head the sky was formed. From his feet the earth, from his ears the directions - thus they arranged the worlds', 14, '/audio/vedic_suktas/purusha_sukta13.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1570, 'Purusha Sukta - Verse 14', 'सप्तास्यासन्परिधयस्त्रिः सप्त समिधः कृताः। देवा यद्यज्ञं तन्वाना अबध्नन्पुरुषं पशुम्॥', 'Saptasyasan Paridhayastrih Sapta Samidhah Kritah Deva Yadyajnam Tanvana Abadhnan Purusham Pashum', 'सात परिधियाँ थीं, इक्कीस समिधाएँ बनाई गईं। जब देवताओं ने यज्ञ का विस्तार किया, तो उन्होंने पुरुष पशु को बाँधा', 'There were seven boundaries, twenty-one fuel sticks were made. When the gods performed the sacrifice, they bound the Purusha as the sacrificial animal', 14, '/audio/vedic_suktas/purusha_sukta14.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1571, 'Purusha Sukta - Verse 15', 'सप्तास्यासन्परिधयस्त्रिः सप्त समिधः कृताः। देवा यद्यज्ञं तन्वाना अबध्नन्पुरुषं पशुम्॥', 'Saptasyasan Paridhayastrih Sapta Samidhah Kritah Deva Yadyajnam Tanvana Abadhnan Purusham Pashum', 'सात परिधियाँ थीं, इक्कीस समिधाएँ बनाई गईं। जब देवताओं ने यज्ञ का विस्तार किया, तो उन्होंने पुरुष पशु को बाँधा', 'There were seven boundaries, twenty-one fuel sticks were made. When the gods performed the sacrifice, they bound the Purusha as the sacrificial animal', 14, '/audio/vedic_suktas/purusha_sukta15.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1572, 'Narayana Sukta - Verse 1', 'सहस्रशीर्षं देवं विश्वाक्षं विश्वशम्भुवम्। विश्वं नारायणं देवमक्षरं परमं पदम्॥', 'Sahasrashirsham Devam Vishvaksham Vishvashambhuvam Vishvam Narayanam Devam Aksharam Paramam Padam', 'सहस्र शीर्ष वाले, विश्व को देखने वाले, विश्व का कल्याण करने वाले, विश्वरूप नारायण देव, अक्षर, परम पद को नमन', 'Salutations to the thousand-headed Lord, the all-seeing, the all-auspicious, Narayana, the supreme imperishable abode', 14, '/audio/vedic_suktas/narayana_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1573, 'Narayana Sukta - Verse 2', 'विश्वतः परमं नित्यं विश्वं नारायणं हरिम्। विश्वमेवेदं पुरुषो विश्वमेह विश्वं हरिः॥', 'Vishvatah Paramam Nityam Vishvam Narayanam Harim Vishvamevedam Purusho Vishvameha Vishvam Harih', 'विश्व से परे, नित्य, विश्वरूप नारायण, हरि। यह सब पुरुष ही है, यह सब हरि ही है', 'Beyond all, eternal, the universal Narayana, Hari. All this is Purusha, all this is Hari', 14, '/audio/vedic_suktas/narayana_sukta2.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1574, 'Narayana Sukta - Verse 3', 'विश्वमेवेदं पुरुषो विश्वमेवेदं हरिः। विश्वमेवेदं नारायणः सर्वं विश्वमिदं हरिः॥', 'Vishvamevedam Purusho Vishvamevedam Harih Vishvamevedam Narayanah Sarvam Vishvamidam Harih', 'यह सब पुरुष ही है, यह सब हरि ही है। यह सब नारायण ही है, सब कुछ हरि ही है', 'All this is Purusha, all this is Hari. All this is Narayana, everything is Hari', 14, '/audio/vedic_suktas/narayana_sukta3.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1575, 'Narayana Sukta - Verse 4', 'नारायण परो ज्योतिरात्मा नारायणः परः। नारायण परं ब्रह्म तत्त्वं नारायणः परः॥', 'Narayana Paro Jyotiratma Narayanah Parah Narayanah Param Brahma Tattvam Narayanah Parah', 'नारायण ही परम ज्योति हैं, नारायण ही परम आत्मा हैं। नारायण ही परम ब्रह्म हैं, नारायण ही परम तत्त्व हैं', 'Narayana is the supreme light, Narayana is the supreme Self. Narayana is the supreme Brahman, Narayana is the supreme reality', 14, '/audio/vedic_suktas/narayana_sukta4.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1576, 'Narayana Sukta - Verse 5', 'नारायण परं धाम नारायण परं तपः। नारायण परं ब्रह्म नारायण परमं पदम्॥', 'Narayana Param Dhama Narayana Param Tapah Narayana Param Brahma Narayana Paramam Padam', 'नारायण ही परम धाम हैं, नारायण ही परम तप हैं। नारायण ही परम ब्रह्म हैं, नारायण ही परम पद हैं', 'Narayana is the supreme abode, Narayana is the supreme austerity. Narayana is the supreme Brahman, Narayana is the supreme state', 14, '/audio/vedic_suktas/narayana_sukta5.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1577, 'Narayana Sukta - Verse 6', 'अन्तरं च बहिश्चैव सर्वं व्याप्य नारायणः। स्थितः सर्वत्र चैवास्मिन्नित्यं नारायणः परः॥', 'Antaram Cha Bahishchaiva Sarvam Vyapya Narayanah Sthitah Sarvatra Chaivasminnityam Narayanah Parah', 'भीतर और बाहर, सब कुछ व्याप्त करके नारायण स्थित हैं। सब जगह यही है - नारायण ही परम हैं', 'Within and without, pervading everything, Narayana is situated. Everywhere in this, Narayana is the supreme', 14, '/audio/vedic_suktas/narayana_sukta6.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1578, 'Sri Sukta - Verse 1', 'हिरण्यवर्णां हरिणीं सुवर्णरजतस्रजाम्। चन्द्रां हिरण्मयीं लक्ष्मीं जातवेदो म आवह॥', 'Hiranyavarnam Harinim Suvarnarajatasrajam Chandram Hiranmayim Lakshmim Jatavedo Ma Avaha', 'स्वर्णवर्णा, हरिणी, सुवर्ण और रजत की माला धारण करने वाली, चन्द्र के समान, स्वर्णमयी लक्ष्मी को, हे जातवेदः (अग्नि), मेरे लिए लाओ', 'O Agni, bring to me Lakshmi, who is golden in color, beautiful, adorned with gold and silver garlands, radiant like the moon, and resplendent with gold', 14, '/audio/vedic_suktas/sri_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1579, 'Sri Sukta - Verse 2', 'तां म आवह जातवेदो लक्ष्मीमनपगामिनीम्। यस्यां हिरण्यं विन्देयं गामश्वं पुरुषानहम्॥', 'Tam Ma Avaha Jatavedo Lakshmimanapagaminim Yasyam Hiranyam Vindeyam Gamashvam Purushanaham', 'उस अनपगामिनी (कभी न टलने वाली) लक्ष्मी को, हे जातवेदः, मेरे लिए लाओ, जिससे मैं सुवर्ण, गौ, अश्व और पुरुष (सेवक) प्राप्त करूं', 'O Jataveda, bring to me that unfailing Lakshmi, by whom I may obtain gold, cows, horses, and servants', 14, '/audio/vedic_suktas/sri_sukta2.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1580, 'Sri Sukta - Verse 3', 'अश्वपूर्वां रथमध्यां हस्तिनादप्रबोधिनीम्। श्रियं देवीमुपह्वये श्रीर्मा देवी जुषताम्॥', 'Ashvapurvam Rathamadhyam Hastinadaprabodhinim Shriyam Devimupahvaye Shrirma Devi Jushatam', 'अश्वों से अग्रगामिनी, रथों के मध्य में स्थित, हाथियों की गर्जना से जाग्रत, उस श्री देवी को मैं पुकारता हूं, वह श्री देवी मुझसे प्रसन्न हों', 'I invoke Goddess Shri, who is preceded by horses, seated in the middle of chariots, awakened by the trumpeting of elephants, may that Goddess Shri be pleased with me', 14, '/audio/vedic_suktas/sri_sukta3.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1581, 'Sri Sukta - Verse 4', 'कां सोस्मितां हिरण्यप्राकारामार्द्रां ज्वलन्तीं तृप्तां तर्पयन्तीम्। पद्मे स्थितां पद्मवर्णां तामिहोपह्वये श्रियम्॥', 'Kam Sosmitam Hiranyaprakaramardram Jvalantim Triptam Tarpayantim Padme Sthitam Padmavarnam Tamihopahvaye Shriyam', 'उन्हें, जो काम और स्मिता से युक्त हैं, सुवर्ण प्राकार वाली, आर्द्र, दीप्तिमान, तृप्त और तर्पयन्ती, पद्म में स्थित, पद्मवर्णा, उन श्री को मैं यहां पुकारता हूं', 'I invoke that Shri here, who is desired and smiling, having golden walls, moist, radiant, content, and satisfying others, seated on a lotus, lotus-hued', 14, '/audio/vedic_suktas/sri_sukta4.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1582, 'Sri Sukta - Verse 5', 'चन्द्रां प्रभासां यशसा ज्वलन्तीं श्रियं लोके देवजुष्टामुदाराम्। तां पद्मिनीमीं शरणमहं प्रपद्ये अलक्ष्मीर्मे नश्यतां त्वां वृणे॥', 'Chandram Prabhasam Yashasa Jwalantim Shriyam Loke Devajushtamudaram Tam Padminimim Sharanamaham Prapadye Alakshmirme Nashyatam Tvam Vrine', 'चन्द्र के समान प्रभासित, यश से ज्वलन्ती, लोक में देवताओं द्वारा सेवित, उदार, उस पद्मिनी श्री की मैं शरण ग्रहण करता हूं। मेरी अलक्ष्मी (दरिद्रता) नष्ट हो, मैं आपको चुनता हूं', 'I take refuge in that Padmini Shri, who is radiant like the moon, blazing with glory, worshipped by gods in the world, and generous. May my misfortune be destroyed, I choose you', 14, '/audio/vedic_suktas/sri_sukta5.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1583, 'Sri Sukta - Verse 6', 'श्रीः स्वर्णपद्मा विमलाननांशा हिरण्यवर्णा हरिणीसुवेषा। सदाऽऽश्रितानामवलोकयन्ती भक्तानुकम्पा कुरुषे प्रसादम्॥', 'Shrih Svarnapadma Vimalananamsha Hiranyavarna Harinisuvesha Sada Ashritanamavalokayanti Bhaktanukampa Kurushe Prasadam', 'श्री, स्वर्ण पद्म वाली, विमल मुख वाली, हिरण्यवर्णा, हरिणी, सुवेषा, सदा आश्रितों की ओर देखने वाली, भक्तों पर अनुकंपा करने वाली, कृपा करें', 'Shri, who sits on a golden lotus, whose face is pure, who is golden-colored, beautiful, well-adorned, always looking at those who seek refuge, compassionate to devotees, bestow your grace', 14, '/audio/vedic_suktas/sri_sukta6.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1584, 'Gayatri Mantra', 'ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि धियो यो नः प्रचोदयात्॥', 'Om Bhur Bhuvah Svah Tat Savitur Varenyam Bhargo Devasya Dhimahi Dhiyo Yo Nah Prachodayat', 'ॐ भूः, भुवः, स्वः, उस प्राणस्वरूप देव के वरणीय तेज का हम ध्यान करते हैं, वे हमारी बुद्धि को प्रेरित करें', 'Om, We meditate on the glory of the Creator, who has created the universe, who is worthy of worship, who is the embodiment of knowledge and light, who removes all sins and ignorance, may he enlighten our intellect', 14, '/audio/vedic_suktas/gayatri_mantra.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1585, 'Gayatri with Bhuh', 'ॐ भूः', 'Om Bhuh', 'ॐ भूः - पृथ्वी लोक', 'Om, Earth', 14, '/audio/vedic_suktas/gayatri_bhuh.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1586, 'Gayatri with Bhuvah', 'ॐ भुवः', 'Om Bhuvah', 'ॐ भुवः - अंतरिक्ष लोक', 'Om, Space', 14, '/audio/vedic_suktas/gayatri_bhuvah.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1587, 'Gayatri with Svah', 'ॐ स्वः', 'Om Svah', 'ॐ स्वः - स्वर्ग लोक', 'Om, Heaven', 14, '/audio/vedic_suktas/gayatri_svah.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1588, 'Maha Mrityunjaya Mantra', 'ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्। उर्वारुकमिव बन्धनान्मृत्योर्मुक्षीय माऽमृतात्॥', 'Om Tryambakam Yajamahe Sugandhim Pushtivardhanam Urvarukamiva Bandhanan Mrityor Mukshiya Maamritat', 'ॐ तीन नेत्रों वाले शिव को हम पूजते हैं, सुगंधित और पोषक, जैसे खीरा बेल से अलग हो, वैसे ही हमें मृत्यु से मुक्त कर अमृत से जोड़ें', 'Om, We worship the three-eyed Lord Shiva who is fragrant and nourishes all beings, May he liberate us from death for the sake of immortality, Just as the cucumber is separated from its bondage', 14, '/audio/vedic_suktas/mrityunjaya_mantra.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1589, 'Mrityunjaya Gayatri', 'ॐ त्र्यम्बकाय विद्महे महादेवाय धीमहि तन्नो रुद्रः प्रचोदयात्॥', 'Om Tryambakaya Vidmahe Mahadevaya Dhimahi Tanno Rudrah Prachodayat', 'ॐ त्र्यम्बक भगवान को जानें, महादेव का ध्यान करें, वे रुद्र हमें प्रेरित करें', 'Om, Let me meditate on the three-eyed Lord, Give me higher intellect, Let Lord Rudra illuminate my mind', 14, '/audio/vedic_suktas/mrityunjaya_gayatri.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1590, 'Shanti Mantra - Om Shanti', 'ॐ शान्तिः शान्तिः शान्तिः', 'Om Shantih Shantih Shantih', 'ॐ शांति, शांति, शांति', 'Om, Peace, Peace, Peace', 14, '/audio/vedic_suktas/om_shanti.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1591, 'Shanti Mantra - Dyau Shanti', 'द्यौः शान्तिरन्तरिक्षं शान्तिः पृथिवी शान्तिरापः शान्तिरोषधयः शान्तिः। वनस्पतयः शान्तिर्विश्वे देवाः शान्तिर्ब्रह्म शान्तिः सर्वं शान्तिः शान्तिरेव शान्तिः सा मा शान्तिरेधि॥', 'Dyauh Shantirantariksham Shantih Prithivi Shantir Apah Shantir Oshadhayah Shantih Vanaspatayah Shantir Vishve Devah Shantir Brahma Shantih Sarvam Shantih Shantireva Shantih Sa Ma Shantiredhi', 'आकाश शांत हो, अंतरिक्ष शांत हो, पृथ्वी शांत हो, जल शांत हो, औषधियां शांत हों, वनस्पतियां शांत हों, सभी देवता शांत हों, ब्रह्म शांत हो, सब कुछ शांत हो, केवल शांति ही शांति हो, वह शांति मुझे प्राप्त हो', 'May the sky be peaceful, may the space be peaceful, may the earth be peaceful, may the waters be peaceful, may the herbs be peaceful, may the plants be peaceful, may all gods be peaceful, may Brahman be peaceful, may everything be peaceful, peace alone is peace, may that peace come to me', 14, '/audio/vedic_suktas/dyau_shanti.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1592, 'Shanti Mantra - Asato Ma', 'असतो मा सद्गमय। तमसो मा ज्योतिर्गमय। मृत्योर्मा अमृतं गमय॥', 'Asato Ma Sadgamaya Tamaso Ma Jyotirgamaya Mrityor Ma Amritam Gamaya', 'असत्य से सत्य की ओर ले चलो, अंधकार से प्रकाश की ओर ले चलो, मृत्यु से अमरता की ओर ले चलो', 'Lead me from the unreal to the real, lead me from darkness to light, lead me from death to immortality', 14, '/audio/vedic_suktas/asato_ma.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1593, 'Shanti Mantra - Om Purnamadah', 'ॐ पूर्णमदः पूर्णमिदं पूर्णात्पूर्णमुदच्यते। पूर्णस्य पूर्णमादाय पूर्णमेवावशिष्यते॥', 'Om Purnamadah Purnamidam Purnat Purnamudachyate Purnasya Purnamadaya Purnamevavashishyate', 'ॐ वह पूर्ण है, यह पूर्ण है, पूर्ण से पूर्ण की उत्पत्ति होती है। पूर्ण का पूर्ण लेने पर भी पूर्ण ही शेष रहता है', 'Om, That is whole, this is whole, from wholeness comes wholeness. Taking wholeness from wholeness, wholeness remains', 14, '/audio/vedic_suktas/purnamadah.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1594, 'Shanti Mantra - Sahana Vavatu', 'ॐ सह नाववतु। सह नौ भुनक्तु। सह वीर्यं करवावहै। तेजस्वि नावधीतमस्तु मा विद्विषावहै। ॐ शान्तिः शान्तिः शान्तिः॥', 'Om Saha Navavatu Saha Nau Bhunaktu Saha Viryam Karavavai Tejasvi Navadhitamastu Ma Vidvishavahai Om Shantih Shantih Shantih', 'ॐ हम दोनों की रक्षा करें, हम दोनों को पोषण दें, हम दोनों साथ मिलकर शक्ति प्राप्त करें। हमारा अध्ययन तेजस्वी हो, हम आपस में द्वेष न करें। ॐ शांति, शांति, शांति', 'Om, May He protect us both, may He nourish us both, may we work together with great energy. May our study be brilliant, may we not quarrel with each other. Om, Peace, Peace, Peace', 14, '/audio/vedic_suktas/sahana_vavatu.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1595, 'Medha Sukta - Verse 1', 'ॐ या मेधा देवगणानां या वीरेषु महीयते। या विश्वेषु द्विजातिषु सा मां मेधा सुखं सुखम्॥', 'Om Ya Medha Devagananam Ya Vireshu Mahiyate Ya Vishveshu Dvijatishu Sa Mam Medha Sukham Sukham', 'ॐ जो मेधा (बुद्धि) देवताओं के गणों में, जो वीरों में महान है, जो सभी द्विजों में है, वह मेधा मुझे सुख-सुख प्रदान करे', 'Om, May that intellect which is among the hosts of gods, which is great among the heroes, which is among all the twice-born, that intellect grant me happiness', 14, '/audio/vedic_suktas/medha_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1596, 'Medha Sukta - Verse 2', 'यां ब्रह्मा वरुणेन्द्रश्च सरस्वती च सविता च। तां मे मेधां सरस्वती दधातु सर्वविद्याप्रदायिनी॥', 'Yam Brahma Varunendrashcha Saraswati Cha Savita Cha Tam Me Medham Saraswati Dadhatu Sarvavidyapradayini', 'जिस मेधा को ब्रह्मा, वरुण, इन्द्र, सरस्वती और सविता धारण करते हैं, वह सर्वविद्या प्रदान करने वाली सरस्वती मुझे मेधा प्रदान करें', 'May Saraswati, who bestows all knowledge, grant me that intellect which is possessed by Brahma, Varuna, Indra, Saraswati, and Savita', 14, '/audio/vedic_suktas/medha_sukta2.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1597, 'Medha Sukta - Verse 3', 'ॐ मेधां मे वरुणो ददातु मेधामग्निः प्रजापतिः। मेधामिन्द्रश्च वायुश्च मेधां मे सरस्वती ददातु॥', 'Om Medham Me Varuno Dadatu Medhamagnih Prajapatih Medhamindrashcha Vayushcha Medham Me Saraswati Dadatu', 'ॐ मुझे वरुण मेधा दें, मुझे अग्नि और प्रजापति मेधा दें। मुझे इन्द्र और वायु मेधा दें, मुझे सरस्वती मेधा दें', 'Om, May Varuna grant me intellect, may Agni and Prajapati grant me intellect. May Indra and Vayu grant me intellect, may Saraswati grant me intellect', 14, '/audio/vedic_suktas/medha_sukta3.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1598, 'Dhanvantari Sukta', 'ॐ नमो भगवते धन्वन्तरये अमृतकलश हस्ताय सर्वामय विनाशनाय त्रैलोक्यनाथाय श्री महाविष्णवे नमः', 'Om Namo Bhagavate Dhanvantaraye Amritakalasha Hastaya Sarvamaya Vinashanaya Trailokyanathaya Shri Mahavishnave Namah', 'ॐ भगवान धन्वंतरि को नमन, जिनके हाथ में अमृत कलश है, सभी रोगों का नाश करने वाले, तीनों लोकों के नाथ, महाविष्णु स्वरूप को नमन', 'Om, Salutations to Lord Dhanvantari, who holds the pot of nectar, destroyer of all diseases, lord of the three worlds, salutations to Mahavishnu', 14, '/audio/vedic_suktas/dhanvantari_sukta.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1599, 'Devi Sukta - Verse 1 (Rigveda 10.125)', 'अहं रुद्रेभिर्वसुभिश्चराम्यहमादित्यैरुत विश्वदेवैः। अहं मित्रावरुणोभा बिभर्म्यहमिन्द्राग्नी अहमश्विनोभा॥', 'Aham Rudrebhirvasubhishcharamyahamadityairuta Vishvadevaih Aham Mitravarunobha Bibharmyahamindragni Ahamashvinobha', 'मैं रुद्रों और वसुओं के साथ चलती हूं, मैं आदित्यों और सभी देवताओं के साथ। मैं मित्र और वरुण दोनों को धारण करती हूं, मैं इन्द्र और अग्नि को, मैं अश्विनी कुमारों को', 'I move with the Rudras and Vasus, I with the Adityas and all gods. I support Mitra and Varuna, I support Indra and Agni, I support the Ashwins', 14, '/audio/vedic_suktas/devi_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1600, 'Devi Sukta - Verse 2', 'अहं सोममाहनसं बिभर्म्यहं त्वष्टारमुत पूषणं भगम्। अहं दधामि द्रविणं हविष्मते सुप्राव्ये यजमानाय सुन्वते॥', 'Aham Somamahanasam Bibharmyaham Tvashtaramuta Pushanam Bhagam Aham Dadhami Dravinam Havishmate Supravye Yajamanaya Sunvate', 'मैं सोम को, जो शत्रुओं को मारने वाला है, धारण करती हूं, मैं त्वष्टा, पूषा और भग को धारण करती हूं। मैं हवि देने वाले, यज्ञ करने वाले, सोम का अभिषेक करने वाले यजमान को धन प्रदान करती हूं', 'I support Soma, the slayer of enemies, I support Tvashta, Pushan, and Bhaga. I bestow wealth upon the sacrificer who offers oblations and performs sacrifice', 14, '/audio/vedic_suktas/devi_sukta2.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `mantras` (`id`, `mantra_name`, `sanskrit_text`, `transliteration`, `translation_hindi`, `translation_english`, `category_id`, `audio_url`, `views_count`, `likes_count`, `created_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1601, 'Devi Sukta - Verse 3', 'अहं राष्ट्री संगमनी वसूनां चिकितुषी प्रथमा यज्ञियानाम्। तां मा देवा व्यदधुः पुरुत्रा भूरिस्थात्रां भूर्यावेशयन्तीम्॥', 'Aham Rashtri Sangamani Vasunam Chikitushi Prathama Yajniyanam Tam Ma Deva Vyadadhuh Purutra Bhuristhatram Bhuryaveshayantim', 'मैं राज्ञी हूं, धनों को एकत्र करने वाली, यज्ञीय पदार्थों को जानने वाली, प्रथम हूं। देवताओं ने मुझे बहुत स्थानों में स्थापित किया है, बहुत स्थानों में प्रवेश करने वाली', 'I am the sovereign queen, the gatherer of treasures, the knower of sacrificial rites, the first. The gods have placed me in many places, entering many abodes', 14, '/audio/vedic_suktas/devi_sukta3.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1602, 'Durga Sukta - Verse 1', 'जातवेदसे सुनवाम सोमं रात्र्यहः प्रतिभाति जायो। अग्निर्यन्ता प्रथमो देवतानां भद्रं तुभ्यं जातवेदो यथासत्॥', 'Jatavedase Sunavama Somam Ratryahah Pratibhati Jayo Agniryanta Prathamo Devatanam Bhadram Tubhyam Jatavedo Yathasat', 'जातवेदा (अग्नि) के लिए हम सोम का अभिषेक करते हैं, जो रात्रि और दिन को प्रकाशित करता है। अग्नि देवताओं में प्रथम नेता हैं, हे जातवेदा, आपके लिए कल्याण हो', 'We offer Soma to Jataveda (Agni), who illuminates night and day. Agni is the first leader among gods, O Jataveda, may there be auspiciousness for you', 14, '/audio/vedic_suktas/durga_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1603, 'Nasadiya Sukta - Verse 1 (Rigveda 10.129)', 'नासदासीन्नो सदासीत्तदानीं नासीद्रजो नो व्योमा परो यत्। किमावरीवः कुह कस्य शर्मन्नम्भः किमासीद्गहनं गभीरम्॥', 'Nasadasinno Sadasi Tadanim Nasirajo No Vyoma Paro Yat Kimavarivah Kuha Kasya Sharmanambhah Kimasid Gahanam Gabhiram', 'उस समय न असत् था, न सत् था। न रज (अंतरिक्ष) था, न व्योम (आकाश) था। क्या था? कहाँ था? किसके संरक्षण में था? वह गहन जल क्या था?', 'There was neither non-existence nor existence then; there was no realm of space, no sky above. What stirred? Where? In whose protection? Was there water, deep and profound?', 14, '/audio/vedic_suktas/nasadiya_sukta1.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1604, 'Nasadiya Sukta - Verse 2', 'न मृत्युरासीदमृतं न तर्हि न रात्र्या अह्न आसीत्प्रकेतः। आनीदवातं स्वधया तदेकं तस्माद्धान्यन्न परः किञ्चनास॥', 'Na Mrityurasidamritam Na Tarhi Na Ratrya Ahna Asitpraketah Anidavatam Svadhaya Tadekam Tasmaddhanyanna Parah Kinchanasa', 'न मृत्यु था, न अमरता थी, न रात्रि-दिन की पहचान थी। वह एक अपने प्राण से बिना वायु के ही स्पन्दित था। उसके अतिरिक्त और कुछ न था', 'There was no death, no immortality; there was no distinction of night and day. That one breathed, windless, by its own power. Other than that, there was nothing else', 14, '/audio/vedic_suktas/nasadiya_sukta2.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1605, 'Nasadiya Sukta - Verse 3', 'तम आसीत्तमसा गूळ्हमग्रे प्रकेतं सलिलं सर्वमा इदम्। तुच्छ्येनाभ्वपिहितं यदासीत्तपसस्तन्महिनाजायतैकम्॥', 'Tama Asit Tamsa Gūdham Agre Praketam Salilam Sarvam A Idam Tuchchenabhu Apihitam Yadasit Tapasastanmahinajayataikam', 'प्रारंभ में अंधकार ही अंधकार था, यह सब अविभाज्य जल था। उस शून्य में जो छिपा था, वह एक तप की महिमा से उत्पन्न हुआ', 'In the beginning, darkness was hidden by darkness; all this was undifferentiated water. That which was covered by emptiness, that one was born by the power of heat (tapas)', 14, '/audio/vedic_suktas/nasadiya_sukta3.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1606, 'Nasadiya Sukta - Verse 7', 'यो अस्याध्यक्षः परमे व्योमन् सो अङ्ग वेद यदि वा न वेद।', 'Yo Asyadhyakshah Parame Vyoman So Anga Veda Yadi Va Na Veda', 'जो इस (सृष्टि) का अध्यक्ष परम व्योम में है, वही जानता है, या नहीं भी जानता', 'He who is the overseer in the highest heaven, he alone knows - or perhaps he does not know', 14, '/audio/vedic_suktas/nasadiya_sukta7.mp3', 0, 0, '2026-03-23 03:32:32', NULL, NULL, NULL, NULL, NULL, NULL),
(1607, 'Sri Vidya Mool Mantra', 'ॐ श्रीं ह्रीं क्लीं ऐं सौः', 'Om Shreem Hreem Kleem Aim Sauh', 'ॐ श्रीं ह्रीं क्लीं ऐं सौः', 'The combined seed syllables of Sri Vidya', 15, '/audio/tantric/sri_vidya_mool.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1608, 'Sri Vidya Panchadashi', 'क ए ई ल ह्रीं ह स क ह ल ह्रीं स क ल ह्रीं', 'Ka E I La Hreem Ha Sa Ka Ha La Hreem Sa Ka La Hreem', 'क ए ई ल ह्रीं ह स क ह ल ह्रीं स क ल ह्रीं', 'The fifteen-syllable Sri Vidya mantra (Panchadashi)', 15, '/audio/tantric/sri_vidya_panchadashi.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1609, 'Sri Vidya Shodashi', 'ॐ क ए ई ल ह्रीं ह स क ह ल ह्रीं स क ल ह्रीं', 'Om Ka E I La Hreem Ha Sa Ka Ha La Hreem Sa Ka La Hreem', 'ॐ क ए ई ल ह्रीं ह स क ह ल ह्रीं स क ल ह्रीं', 'The sixteen-syllable Sri Vidya mantra (Shodashi) with Om', 15, '/audio/tantric/sri_vidya_shodashi.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1610, 'Sri Vidya Bala Mantra', 'ॐ ऐं ह्रीं क्लीं सौः', 'Om Aim Hreem Kleem Sauh', 'ॐ ऐं ह्रीं क्लीं सौः', 'The seed mantra for Bala Tripurasundari', 15, '/audio/tantric/sri_vidya_bala.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1611, 'Sri Chakra Mantra', 'ॐ श्रीं ह्रीं क्लीं ऐं ह्रीं', 'Om Shreem Hreem Kleem Aim Hreem', 'ॐ श्रीं ह्रीं क्लीं ऐं ह्रीं', 'The mantra for Sri Chakra worship', 15, '/audio/tantric/sri_chakra.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1612, 'Tripura Sundari Mool Mantra', 'ॐ ह्रीं क्लीं ऐं त्रिपुरसुन्दर्यै नमः', 'Om Hreem Kleem Aim Tripurasundaryai Namah', 'ॐ ह्रीं क्लीं ऐं त्रिपुरसुन्दरी को नमन', 'Om Hreem Kleem Aim, Salutations to Tripura Sundari', 15, '/audio/tantric/tripura_sundari_mool.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1613, 'Tripura Sundari Gayatri', 'ॐ त्रिपुरायै विद्महे महेश्वर्यै धीमहि तन्नो ललिता प्रचोदयात्॥', 'Om Tripurayai Vidmahe Maheshwaryai Dhimahi Tanno Lalita Prachodayat', 'ॐ त्रिपुरा देवी को जानें, महेश्वरी का ध्यान करें, वे ललिता हमें प्रेरित करें', 'Om, Let me meditate on Tripura, Give me higher intellect, Let Goddess Lalita illuminate my mind', 15, '/audio/tantric/tripura_sundari_gayatri.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1614, 'Tripura Sundari Beej', 'ॐ क्लीं', 'Om Kleem', 'ॐ क्लीं', 'The seed mantra of Tripura Sundari for attraction', 15, '/audio/tantric/tripura_sundari_beej.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1615, 'Tripura Bhairavi Mantra', 'ॐ ह्रीं क्लीं त्रिपुरभैरव्यै नमः', 'Om Hreem Kleem Tripurabhairavyai Namah', 'ॐ ह्रीं क्लीं त्रिपुरभैरवी को नमन', 'Om Hreem Kleem, Salutations to Tripura Bhairavi', 15, '/audio/tantric/tripura_bhairavi.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1616, 'Bala Tripurasundari Mool', 'ॐ ऐं ह्रीं क्लीं बालायै नमः', 'Om Aim Hreem Kleem Balayai Namah', 'ॐ ऐं ह्रीं क्लीं बाला देवी को नमन', 'Om Aim Hreem Kleem, Salutations to Bala Devi', 15, '/audio/tantric/bala_mool.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1617, 'Bala Mantra', 'ॐ ऐं ह्रीं क्लीं', 'Om Aim Hreem Kleem', 'ॐ ऐं ह्रीं क्लीं', 'The seed mantra of Bala Tripurasundari', 15, '/audio/tantric/bala_mantra.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1618, 'Bala Gayatri', 'ॐ बालायै विद्महे मनोज्ञायै धीमहि तन्नो बाला प्रचोदयात्॥', 'Om Balayai Vidmahe Manojnayai Dhimahi Tanno Bala Prachodayat', 'ॐ बाला देवी को जानें, मनोज्ञा का ध्यान करें, वे बाला हमें प्रेरित करें', 'Om, Let me meditate on Bala, Give me higher intellect, Let Goddess Bala illuminate my mind', 15, '/audio/tantric/bala_gayatri.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1619, 'Lalita Sahasranama - Opening', 'ॐ श्री माता श्री महाराज्ञी श्रीमत् सिंहासनेश्वरी। चिदग्निकुण्ड सम्भूता देवकाय समुद्भवा॥', 'Om Shri Mata Shri Maharajni Shrimat Simhasaneshwari Chidagnikunda Sambhuta Devakaya Samudbhava', 'ॐ श्री माता, श्री महाराज्ञी, श्रीमत सिंहासनेश्वरी, चिदग्निकुण्ड से उत्पन्न, देवकाय से प्रकट', 'Om, The Divine Mother, the Great Queen, the One seated on the glorious throne, born from the fire of consciousness, manifested from the divine body', 15, '/audio/tantric/lalita_open.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1620, 'Lalita Sahasranama - Verse 1', 'उद्यद्भानु सहस्राभा चतुर्बाहु समन्विता। रागस्वरूप पाशाढ्या क्रोधाकारांकुशोज्ज्वला॥', 'Udyadbhanu Sahasrabha Chaturbahu Samanvita Ragasvarupa Pashadya Krodhakara Kushojjwala', 'उदीयमान हजार सूर्यों के समान तेज वाली, चतुर्भुजा, रागस्वरूप पाश धारण करने वाली, क्रोधाकार अंकुश से दीप्त', 'Resplendent like a thousand rising suns, endowed with four arms, holding the noose of desire, brilliant with the goad of anger', 15, '/audio/tantric/lalita_verse1.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1621, 'Lalita Sahasranama - Verse 2', 'मनोरूपेक्षु कोदण्डा पञ्चतन्मात्र सायका। निजारुण प्रभापूर मज्जद् ब्रह्माण्ड मण्डला॥', 'Manorupikshu Kodanda Panchatanmatra Sayaka Najaruna Prabhapura Majjad Brahmanda Mandala', 'मनोरूप इक्षुकोदण्ड धारण करने वाली, पंचतन्मात्र रूपी बाणों वाली, अपनी लालिमा से ब्रह्मांड मंडल को सराबोर करने वाली', 'With a bow of sugarcane that is the mind, with arrows that are the five subtle elements, her own red radiance flooding the entire cosmic sphere', 15, '/audio/tantric/lalita_verse2.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1622, 'Lalita Sahasranama - Verse 3', 'चम्पकाशोक पुन्नाग सौगन्धिक लसत्कचा। कुरुविन्द मणि श्रेणी कनत्कोटीर मण्डिता॥', 'Champakashoka Punnaga Saugandhika Lasatkacha Kuruvinda Mani Shreni Kanatkotira Mandita', 'चम्पा, अशोक, पुन्नाग, सौगन्धिक फूलों से सुशोभित केश वाली, कुरुविन्द मणियों की श्रेणी से जगमगाते कोटीर से मण्डित', 'Whose hair is adorned with champaka, ashoka, punnaga, and saugandhika flowers, whose crown shines with rows of kuruvinda gems', 15, '/audio/tantric/lalita_verse3.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1623, 'Lalita Sahasranama - Verse 4', 'अष्टमी चन्द्र विभ्राज दलिकस्थ लोचना। मुख चन्द्र कलंकाभ मृगनाभि विशेषका॥', 'Ashtami Chandra Vibhraja Dalikastha Lochana Mukha Chandra Kalankabha Mriganabhi Visheshaka', 'अष्टमी के चन्द्र के समान दीप्त, दलिक (नेत्र कोने) में स्थित नेत्र वाली, मुख चन्द्र पर कलंक के समान कस्तूरी तिलक वाली', 'Whose eyes are placed at the corners like the eighth-day moon, whose face has a musk tilaka like the mark on the moon', 15, '/audio/tantric/lalita_verse4.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1624, 'Lalita Sahasranama - Verse 5', 'वदन स्मर मांगल्य गृह तोरण चिल्लिका। वक्त्र लक्ष्मी परीवाह चलन्मीनाभ लोचना॥', 'Vadana Smar Mangalya Griha Torana Chillika Vaktra Lakshmi Parivaha Chalanminabha Lochana', 'जिनके वदन रूपी मांगल्य गृह के तोरण सी चिल्लिका, जिनके नेत्र वक्त्रलक्ष्मी रूपी नदी में तैरती हुई मीन के समान हैं', 'Whose eyelashes are like the archways of the auspicious house that is her face, whose eyes are like fish swimming in the river of her facial beauty', 15, '/audio/tantric/lalita_verse5.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1625, 'Lalita Sahasranama - Concluding', 'इति श्रीललिता सहस्रनाम स्तोत्रं सम्पूर्णम्। यः पठेच्छृणुयाद्वापि स सर्वान् कामान् आप्नुयात्॥', 'Iti Shri Lalita Sahasranama Stotram Sampurnam Yah Pathechchhrinuyadvapi Sa Sarvan Kaman Apnuyat', 'इस प्रकार श्री ललिता सहस्रनाम स्तोत्र सम्पूर्ण हुआ। जो इसे पढ़े या सुने, वह सभी मनोरथों को प्राप्त करता है', 'Thus ends the Shri Lalita Sahasranama Stotra. Whoever reads or hears this attains all desires', 15, '/audio/tantric/lalita_close.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1626, 'Kali Tantric Mantra', 'ॐ क्रीं क्रीं क्रीं हूं हूं ह्रीं ह्रीं दक्षिणे कालिके क्रीं क्रीं क्रीं हूं हूं ह्रीं ह्रीं स्वाहा', 'Om Kreem Kreem Kreem Hum Hum Hreem Hreem Dakshine Kalike Kreem Kreem Kreem Hum Hum Hreem Hreem Swaha', 'ॐ क्रीं क्रीं क्रीं हूं हूं ह्रीं ह्रीं दक्षिणा कालिका को क्रीं क्रीं क्रीं हूं हूं ह्रीं ह्रीं स्वाहा', 'Om, Salutations to Dakshina Kali with all seed syllables, Swaha', 15, '/audio/tantric/kali_tantric.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1627, 'Tara Mool Mantra', 'ॐ त्रां त्रीं त्रौं सः तारायै नमः', 'Om Tram Treem Traum Sah Tarayai Namah', 'ॐ त्रां त्रीं त्रौं सः तारा देवी को नमन', 'Om Tram Treem Traum Sah, Salutations to Goddess Tara', 15, '/audio/tantric/tara_mool.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1628, 'Tara Beej Mantra', 'ॐ त्रीं', 'Om Treem', 'ॐ त्रीं', 'The seed mantra of Tara', 15, '/audio/tantric/tara_beej.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1629, 'Tara Gayatri', 'ॐ तारायै विद्महे महोग्रायै धीमहि तन्नो तारा प्रचोदयात्॥', 'Om Tarayai Vidmahe Mahograyai Dhimahi Tanno Tara Prachodayat', 'ॐ तारा देवी को जानें, महोग्रा का ध्यान करें, वे तारा हमें प्रेरित करें', 'Om, Let me meditate on Tara, Give me higher intellect, Let Goddess Tara illuminate my mind', 15, '/audio/tantric/tara_gayatri.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1630, 'Tripura Sundari Maha Mantra', 'ॐ ऐं ह्रीं क्लीं त्रिपुरसुन्दर्यै नमः', 'Om Aim Hreem Kleem Tripurasundaryai Namah', 'ॐ ऐं ह्रीं क्लीं त्रिपुरसुन्दरी को नमन', 'Om Aim Hreem Kleem, Salutations to Tripura Sundari', 15, '/audio/tantric/tripura_maha.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1631, 'Bhuvaneshwari Mool Mantra', 'ॐ ह्रीं भुवनेश्वर्यै नमः', 'Om Hreem Bhuvaneshwaryai Namah', 'ॐ ह्रीं भुवनेश्वरी को नमन', 'Om Hreem, Salutations to Bhuvaneshwari', 15, '/audio/tantric/bhuvaneshwari_mool.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1632, 'Bhuvaneshwari Beej', 'ॐ ह्रीं', 'Om Hreem', 'ॐ ह्रीं', 'The seed mantra of Bhuvaneshwari', 15, '/audio/tantric/bhuvaneshwari_beej.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1633, 'Bhuvaneshwari Gayatri', 'ॐ भुवनेश्वर्यै विद्महे महामायायै धीमहि तन्नो भुवनेश्वरी प्रचोदयात्॥', 'Om Bhuvaneshwaryai Vidmahe Mahamayayai Dhimahi Tanno Bhuvaneshwari Prachodayat', 'ॐ भुवनेश्वरी को जानें, महामाया का ध्यान करें, वे भुवनेश्वरी हमें प्रेरित करें', 'Om, Let me meditate on Bhuvaneshwari, Give me higher intellect, Let Goddess Bhuvaneshwari illuminate my mind', 15, '/audio/tantric/bhuvaneshwari_gayatri.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
(1634, 'Bhairavi Mool Mantra', 'ॐ ह्रीं भैरव्यै नमः', 'Om Hreem Bhairavyai Namah', 'ॐ ह्रीं भैरवी को नमन', 'Om Hreem, Salutations to Bhairavi', 15, '/audio/tantric/bhairavi_mool.mp3', 0, 0, '2026-03-23 04:00:39', NULL, NULL, NULL, NULL, NULL, NULL),
