(1, 'kaustubhraikar@gmail.com', 'Kaustubh Raikar', 'facdfeab5df3035355ff5009867b34352ef2787523069cc2581827ad82fbc360', '2026-10-30 22:06:46', 1, '2026-10-30 21:56:46');
INSERT INTO `pooja_vidhi` (`id`, `vidhi_name`, `deity_name`, `festival`, `category`, `description`, `steps`, `required_items`, `mantras`, `samagri_list`, `vidhi_duration`, `best_time`, `day`, `tithi`, `significance`, `benefits`, `precautions`, `video_url`, `audio_url`, `is_premium`, `views_count`, `likes_count`, `created_at`, `updated_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`) VALUES
(1, 'Ganesh Pooja Vidhi', 'Ganesh', 'Ganesh Chaturthi', 'Festival', 'गणेश पूजा विधि - किसी भी शुभ कार्य के आरंभ में भगवान गणेश की पूजा की जाती है। यह विधि गणेश चतुर्थी और दैनिक पूजा के लिए उपयोगी है।', '[{\"step\":1,\"name\":\"ध्यान Dhyana\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। पूर्व या उत्तर दिशा की ओर मुख करके आसन पर बैठें। भगवान गणेश का ध्यान करें।\"},{\"step\":2,\"name\":\"आवाहन Avahana\",\"description\":\"गणेश जी की मूर्ति या चित्र स्थापित करें। ॐ गं गणपतये नमः आवाहयामि मंत्र से आवाहन करें।\"},{\"step\":3,\"name\":\"आसन Asana\",\"description\":\"ॐ गं गणपतये नमः आसनं समर्पयामि मंत्र से आसन अर्पित करें।\"},{\"step\":4,\"name\":\"पाद्य Padya\",\"description\":\"ॐ गं गणपतये नमः पाद्यं समर्पयामि मंत्र से चरणों का जल अर्पित करें।\"},{\"step\":5,\"name\":\"अर्घ्य Arghya\",\"description\":\"ॐ गं गणपतये नमः अर्घ्यं समर्पयामि मंत्र से अर्घ्य अर्पित करें।\"},{\"step\":6,\"name\":\"स्नान Snana\",\"description\":\"जल, पंचामृत से अभिषेक करें। ॐ गं गणपतये नमः स्नानं समर्पयामि मंत्र बोलें।\"},{\"step\":7,\"name\":\"वस्त्र Vastra\",\"description\":\"लाल वस्त्र या धोती अर्पित करें। ॐ गं गणपतये नमः वस्त्रं समर्पयामि।\"},{\"step\":8,\"name\":\"यज्ञोपवीत Yajnopavita\",\"description\":\"जनेऊ अर्पित करें। ॐ गं गणपतये नमः यज्ञोपवीतं समर्पयामि।\"},{\"step\":9,\"name\":\"गंध Gandha\",\"description\":\"चंदन, रोली, कुमकुम अर्पित करें। ॐ गं गणपतये नमः गंधं समर्पयामि।\"},{\"step\":10,\"name\":\"अक्षत Akshata\",\"description\":\"अक्षत अर्पित करें। ॐ गं गणपतये नमः अक्षतान् समर्पयामि।\"},{\"step\":11,\"name\":\"पुष्प Pushpa\",\"description\":\"दुर्वा, लाल फूल, जवा के फूल अर्पित करें। ॐ गं गणपतये नमः पुष्पं समर्पयामि।\"},{\"step\":12,\"name\":\"धूप Dhupa\",\"description\":\"अगरबत्ती या धूप जलाएं। ॐ गं गणपतये नमः धूपं आघ्रापयामि।\"},{\"step\":13,\"name\":\"दीप Deepa\",\"description\":\"घी या तेल का दीपक जलाएं। ॐ गं गणपतये नमः दीपं दर्शयामि।\"},{\"step\":14,\"name\":\"नैवेद्य Naivedya\",\"description\":\"मोदक, लड्डू, फल अर्पित करें। ॐ गं गणपतये नमः नैवेद्यं समर्पयामि।\"},{\"step\":15,\"name\":\"ताम्बूल Tambula\",\"description\":\"पान, सुपारी, लौंग, इलायची अर्पित करें।\"},{\"step\":16,\"name\":\"आरती Aarti\",\"description\":\"गणेश आरती - सुखकर्ता दुःखहर्ता या जय गणेश जय गणेश करें।\"},{\"step\":17,\"name\":\"प्रदक्षिणा Pradakshina\",\"description\":\"तीन या पांच बार प्रदक्षिणा करें।\"},{\"step\":18,\"name\":\"प्रार्थना Prarthana\",\"description\":\"अपनी मनोकामना प्रार्थना करें।\"},{\"step\":19,\"name\":\"क्षमा प्रार्थना Kshama Prarthana\",\"description\":\"पूजा में हुई त्रुटियों के लिए क्षमा प्रार्थना करें।\"},{\"step\":20,\"name\":\"प्रसाद वितरण Prasad Distribution\",\"description\":\"प्रसाद भक्तों में वितरित करें。\"}]', '[{\"item\":\"गणेश मूर्ति या चित्र\",\"quantity\":\"1\"},{\"item\":\"लाल वस्त्र\",\"quantity\":\"1\"},{\"item\":\"दुर्वा गणेश जी को प्रिय\",\"quantity\":\"21 गांठें\"},{\"item\":\"लाल फूल जवा के फूल\",\"quantity\":\"21\"},{\"item\":\"मोदक लड्डू\",\"quantity\":\"11\"},{\"item\":\"चंदन\",\"quantity\":\"थोड़ा\"},{\"item\":\"रोली कुमकुम\",\"quantity\":\"थोड़ा\"},{\"item\":\"अक्षत चावल\",\"quantity\":\"मुट्ठी भर\"},{\"item\":\"पंचामृत\",\"quantity\":\"1 कटोरी\"},{\"item\":\"जल\",\"quantity\":\"2 कटोरी\"},{\"item\":\"धूप अगरबत्ती\",\"quantity\":\"1 पैकेट\"},{\"item\":\"घी का दीपक\",\"quantity\":\"1\"},{\"item\":\"पान सुपारी लौंग इलायची\",\"quantity\":\"5-5\"},{\"item\":\"नारियल\",\"quantity\":\"1\"},{\"item\":\"फल\",\"quantity\":\"2-3 प्रकार\"},{\"item\":\"आरती थाली\",\"quantity\":\"1\"},{\"item\":\"कपूर\",\"quantity\":\"1 पैकेट\"}]', NULL, 'दुर्वा, लाल फूल, मोदक, लड्डू, चंदन, रोली, अक्षत, पंचामृत, जल, धूप, दीपक, नारियल, फल, पान, सुपारी, कपूर, आरती थाली', '30-45 मिनट', 'प्रातःकाल 6-8 बजे या सायंकाल 4-6 बजे', 'मंगलवार, बुधवार', NULL, 'गणेश चतुर्थी, बुधवार, किसी भी शुभ कार्य के आरंभ में', 'गणेश पूजा करने से विघ्नों का नाश होता है, बुद्धि और विवेक की वृद्धि होती है, कार्यों में सफलता मिलती है।', 'गणेश जी को तुलसी अर्पित नहीं करनी चाहिए। श्रद्धा और नियम से पूजा करें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(2, 'Shiva Pooja Vidhi (Rudrabhishek)', 'Shiva', 'Mahashivratri', 'Festival', 'शिव पूजा विधि - रुद्राभिषेक भगवान शिव की सबसे प्रिय पूजा है। जल, दूध, दही, घी, शहद, गंगाजल से शिवलिंग का अभिषेक किया जाता है।', '[{\"step\":1,\"name\":\"शुद्धिकरण Shuddhikaran\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। पूर्व या उत्तर दिशा में मुख करके बैठें।\"},{\"step\":2,\"name\":\"संकल्प Sankalpa\",\"description\":\"जल, फूल, अक्षत हाथ में लेकर संकल्प करें।\"},{\"step\":3,\"name\":\"शिवलिंग स्थापना\",\"description\":\"शिवलिंग स्थापित करें। पारद, स्फटिक या मिट्टी का शिवलिंग उत्तम होता है।\"},{\"step\":4,\"name\":\"आवाहन Avahana\",\"description\":\"ॐ नमः शिवाय मंत्र से शिवलिंग में भगवान शिव का आवाहन करें।\"},{\"step\":5,\"name\":\"पंचामृत स्नान Panchamrit Snana\",\"description\":\"पंचामृत से शिवलिंग का अभिषेक करें। प्रत्येक मंत्र से एक बार अभिषेक करें।\"},{\"step\":6,\"name\":\"जलाभिषेक Jalabhishek\",\"description\":\"शुद्ध जल से शिवलिंग का अभिषेक करें। ॐ नमः शिवाय मंत्र का जाप करते हुए निरंतर जल चढ़ाएं।\"},{\"step\":7,\"name\":\"बेलपत्र अर्पण Bilva Patra Arpan\",\"description\":\"बेलपत्र शिवलिंग पर अर्पित करें। ॐ नमः शिवाय मंत्र बोलें। 11, 21, 51, या 108 बेलपत्र अर्पित कर सकते हैं।\"},{\"step\":8,\"name\":\"धतूरा अर्पण Dhatura Arpan\",\"description\":\"धतूरा, भांग, मदार के फूल अर्पित करें।\"},{\"step\":9,\"name\":\"पुष्प अर्पण Pushpa Arpan\",\"description\":\"लाल फूल, आक के फूल, केवड़ा, चमेली के फूल अर्पित करें।\"},{\"step\":10,\"name\":\"चंदन अर्पण Chandan Arpan\",\"description\":\"शिवलिंग पर चंदन लगाएं।\"},{\"step\":11,\"name\":\"धूप-दीप Dhupa-Dipa\",\"description\":\"कपूर या घी का दीपक जलाएं।\"},{\"step\":12,\"name\":\"नैवेद्य Naivedya\",\"description\":\"पंचामृत, फल, मिठाई, पान अर्पित करें।\"},{\"step\":13,\"name\":\"रुद्र पाठ Rudra Path\",\"description\":\"रुद्राष्टाध्यायी या रुद्र सूक्त का पाठ करें।\"},{\"step\":14,\"name\":\"महामृत्युंजय मंत्र जाप\",\"description\":\"महामृत्युंजय मंत्र का 108 बार जाप करें।\"},{\"step\":15,\"name\":\"आरती Aarti\",\"description\":\"शिव आरती ॐ जय शिव ओंकारा करें।\"},{\"step\":16,\"name\":\"प्रदक्षिणा Pradakshina\",\"description\":\"शिवलिंग की तीन बार प्रदक्षिणा करें।\"},{\"step\":17,\"name\":\"क्षमा प्रार्थना Kshama Prarthana\",\"description\":\"पूजा में हुई त्रुटियों के लिए क्षमा प्रार्थना करें。\"}]', '[{\"item\":\"शिवलिंग पारद स्फटिक मिट्टी\",\"quantity\":\"1\"},{\"item\":\"बेलपत्र तीन पत्तों वाला\",\"quantity\":\"108\"},{\"item\":\"धतूरा\",\"quantity\":\"21\"},{\"item\":\"भांग\",\"quantity\":\"थोड़ी\"},{\"item\":\"लाल फूल आक के फूल\",\"quantity\":\"21\"},{\"item\":\"पंचामृत\",\"quantity\":\"1 लीटर\"},{\"item\":\"शुद्ध जल\",\"quantity\":\"2 लीटर\"},{\"item\":\"चंदन\",\"quantity\":\"थोड़ा\"},{\"item\":\"रुद्राक्ष\",\"quantity\":\"1 माला\"},{\"item\":\"धूप अगरबत्ती\",\"quantity\":\"1 पैकेट\"},{\"item\":\"घी का दीपक\",\"quantity\":\"1\"},{\"item\":\"कपूर\",\"quantity\":\"1 पैकेट\"},{\"item\":\"फल\",\"quantity\":\"2-3 प्रकार\"},{\"item\":\"पान सुपारी लौंग इलायची\",\"quantity\":\"5-5\"},{\"item\":\"नारियल\",\"quantity\":\"1\"},{\"item\":\"आरती थाली\",\"quantity\":\"1\"}]', NULL, 'शिवलिंग, बेलपत्र, धतूरा, पंचामृत, जल, चंदन, रुद्राक्ष, फल, पान, सुपारी, कपूर, घी, धूप', '45-60 मिनट', 'प्रातःकाल 4-6 बजे (ब्रह्म मुहूर्त) या सायंकाल 6-8 बजे', 'सोमवार, प्रदोष काल', NULL, 'सोमवार, शिवरात्रि, प्रदोष, और विशेष संकटों से मुक्ति के लिए', 'शिव पूजा से मानसिक शांति, रोगों से मुक्ति, आयु में वृद्धि, और मृत्यु के भय से मुक्ति मिलती है।', 'तुलसी और केतकी के फूल शिवलिंग पर अर्पित नहीं करने चाहिए। पूजा के दौरान मौन रहें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'Lakshmi Pooja Vidhi (Diwali Special)', 'Lakshmi', 'Diwali', 'Festival', 'दीपावली पर लक्ष्मी पूजा का विशेष महत्व है। यह पूजा धन, समृद्धि और सुख-शांति की प्राप्ति के लिए की जाती है।', '[{\"step\":1,\"name\":\"दीपक प्रज्वलन Deepak Prajvalan\",\"description\":\"पूजा स्थान की साफ-सफाई करें। घी के दीपक जलाएं और पूरे घर में दीप जलाएं।\"},{\"step\":2,\"name\":\"संकल्प Sankalpa\",\"description\":\"स्नान कर स्वच्छ वस्त्र धारण करें। जल, फूल, अक्षत हाथ में लेकर संकल्प करें।\"},{\"step\":3,\"name\":\"माता लक्ष्मी का आवाहन Avahana\",\"description\":\"लक्ष्मी यंत्र या मूर्ति स्थापित करें। ॐ श्रीं ह्रीं क्लीं महालक्ष्म्यै नमः मंत्र से आवाहन करें।\"},{\"step\":4,\"name\":\"श्री गणेश पूजन Ganesh Poojan\",\"description\":\"सर्वप्रथम गणेश जी की पूजा करें। विघ्नहर्ता गणपति का ध्यान करें।\"},{\"step\":5,\"name\":\"लक्ष्मी स्नान Lakshmi Snana\",\"description\":\"जल, पंचामृत से लक्ष्मी मूर्ति का अभिषेक करें। ॐ श्रीं ह्रीं क्लीं महालक्ष्म्यै नमः मंत्र बोलें।\"},{\"step\":6,\"name\":\"वस्त्र अर्पण Vastra Arpan\",\"description\":\"लाल वस्त्र, चुनरी अर्पित करें।\"},{\"step\":7,\"name\":\"गंध अर्पण Gandha Arpan\",\"description\":\"चंदन, केसर, कुमकुम अर्पित करें।\"},{\"step\":8,\"name\":\"अक्षत अर्पण Akshata Arpan\",\"description\":\"चावल और हल्दी मिलाकर अक्षत अर्पित करें।\"},{\"step\":9,\"name\":\"पुष्प अर्पण Pushpa Arpan\",\"description\":\"लाल फूल, कमल के फूल अर्पित करें।\"},{\"step\":10,\"name\":\"धूप-दीप Dhupa-Dipa\",\"description\":\"धूप और दीपक जलाएं।\"},{\"step\":11,\"name\":\"नैवेद्य Naivedya\",\"description\":\"मिष्ठान्न, फल, पान, सुपारी, नारियल अर्पित करें।\"},{\"step\":12,\"name\":\"श्री सूक्त पाठ Shri Sukta Path\",\"description\":\"श्री सूक्त का पाठ करें।\"},{\"step\":13,\"name\":\"लक्ष्मी गायत्री जाप\",\"description\":\"लक्ष्मी गायत्री का 108 बार जाप करें।\"},{\"step\":14,\"name\":\"कनकधारा स्तोत्र\",\"description\":\"कनकधारा स्तोत्र का पाठ करें।\"},{\"step\":15,\"name\":\"आरती Aarti\",\"description\":\"लक्ष्मी आरती ॐ जय लक्ष्मी माता करें।\"},{\"step\":16,\"name\":\"प्रदक्षिणा Pradakshina\",\"description\":\"तीन बार प्रदक्षिणा करें।\"},{\"step\":17,\"name\":\"क्षमा प्रार्थना Kshama Prarthana\",\"description\":\"पूजा में हुई त्रुटियों के लिए क्षमा प्रार्थना करें।\"},{\"step\":18,\"name\":\"प्रसाद वितरण Prasad Distribution\",\"description\":\"प्रसाद का वितरण करें。\"}]', '[{\"item\":\"लक्ष्मी मूर्ति या चित्र\",\"quantity\":\"1\"},{\"item\":\"श्री यंत्र\",\"quantity\":\"1\"},{\"item\":\"लाल वस्त्र चुनरी\",\"quantity\":\"1\"},{\"item\":\"लाल फूल कमल के फूल\",\"quantity\":\"21\"},{\"item\":\"चंदन केसर कुमकुम\",\"quantity\":\"थोड़ा\"},{\"item\":\"अक्षत चावल हल्दी\",\"quantity\":\"1 कटोरी\"},{\"item\":\"पंचामृत\",\"quantity\":\"1 कटोरी\"},{\"item\":\"जल\",\"quantity\":\"2 कटोरी\"},{\"item\":\"धूप अगरबत्ती\",\"quantity\":\"1 पैकेट\"},{\"item\":\"घी का दीपक\",\"quantity\":\"1\"},{\"item\":\"मिष्ठान्न\",\"quantity\":\"2-3 प्रकार\"},{\"item\":\"फल\",\"quantity\":\"3-5 प्रकार\"},{\"item\":\"पान सुपारी लौंग इलायची\",\"quantity\":\"5-5\"},{\"item\":\"नारियल\",\"quantity\":\"1\"},{\"item\":\"सिक्के\",\"quantity\":\"11\"},{\"item\":\"आरती थाली\",\"quantity\":\"1\"},{\"item\":\"कपूर\",\"quantity\":\"1 पैकेट\"}]', NULL, 'लक्ष्मी मूर्ति, श्री यंत्र, लाल वस्त्र, लाल फूल, चंदन, केसर, कुमकुम, अक्षत, पंचामृत, मिष्ठान्न, फल, पान, सुपारी, नारियल, सिक्के, दीपक, धूप, कपूर', '45-60 मिनट', 'सायंकाल 6-8 बजे (प्रदोष काल)', 'शुक्रवार, दीपावली', NULL, 'दीपावली पर लक्ष्मी पूजा का विशेष महत्व है। इस दिन माता लक्ष्मी पृथ्वी पर भ्रमण करती हैं।', 'लक्ष्मी पूजा से धन, समृद्धि, वैभव, सुख-शांति की प्राप्ति होती है।', 'पूजा स्थान स्वच्छ होना चाहिए। दक्षिण दिशा की ओर मुख न करें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Sandhyavandana Vidhi', 'Surya', NULL, 'Daily', 'संध्यावंदन एक दैनिक वैदिक अनुष्ठान है जो सूर्योपासना के लिए किया जाता है। यह प्रातः, मध्याह्न और सायंकाल में किया जाता है।', '[{\"step\":1,\"name\":\"आचमन Achamana\",\"description\":\"शुद्ध जल से तीन बार आचमन करें। ॐ केशवाय स्वाहा, ॐ नारायणाय स्वाहा, ॐ माधवाय स्वाहा।\"},{\"step\":2,\"name\":\"प्राणायाम Pranayama\",\"description\":\"तीन बार प्राणायाम करें। ॐ भूः, ॐ भुवः, ॐ स्वः का उच्चारण करते हुए।\"},{\"step\":3,\"name\":\"संकल्प Sankalpa\",\"description\":\"जल हाथ में लेकर संकल्प करें।\"},{\"step\":4,\"name\":\"मार्जन Marjana\",\"description\":\"जल से शरीर के विभिन्न अंगों को स्पर्श करें।\"},{\"step\":5,\"name\":\"अर्घ्यदान Arghyadan\",\"description\":\"सूर्य को जल अर्पित करें। तीन बार अर्घ्य दें।\"},{\"step\":6,\"name\":\"गायत्री जाप Gayatri Jap\",\"description\":\"गायत्री मंत्र का 108 बार जाप करें।\"},{\"step\":7,\"name\":\"तर्पण Tarpan\",\"description\":\"देव, ऋषि और पितरों को तर्पण दें।\"},{\"step\":8,\"name\":\"दिग्देवता वंदन\",\"description\":\"दसों दिशाओं के देवताओं को नमस्कार करें।\"},{\"step\":9,\"name\":\"क्षमाप्रार्थना\",\"description\":\"पूजा में हुई त्रुटियों के लिए क्षमा प्रार्थना करें。\"}]', '[{\"item\":\"जलपात्र तांबे का\",\"quantity\":\"1\"},{\"item\":\"आसन\",\"quantity\":\"1\"},{\"item\":\"अर्घ्य पात्र\",\"quantity\":\"1\"},{\"item\":\"अक्षत\",\"quantity\":\"थोड़ा\"},{\"item\":\"फूल\",\"quantity\":\"थोड़ा\"},{\"item\":\"चंदन\",\"quantity\":\"थोड़ा\"}]', NULL, 'तांबे का जलपात्र, आसन, अर्घ्य पात्र, अक्षत, फूल, चंदन, गायत्री माला रुद्राक्ष', '15-20 मिनट', 'प्रातः सूर्योदय से पहले, मध्याह्न 12 बजे, सायं सूर्यास्त के समय', 'प्रतिदिन', NULL, 'संध्यावंदन वैदिक संस्कृति का महत्वपूर्ण अंग है। यह सूर्य देव को समर्पित है।', 'संध्यावंदन से मानसिक शांति, आत्मिक बल, सकारात्मक ऊर्जा प्राप्त होती है।', 'मैले कपड़ों में संध्यावंदन न करें। शुद्धता और एकाग्रता बनाए रखें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Satyanarayan Pooja Vidhi', 'Satyanarayan', NULL, 'Special', 'सत्यनारायण पूजा एक प्रसिद्ध व्रत और पूजा है जो किसी भी शुभ अवसर पर, संकट से मुक्ति के लिए, या मनोकामना पूर्ति के लिए की जाती है।', '[{\"step\":1,\"name\":\"संकल्प Sankalpa\",\"description\":\"स्नान कर स्वच्छ वस्त्र धारण करें। संकल्प लें कि मैं सत्यनारायण भगवान की पूजा करूंगा।\"},{\"step\":2,\"name\":\"गणेश पूजन\",\"description\":\"प्रथम गणेश जी की पूजा करें।\"},{\"step\":3,\"name\":\"नवग्रह पूजन\",\"description\":\"नवग्रहों की पूजा करें।\"},{\"step\":4,\"name\":\"कलश स्थापना\",\"description\":\"कलश स्थापित करें। कलश में जल, सुपारी, पान, नारियल रखें।\"},{\"step\":5,\"name\":\"सत्यनारायण भगवान का आवाहन\",\"description\":\"सत्यनारायण भगवान की मूर्ति या चित्र स्थापित करें। ॐ सत्यनारायणाय नमः मंत्र से आवाहन करें।\"},{\"step\":6,\"name\":\"षोडशोपचार पूजन\",\"description\":\"16 उपचारों से पूजा करें - आसन, पाद्य, अर्घ्य, स्नान, वस्त्र, यज्ञोपवीत, गंध, अक्षत, पुष्प, धूप, दीप, नैवेद्य, ताम्बूल, आरती, प्रदक्षिणा, मंत्रपुष्प।\"},{\"step\":7,\"name\":\"सत्यनारायण कथा वाचन\",\"description\":\"पांच अध्यायों की सत्यनारायण कथा सुनें या सुनाएं।\"},{\"step\":8,\"name\":\"आरती\",\"description\":\"सत्यनारायण आरती करें।\"},{\"step\":9,\"name\":\"प्रसाद वितरण\",\"description\":\"पंचामृत, फल, मिठाई का प्रसाद वितरित करें।\"},{\"step\":10,\"name\":\"क्षमा प्रार्थना\",\"description\":\"पूजा में हुई त्रुटियों के लिए क्षमा प्रार्थना करें。\"}]', '[{\"item\":\"सत्यनारायण भगवान की मूर्ति या चित्र\",\"quantity\":\"1\"},{\"item\":\"कलश\",\"quantity\":\"1\"},{\"item\":\"नारियल कलश पर\",\"quantity\":\"1\"},{\"item\":\"पंचामृत\",\"quantity\":\"1 कटोरी\"},{\"item\":\"मिष्ठान्न\",\"quantity\":\"2-3 प्रकार\"},{\"item\":\"गेहूं का आटा\",\"quantity\":\"2 किलो\"},{\"item\":\"चीनी\",\"quantity\":\"1 किलो\"},{\"item\":\"केले\",\"quantity\":\"11\"},{\"item\":\"पान सुपारी लौंग इलायची\",\"quantity\":\"11-11\"},{\"item\":\"फूल\",\"quantity\":\"1 माला\"},{\"item\":\"चंदन रोली अक्षत\",\"quantity\":\"थोड़ा\"},{\"item\":\"धूप दीपक\",\"quantity\":\"1-1\"},{\"item\":\"सत्यनारायण कथा पुस्तक\",\"quantity\":\"1\"},{\"item\":\"आरती थाली\",\"quantity\":\"1\"}]', NULL, 'सत्यनारायण मूर्ति, कलश, नारियल, पंचामृत, मिष्ठान्न, गेहूं का आटा, चीनी, केले, पान, सुपारी, फूल, चंदन, रोली, अक्षत, धूप, दीपक, सत्यनारायण कथा पुस्तक', '1-2 घंटे', 'प्रातः 8-10 बजे या सायं 4-6 बजे', 'पूर्णिमा, संकष्टी चतुर्थी, या किसी भी शुभ दिन', NULL, 'सत्यनारायण पूजा भगवान विष्णु के सत्य स्वरूप की पूजा है।', 'सत्यनारायण पूजा करने से सभी संकट दूर होते हैं, मनोकामनाएं पूर्ण होती हैं।', 'कथा के पांचों अध्याय पूरे सुनना चाहिए। पूजा के बाद बिना प्रसाद लिए कोई न जाए।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Durga Saptashati Path Vidhi', 'Durga', 'Navratri', 'Festival', 'दुर्गा सप्तशती पाठ नवरात्रि के दौरान किया जाने वाला प्रमुख अनुष्ठान है। इसमें 13 अध्यायों का पाठ किया जाता है।', '[{\"step\":1,\"name\":\"शुद्धिकरण\",\"description\":\"स्नान कर शुद्ध वस्त्र धारण करें। पूजा स्थान को गंगाजल से शुद्ध करें।\"},{\"step\":2,\"name\":\"कलश स्थापना\",\"description\":\"नवरात्रि के प्रथम दिन कलश स्थापना करें। कलश में जल, पंचरत्न, सुपारी, पान रखें।\"},{\"step\":3,\"name\":\"देवी का आवाहन\",\"description\":\"दुर्गा मूर्ति या यंत्र स्थापित करें। ॐ ऐं ह्रीं क्लीं चामुण्डायै विच्चे मंत्र से आवाहन करें।\"},{\"step\":4,\"name\":\"नवार्ण मंत्र जाप\",\"description\":\"नवार्ण मंत्र का 108 बार जाप करें।\"},{\"step\":5,\"name\":\"दुर्गा सप्तशती पाठ\",\"description\":\"दुर्गा सप्तशती के 13 अध्यायों का पाठ करें। प्रत्येक दिन 3 अध्याय का पाठ करें।\"},{\"step\":6,\"name\":\"देवी सूक्त पाठ\",\"description\":\"देवी सूक्त, रात्रि सूक्त, क्षमा सूक्त का पाठ करें।\"},{\"step\":7,\"name\":\"अर्घ्य अर्पण\",\"description\":\"देवी को अर्घ्य, पुष्प, धूप, दीप अर्पित करें।\"},{\"step\":8,\"name\":\"नैवेद्य अर्पण\",\"description\":\"हलवा, पूरी, चना, नारियल, फल अर्पित करें।\"},{\"step\":9,\"name\":\"आरती\",\"description\":\"दुर्गा आरती जय अम्बे गौरी करें।\"},{\"step\":10,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"},{\"step\":11,\"name\":\"विसर्जन Navami\",\"description\":\"नवमी के दिन पूजन के बाद विसर्जन करें。\"}]', '[{\"item\":\"दुर्गा मूर्ति या यंत्र\",\"quantity\":\"1\"},{\"item\":\"कलश\",\"quantity\":\"1\"},{\"item\":\"नारियल\",\"quantity\":\"1\"},{\"item\":\"लाल वस्त्र\",\"quantity\":\"1\"},{\"item\":\"लाल फूल\",\"quantity\":\"51\"},{\"item\":\"चंदन कुमकुम अक्षत\",\"quantity\":\"थोड़ा\"},{\"item\":\"पंचामृत\",\"quantity\":\"1 कटोरी\"},{\"item\":\"धूप दीपक\",\"quantity\":\"1-1\"},{\"item\":\"हलवा-पूरी चना\",\"quantity\":\"भोग के लिए\"},{\"item\":\"फल\",\"quantity\":\"5 प्रकार\"},{\"item\":\"दुर्गा सप्तशती पुस्तक\",\"quantity\":\"1\"},{\"item\":\"श्री यंत्र\",\"quantity\":\"1 वैकल्पिक\"}]', NULL, 'दुर्गा मूर्ति, कलश, लाल वस्त्र, लाल फूल, चंदन, कुमकुम, पंचामृत, धूप, दीपक, हलवा-पूरी, फल, दुर्गा सप्तशती पुस्तक', '1-2 घंटे प्रतिदिन', 'प्रातः 6-9 बजे या सायं 4-7 बजे', 'नवरात्रि के 9 दिन', NULL, 'दुर्गा सप्तशती का पाठ नवरात्रि के दौरान विशेष फलदायक होता है।', 'दुर्गा सप्तशती पाठ से सभी संकटों का नाश होता है, शत्रुओं पर विजय मिलती है।', 'पाठ के दौरान मौन रहें। अशुद्ध अवस्था में पाठ न करें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Vishnu Sahasranama Path Vidhi', 'Vishnu', NULL, 'Daily/Special', 'विष्णु सहस्रनाम भगवान विष्णु के 1000 नामों का पाठ है। यह पाठ सभी पापों का नाश करने वाला और मोक्ष प्रदान करने वाला माना जाता है।', '[{\"step\":1,\"name\":\"शुद्धिकरण\",\"description\":\"प्रातः स्नान कर शुद्ध वस्त्र धारण करें। पूर्व या उत्तर दिशा में मुख करके बैठें।\"},{\"step\":2,\"name\":\"आचमन\",\"description\":\"जल से तीन बार आचमन करें।\"},{\"step\":3,\"name\":\"प्राणायाम\",\"description\":\"तीन बार प्राणायाम करें।\"},{\"step\":4,\"name\":\"संकल्प\",\"description\":\"जल, अक्षत, पुष्प हाथ में लेकर संकल्प करें।\"},{\"step\":5,\"name\":\"गणेश पूजन\",\"description\":\"गणेश जी की पूजा करें।\"},{\"step\":6,\"name\":\"विष्णु पूजन\",\"description\":\"विष्णु मूर्ति या चित्र स्थापित करें। ॐ नमो भगवते वासुदेवाय मंत्र से पूजा करें।\"},{\"step\":7,\"name\":\"विष्णु सहस्रनाम पाठ\",\"description\":\"विष्णु सहस्रनाम का पाठ करें। फलश्रुति सहित पूरा पाठ करें।\"},{\"step\":8,\"name\":\"आरती\",\"description\":\"विष्णु आरती जय विष्णु भगवान करें।\"},{\"step\":9,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें。\"}]', '[{\"item\":\"विष्णु मूर्ति या चित्र\",\"quantity\":\"1\"},{\"item\":\"तुलसी दल\",\"quantity\":\"11\"},{\"item\":\"फूल\",\"quantity\":\"1 माला\"},{\"item\":\"चंदन\",\"quantity\":\"थोड़ा\"},{\"item\":\"अक्षत\",\"quantity\":\"थोड़ा\"},{\"item\":\"धूप दीपक\",\"quantity\":\"1-1\"},{\"item\":\"मिष्ठान्न\",\"quantity\":\"भोग के लिए\"},{\"item\":\"फल\",\"quantity\":\"2-3 प्रकार\"},{\"item\":\"विष्णु सहस्रनाम पुस्तक\",\"quantity\":\"1\"}]', NULL, 'विष्णु मूर्ति, तुलसी दल, फूल, चंदन, अक्षत, धूप, दीपक, मिष्ठान्न, फल, विष्णु सहस्रनाम पुस्तक', '30-45 मिनट', 'प्रातः 6-8 बजे', 'गुरुवार, एकादशी', NULL, 'विष्णु सहस्रनाम का पाठ सभी पापों का नाश करने वाला, मोक्ष प्रदान करने वाला है।', 'विष्णु सहस्रनाम पाठ से मानसिक शांति, धन-समृद्धि, सभी कष्टों से मुक्ति मिलती है।', 'पाठ के दौरान शुद्धता बनाए रखें। तुलसी का विशेष महत्व है।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Hanuman Pooja Vidhi', 'Hanuman', 'Hanuman Jayanti', 'Special', 'हनुमान पूजा बल, बुद्धि और साहस की प्राप्ति के लिए की जाती है। हनुमान जी संकट मोचन कहलाते हैं।', '[{\"step\":1,\"name\":\"शुद्धिकरण\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। पूर्व या उत्तर दिशा में मुख करें।\"},{\"step\":2,\"name\":\"आचमन और प्राणायाम\",\"description\":\"आचमन और प्राणायाम करें।\"},{\"step\":3,\"name\":\"संकल्प\",\"description\":\"हनुमान जी की पूजा का संकल्प लें।\"},{\"step\":4,\"name\":\"गणेश पूजन\",\"description\":\"गणेश जी की पूजा करें।\"},{\"step\":5,\"name\":\"हनुमान मूर्ति स्थापना\",\"description\":\"हनुमान जी की मूर्ति या चित्र स्थापित करें। लाल आसन बिछाएं।\"},{\"step\":6,\"name\":\"सिंदूर अर्पण\",\"description\":\"हनुमान जी को सिंदूर अर्पित करें। ॐ हनुमते नमः मंत्र बोलें।\"},{\"step\":7,\"name\":\"लाल फूल अर्पण\",\"description\":\"लाल गुलाब या जवा के फूल अर्पित करें।\"},{\"step\":8,\"name\":\"चोला अर्पण\",\"description\":\"लाल चोला अर्पित करें।\"},{\"step\":9,\"name\":\"नैवेद्य अर्पण\",\"description\":\"चने की दाल, गुड़, बूंदी के लड्डू अर्पित करें।\"},{\"step\":10,\"name\":\"हनुमान चालीसा पाठ\",\"description\":\"हनुमान चालीसा का पाठ करें।\"},{\"step\":11,\"name\":\"बजरंग बाण पाठ\",\"description\":\"बजरंग बाण का पाठ करें वैकल्पिक।\"},{\"step\":12,\"name\":\"सुंदरकांड पाठ\",\"description\":\"सुंदरकांड का पाठ करें वैकल्पिक।\"},{\"step\":13,\"name\":\"आरती\",\"description\":\"हनुमान आरती आरती कीजै हनुमान लला की करें।\"},{\"step\":14,\"name\":\"प्रदक्षिणा\",\"description\":\"तीन बार प्रदक्षिणा करें।\"},{\"step\":15,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें。\"}]', '[{\"item\":\"हनुमान मूर्ति या चित्र\",\"quantity\":\"1\"},{\"item\":\"सिंदूर\",\"quantity\":\"1 पैकेट\"},{\"item\":\"लाल फूल जवा के फूल\",\"quantity\":\"21\"},{\"item\":\"लाल चोला लाल वस्त्र\",\"quantity\":\"1\"},{\"item\":\"चने की दाल\",\"quantity\":\"250 ग्राम\"},{\"item\":\"गुड़\",\"quantity\":\"250 ग्राम\"},{\"item\":\"बूंदी के लड्डू\",\"quantity\":\"11\"},{\"item\":\"चंदन रोली\",\"quantity\":\"थोड़ा\"},{\"item\":\"अक्षत\",\"quantity\":\"थोड़ा\"},{\"item\":\"धूप दीपक\",\"quantity\":\"1-1\"},{\"item\":\"कपूर\",\"quantity\":\"1 पैकेट\"},{\"item\":\"हनुमान चालीसा पुस्तक\",\"quantity\":\"1\"},{\"item\":\"बजरंग बाण पुस्तक\",\"quantity\":\"1 वैकल्पिक\"}]', NULL, 'हनुमान मूर्ति, सिंदूर, लाल फूल, लाल चोला, चने की दाल, गुड़, बूंदी के लड्डू, चंदन, रोली, अक्षत, धूप, दीपक, कपूर, हनुमान चालीसा', '30-45 मिनट', 'प्रातः 6-8 बजे या सायं 4-6 बजे', 'मंगलवार, शनिवार', NULL, 'हनुमान जी बल, बुद्धि और साहस के देवता हैं। उनकी पूजा से सभी संकटों से मुक्ति मिलती है।', 'हनुमान पूजा से बल, बुद्धि, साहस की प्राप्ति होती है। शत्रुओं पर विजय मिलती है।', 'मंगलवार और शनिवार को हनुमान जी की पूजा का विशेष महत्व है। सिंदूर का प्रयोग अवश्य करें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:38', '2026-03-27 13:54:38', NULL, NULL, NULL, NULL, NULL, NULL),
(9, 'Santoshi Mata Vrat Vidhi', 'Santoshi', NULL, 'Vrat', 'संतोषी माता का व्रत शुक्रवार को किया जाता है। यह व्रत 16 शुक्रवार तक करने से संतोष की प्राप्ति होती है।', '[{\"step\":1,\"name\":\"संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। 16 शुक्रवार का संकल्प लें।\"},{\"step\":2,\"name\":\"गणेश पूजन\",\"description\":\"गणेश जी की पूजा करें।\"},{\"step\":3,\"name\":\"संतोषी माता पूजन\",\"description\":\"संतोषी माता की मूर्ति या चित्र स्थापित करें। ॐ संतोष्यै नमः मंत्र से पूजा करें।\"},{\"step\":4,\"name\":\"गुड़-चना अर्पण\",\"description\":\"संतोषी माता को गुड़ और चना अर्पित करें।\"},{\"step\":5,\"name\":\"कथा वाचन\",\"description\":\"संतोषी माता की कथा सुनें या सुनाएं।\"},{\"step\":6,\"name\":\"आरती\",\"description\":\"संतोषी माता की आरती जय संतोषी माता करें।\"},{\"step\":7,\"name\":\"प्रसाद वितरण\",\"description\":\"गुड़-चने का प्रसाद वितरित करें。\"}]', '[{\"item\":\"संतोषी माता की मूर्ति या चित्र\",\"quantity\":\"1\"},{\"item\":\"गुड़\",\"quantity\":\"250 ग्राम\"},{\"item\":\"चना\",\"quantity\":\"250 ग्राम\"},{\"item\":\"फल\",\"quantity\":\"2-3 प्रकार\"},{\"item\":\"पान सुपारी\",\"quantity\":\"5-5\"},{\"item\":\"फूल\",\"quantity\":\"1 माला\"},{\"item\":\"चंदन रोली अक्षत\",\"quantity\":\"थोड़ा\"},{\"item\":\"धूप दीपक\",\"quantity\":\"1-1\"}]', NULL, 'संतोषी माता मूर्ति, गुड़, चना, फल, पान, सुपारी, फूल, चंदन, रोली, अक्षत, धूप, दीपक', '1-2 घंटे', 'प्रातः 8-10 बजे', 'शुक्रवार', NULL, 'संतोषी माता का व्रत 16 शुक्रवार तक करने से संतोष की प्राप्ति होती है।', 'संतोषी माता का व्रत करने से घर में सुख-शांति, संतोष, और समृद्धि आती है।', 'व्रत के दिन खट्टा न खाएं। गुड़-चने का भोग लगाना आवश्यक है।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:39', '2026-03-27 13:54:39', NULL, NULL, NULL, NULL, NULL, NULL),
(10, 'Tulsi Pooja Vidhi', 'Tulsi', NULL, 'Daily', 'तुलसी पूजा प्रतिदिन की जाती है। तुलसी माता को भगवान विष्णु की प्रिय माना जाता है। तुलसी पूजा से घर में सुख-समृद्धि आती है।', '[{\"step\":1,\"name\":\"शुद्धिकरण\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें।\"},{\"step\":2,\"name\":\"तुलसी वृंदावन की सफाई\",\"description\":\"तुलसी के पौधे और उसके आसपास की सफाई करें।\"},{\"step\":3,\"name\":\"जल अर्पण\",\"description\":\"तुलसी में जल अर्पित करें। ॐ तुलस्यै नमः मंत्र बोलें।\"},{\"step\":4,\"name\":\"दीपक जलाना\",\"description\":\"तुलसी के समीप दीपक जलाएं।\"},{\"step\":5,\"name\":\"फूल अर्पण\",\"description\":\"तुलसी को फूल अर्पित करें।\"},{\"step\":6,\"name\":\"परिक्रमा\",\"description\":\"तुलसी की तीन या सात बार परिक्रमा करें।\"},{\"step\":7,\"name\":\"आरती\",\"description\":\"तुलसी आरती जय तुलसी माता करें।\"},{\"step\":8,\"name\":\"प्रार्थना\",\"description\":\"सुख-समृद्धि की प्रार्थना करें。\"}]', '[{\"item\":\"तुलसी का पौधा\",\"quantity\":\"1\"},{\"item\":\"जल\",\"quantity\":\"1 लोटा\"},{\"item\":\"दीपक घी का\",\"quantity\":\"1\"},{\"item\":\"फूल\",\"quantity\":\"थोड़ा\"},{\"item\":\"चंदन\",\"quantity\":\"थोड़ा\"},{\"item\":\"धूप\",\"quantity\":\"1\"}]', NULL, 'तुलसी का पौधा, जल, घी का दीपक, फूल, चंदन, धूप', '10-15 मिनट', 'सूर्यास्त के समय', 'प्रतिदिन, विशेषकर गुरुवार', NULL, 'तुलसी पूजा से घर में सुख-शांति, समृद्धि और सकारात्मक ऊर्जा का संचार होता है।', 'तुलसी पूजा से घर में सुख-समृद्धि आती है, रोगों से मुक्ति मिलती है।', 'तुलसी को सूर्यास्त के बाद न छुएं। रविवार को तुलसी न तोड़ें।', NULL, NULL, 0, 0, 0, '2026-03-27 13:54:39', '2026-03-27 13:54:39', NULL, NULL, NULL, NULL, NULL, NULL);
