INSERT INTO `vrat_katha` (`id`, `katha_name`, `deity_name`, `vrat_duration`, `vrat_day`, `vrat_month`, `tithi`, `description`, `significance`, `benefits`, `rules`, `katha_chapters`, `vidhi`, `samagri_list`, `opening_verse`, `closing_verse`, `aarti_name`, `audio_url`, `video_url`, `is_premium`, `views_count`, `likes_count`, `created_at`, `updated_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`, `vrat_significance`, `duration`, `synopsis`, `title`, `sanskrit`, `sanskrit_title`, `category`, `category_label`, `deity`, `katha_text`, `chapters`, `translation_hi`, `translation_en`, `is_featured`) VALUES
(1, 'Solah Somvar Vrat Katha', 'Shiva', '16 Mondays', 'Monday', 'Throughout Year', 'Any Monday', 'सोलह सोमवार व्रत भगवान शिव को समर्पित है। यह व्रत 16 सोमवार तक किया जाता है। यह व्रत विशेष रूप से अविवाहित लड़कियां अच्छा वर पाने के लिए और विवाहित महिलाएं सुखी वैवाहिक जीवन के लिए करती हैं।', 'सोलह सोमवार व्रत भगवान शिव की कृपा प्राप्ति के लिए अत्यंत फलदायी है। यह व्रत करने से सभी मनोकामनाएं पूर्ण होती हैं।', 'इस व्रत को करने से मनोवांछित वर की प्राप्ति, वैवाहिक जीवन में सुख-शांति, धन-समृद्धि, संतान सुख और सभी कष्टों से मुक्ति मिलती है।', 'व्रत के दिन केवल एक बार फलाहार करें। बिना नमक का भोजन करें। ब्रह्मचर्य का पालन करें। झूठ न बोलें। क्रोध न करें।', '[\r\n    {\"chapter\":1,\"title\":\"प्रथम सोमवार - राजा धर्मसेन की कथा\",\"story\":\"प्राचीन काल में धर्मसेन नामक एक राजा थे। उनके राज्य में सुख-समृद्धि थी, लेकिन उनकी कोई संतान नहीं थी। एक दिन राजा ने महर्षि वशिष्ठ से संतान प्राप्ति का उपाय पूछा। ऋषि ने कहा - हे राजन, आप सोलह सोमवार का व्रत करें। भगवान शिव की कृपा से आपको संतान सुख अवश्य प्राप्त होगा। राजा ने विधि-विधान से व्रत किया। सोलहवें सोमवार को भगवान शिव ने प्रसन्न होकर राजा को पुत्र रत्न प्रदान किया। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"द्वितीय सोमवार - गरीणी ब्राह्मणी की कथा\",\"story\":\"एक गरीब ब्राह्मणी के पास खाने को अन्न नहीं था। उसने सोलह सोमवार का व्रत किया। व्रत के प्रभाव से उसके घर में धन-धान्य की कमी नहीं रही। वह सुखी हो गई।\"},\r\n    {\"chapter\":3,\"title\":\"सोलहवाँ सोमवार - फल प्राप्ति\",\"story\":\"सोलहवें सोमवार को व्रत पूर्ण करने पर भगवान शिव और माता पार्वती प्रसन्न होते हैं और व्रत करने वाले की सभी मनोकामनाएं पूर्ण करते हैं।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। जल, फूल, अक्षत हाथ में लेकर सोलह सोमवार व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"शिवलिंग स्थापना\",\"description\":\"शिवलिंग स्थापित करें या शिव मंदिर जाएं।\"},\r\n    {\"step\":3,\"name\":\"अभिषेक\",\"description\":\"शिवलिंग का जल, दूध, दही, घी, शहद, गंगाजल से अभिषेक करें।\"},\r\n    {\"step\":4,\"name\":\"बेलपत्र अर्पण\",\"description\":\"शिवलिंग पर बेलपत्र, धतूरा, भांग अर्पित करें।\"},\r\n    {\"step\":5,\"name\":\"शिव चालीसा पाठ\",\"description\":\"शिव चालीसा या शिव स्तोत्र का पाठ करें।\"},\r\n    {\"step\":6,\"name\":\"आरती\",\"description\":\"शिव आरती ॐ जय शिव ओंकारा करें।\"},\r\n    {\"step\":7,\"name\":\"कथा वाचन\",\"description\":\"सोलह सोमवार व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":8,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें। प्रत्येक सोमवार को यह विधि करें। 16 सोमवार पूरे होने पर उद्यापन करें।\"}\r\n]', 'शिवलिंग, बेलपत्र, धतूरा, भांग, पंचामृत, जल, चंदन, रुद्राक्ष, फल, मिठाई, दीपक, धूप, कपूर', 'ॐ नमः शिवाय। हे शिवशंकर, मैं सोलह सोमवार व्रत का संकल्प लेता/लेती हूँ।', 'ॐ नमः शिवाय। हे शिवशंकर, आपकी कृपा से सोलह सोमवार व्रत सफलतापूर्वक संपन्न हुआ। मेरी सभी मनोकामनाएं पूर्ण करें।', 'Om Jai Shiv Omkara', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:49', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'सोलह सोमवार व्रत भगवान शिव की कृपा प्राप्ति के लिए अत्यंत फलदायी है। यह व्रत करने से सभी मनोकामनाएं पूर्ण होती हैं।', '16 Mondays', 'सोलह सोमवार व्रत भगवान शिव को समर्पित है। यह व्रत 16 सोमवार तक किया जाता है। यह व्रत विशेष रूप से अविवाहित लड़कियां अच्छा वर पाने के लिए और विवाहित महिलाएं सुखी वैवाहिक जीवन के लिए करती हैं।', 'Solah Somvar Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Shiva', 'सोलह सोमवार व्रत भगवान शिव को समर्पित है। यह व्रत 16 सोमवार तक किया जाता है। यह व्रत विशेष रूप से अविवाहित लड़कियां अच्छा वर पाने के लिए और विवाहित महिलाएं सुखी वैवाहिक जीवन के लिए करती हैं।', NULL, NULL, NULL, 1),
(2, 'Mangala Gauri Vrat Katha', 'Gauri', '5 Tuesdays', 'Tuesday', 'Shravan (Jul-Aug)', 'Shravan Mangalvar', 'मंगला गौरी व्रत सावन मास के मंगलवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं। अविवाहित लड़कियां अच्छा वर पाने के लिए यह व्रत करती हैं।', 'सावन के मंगलवार को मंगला गौरी व्रत का विशेष महत्व है। यह व्रत माता पार्वती को समर्पित है और सुहागन महिलाओं के लिए अत्यंत फलदायी है।', 'इस व्रत को करने से पति की लंबी आयु, सुखी वैवाहिक जीवन, सौभाग्य की रक्षा, संतान सुख और सभी मनोकामनाओं की पूर्ति होती है।', 'व्रत के दिन केवल एक बार फलाहार करें। बिना नमक का भोजन करें। सात्विक भोजन करें। ब्रह्मचर्य का पालन करें।', '[\r\n    {\"chapter\":1,\"title\":\"प्रथम मंगलवार - मंगला गौरी व्रत की उत्पत्ति\",\"story\":\"प्राचीन काल में एक सुंदरी नाम की कन्या थी। उसकी माता ने उसे सावन के मंगलवार को मंगला गौरी व्रत करने को कहा। सुंदरी ने विधि-विधान से व्रत किया। व्रत के प्रभाव से उसे मनचाहा वर मिला। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"दूसरा मंगलवार - राजा की रानी की कथा\",\"story\":\"एक राजा की रानी निरंतर मंगला गौरी व्रत करती थी। व्रत के प्रभाव से राजा का राज्य समृद्ध रहता था। एक बार राजा ने पूछा - तुम इतना कठोर व्रत क्यों करती हो? रानी ने व्रत की महिमा बताई। राजा ने भी श्रद्धा से व्रत किया। तब से राज्य में सुख-समृद्धि आ गई।\"},\r\n    {\"chapter\":3,\"title\":\"पाँचवाँ मंगलवार - फल प्राप्ति\",\"story\":\"पाँचवें मंगलवार को व्रत पूर्ण करने पर माता पार्वती प्रसन्न होती हैं और व्रत करने वाली की सभी मनोकामनाएं पूर्ण करती हैं।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। मंगला गौरी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"माता गौरी की पूजा\",\"description\":\"माता गौरी की मूर्ति या चित्र स्थापित करें। सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":3,\"name\":\"कथा वाचन\",\"description\":\"मंगला गौरी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":4,\"name\":\"नैवेद्य अर्पण\",\"description\":\"फल, मिठाई, नारियल, पान, सुपारी अर्पित करें।\"},\r\n    {\"step\":5,\"name\":\"आरती\",\"description\":\"गौरी आरती करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें। पाँच मंगलवार तक यह विधि करें।\"}\r\n]', 'सोलह श्रृंगार की वस्तुएं (सिंदूर, काजल, बिछिया, नथ, आदि), फल, मिठाई, नारियल, पान, सुपारी, सुपारी, दीपक, धूप, कपूर', 'ॐ गौर्यै नमः। हे माता गौरी, मैं मंगला गौरी व्रत का संकल्प लेती हूँ।', 'ॐ गौर्यै नमः। हे माता गौरी, आपकी कृपा से मंगला गौरी व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Jai Ambe Gauri', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:49', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'सावन के मंगलवार को मंगला गौरी व्रत का विशेष महत्व है। यह व्रत माता पार्वती को समर्पित है और सुहागन महिलाओं के लिए अत्यंत फलदायी है।', '5 Tuesdays', 'मंगला गौरी व्रत सावन मास के मंगलवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं। अविवाहित लड़कियां अच्छा वर पाने के लिए यह व्रत करती हैं।', 'Mangala Gauri Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Gauri', 'मंगला गौरी व्रत सावन मास के मंगलवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं। अविवाहित लड़कियां अच्छा वर पाने के लिए यह व्रत करती हैं।', NULL, NULL, NULL, 1),
(3, 'Varalakshmi Vrat Katha', 'Lakshmi', '1 Day', 'Friday', 'Shravan (Jul-Aug)', 'Shravan Shukla Shukravar', 'वरलक्ष्मी व्रत श्रावण मास के शुक्ल पक्ष के शुक्रवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए करती हैं।', 'वरलक्ष्मी व्रत का विशेष महत्व है। यह व्रत माता लक्ष्मी को समर्पित है। इस दिन माता लक्ष्मी की पूजा करने से घर में धन-धान्य की कमी नहीं होती।', 'इस व्रत को करने से धन-समृद्धि, सुख-शांति, संतान सुख, पति की लंबी आयु और सभी मनोकामनाओं की पूर्ति होती है।', 'व्रत के दिन केवल एक बार फलाहार या सात्विक भोजन करें। निर्जला व्रत भी किया जा सकता है।', '[\r\n    {\"chapter\":1,\"title\":\"वरलक्ष्मी व्रत की उत्पत्ति\",\"story\":\"प्राचीन काल में चारोली नाम की एक सुहागन महिला थी। वह अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए सदा चिंतित रहती थी। एक रात उसने सपने में माता लक्ष्मी को देखा। माता ने कहा - हे सुभाग्यवती, श्रावण मास के शुक्ल पक्ष के शुक्रवार को मेरा व्रत करो। इससे तुम्हारी सभी मनोकामनाएं पूर्ण होंगी। चारोली ने श्रद्धा से व्रत किया। व्रत के प्रभाव से उसके घर में सुख-समृद्धि आ गई। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"रानी की कथा\",\"story\":\"एक राजा की रानी ने वरलक्ष्मी व्रत किया। व्रत के प्रभाव से राज्य में सुख-समृद्धि आ गई। राजा की सभी मनोकामनाएं पूर्ण हुईं।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। वरलक्ष्मी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"कलश स्थापना\",\"description\":\"कलश स्थापित करें। कलश में जल, सुपारी, पान, नारियल रखें। कलश पर लक्ष्मी का चित्र लगाएं।\"},\r\n    {\"step\":3,\"name\":\"माता लक्ष्मी की पूजा\",\"description\":\"माता लक्ष्मी की मूर्ति या चित्र स्थापित करें। ॐ श्रीं ह्रीं क्लीं महालक्ष्म्यै नमः मंत्र से पूजा करें।\"},\r\n    {\"step\":4,\"name\":\"सोलह श्रृंगार\",\"description\":\"माता लक्ष्मी को सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":5,\"name\":\"कथा वाचन\",\"description\":\"वरलक्ष्मी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":6,\"name\":\"आरती\",\"description\":\"लक्ष्मी आरती ॐ जय लक्ष्मी माता करें।\"},\r\n    {\"step\":7,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"}\r\n]', 'कलश, नारियल, सोलह श्रृंगार की वस्तुएं, लाल वस्त्र, लाल फूल, चंदन, कुमकुम, अक्षत, पंचामृत, फल, मिठाई, पान, सुपारी, दीपक, धूप, कपूर', 'ॐ श्रीं महालक्ष्म्यै नमः। हे माता वरलक्ष्मी, मैं वरलक्ष्मी व्रत का संकल्प लेती हूँ।', 'ॐ श्रीं महालक्ष्म्यै नमः। हे माता वरलक्ष्मी, आपकी कृपा से वरलक्ष्मी व्रत सफलतापूर्वक संपन्न हुआ।', 'Om Jai Lakshmi Mata', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'वरलक्ष्मी व्रत का विशेष महत्व है। यह व्रत माता लक्ष्मी को समर्पित है। इस दिन माता लक्ष्मी की पूजा करने से घर में धन-धान्य की कमी नहीं होती।', '1 Day', 'वरलक्ष्मी व्रत श्रावण मास के शुक्ल पक्ष के शुक्रवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए करती हैं।', 'Varalakshmi Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Lakshmi', 'वरलक्ष्मी व्रत श्रावण मास के शुक्ल पक्ष के शुक्रवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए करती हैं।', NULL, NULL, NULL, 1),
(4, 'Hartalika Teej Vrat Katha', 'Shiva-Parvati', '1 Day', 'Not Specified', 'Bhadrapada (Aug-Sep)', 'Shukla Tritiya', 'हरतालिका तीज व्रत भाद्रपद शुक्ल तृतीया को किया जाता है। यह व्रत विवाहित और अविवाहित दोनों महिलाएं करती हैं। यह व्रत माता पार्वती और भगवान शिव को समर्पित है।', 'हरतालिका तीज का व्रत माता पार्वती के अद्भुत तप का स्मरण है। माता पार्वती ने भगवान शिव को पति रूप में प्राप्त करने के लिए यह कठोर तप किया था।', 'इस व्रत को करने से मनोवांछित वर की प्राप्ति, सुखी वैवाहिक जीवन, पति की लंबी आयु और सभी मनोकामनाओं की पूर्ति होती है।', 'निर्जला व्रत रखें। पूरे दिन जल भी न पिएं। रात में जागरण करें। भगवान शिव और माता पार्वती की पूजा करें।', '[\r\n    {\"chapter\":1,\"title\":\"हरतालिका तीज की उत्पत्ति\",\"story\":\"माता पार्वती ने भगवान शिव को पति रूप में प्राप्त करने के लिए घोर तप किया। उनकी सखियाँ उन्हें घर ले आईं, लेकिन पार्वती ने फिर से तप शुरू कर दिया। उनके तप से प्रसन्न होकर भगवान शिव ने उन्हें पत्नी रूप में स्वीकार किया। तब से यह व्रत हरतालिका तीज के नाम से प्रसिद्ध हुआ। हरतालिका का अर्थ है - हर (शिव) और तालिका (तप) - शिव के लिए किया गया तप।\"},\r\n    {\"chapter\":2,\"title\":\"सखियों का सहयोग\",\"story\":\"माता पार्वती की सखियों ने उनके तप में सहयोग किया। उन्होंने ही पार्वती को भगवान शिव की महिमा बताई और तप करने की प्रेरणा दी। इसलिए इस दिन सखियों का भी पूजन किया जाता है।\"},\r\n    {\"chapter\":3,\"title\":\"व्रत का फल\",\"story\":\"जो महिलाएं श्रद्धा और नियम से हरतालिका तीज का व्रत करती हैं, उन्हें माता पार्वती की तरह सुखी वैवाहिक जीवन प्राप्त होता है। अविवाहित कन्याओं को मनोवांछित वर की प्राप्ति होती है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। हरतालिका तीज व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"भगवान शिव और पार्वती की पूजा\",\"description\":\"भगवान शिव और माता पार्वती की मूर्ति स्थापित करें। पार्वती जी को सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":3,\"name\":\"शिवलिंग अभिषेक\",\"description\":\"शिवलिंग का जल, दूध, दही, घी, शहद से अभिषेक करें।\"},\r\n    {\"step\":4,\"name\":\"कथा वाचन\",\"description\":\"हरतालिका तीज व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":5,\"name\":\"जागरण\",\"description\":\"रात्रि में जागरण करें। भगवान शिव और पार्वती की भजन-कीर्तन करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें। अगले दिन पारण करें।\"}\r\n]', 'भगवान शिव और पार्वती की मूर्ति, सोलह श्रृंगार की वस्तुएं, बेलपत्र, धतूरा, पंचामृत, फल, मिठाई, दीपक, धूप, कपूर', 'ॐ गौर्यै नमः। ॐ शिवाय नमः। हे माता पार्वती, हे भगवान शिव, मैं हरतालिका तीज व्रत का संकल्प लेती हूँ।', 'ॐ गौर्यै नमः। ॐ शिवाय नमः। हे माता पार्वती, हे भगवान शिव, आपकी कृपा से हरतालिका तीज व्रत सफलतापूर्वक संपन्न हुआ।', 'Om Jai Shiv Omkara', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'हरतालिका तीज का व्रत माता पार्वती के अद्भुत तप का स्मरण है। माता पार्वती ने भगवान शिव को पति रूप में प्राप्त करने के लिए यह कठोर तप किया था।', '1 Day', 'हरतालिका तीज व्रत भाद्रपद शुक्ल तृतीया को किया जाता है। यह व्रत विवाहित और अविवाहित दोनों महिलाएं करती हैं। यह व्रत माता पार्वती और भगवान शिव को समर्पित है।', 'Hartalika Teej Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Shiva-Parvati', 'हरतालिका तीज व्रत भाद्रपद शुक्ल तृतीया को किया जाता है। यह व्रत विवाहित और अविवाहित दोनों महिलाएं करती हैं। यह व्रत माता पार्वती और भगवान शिव को समर्पित है।', NULL, NULL, NULL, 1),
(5, 'Karva Chauth Vrat Katha', 'Gauri', '1 Day', 'Thursday', 'Kartik (Oct-Nov)', 'Krishna Chaturthi', 'करवा चौथ व्रत कार्तिक मास की कृष्ण चतुर्थी को किया जाता है। यह व्रत सुहागिन महिलाएं अपने पति की लंबी आयु, सुख-समृद्धि और सुरक्षा के लिए करती हैं।', 'करवा चौथ का व्रत सुहागिन महिलाओं के लिए अत्यंत महत्वपूर्ण है। यह व्रत निर्जला किया जाता है। चंद्रोदय के समय आरती कर व्रत खोला जाता है।', 'इस व्रत को करने से पति की लंबी आयु, सुखी वैवाहिक जीवन, संतान सुख और परिवार में सुख-शांति की प्राप्ति होती है।', 'निर्जला व्रत रखें। पूरे दिन जल भी न पिएं। चंद्रोदय के बाद ही भोजन करें। सात्विक भोजन करें।', '[\r\n    {\"chapter\":1,\"title\":\"करवा चौथ की उत्पत्ति\",\"story\":\"प्राचीन काल में वीरावती नाम की एक सुहागन थी। उसके सात भाई थे। एक बार करवा चौथ के दिन वीरावती ने व्रत रखा। वह बहुत भूखी-प्यासी हो गई। उसके भाइयों ने उससे झूठा चंद्रमा दिखाकर उसे व्रत तोड़ने को कहा। वीरावती ने व्रत तोड़ दिया। तुरंत उसके पति की मृत्यु हो गई। वीरावती रोने लगी। तब एक देवी ने आकर कहा - तुमने झूठा चंद्रमा देखकर व्रत तोड़ा है। अब फिर से व्रत करो। वीरावती ने श्रद्धा से व्रत किया। उसके पति को पुनः जीवन मिला। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"रानी की कथा\",\"story\":\"एक राजा की रानी ने करवा चौथ का व्रत किया। व्रत के प्रभाव से राजा को युद्ध में विजय मिली। राजा की आयु लंबी हुई।\"},\r\n    {\"chapter\":3,\"title\":\"चंद्रोदय पूजा\",\"story\":\"सायंकाल चंद्रोदय के समय महिलाएं छलनी से चंद्रमा देखती हैं, फिर अपने पति को देखती हैं और आरती करती हैं। इससे पति की लंबी आयु की प्राप्ति होती है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। करवा चौथ व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"सरगी (सेवा)\",\"description\":\"सूर्योदय से पूर्व सरगी (फलाहार) ग्रहण करें।\"},\r\n    {\"step\":3,\"name\":\"दिन में पूजा की तैयारी\",\"description\":\"दिन में करवा (मिट्टी का बर्तन) भरकर पूजा की तैयारी करें।\"},\r\n    {\"step\":4,\"name\":\"सायंकाल पूजा\",\"description\":\"सायंकाल माता गौरी और भगवान शिव की पूजा करें। करवा चौथ की कथा सुनें।\"},\r\n    {\"step\":5,\"name\":\"चंद्रोदय पूजा\",\"description\":\"चंद्रोदय पर छलनी से चंद्रमा देखें, फिर पति को देखें।\"},\r\n    {\"step\":6,\"name\":\"आरती\",\"description\":\"माता गौरी की आरती करें।\"},\r\n    {\"step\":7,\"name\":\"पारण\",\"description\":\"पति के हाथ से जल ग्रहण कर व्रत खोलें।\"}\r\n]', 'करवा (मिट्टी का बर्तन), छलनी, सोलह श्रृंगार की वस्तुएं, माता गौरी की मूर्ति, फल, मिठाई, दीपक, धूप, कपूर, चंदन, कुमकुम, अक्षत', 'ॐ गौर्यै नमः। हे माता गौरी, मैं करवा चौथ व्रत का संकल्प लेती हूँ। मेरे पति की लंबी आयु के लिए यह व्रत कर रही हूँ।', 'ॐ गौर्यै नमः। हे माता गौरी, आपकी कृपा से करवा चौथ व्रत सफलतापूर्वक संपन्न हुआ। मेरे पति की आयु लंबी हो।', 'Jai Gauri Maiya', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'करवा चौथ का व्रत सुहागिन महिलाओं के लिए अत्यंत महत्वपूर्ण है। यह व्रत निर्जला किया जाता है। चंद्रोदय के समय आरती कर व्रत खोला जाता है।', '1 Day', 'करवा चौथ व्रत कार्तिक मास की कृष्ण चतुर्थी को किया जाता है। यह व्रत सुहागिन महिलाएं अपने पति की लंबी आयु, सुख-समृद्धि और सुरक्षा के लिए करती हैं।', 'Karva Chauth Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Gauri', 'करवा चौथ व्रत कार्तिक मास की कृष्ण चतुर्थी को किया जाता है। यह व्रत सुहागिन महिलाएं अपने पति की लंबी आयु, सुख-समृद्धि और सुरक्षा के लिए करती हैं।', NULL, NULL, NULL, 1),
(6, 'Ekadashi Vrat Katha', 'Vishnu', '1 Day', 'Not Specified', 'Throughout Year', 'Ekadashi', 'एकादशी व्रत हर महीने के शुक्ल और कृष्ण पक्ष की एकादशी तिथि को किया जाता है। यह व्रत भगवान विष्णु को समर्पित है।', 'एकादशी व्रत का विशेष महत्व है। यह व्रत भगवान विष्णु को अत्यंत प्रिय है। इस दिन भगवान विष्णु की पूजा करने से सभी पापों का नाश होता है।', 'इस व्रत को करने से पापों का नाश, आयु में वृद्धि, सुख-समृद्धि, संतान सुख और मोक्ष की प्राप्ति होती है।', 'निराहार या फलाहार व्रत रखें। अन्न का त्याग करें। सात्विक भोजन करें। भगवान विष्णु का ध्यान करें।', '[\r\n    {\"chapter\":1,\"title\":\"एकादशी की उत्पत्ति\",\"story\":\"प्राचीन काल में एक राक्षस मुर नामक दैत्य था। उसने देवताओं को पराजित कर स्वर्ग पर अधिकार कर लिया। देवता भगवान विष्णु के पास गए। भगवान विष्णु ने मुर से युद्ध किया। युद्ध के दौरान भगवान विष्णु थक गए और एक गुफा में विश्राम करने लगे। तब मुर ने उन पर आक्रमण कर दिया। तब भगवान विष्णु के शरीर से एक दिव्य कन्या प्रकट हुई। उसने मुर का वध कर दिया। भगवान विष्णु ने प्रसन्न होकर उस कन्या को एकादशी नाम दिया और वरदान दिया कि जो कोई एकादशी का व्रत करेगा, उसके सभी पाप नष्ट होंगे। तब से एकादशी व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"पांडवों की कथा\",\"story\":\"महाभारत के युद्ध के बाद पांडवों को राज्य मिला। युधिष्ठिर ने भगवान कृष्ण से पूछा कि सबसे श्रेष्ठ व्रत कौन सा है? भगवान कृष्ण ने एकादशी व्रत की महिमा बताई। युधिष्ठिर ने एकादशी व्रत किया और सभी पापों से मुक्त हुए।\"},\r\n    {\"chapter\":3,\"title\":\"फल श्रुति\",\"story\":\"जो व्यक्ति एकादशी का व्रत श्रद्धा और नियम से करता है, उसे हजार अश्वमेघ यज्ञ के बराबर फल मिलता है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। एकादशी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"भगवान विष्णु की पूजा\",\"description\":\"भगवान विष्णु की मूर्ति या चित्र स्थापित करें। तुलसी दल अर्पित करें।\"},\r\n    {\"step\":3,\"name\":\"कथा वाचन\",\"description\":\"एकादशी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":4,\"name\":\"भजन-कीर्तन\",\"description\":\"दिन भर भगवान विष्णु के भजन-कीर्तन करें।\"},\r\n    {\"step\":5,\"name\":\"जागरण\",\"description\":\"रात्रि में जागरण करें।\"},\r\n    {\"step\":6,\"name\":\"पारण\",\"description\":\"द्वादशी के दिन प्रातः पारण करें।\"}\r\n]', 'तुलसी दल, फल, मिठाई, पंचामृत, दीपक, धूप, कपूर, भगवान विष्णु की मूर्ति', 'ॐ नमो भगवते वासुदेवाय। हे भगवान विष्णु, मैं एकादशी व्रत का संकल्प लेता/लेती हूँ।', 'ॐ नमो भगवते वासुदेवाय। हे भगवान विष्णु, आपकी कृपा से एकादशी व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Vishnu Bhagwan', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'एकादशी व्रत का विशेष महत्व है। यह व्रत भगवान विष्णु को अत्यंत प्रिय है। इस दिन भगवान विष्णु की पूजा करने से सभी पापों का नाश होता है।', '1 Day', 'एकादशी व्रत हर महीने के शुक्ल और कृष्ण पक्ष की एकादशी तिथि को किया जाता है। यह व्रत भगवान विष्णु को समर्पित है।', 'Ekadashi Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Vishnu', 'एकादशी व्रत हर महीने के शुक्ल और कृष्ण पक्ष की एकादशी तिथि को किया जाता है। यह व्रत भगवान विष्णु को समर्पित है।', NULL, NULL, NULL, 1),
(7, 'अहोई अष्टमी व्रत कथा (संतान रक्षा एवं दीर्घायु)', 'Ahoi Mata', '1 Day', 'Thursday', 'Kartik (Oct-Nov)', 'Krishna Ashtami', 'अहोई अष्टमी व्रत कार्तिक मास की कृष्ण अष्टमी को किया जाता है। यह व्रत संतान की सुरक्षा और सुख-समृद्धि के लिए माताएं करती हैं।', 'अहोई अष्टमी का व्रत संतान की लंबी आयु और सुरक्षा के लिए किया जाता है। यह व्रत दीपावली से 8 दिन पूर्व आता है।', 'इस व्रत को करने से संतान की लंबी आयु, सुख-समृद्धि, सुरक्षा और सभी मनोकामनाओं की पूर्ति होती है।', 'निर्जला व्रत रखें। सूर्यास्त के बाद तारे दिखने पर व्रत खोलें। सात्विक भोजन करें।', '[\r\n    {\"chapter\":1,\"title\":\"अहोई अष्टमी की उत्पत्ति\",\"story\":\"प्राचीन काल में एक गरीब महिला के सात पुत्र थे। एक दिन वह जंगल में मिट्टी खोद रही थी। उसने अनजाने में एक सियार के बच्चे को मार डाला। उसके सभी पुत्र मर गए। वह बहुत दुखी हुई। तब एक देवी ने उसे अहोई अष्टमी का व्रत करने को कहा। उसने श्रद्धा से व्रत किया। व्रत के प्रभाव से उसके सभी पुत्र पुनः जीवित हो गए। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"रानी की कथा\",\"story\":\"एक राजा की रानी के पुत्र मर गए थे। उसने अहोई अष्टमी का व्रत किया। व्रत के प्रभाव से उसके पुत्र पुनः जीवित हो गए।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। अहोई अष्टमी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"अहोई माता की पूजा\",\"description\":\"अहोई माता की मूर्ति या चित्र स्थापित करें। सियार का चित्र भी बनाएं।\"},\r\n    {\"step\":3,\"name\":\"कथा वाचन\",\"description\":\"अहोई अष्टमी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":4,\"name\":\"तारा दर्शन\",\"description\":\"सायंकाल तारे दिखने पर पूजा करें।\"},\r\n    {\"step\":5,\"name\":\"आरती\",\"description\":\"अहोई माता की आरती करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"}\r\n]', 'अहोई माता की मूर्ति, सियार का चित्र, फल, मिठाई, दीपक, धूप, कपूर, चंदन, कुमकुम, अक्षत, सूत के धागे', 'ॐ अहोई मातायै नमः। हे माता अहोई, मैं अपनी संतान की सुरक्षा के लिए यह व्रत कर रही हूँ।', 'ॐ अहोई मातायै नमः। हे माता अहोई, आपकी कृपा से यह व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Ahoi Mata', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'अहोई अष्टमी का व्रत संतान की लंबी आयु और सुरक्षा के लिए किया जाता है। यह व्रत दीपावली से 8 दिन पूर्व आता है।', '1 Day', 'अहोई अष्टमी व्रत कार्तिक मास की कृष्ण अष्टमी को किया जाता है। यह व्रत संतान की सुरक्षा और सुख-समृद्धि के लिए माताएं करती हैं।', 'अहोई अष्टमी व्रत कथा (संतान रक्षा एवं दीर्घायु)', NULL, 'अहोईअष्टमीव्रतकथा', 'vrat_katha', 'व्रत कथा', 'Ahoi Mata', 'प्राचीन काल में एक नगर में एक धर्मात्मा साहूकार रहता था। उसके सात पुत्र और सात बहुएं थीं। दीपावली से पूर्व कार्तिक मास की कृष्ण पक्ष की अष्टमी तिथि को घर की लिपाई-पुताई के लिए साहूकार की सातों बहुएं जंगल में खदान से पीली मिट्टी खोदने गईं। साहूकार की छोटी बहू जब खुरपी से मिट्टी खोद रही थी, तो उसकी खुरपी खदान के भीतर बने एक सेह (स्याही/साही) की मांद में जा लगी, जिससे सेह का एक नन्हा बच्चा कटकर मर गया।\n\nछोटी बहू को इस अनजाने में हुए पाप से अत्यधिक पश्चाताप हुआ। सेह की माता ने क्रोधित होकर शाप दिया—\'जिस प्रकार तुमने मेरे बच्चे को मारा है, उसी प्रकार मैं तुम्हारी कोख को बांधूंगी और तुम्हारी सन्तान जीवित नहीं रहेगी।\' शाप के प्रभाव से छोटी बहू के जन्म लेते ही एक के बाद एक सातों पुत्र अल्पायु में ही काल के गाल में समा गए। साहूकार की बहू विलाप करने लगी।\n\nएक दिन उसने एक वृद्ध तपस्वी मुनि से अपने कष्ट का कारण और निवारण पूछा। मुनि ने बताया—\'बेटी! अनजाने में तुमसे सेह के बच्चे की हत्या हुई थी, उसी के शाप से तुम्हारी सन्तान नहीं बचती। तुम कार्तिक कृष्ण अष्टमी को अहोई माता (भगवती पार्वती का स्वरूप) का निर्जला व्रत रखो, सेह और उसके बच्चों का चित्र दीवार पर बनाकर उनका पूजन करो और गौमाता की सेवा कर क्षमा याचना करो।\'\n\nसाहूकार की बहू ने पूर्ण श्रद्धा और निष्ठा के साथ कार्तिक कृष्ण अष्टमी को अहोई अष्टमी का व्रत रखा। सायंकाल आकाश में तारे दिखने पर उसने अर्घ्य दिया, अहोई माता की कथा सुनी और सेह माता से हाथ जोड़कर क्षमा मांगी। उसकी सच्ची भक्ति और प्रायश्चित से अहोई माता प्रसन्न हुईं और उसके सभी मृत पुत्रों को पुनर्जीवन प्रदान किया। तब से यह व्रत सन्तान की दीर्घायु और रक्षा के लिए विख्यात हुआ।', NULL, 'अहोई अष्टमी का व्रत माताओं द्वारा अपनी संतान की दीर्घायु, स्वास्थ्य और उज्ज्वल भविष्य के लिए किया जाता है। सच्ची प्रार्थना से हर अनिष्ट टल जाता है।', NULL, 1),
(8, 'वट सावित्री व्रत कथा (सती सावित्री एवं सत्यवान)', 'Savitri-Satyavan', '1 Day', 'Not Specified', 'Jyeshtha (May-Jun)', 'Amavasya/Purnima', 'वट सावित्री व्रत ज्येष्ठ मास की अमावस्या या पूर्णिमा को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं।', 'वट सावित्री व्रत का विशेष महत्व है। यह व्रत सावित्री के अद्भुत पतिव्रत धर्म का स्मरण है। सावित्री ने यमराज से अपने पति सत्यवान का प्राण वापस लिया था।', 'इस व्रत को करने से पति की लंबी आयु, सुखी वैवाहिक जीवन, संतान सुख और सभी मनोकामनाओं की पूर्ति होती है।', 'व्रत के दिन वट वृक्ष की पूजा करें। निर्जला व्रत रखें। सात्विक भोजन करें।', '[\r\n    {\"chapter\":1,\"title\":\"वट सावित्री व्रत की उत्पत्ति\",\"story\":\"सावित्री राजा अश्वपति की पुत्री थीं। उन्होंने सत्यवान को पति रूप में वरण किया। सत्यवान को एक वर्ष में मृत्यु का श्राप था। सत्यवान के मृत्यु के समय यमराज आए। सावित्री ने यमराज का पीछा किया। यमराज ने कहा - सावित्री, तुम वापस लौट जाओ। सावित्री ने कहा - जहाँ मेरे पति हैं, वहीं मैं हूँ। सावित्री की पतिव्रता से प्रसन्न होकर यमराज ने सत्यवान को पुनः जीवन दान दिया। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"वट वृक्ष का महत्व\",\"story\":\"वट वृक्ष अजर-अमर माना जाता है। इस दिन वट वृक्ष की पूजा करने से पति की आयु लंबी होती है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। वट सावित्री व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"वट वृक्ष पूजा\",\"description\":\"वट वृक्ष के नीचे जाकर पूजा करें। वट वृक्ष की परिक्रमा करें।\"},\r\n    {\"step\":3,\"name\":\"सावित्री-सत्यवान की पूजा\",\"description\":\"सावित्री-सत्यवान की मूर्ति स्थापित करें। सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":4,\"name\":\"कथा वाचन\",\"description\":\"वट सावित्री व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":5,\"name\":\"आरती\",\"description\":\"सावित्री माता की आरती करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"}\r\n]', 'सावित्री-सत्यवान की मूर्ति, सोलह श्रृंगार की वस्तुएं, फल, मिठाई, दीपक, धूप, कपूर, चंदन, कुमकुम, अक्षत, सूत के धागे', 'ॐ सावित्र्यै नमः। हे माता सावित्री, मैं अपने पति की लंबी आयु के लिए यह व्रत कर रही हूँ।', 'ॐ सावित्र्यै नमः। हे माता सावित्री, आपकी कृपा से यह व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Savitri Mata', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'वट सावित्री व्रत का विशेष महत्व है। यह व्रत सावित्री के अद्भुत पतिव्रत धर्म का स्मरण है। सावित्री ने यमराज से अपने पति सत्यवान का प्राण वापस लिया था।', '1 Day', 'वट सावित्री व्रत ज्येष्ठ मास की अमावस्या या पूर्णिमा को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं।', 'वट सावित्री व्रत कथा (सती सावित्री एवं सत्यवान)', NULL, 'वटसावित्रीव्रतमहात्म्यम्', 'vrat_katha', 'व्रत कथा', 'Savitri-Satyavan', 'भद्र देश के धर्मात्मा राजा अश्वपति की कोई संतान नहीं थी। राजा ने अठारह वर्षों तक माता सावित्री की कठोर तपस्या की, जिससे प्रसन्न होकर देवी ने उन्हें एक सर्वगुण सम्पन्न कन्या का वरदान दिया। देवी के अनुग्रह से जन्मी इस कन्या का नाम \'सावित्री\' रखा गया। जब सावित्री विवाह योग्य हुईं, तो राजा ने उन्हें स्वयं सुयोग्य वर खोजने का आदेश दिया। सावित्री ने तपोवन में जाकर शाल्व देश के द्युमत्सेन के पुत्र सत्यवान को अपने पति रूप में वरण किया। राजा द्युमत्सेन अंधे हो चुके थे और उनका राज्य शत्रुओं ने छीन लिया था, जिससे वे वन में सादा जीवन व्यतीत कर रहे थे।\n\nजब देवर्षि नारद ने सावित्री के इस वरण के बारे में सुना, तो वे राजा अश्वपति के पास पहुंचे और बोले—\'राजन्! सत्यवान शूरवीर, सत्यवादी और रूपवान हैं, किन्तु इनके भाग्य में एक भारी दोष है। आज से ठीक एक वर्ष पश्चात् इनकी मृत्यु निश्चित है।\' राजा अश्वपति चिंतित हो गए और उन्होंने सावित्री को किसी अन्य वर को चुनने को कहा। किन्तु सावित्री ने दृढ़ता से कहा—\'पिताजी! आर्य कन्या अपने जीवन में एक ही बार पति का वरण करती है। मैंने सत्यवान को चुन लिया है, चाहे वे अल्पायु हों या दीर्घायु, मेरे पति केवल वही होंगे।\'\n\nसावित्री का विवाह सत्यवान से हुआ। सावित्री ने राजसी वैभव त्याग कर वन में सास-ससुर और पति की अनन्य सेवा प्रारंभ की। नारद जी द्वारा बताई गई मृत्यु की तिथि जब निकट आई, तो सावित्री ने तीन दिन पूर्व से ही \'त्रिरात्र व्रत\' (कठोर निर्जला उपवास) प्रारंभ कर दिया। नियत दिन सत्यवान कुल्हाड़ी लेकर लकड़ी काटने वन में जाने लगे। सावित्री ने भी सास-ससुर की अनुमति लेकर उनके साथ जाने की प्रार्थना की। वन में वट वृक्ष के नीचे लकड़ी काटते समय सत्यवान के सिर में तीव्र पीड़ा होने लगी। वे सावित्री की गोद में सिर रखकर सो गए।\n\nउसी समय दक्षिण दिशा से साक्षात् मृत्यु के देवता यमराज भैंसे पर सवार होकर आए। उनके हाथ में कालपाश था। यमराज ने सत्यवान के शरीर से अंगूठे के बराबर जीवात्मा को पाश में बांध लिया और दक्षिण दिशा की ओर चल पड़े। सावित्री भी पति के जीवात्मा के पीछे-पीछे चलने लगीं। यमराज ने कहा—\'हे पतिव्रते! तुम वापस लौट जाओ और सत्यवान का श्राद्ध-तर्पण करो। जीवित प्राणी मेरे पीछे नहीं आ सकते।\' सावित्री ने उत्तर दिया—\'प्रभो! जहां मेरे पति जा रहे हैं, पत्नी होने के नाते मेरा कर्तव्य है कि मैं भी वहीं जाऊं। पातिव्रत्य धर्म के प्रभाव से मुझे कोई मार्ग दुर्गम नहीं लगता।\'\n\nसावित्री के धर्मयुक्त वचनों से प्रसन्न होकर यमराज ने कहा—\'हे कल्याणी! सत्यवान के जीवन को छोड़कर तुम कोई भी तीन वर मांग लो।\' सावित्री ने प्रथम वर में अपने अंधे सास-ससुर के नेत्रों की ज्योति मांगी। द्वितीय वर में उनका छिना हुआ राज्य वापस मांगा। तृतीय वर में अपने पिता के लिए सौ पुत्रों का वरदान मांगा। यमराज ने तथास्तु कहकर आगे बढ़ना चाहा, किन्तु सावित्री फिर भी पीछे चलती रहीं। उन्होंने धर्म, दया और सत्संग की महिमा पर ऐसे गूढ़ विचार व्यक्त किए कि यमराज अत्यंत विस्मित और मुदित हो गए। उन्होंने कहा—\'सावित्री! मैं तुम्हारी पवित्रता से अभिभूत हूं। एक और अंतिम वर मांगो, पर सत्यवान का प्राण मत मांगना।\'\n\nसावित्री ने हाथ जोड़कर कहा—\'हे धर्मराज! यदि आप मुझ पर वास्तव में प्रसन्न हैं, तो मुझे सत्यवान के वीर्य से सौ पराक्रमी और धर्मिष्ठ पुत्रों की माता बनने का वरदान दीजिए।\' यमराज ने बिना सोचे \'तथास्तु\' कह दिया। सावित्री मुस्कुराईं और बोलीं—\'हे प्रभु! आप सत्यवादी हैं। एक पतिव्रता नारी अपने पति के बिना पुत्र कैसे उत्पन्न कर सकती है? अतः आपको सत्यवान को जीवनदान देना ही होगा।\'\n\nयमराज अपनी प्रतिज्ञा में बंध गए। वे सावित्री के अदम्य पातिव्रत्य, तेज और वाकपटुता के आगे नतमस्तक हो गए। उन्होंने सत्यवान के सूक्ष्म शरीर को पाश से मुक्त करते हुए कहा—\'हे सती शिरोमणि! तुम्हारी जैसी पतिव्रता नारी तीनों लोकों में दुर्लभ है। मैंने तुम्हारे पति को चार सौ वर्षों की नवीन दीर्घायु प्रदान की। तुम्हारा यह वट सावित्री व्रत कल्प-कल्पान्तर तक स्त्रियों को अखण्ड सौभाग्य प्रदान करेगा।\'\n\nसावित्री उसी वट वृक्ष के नीचे लौटीं, जहां सत्यवान का शव पड़ा था। सत्यवान ऐसे उठ बैठे जैसे गहरी नींद से जागे हों। उधर उनके सास-ससुर की आंखों की ज्योति लौट आई और उनका राज्य भी वापस मिल गया।', NULL, 'वट सावित्री व्रत सती सावित्री के अदम्य पातिव्रत्य, बुद्धि और निष्ठा का पावन प्रतीक है। इस व्रत से सौभाग्य, पति की दीर्घायु और समस्त पारिवारिक सुखों की प्राप्ति होती है।', NULL, 1),
('katha_brihaspativar', 'गुरुवार (बृहस्पतिवार) व्रत कथा', 'देवगुरु बृहस्पति एवं श्री हरि विष्णु', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'વિદ્યા અને સદ્બુદ્ધિ જ સાચી સંપત્તિ છે. ગુરુવારના વ્રતથી જ્ઞાન, સંપત્તિ અને સુખી દાંપત્યજીવન પ્રાપ્ત થાય છે.', 'विद्या आणि विवेक हीच खरी संपत्ती आहे. गुरुवारच्या व्रताने विवेक जागृत होऊन ऐश्वर्य आणि शांती प्राप्त होते.', NULL, NULL, NULL, NULL, 'गुरुवार के व्रत से ज्ञान, विद्या, धन, सुखी वैवाहिक जीवन और देवगुरु बृहस्पति की कृपा से अटके हुए कार्य शीघ्र सिद्ध होते हैं।', '15-20 मिनट', 'अहंकारी रानी की दरिद्रता, देवगुरु बृहस्पति के व्रत-नियमों से पुनः ऐश्वर्य प्राप्ति और चने की दाल व गुड़ से पूजन का विधान।', 'गुरुवार (बृहस्पतिवार) व्रत कथा', 'बृहस्पतिवारव्रतकथा गुरुप्रीतिकरी', 'बृहस्पतिवारव्रतकथा गुरुप्रीतिकरी', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'देवगुरु बृहस्पति एवं श्री हरि विष्णु', 'एक प्रतापी राजा के राज्य में अपार सम्पदा थी, किन्तु उसकी रानी अत्यंत कृपण थी। जब भी कोई याचक महल के द्वार पर आता, वह उसे दुत्कार कर भगा देती। एक दिन देवगुरु बृहस्पति संन्यासी के वेश में पधारे और भिक्षा मांगी। रानी ने कहा—महाराज! मैं दान-पुण्य से तंग आ चुकी हूं, कोई ऐसा उपाय बताएं जिससे यह सारा धन समाप्त हो जाए और मुझे किसी को कुछ न देना पड़े। साधु ने कहा—यदि तुम्हारी यही इच्छा है, तो बृहस्पतिवार के दिन घर लीपकर पीली मिट्टी से पुतवाना, बाल धोना और पुरुषों से हजामत बनवाना।\n\nरानी ने वैसा ही किया। कुछ ही सप्ताह में राजा का सारा राजपाट और धन नष्ट हो गया। वे दाने-दाने को मोहताज हो गए। रानी पश्चाताप में रोने लगी। तब देवगुरु ने पुनः दर्शन देकर गुरुवार व्रत, चने की दाल, गुड़, हल्दी और केले के वृक्ष की पूजा का विधान बताया। रानी ने भक्तिपूर्वक व्रत किया और उसका वैभव पूर्ववत लौट आया।', NULL, 'विद्या और सद्बुद्धि ही सच्चा धन है। गुरुवार के व्रत से बुद्धि निर्मल होती है और अहंकार का नाश होकर जीवन में श्री-सम्पत्ति का वास होता है।', 'Wisdom and benevolence are true riches. Devotion on Thursdays cleanses ego, revives lost fortune, and bestows intellect and grace.', 1),
('katha_gajendra_moksha', 'गजेन्द्र मोक्ष पावन उद्धार कथा', 'भगवान श्री हरि विष्णु', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'જ્યારે માનવ અહંકાર છોડીને પ્રભુના શરણે જાય છે, ત્યારે ભગવાન પલભરમાં સહાય માટે દોડી આવે છે.', 'जेव्हा मनुष्य सर्व अहंकार सोडून ईश्वराला शरण जातो, तेव्हा परमात्मा एका क्षणात संकटमुक्त करतो.', NULL, NULL, NULL, NULL, 'गजेन्द्र मोक्ष का पाठ करने से असाध्य रोगों, मृत्यु भय, ऋण और जीवन के घोर संकटों से तत्काल मुक्ति मिलती है।', '15-18 मिनट', 'ऋतुमान पर्वत पर हाथियों के राजा गजेन्द्र का सरोवर में प्रवेश, ग्राह (मगरमच्छ) द्वारा पैर पकड़ना, हजार वर्षों का संघर्ष और एक कमल पुष्प अर्पित कर प्रभु की शरणागति।', 'गजेन्द्र मोक्ष पावन उद्धार कथा', 'गजेन्द्रमोक्षश्रीमद्भागवतमहात्म्य', 'गजेन्द्रमोक्षश्रीमद्भागवतमहात्म्य', 'pauranik_katha', 'पौराणिक लीला कथा', 'भगवान श्री हरि विष्णु', 'श्रीमद्भागवत महापुराण के अष्टम स्कन्ध में गजेन्द्र मोक्ष की परम पावन कथा है। त्रिकूट पर्वत पर गजेन्द्र नामक एक बलशाली गजराज रहता था। एक दिन वह अपनी हथिनियों और शावकों सहित एक रमणीक सरोवर में जलक्रीड़ा करने उतरा। उसी सरोवर में एक शक्तिशाली ग्राह (मगरमच्छ) रहता था। ग्राह ने गजेन्द्र के पैर को अपने जबड़ों में जकड़ लिया। गजेन्द्र ने छूटने का अथक प्रयास किया। उसके परिवार और साथी हाथियों ने भी खींचने की चेष्टा की, किन्तु जब ग्राह का बल बढ़ने लगा तो सभी साथी उसे असहाय छोड़कर चले गए।\n\nजल में ग्राह का बल हजार गुना था। यह द्वन्द्व युद्ध एक सहस्र (हजार) वर्षों तक चला। जब गजेन्द्र का शरीर अशक्त हो गया और अहंकार टूट गया, तब उसे पूर्वजन्म के संस्कारों से भगवान विष्णु का स्मरण हुआ। उसने सरोवर से अपनी सूंड में एक नीलकमल उठाया और आकाश की ओर उठाकर आर्तनाद किया: \"हे नाथ! हे नारायण! शरणागत की रक्षा करो।\" भक्त की करुण पुकार सुनते ही भगवान विष्णु गरुड़ पर सवार होकर तत्काल प्रकट हुए और अपने सुदर्शन चक्र से ग्राह का मुख विदीर्ण कर गजेन्द्र को जीवनदान और मोक्ष प्रदान किया।', NULL, 'जब मनुष्य अपने बल और सांसारिक सम्बन्धों का अहंकार त्यागकर प्रभु के चरणों में पूर्ण शरणागति लेता है, तब परमात्मा क्षणभर में संकट से उबार लेते हैं।', 'When one completely surrenders pride and worldly reliances to the Supreme Divine, salvation and grace descend instantaneously.', 1),
('katha_ganga_avataran', 'गंगा अवतरण एवं भागीरथ तपस्या', 'माता गंगा, भगवान शिव एवं श्री हरि', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'દ્રઢ સંકલ્પ અને શિવજીની કૃપાથી અસંભવ કાર્ય પણ સંભવ બને છે. ગંગા અવતરણ પવિત્રતા અને પુરુષાર્થનું પ્રતીક છે.', 'दृढ निश्चय आणि ईश्वराची कृपा असेल तर अशक्यही शक्य होते. भागीरथाचे प्रयत्न हेच मानवजातीचे आदर्श आहेत.', NULL, NULL, NULL, NULL, 'गंगा अवतरण कथा के श्रवण से पितृ दोष शान्त होते हैं, अंतःकरण पवित्र होता है और पूर्वजों को सद्गति प्राप्त होती है।', '18-22 मिनट', 'राजा सगर के साठ हजार पुत्रों का कपिल मुनि के कोप से भस्म होना, राजा भागीरथ की कठोर तपस्या, शिव जी की जटाओं में गंगा का वेग समाना और पाताल लोक का उद्धार।', 'गंगा अवतरण एवं भागीरथ तपस्या', 'गङ्गावतरणभागीरथतपःकथा', 'गङ्गावतरणभागीरथतपःकथा', 'pauranik_katha', 'पौराणिक लीला कथा', 'माता गंगा, भगवान शिव एवं श्री हरि', 'सूर्यवंशी राजा सगर ने अश्वमेध यज्ञ किया। देवराज इन्द्र ने ईर्ष्यावश यज्ञ का घोड़ा चुराकर पाताल लोक में महर्षि कपिल के आश्रम में बांध दिया। घोड़े को खोजते हुए राजा सगर के साठ हजार पुत्र पाताल पहुंचे और कपिल मुनि को चोर समझकर उन पर प्रहार करने दौड़े। मुनि ने जैसे ही नेत्र खोले, उनके तपोबल की क्रोधाग्नि से साठों हजार राजकुमार भस्म हो गए। उनकी आत्माएं बिना तर्पण के भटकने लगीं।\n\nअनेक पीढ़ियों के पश्चात् राजा भागीरथ ने अपने पूर्वजों के उद्धार का दृढ़ संकल्प लिया। उन्होंने हिमालय पर जाकर ब्रह्मा जी की घोर तपस्या की। ब्रह्मा जी ने कहा—मैं गंगा को पृथ्वी पर भेजने को तैयार हूं, किन्तु उनके वेग को केवल भगवान शिव ही धारण कर सकते हैं। भागीरथ ने फिर एक पैर पर खड़े होकर महादेव की तपस्या की। भगवान शिव प्रसन्न हुए और उन्होंने गंगा के प्रचंड वेग को अपनी जटाओं में समेट लिया। इसके बाद गंगा की एक निर्मल धारा जटाओं से निकली और भागीरथ के पीछे-पीछे पाताल लोक पहुंची, जहां साठ हजार पूर्वजों की भस्म का स्पर्श कर उन्हें वैकुण्ठ लोक पहुंचा दिया।', NULL, 'असंभव को भी संभव कर दिखाने वाले संकल्प को ही \\\"भागीरथ प्रयास\\\" कहते हैं। दृढ़ निष्ठा और शिव कृपा से कोई भी लक्ष्य अप्राप्य नहीं है।', 'Unrelenting perseverance aligned with divine grace can achieve the seemingly impossible, cleansing generations of hardship.', 1),
('katha_mangalvar', 'मंगलवार व्रत कथा (श्री हनुमान कृपा)', 'महावीर हनुमान जी', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'હનુમાનજી સંકટમોચન છે. મંગળવારનું વ્રત કરવાથી જીવનના તમામ અમંગળ દૂર થાય છે અને શક્તિ તથા સાહસ મળે છે.', 'हनुमान जी सर्व संकटांचे निवारण करणारे आहेत. मंगळवारच्या व्रताने भय, रोग आणि संकटे नष्ट होतात.', NULL, NULL, NULL, NULL, 'मंगलवार का व्रत रखने से मंगल ग्रह के क्रूर दोष शांत होते हैं, भय, भूत-पिशाच और शत्रुओं का नाश होता है तथा शक्ति और साहस की वृद्धि होती है।', '12-15 मिनट', 'ब्राह्मण दम्पति केशव और अंजलि की निष्ठा, पवनपुत्र हनुमान जी की परीक्षा और मंगल दोष निवारण कर तेजस्वी पुत्र प्राप्ति की कथा।', 'मंगलवार व्रत कथा (श्री हनुमान कृपा)', 'मङ्गलवारव्रतकथा हनुमत्कृपा', 'मङ्गलवारव्रतकथा हनुमत्कृपा', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'महावीर हनुमान जी', 'प्राचीन काल में एक ब्राह्मण दम्पति रहते थे। ब्राह्मण का नाम केशव और ब्राह्मणी का नाम अंजलि था। उनके कोई सन्तान नहीं थी। ब्राह्मणी मंगलवार को नियमपूर्वक हनुमान जी का व्रत रखती थी और भोग लगाए बिना अन्न ग्रहण नहीं करती थी। एक बार किसी कारणवश ब्राह्मणी मंगलवार को भोग न बना सकी। उसने संकल्प लिया कि अगले मंगलवार को ही भोग लगाकर भोजन करेगी। छह दिन तक वह भूखी-प्यासी रही।\n\nसातवें दिन मंगलवार को वह मूर्छित हो गई। हनुमान जी उसकी अनन्य भक्ति देखकर अत्यंत प्रसन्न हुए और साक्षात् प्रकट होकर उसे एक अति सुन्दर बालक का वरदान दिया। उस बालक का नाम मंगल रखा गया। जब ब्राह्मण घर लौटा तो बालक को देखकर सन्देह करने लगा। एक दिन उसने कुएं में बालक को गिरा दिया। जब वह घर पहुंचा तो बालक को पूर्ववत आंगन में खेलते देखा। उसी रात्रि हनुमान जी ने स्वप्न में ब्राह्मण को दर्शन देकर ब्राह्मणी की सत्यनिष्ठा बताई। ब्राह्मण ने लज्जित होकर क्षमा मांगी।', NULL, 'हनुमान जी संकटमोचन हैं। मंगलवार का व्रत करने वाले साधक के जीवन से समस्त अमंगल दूर होकर सदा मंगल ही मंगल होता है।', 'Lord Hanuman is the dispeller of all adversities. Tuesday observance cleanses astrological afflictions, instills immense valour, and bestows auspiciousness.', 1),
('katha_samudra_manthan', 'समुद्र मंथन एवं अमृत प्राकट्य', 'भगवान विष्णु, कुर्म अवतार एवं महादेव', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'જીવન પણ એક સમુદ્ર મંથન સમાન છે. સાધનામાં પહેલા કષ્ટો આવે છે, જેને ધૈર્યથી સહન કરવાથી અંતે પરમાનંદનું અમૃત મળે છે.', 'जीवन देखील एका समुद्र मंथनासारखे आहे. आधी संकटरूपी विष पचवावे लागते, तेव्हाच आत्मिक शांतीचे अमृत लाभते.', NULL, NULL, NULL, NULL, 'इस पावन कथा के श्रवण से मनुष्य का चित्त मंथन होता है, दुर्गुणों रूपी विष का शमन होकर सद्गुणों रूपी अमृत की प्राप्ति होती है।', '20-25 मिनट', 'दुर्वासा ऋषि का शाप, देवताओं का तेजहीन होना, मन्दराचल पर्वत और वासुकि नाग द्वारा क्षीरसागर मंथन, हलाहल विष और चौदह रत्नों का प्राकट्य।', 'समुद्र मंथन एवं अमृत प्राकट्य', 'समुद्रमन्थनलीलाकथा', 'समुद्रमन्थनलीलाकथा', 'pauranik_katha', 'पौराणिक लीला कथा', 'भगवान विष्णु, कुर्म अवतार एवं महादेव', 'श्रीमद्भागवत एवं विष्णु पुराण के अनुसार, एक बार महर्षि दुर्वासा ने देवराज इन्द्र को एक दिव्य पुष्पमाला भेंट की। ऐश्वर्य के मद में चूर इन्द्र ने वह माला अपने ऐरावत हाथी के मस्तक पर रख दी। हाथी ने माला को पैरों तले कुचल दिया। इस अपमान से कुपित होकर दुर्वासा ऋषि ने शाप दिया कि तुम्हारा तीनों लोकों का ऐश्वर्य और श्री नष्ट हो जाए। शाप के प्रभाव से देवता निर्बल हो गए और दैत्यराज बलि ने स्वर्ग पर अधिकार कर लिया।\n\nहताश देवता भगवान विष्णु की शरण में गए। श्रीहरि ने युक्ति दी कि दैत्यों से संधि कर क्षीरसागर का मंथन करो, जिससे अमृत निकलेगा। मन्दराचल पर्वत को मथानी और नागराज वासुकि को नेती बनाया गया। जब मन्दराचल समुद्र में डूबने लगा, तब भगवान विष्णु ने कच्छप (कूर्म) अवतार धारण कर पर्वत को अपनी पीठ पर संभाला। मंथन से सर्वप्रथम कालकूट हलाहल विष निकला, जिससे तीनों लोक जलने लगे। देवताओं की करुण पुकार पर भगवान शिव ने उस विष को पीकर अपने कण्ठ में धारण कर लिया, जिससे वे नीलकण्ठ कहलाए। तत्पश्चात् कामधेनु, उच्चैःश्रवा अश्व, ऐरावत, कौस्तुभ मणि, कल्पवृक्ष, रम्भा, महालक्ष्मी, वारुणी, धन्वन्तरि और अमृत कलश प्रकट हुए। मोहिनी रूप धरकर भगवान विष्णु ने देवताओं को अमृतपान कराया।', NULL, 'जीवन भी एक क्षीरसागर है। साधना रूपी मंथन में पहले विष (कष्ट और वासनाएं) बाहर आते हैं, जिन्हें धैर्य से सहना पड़ता है, तभी अंत में शांति रूपी अमृत प्राप्त होता है।', 'Life is a cosmic ocean. Spiritual churning initially surfaces latent poisons which require poise, ultimately yielding divine nectar and inner illumination.', 1),
('katha_satyanarayan', 'श्री सत्यनारायण व्रत कथा (सम्पूर्ण ५ अध्याय)', 'भगवान श्री सत्यनारायण (विष्णु)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'સત્ય જ નારાયણ છે અને નારાયણ જ પરમ સત્ય છે. જે માનવ સત્ય આચરીને પ્રભુની પૂજા કરે છે, તે પરમ સુખ અને મુક્તિ પામે છે.', 'सत्य हेच नारायण आणि नारायण हेच परम सत्य आहेत. जो मानव सत्याचे आचरण करून ईश्वराची पूजा करतो, त्याला सर्व सुख आणि मोक्ष प्राप्त होतो.', NULL, NULL, NULL, NULL, 'पूर्णिमा, संक्रान्ति अथवा किसी भी शुभ अवसर पर श्री सत्यनारायण व्रत करने से समस्त कष्टों का नाश और परमानन्द की प्राप्ति होती है।', '35-45 मिनट', 'स्कन्द पुराण के रेवाखण्ड से उद्धृत, भगवान सत्यनारायण की सर्वमनोरथ सिद्धि, दारिद्र्य नाश एवं सत्य धर्म प्रतिष्ठापना की पावन कथा।', 'श्री सत्यनारायण व्रत कथा (सम्पूर्ण ५ अध्याय)', 'श्रीमत्सत्यनारायणव्रतकथा', 'श्रीमत्सत्यनारायणव्रतकथा', 'vrat_katha', 'महापर्व व्रत कथा', 'भगवान श्री सत्यनारायण (विष्णु)', 'एक समय नैमिषारण्य तीर्थ में शौनकादि ऋषियों ने महर्षि सूत जी से पूछा कि कलियुग में मनुष्य किस सरल उपाय से मनोवांछित फल प्राप्त कर सकता है? सूत जी बोले—एक बार देवर्षि नारद जी ने भगवान विष्णु से यही प्रश्न किया था। तब भगवान ने कहा: वत्स! कलियुग में सत्यनारायण का व्रत सर्वफलप्रदाता है।\n\nकाशीपुरी में शतानन्द नाम का एक दरिद्र ब्राह्मण भिक्षाटन से जीवन यापन करता था। भगवान ने वृद्ध ब्राह्मण का रूप धारण कर उसे सत्यनारायण व्रत की विधि बताई। ब्राह्मण ने सपरिवार व्रत किया और अपार ऐश्वर्य प्राप्त किया। उसी ब्राह्मण को देखकर एक निर्धन काष्ठ विक्रेता (लकड़हारे) ने भी व्रत का संकल्प लिया और भगवान की कृपा से धनवान बना।\n\nतृतीय अध्याय में साधु वैश्य की कथा है, जिसने सन्तान प्राप्ति के लिए व्रत का संकल्प लिया था। कन्या कलावती के जन्म के बाद भी उसने लोभवश व्रत नहीं किया, जिससे उसे राजा चन्द्रकेतु के कारागार में बन्दी होना पड़ा। पश्चाताप कर जब उसकी पत्नी लीलावती ने व्रत किया, तब वे कारागार से मुक्त हुए।\n\nचतुर्थ अध्याय में साधु वैश्य के रत्न-नौका पर भगवान की परीक्षा और दण्डवत क्षमा याचना की कथा है।\n\nपंचम अध्याय में राजा तुंगध्वज की कथा है, जिन्होंने वन में गोपों द्वारा दिए गए सत्यनारायण प्रसाद का अनादर किया, जिससे उनका राजपाट नष्ट हो गया। पश्चात् उन्होंने गोपों सहित क्षमा मांगकर प्रसाद ग्रहण किया और पुनः अपना राज्य प्राप्त किया।', NULL, 'सत्य ही नारायण हैं और नारायण ही सत्य हैं। जो मनुष्य सत्य का आचरण करते हुए भगवान का पूजन करता है, वह इस लोक में सुख भोगकर मोक्ष प्राप्त करता है।', 'Truth alone is Narayana and Narayana is the Supreme Truth. Whosoever reveres the Lord through truthful conduct and steadfast devotion attains worldly joy and ultimate spiritual liberation.', 1),
('katha_shanivar', 'शनिवार व्रत कथा (शनि देव एवं नवग्रह)', 'कर्मफलदाता शनि देव', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'શનિદેવ ન્યાયના દેવ છે. સત્ય માર્ગે ચાલનાર અને ગરીબોની સેવા કરનાર પર શનિદેવ સદાય કૃપાળુ રહે છે.', 'शनिदेव कर्माचे फळ देणारे निष्पक्ष न्यायमूर्ती आहेत. सत्याचे आचरण करणाऱ्यांवर शनिदेवाची कृपा सदैव राहते.', NULL, NULL, NULL, NULL, 'शनिवार का व्रत रखने और पीपल पर दीप जलाने से साढ़ेसाती, ढैय्या, शनि पीड़ा और आकस्मिक संकटों का शमन होता है।', '18-22 मिनट', 'नवग्रहों में ज्येष्ठता का विवाद, राजा विक्रमादित्य का न्याय, शनि देव का प्रकोप एवं अन्ततः क्षमा याचना कर सुख-शांति की पुनः प्राप्ति।', 'शनिवार व्रत कथा (शनि देव एवं नवग्रह)', 'शनिवारव्रतकथा सौरिकृपा', 'शनिवारव्रतकथा सौरिकृपा', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'कर्मफलदाता शनि देव', 'एक बार स्वर्गलोक में सूर्य, चन्द्र, मंगल, बुध, बृहस्पति, शुक्र, शनि, राहु और केतु—इन नवग्रहों में विवाद हुआ कि हममें सबसे श्रेष्ठ कौन है? निर्णय के लिए वे देवराज इन्द्र के पास गए। इन्द्र ने असमर्थता जताते हुए उन्हें पृथ्वी पर न्यायप्रिय राजा विक्रमादित्य के पास भेज दिया।\n\nराजा विक्रमादित्य ने नौ धातुओं—स्वर्ण, रजत, कांस्य, ताम्र, सीसा, रांगा, जस्ता, अभ्रक और लोहे के नौ आसन बनवाए। लोहे का आसन सबसे अंत में रखा गया। शनि देव लोहे के आसन पर बैठे और इसे अपना अपमान समझा। शनि देव ने विक्रमादित्य से कहा—राजा! तुम मुझे नहीं जानते। मेरी दृष्टि से कोई नहीं बच सकता। इसके बाद राजा पर शनि की साढ़ेसाती प्रारंभ हुई। राजा को देश निकाला मिला, हाथ-पैर कटवा दिए गए और वे एक तेली के घर कोल्हू चलाने लगे। जब विक्रमादित्य ने अपनी भूल स्वीकार कर शनिवार को दीप जलाकर शनि स्तुति की, तब शनि देव प्रसन्न हुए और उनके अंग पूर्ववत कर पुनः उज्जैन का राजा बना दिया।', NULL, 'शनि देव शत्रु नहीं, निष्पक्ष कर्मफलदाता हैं। जो सत्य के मार्ग पर चलता है और दीन-दुखियों की सेवा करता है, शनि देव उस पर असीम कृपा बरसाते हैं।', 'Lord Shani is the righteous dispenser of karma. Genuine humility, service to the needy, and Saturday prayers avert distress and bless one with stability.', 1),
('katha_shiva_vivah', 'शिव-पार्वती पावन विवाह कथा', 'महादेव शिव एवं माता पार्वती', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'માતા પાર્વતીની તપસ્યા અને મહાદેવની કૃપા દર્શાવે છે કે સાચી ભક્તિ અને નિષ્ઠાથી ઈશ્વરને પણ પામી શકાય છે.', 'माता पार्वतींचे खडतर तप आणि शंकरांचे औदार्य हेच सिद्ध करते की शुद्ध प्रेमाने ईश्वरही वश होतो.', NULL, NULL, NULL, NULL, 'शिव-पार्वती विवाह कथा का पाठ करने से दांपत्य जीवन में मधुरता आती है, सुयोग्य जीवनसाथी मिलता है और घर में मंगलकारी ऊर्जा का संचार होता है।', '25-30 मिनट', 'सती का देहत्याग, गिरिराज हिमवान के घर पार्वती के रूप में पुनर्जन्म, कठोर तपस्या, कामदेव दहन और महाशिवरात्रि के पावन परिणय की अनुपम गाथा।', 'शिव-पार्वती पावन विवाह कथा', 'शिवपार्वतीकल्याणमहोत्सव', 'शिवपार्वतीकल्याणमहोत्सव', 'pauranik_katha', 'पौराणिक लीला कथा', 'महादेव शिव एवं माता पार्वती', 'दक्ष प्रजापति के यज्ञ में अपने पति महादेव का अपमान सहन न कर पाने के कारण माता सती ने योगाग्नि में अपने प्राणों की आहुति दे दी। इसके पश्चात् उन्होंने पर्वतराज हिमवान और मैनावती के घर उमा (पार्वती) के रूप में जन्म लिया। नारद जी ने माता-पिता को बताया कि इनका विवाह केवल दिगम्बर महादेव से ही सम्भव है। पार्वती जी ने वन में जाकर हजारों वर्षों तक निराहार रहकर कठोर तपस्या की।\n\nउनकी तपस्या की परीक्षा लेने स्वयं सप्तर्षि आए, किन्तु पार्वती जी अपने संकल्प पर अडिग रहीं—\"वरउँ संभु न त रहउँ कुआरी।\" दूसरी ओर तारकासुर के अत्याचार से त्रस्त देवताओं ने शिव जी की समाधि भंग करने कामदेव को भेजा। महादेव ने तीसरा नेत्र खोलकर कामदेव को भस्म कर दिया। अन्ततः पार्वती जी की अनन्य निष्ठा से प्रसन्न होकर भगवान शिव प्रकट हुए और विवाह का प्रस्ताव स्वीकार किया। महाशिवरात्रि के शुभ दिन नंदी, भृंगी, भूत, प्रेत और समस्त देवताओं की अद्भुत बारात लेकर महादेव हिमवान के नगर पहुंचे। ब्रह्मा जी ने विवाह के वैदिक मन्त्र पढ़े और माता पार्वती तथा महादेव का पावन परिणय सम्पन्न हुआ।', NULL, 'माता पार्वती का तप और भगवान शिव का संयम यह सिखाता है कि आत्मिक प्रेम और निष्ठा से ईश्वर को भी वशीभूत किया जा सकता है।', 'Mother Parvati’s unwavering penance and Shiva’s cosmic stillness illustrate that sincere love and dedication surmount all worldly impediments.', 1),
('katha_somvar', 'सोमवार व्रत कथा (भगवान शिव कृपा)', 'देवाधिदेव महादेव शिव', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'ભોળાનાથ માત્ર શ્રદ્ધા અને સમર્પણના ભૂખ્યા છે. સોમવારનું વ્રત જીવનના સઘળા સંકટો દૂર કરી સુખ અને દીર્ઘાયુ આપે છે.', 'भोळेनाथ केवळ निष्काम भक्तीने प्रसन्न होतात. सोमवारचे व्रत सर्व संकटांचे निवारण करून दीर्घायुष्य आणि शांती प्रदान करते.', NULL, NULL, NULL, NULL, 'सोमवार का व्रत रखने से मानसिक शान्ति, रोग-शोक से मुक्ति, सुयोग्य जीवनसाथी और भगवान आशुतोष का अक्षय आशीर्वाद प्राप्त होता है।', '15-20 मिनट', 'एक निःसंतान धर्मात्मा साहूकार की शिव भक्ति, पुत्र प्राप्ति, अल्पायु संकट एवं महादेव-पार्वती जी के अनुग्रह से दीर्घायु जीवन की अमर गाथा।', 'सोमवार व्रत कथा (भगवान शिव कृपा)', 'सोमवारव्रतकथा शिवप्रीतिकरी', 'सोमवारव्रतकथा शिवप्रीतिकरी', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'देवाधिदेव महादेव शिव', 'किसी नगर में एक गुणवान साहूकार रहता था। उसके घर में धन-धान्य की कोई कमी न थी, किन्तु कोई संतान न होने से वह अत्यधिक दुःखी रहता था। वह प्रतिदिन शिव मन्दिर जाकर शिवलिंग पर जल और बेलपत्र अर्पित करता था। माता पार्वती ने साहूकार की निष्काम भक्ति देखकर महादेव से उस पर कृपा करने की प्रार्थना की। महादेव ने कहा—देवी! इसके भाग्य में पुत्र योग नहीं है, यदि दिया भी जाए तो वह मात्र बारह वर्ष की आयु तक ही जीवित रहेगा। साहूकार ने यह सब सुन लिया, फिर भी वह विचलित न हुआ।\n\nसाहूकार के घर एक सुन्दर पुत्र ने जन्म लिया। जब वह ग्यारह वर्ष का हुआ, तो साहूकार ने उसे उसके मामा के साथ काशी विद्याध्ययन के लिए भेजा और मार्ग में यज्ञ-हवन करते हुए ब्राह्मणों को भोजन कराने का निर्देश दिया। मार्ग में एक राजकुमारी के विवाह में धोखे से इस बालक का विवाह संपन्न हुआ।\n\nकाशी में जब बालक बारहवें वर्ष में प्रविष्ट हुआ, तो काल के प्रभाव से उसके प्राण पखेरू उड़ गए। उसके मामा विलाप करने लगे। उसी समय भगवान शिव और माता पार्वती वहां से निकले। माता पार्वती के करुण अनुग्रह पर औघड़दानी महादेव ने बालक को जीवनदान प्रदान किया। बालक अपनी वधू के साथ सकुशल घर लौटा।', NULL, 'भगवान भोलेनाथ भाव के भूखे हैं। सच्चे हृदय से किया गया सोमवार का व्रत अल्पायु संकट को भी टालकर जीवन में नवप्रभात ला देता है।', 'Lord Shiva is easily pleased by pure devotion. Steadfast Monday fasting dispels all distress, prolongs longevity, and grants inner peace.', 1),
('katha_vaibhav_lakshmi', 'शुक्रवार वैभव लक्ष्मी व्रत कथा', 'माता वैभव लक्ष्मी', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'જ્યાં પ્રેમ, સદ્ભાવ અને પવિત્રતા હોય છે ત્યાં લક્ષ્મીજી વાસ કરે છે. વૈભવ લક્ષ્મી વ્રતથી સર્વ કષ્ટો નાશ પામે છે.', 'जिथे स्वच्छता आणि सद्भाव असतो तिथेच लक्ष्मीचा वास असतो. वैभव लक्ष्मी व्रताने सर्व दारिद्र्य दूर होते.', NULL, NULL, NULL, NULL, 'शुक्रवार को वैभव लक्ष्मी का व्रत करने से घर में दारिद्र्य का नाश होता है, सुख-समृद्धि, व्यापार में उन्नति और गृह-क्लेश से मुक्ति मिलती है।', '15-20 मिनट', 'शीला नामक साध्वी स्त्री की अटूट भक्ति, जुए और कुसंगत में फंसे पति का उद्धार और माता लक्ष्मी के अष्ट स्वरूपों की आराधना।', 'शुक्रवार वैभव लक्ष्मी व्रत कथा', 'वैभवलक्ष्मीव्रतकथा श्रीप्रदा', 'वैभवलक्ष्मीव्रतकथा श्रीप्रदा', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'माता वैभव लक्ष्मी', 'एक बड़े शहर में शीला नाम की एक धर्मपरायण स्त्री अपने पति के साथ रहती थी। उसका पति अत्यंत परिश्रमी और सुशील था। दोनों सुखी जीवन व्यतीत कर रहे थे। कालान्तर में उसका पति कुसंगति में पड़ गया और मद्यपान तथा जुए का आदी हो गया। सारा संचित धन समाप्त हो गया और घर में भुखमरी की नौबत आ गई।\n\nएक शुक्रवार को शीला के द्वार पर एक वृद्ध तेजस्विनी मां आई। शीला ने सत्कार कर अपने आंसुओं से उनका स्वागत किया। मां ने कहा—बेटी! मैं लक्ष्मी का स्वरूप हूं। तू निराश न हो। मां ने उसे शुक्रवार वैभव लक्ष्मी व्रत की सरल विधि बताई: श्रीयंत्र का पूजन, खीर का भोग और शुक्रवार की शाम को दीप प्रज्वलन। शीला ने पूर्ण निष्ठा से व्रत किया। उसके पति की बुद्धि शुद्ध हो गई, उसने कुसंगति त्याग दी और पुनः परिश्रम कर धन अर्जित करने लगा। घर में पुनः सुख-शान्ति और वैभव छा गया।', NULL, 'माता लक्ष्मी का वास वहीं होता है जहां सद्भाव, स्वच्छता और प्रेम है। वैभव लक्ष्मी व्रत से हर प्रकार का दारिद्र्य मिट जाता है।', 'Goddess Lakshmi abides where truth, cleanliness, and harmony reign. Friday observance dispels poverty and fills homes with peace and prosperity.', 1);
INSERT INTO `vrat_kathas` (`id`, `katha_name`, `deity_name`, `vrat_duration`, `vrat_day`, `vrat_month`, `tithi`, `description`, `significance`, `benefits`, `rules`, `katha_chapters`, `vidhi`, `samagri_list`, `opening_verse`, `closing_verse`, `aarti_name`, `audio_url`, `video_url`, `is_premium`, `views_count`, `likes_count`, `created_at`, `updated_at`, `translation_gu`, `translation_mr`, `translation_bn`, `translation_te`, `translation_ta`, `translation_kn`, `vrat_significance`, `duration`, `synopsis`, `title`, `sanskrit`, `sanskrit_title`, `category`, `category_label`, `deity`, `katha_text`, `chapters`, `translation_hi`, `translation_en`, `is_featured`) VALUES
(1, 'Solah Somvar Vrat Katha', 'Shiva', '16 Mondays', 'Monday', 'Throughout Year', 'Any Monday', 'सोलह सोमवार व्रत भगवान शिव को समर्पित है। यह व्रत 16 सोमवार तक किया जाता है। यह व्रत विशेष रूप से अविवाहित लड़कियां अच्छा वर पाने के लिए और विवाहित महिलाएं सुखी वैवाहिक जीवन के लिए करती हैं।', 'सोलह सोमवार व्रत भगवान शिव की कृपा प्राप्ति के लिए अत्यंत फलदायी है। यह व्रत करने से सभी मनोकामनाएं पूर्ण होती हैं।', 'इस व्रत को करने से मनोवांछित वर की प्राप्ति, वैवाहिक जीवन में सुख-शांति, धन-समृद्धि, संतान सुख और सभी कष्टों से मुक्ति मिलती है।', 'व्रत के दिन केवल एक बार फलाहार करें। बिना नमक का भोजन करें। ब्रह्मचर्य का पालन करें। झूठ न बोलें। क्रोध न करें।', '[\r\n    {\"chapter\":1,\"title\":\"प्रथम सोमवार - राजा धर्मसेन की कथा\",\"story\":\"प्राचीन काल में धर्मसेन नामक एक राजा थे। उनके राज्य में सुख-समृद्धि थी, लेकिन उनकी कोई संतान नहीं थी। एक दिन राजा ने महर्षि वशिष्ठ से संतान प्राप्ति का उपाय पूछा। ऋषि ने कहा - हे राजन, आप सोलह सोमवार का व्रत करें। भगवान शिव की कृपा से आपको संतान सुख अवश्य प्राप्त होगा। राजा ने विधि-विधान से व्रत किया। सोलहवें सोमवार को भगवान शिव ने प्रसन्न होकर राजा को पुत्र रत्न प्रदान किया। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"द्वितीय सोमवार - गरीणी ब्राह्मणी की कथा\",\"story\":\"एक गरीब ब्राह्मणी के पास खाने को अन्न नहीं था। उसने सोलह सोमवार का व्रत किया। व्रत के प्रभाव से उसके घर में धन-धान्य की कमी नहीं रही। वह सुखी हो गई।\"},\r\n    {\"chapter\":3,\"title\":\"सोलहवाँ सोमवार - फल प्राप्ति\",\"story\":\"सोलहवें सोमवार को व्रत पूर्ण करने पर भगवान शिव और माता पार्वती प्रसन्न होते हैं और व्रत करने वाले की सभी मनोकामनाएं पूर्ण करते हैं।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। जल, फूल, अक्षत हाथ में लेकर सोलह सोमवार व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"शिवलिंग स्थापना\",\"description\":\"शिवलिंग स्थापित करें या शिव मंदिर जाएं।\"},\r\n    {\"step\":3,\"name\":\"अभिषेक\",\"description\":\"शिवलिंग का जल, दूध, दही, घी, शहद, गंगाजल से अभिषेक करें।\"},\r\n    {\"step\":4,\"name\":\"बेलपत्र अर्पण\",\"description\":\"शिवलिंग पर बेलपत्र, धतूरा, भांग अर्पित करें।\"},\r\n    {\"step\":5,\"name\":\"शिव चालीसा पाठ\",\"description\":\"शिव चालीसा या शिव स्तोत्र का पाठ करें।\"},\r\n    {\"step\":6,\"name\":\"आरती\",\"description\":\"शिव आरती ॐ जय शिव ओंकारा करें।\"},\r\n    {\"step\":7,\"name\":\"कथा वाचन\",\"description\":\"सोलह सोमवार व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":8,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें। प्रत्येक सोमवार को यह विधि करें। 16 सोमवार पूरे होने पर उद्यापन करें।\"}\r\n]', 'शिवलिंग, बेलपत्र, धतूरा, भांग, पंचामृत, जल, चंदन, रुद्राक्ष, फल, मिठाई, दीपक, धूप, कपूर', 'ॐ नमः शिवाय। हे शिवशंकर, मैं सोलह सोमवार व्रत का संकल्प लेता/लेती हूँ।', 'ॐ नमः शिवाय। हे शिवशंकर, आपकी कृपा से सोलह सोमवार व्रत सफलतापूर्वक संपन्न हुआ। मेरी सभी मनोकामनाएं पूर्ण करें।', 'Om Jai Shiv Omkara', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:49', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'सोलह सोमवार व्रत भगवान शिव की कृपा प्राप्ति के लिए अत्यंत फलदायी है। यह व्रत करने से सभी मनोकामनाएं पूर्ण होती हैं।', '16 Mondays', 'सोलह सोमवार व्रत भगवान शिव को समर्पित है। यह व्रत 16 सोमवार तक किया जाता है। यह व्रत विशेष रूप से अविवाहित लड़कियां अच्छा वर पाने के लिए और विवाहित महिलाएं सुखी वैवाहिक जीवन के लिए करती हैं।', 'Solah Somvar Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Shiva', 'सोलह सोमवार व्रत भगवान शिव को समर्पित है। यह व्रत 16 सोमवार तक किया जाता है। यह व्रत विशेष रूप से अविवाहित लड़कियां अच्छा वर पाने के लिए और विवाहित महिलाएं सुखी वैवाहिक जीवन के लिए करती हैं।', NULL, NULL, NULL, 1),
(2, 'Mangala Gauri Vrat Katha', 'Gauri', '5 Tuesdays', 'Tuesday', 'Shravan (Jul-Aug)', 'Shravan Mangalvar', 'मंगला गौरी व्रत सावन मास के मंगलवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं। अविवाहित लड़कियां अच्छा वर पाने के लिए यह व्रत करती हैं।', 'सावन के मंगलवार को मंगला गौरी व्रत का विशेष महत्व है। यह व्रत माता पार्वती को समर्पित है और सुहागन महिलाओं के लिए अत्यंत फलदायी है।', 'इस व्रत को करने से पति की लंबी आयु, सुखी वैवाहिक जीवन, सौभाग्य की रक्षा, संतान सुख और सभी मनोकामनाओं की पूर्ति होती है।', 'व्रत के दिन केवल एक बार फलाहार करें। बिना नमक का भोजन करें। सात्विक भोजन करें। ब्रह्मचर्य का पालन करें।', '[\r\n    {\"chapter\":1,\"title\":\"प्रथम मंगलवार - मंगला गौरी व्रत की उत्पत्ति\",\"story\":\"प्राचीन काल में एक सुंदरी नाम की कन्या थी। उसकी माता ने उसे सावन के मंगलवार को मंगला गौरी व्रत करने को कहा। सुंदरी ने विधि-विधान से व्रत किया। व्रत के प्रभाव से उसे मनचाहा वर मिला। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"दूसरा मंगलवार - राजा की रानी की कथा\",\"story\":\"एक राजा की रानी निरंतर मंगला गौरी व्रत करती थी। व्रत के प्रभाव से राजा का राज्य समृद्ध रहता था। एक बार राजा ने पूछा - तुम इतना कठोर व्रत क्यों करती हो? रानी ने व्रत की महिमा बताई। राजा ने भी श्रद्धा से व्रत किया। तब से राज्य में सुख-समृद्धि आ गई।\"},\r\n    {\"chapter\":3,\"title\":\"पाँचवाँ मंगलवार - फल प्राप्ति\",\"story\":\"पाँचवें मंगलवार को व्रत पूर्ण करने पर माता पार्वती प्रसन्न होती हैं और व्रत करने वाली की सभी मनोकामनाएं पूर्ण करती हैं।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। मंगला गौरी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"माता गौरी की पूजा\",\"description\":\"माता गौरी की मूर्ति या चित्र स्थापित करें। सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":3,\"name\":\"कथा वाचन\",\"description\":\"मंगला गौरी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":4,\"name\":\"नैवेद्य अर्पण\",\"description\":\"फल, मिठाई, नारियल, पान, सुपारी अर्पित करें।\"},\r\n    {\"step\":5,\"name\":\"आरती\",\"description\":\"गौरी आरती करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें। पाँच मंगलवार तक यह विधि करें।\"}\r\n]', 'सोलह श्रृंगार की वस्तुएं (सिंदूर, काजल, बिछिया, नथ, आदि), फल, मिठाई, नारियल, पान, सुपारी, सुपारी, दीपक, धूप, कपूर', 'ॐ गौर्यै नमः। हे माता गौरी, मैं मंगला गौरी व्रत का संकल्प लेती हूँ।', 'ॐ गौर्यै नमः। हे माता गौरी, आपकी कृपा से मंगला गौरी व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Jai Ambe Gauri', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:49', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'सावन के मंगलवार को मंगला गौरी व्रत का विशेष महत्व है। यह व्रत माता पार्वती को समर्पित है और सुहागन महिलाओं के लिए अत्यंत फलदायी है।', '5 Tuesdays', 'मंगला गौरी व्रत सावन मास के मंगलवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं। अविवाहित लड़कियां अच्छा वर पाने के लिए यह व्रत करती हैं।', 'Mangala Gauri Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Gauri', 'मंगला गौरी व्रत सावन मास के मंगलवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं। अविवाहित लड़कियां अच्छा वर पाने के लिए यह व्रत करती हैं।', NULL, NULL, NULL, 1),
(3, 'Varalakshmi Vrat Katha', 'Lakshmi', '1 Day', 'Friday', 'Shravan (Jul-Aug)', 'Shravan Shukla Shukravar', 'वरलक्ष्मी व्रत श्रावण मास के शुक्ल पक्ष के शुक्रवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए करती हैं।', 'वरलक्ष्मी व्रत का विशेष महत्व है। यह व्रत माता लक्ष्मी को समर्पित है। इस दिन माता लक्ष्मी की पूजा करने से घर में धन-धान्य की कमी नहीं होती।', 'इस व्रत को करने से धन-समृद्धि, सुख-शांति, संतान सुख, पति की लंबी आयु और सभी मनोकामनाओं की पूर्ति होती है।', 'व्रत के दिन केवल एक बार फलाहार या सात्विक भोजन करें। निर्जला व्रत भी किया जा सकता है।', '[\r\n    {\"chapter\":1,\"title\":\"वरलक्ष्मी व्रत की उत्पत्ति\",\"story\":\"प्राचीन काल में चारोली नाम की एक सुहागन महिला थी। वह अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए सदा चिंतित रहती थी। एक रात उसने सपने में माता लक्ष्मी को देखा। माता ने कहा - हे सुभाग्यवती, श्रावण मास के शुक्ल पक्ष के शुक्रवार को मेरा व्रत करो। इससे तुम्हारी सभी मनोकामनाएं पूर्ण होंगी। चारोली ने श्रद्धा से व्रत किया। व्रत के प्रभाव से उसके घर में सुख-समृद्धि आ गई। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"रानी की कथा\",\"story\":\"एक राजा की रानी ने वरलक्ष्मी व्रत किया। व्रत के प्रभाव से राज्य में सुख-समृद्धि आ गई। राजा की सभी मनोकामनाएं पूर्ण हुईं।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। वरलक्ष्मी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"कलश स्थापना\",\"description\":\"कलश स्थापित करें। कलश में जल, सुपारी, पान, नारियल रखें। कलश पर लक्ष्मी का चित्र लगाएं।\"},\r\n    {\"step\":3,\"name\":\"माता लक्ष्मी की पूजा\",\"description\":\"माता लक्ष्मी की मूर्ति या चित्र स्थापित करें। ॐ श्रीं ह्रीं क्लीं महालक्ष्म्यै नमः मंत्र से पूजा करें।\"},\r\n    {\"step\":4,\"name\":\"सोलह श्रृंगार\",\"description\":\"माता लक्ष्मी को सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":5,\"name\":\"कथा वाचन\",\"description\":\"वरलक्ष्मी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":6,\"name\":\"आरती\",\"description\":\"लक्ष्मी आरती ॐ जय लक्ष्मी माता करें।\"},\r\n    {\"step\":7,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"}\r\n]', 'कलश, नारियल, सोलह श्रृंगार की वस्तुएं, लाल वस्त्र, लाल फूल, चंदन, कुमकुम, अक्षत, पंचामृत, फल, मिठाई, पान, सुपारी, दीपक, धूप, कपूर', 'ॐ श्रीं महालक्ष्म्यै नमः। हे माता वरलक्ष्मी, मैं वरलक्ष्मी व्रत का संकल्प लेती हूँ।', 'ॐ श्रीं महालक्ष्म्यै नमः। हे माता वरलक्ष्मी, आपकी कृपा से वरलक्ष्मी व्रत सफलतापूर्वक संपन्न हुआ।', 'Om Jai Lakshmi Mata', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'वरलक्ष्मी व्रत का विशेष महत्व है। यह व्रत माता लक्ष्मी को समर्पित है। इस दिन माता लक्ष्मी की पूजा करने से घर में धन-धान्य की कमी नहीं होती।', '1 Day', 'वरलक्ष्मी व्रत श्रावण मास के शुक्ल पक्ष के शुक्रवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए करती हैं।', 'Varalakshmi Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Lakshmi', 'वरलक्ष्मी व्रत श्रावण मास के शुक्ल पक्ष के शुक्रवार को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति, पुत्र और परिवार की सुख-समृद्धि के लिए करती हैं।', NULL, NULL, NULL, 1),
(4, 'Hartalika Teej Vrat Katha', 'Shiva-Parvati', '1 Day', 'Not Specified', 'Bhadrapada (Aug-Sep)', 'Shukla Tritiya', 'हरतालिका तीज व्रत भाद्रपद शुक्ल तृतीया को किया जाता है। यह व्रत विवाहित और अविवाहित दोनों महिलाएं करती हैं। यह व्रत माता पार्वती और भगवान शिव को समर्पित है।', 'हरतालिका तीज का व्रत माता पार्वती के अद्भुत तप का स्मरण है। माता पार्वती ने भगवान शिव को पति रूप में प्राप्त करने के लिए यह कठोर तप किया था।', 'इस व्रत को करने से मनोवांछित वर की प्राप्ति, सुखी वैवाहिक जीवन, पति की लंबी आयु और सभी मनोकामनाओं की पूर्ति होती है।', 'निर्जला व्रत रखें। पूरे दिन जल भी न पिएं। रात में जागरण करें। भगवान शिव और माता पार्वती की पूजा करें।', '[\r\n    {\"chapter\":1,\"title\":\"हरतालिका तीज की उत्पत्ति\",\"story\":\"माता पार्वती ने भगवान शिव को पति रूप में प्राप्त करने के लिए घोर तप किया। उनकी सखियाँ उन्हें घर ले आईं, लेकिन पार्वती ने फिर से तप शुरू कर दिया। उनके तप से प्रसन्न होकर भगवान शिव ने उन्हें पत्नी रूप में स्वीकार किया। तब से यह व्रत हरतालिका तीज के नाम से प्रसिद्ध हुआ। हरतालिका का अर्थ है - हर (शिव) और तालिका (तप) - शिव के लिए किया गया तप।\"},\r\n    {\"chapter\":2,\"title\":\"सखियों का सहयोग\",\"story\":\"माता पार्वती की सखियों ने उनके तप में सहयोग किया। उन्होंने ही पार्वती को भगवान शिव की महिमा बताई और तप करने की प्रेरणा दी। इसलिए इस दिन सखियों का भी पूजन किया जाता है।\"},\r\n    {\"chapter\":3,\"title\":\"व्रत का फल\",\"story\":\"जो महिलाएं श्रद्धा और नियम से हरतालिका तीज का व्रत करती हैं, उन्हें माता पार्वती की तरह सुखी वैवाहिक जीवन प्राप्त होता है। अविवाहित कन्याओं को मनोवांछित वर की प्राप्ति होती है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। हरतालिका तीज व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"भगवान शिव और पार्वती की पूजा\",\"description\":\"भगवान शिव और माता पार्वती की मूर्ति स्थापित करें। पार्वती जी को सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":3,\"name\":\"शिवलिंग अभिषेक\",\"description\":\"शिवलिंग का जल, दूध, दही, घी, शहद से अभिषेक करें।\"},\r\n    {\"step\":4,\"name\":\"कथा वाचन\",\"description\":\"हरतालिका तीज व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":5,\"name\":\"जागरण\",\"description\":\"रात्रि में जागरण करें। भगवान शिव और पार्वती की भजन-कीर्तन करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें। अगले दिन पारण करें।\"}\r\n]', 'भगवान शिव और पार्वती की मूर्ति, सोलह श्रृंगार की वस्तुएं, बेलपत्र, धतूरा, पंचामृत, फल, मिठाई, दीपक, धूप, कपूर', 'ॐ गौर्यै नमः। ॐ शिवाय नमः। हे माता पार्वती, हे भगवान शिव, मैं हरतालिका तीज व्रत का संकल्प लेती हूँ।', 'ॐ गौर्यै नमः। ॐ शिवाय नमः। हे माता पार्वती, हे भगवान शिव, आपकी कृपा से हरतालिका तीज व्रत सफलतापूर्वक संपन्न हुआ।', 'Om Jai Shiv Omkara', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'हरतालिका तीज का व्रत माता पार्वती के अद्भुत तप का स्मरण है। माता पार्वती ने भगवान शिव को पति रूप में प्राप्त करने के लिए यह कठोर तप किया था।', '1 Day', 'हरतालिका तीज व्रत भाद्रपद शुक्ल तृतीया को किया जाता है। यह व्रत विवाहित और अविवाहित दोनों महिलाएं करती हैं। यह व्रत माता पार्वती और भगवान शिव को समर्पित है।', 'Hartalika Teej Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Shiva-Parvati', 'हरतालिका तीज व्रत भाद्रपद शुक्ल तृतीया को किया जाता है। यह व्रत विवाहित और अविवाहित दोनों महिलाएं करती हैं। यह व्रत माता पार्वती और भगवान शिव को समर्पित है।', NULL, NULL, NULL, 1),
(5, 'Karva Chauth Vrat Katha', 'Gauri', '1 Day', 'Thursday', 'Kartik (Oct-Nov)', 'Krishna Chaturthi', 'करवा चौथ व्रत कार्तिक मास की कृष्ण चतुर्थी को किया जाता है। यह व्रत सुहागिन महिलाएं अपने पति की लंबी आयु, सुख-समृद्धि और सुरक्षा के लिए करती हैं।', 'करवा चौथ का व्रत सुहागिन महिलाओं के लिए अत्यंत महत्वपूर्ण है। यह व्रत निर्जला किया जाता है। चंद्रोदय के समय आरती कर व्रत खोला जाता है।', 'इस व्रत को करने से पति की लंबी आयु, सुखी वैवाहिक जीवन, संतान सुख और परिवार में सुख-शांति की प्राप्ति होती है।', 'निर्जला व्रत रखें। पूरे दिन जल भी न पिएं। चंद्रोदय के बाद ही भोजन करें। सात्विक भोजन करें।', '[\r\n    {\"chapter\":1,\"title\":\"करवा चौथ की उत्पत्ति\",\"story\":\"प्राचीन काल में वीरावती नाम की एक सुहागन थी। उसके सात भाई थे। एक बार करवा चौथ के दिन वीरावती ने व्रत रखा। वह बहुत भूखी-प्यासी हो गई। उसके भाइयों ने उससे झूठा चंद्रमा दिखाकर उसे व्रत तोड़ने को कहा। वीरावती ने व्रत तोड़ दिया। तुरंत उसके पति की मृत्यु हो गई। वीरावती रोने लगी। तब एक देवी ने आकर कहा - तुमने झूठा चंद्रमा देखकर व्रत तोड़ा है। अब फिर से व्रत करो। वीरावती ने श्रद्धा से व्रत किया। उसके पति को पुनः जीवन मिला। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"रानी की कथा\",\"story\":\"एक राजा की रानी ने करवा चौथ का व्रत किया। व्रत के प्रभाव से राजा को युद्ध में विजय मिली। राजा की आयु लंबी हुई।\"},\r\n    {\"chapter\":3,\"title\":\"चंद्रोदय पूजा\",\"story\":\"सायंकाल चंद्रोदय के समय महिलाएं छलनी से चंद्रमा देखती हैं, फिर अपने पति को देखती हैं और आरती करती हैं। इससे पति की लंबी आयु की प्राप्ति होती है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। करवा चौथ व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"सरगी (सेवा)\",\"description\":\"सूर्योदय से पूर्व सरगी (फलाहार) ग्रहण करें।\"},\r\n    {\"step\":3,\"name\":\"दिन में पूजा की तैयारी\",\"description\":\"दिन में करवा (मिट्टी का बर्तन) भरकर पूजा की तैयारी करें।\"},\r\n    {\"step\":4,\"name\":\"सायंकाल पूजा\",\"description\":\"सायंकाल माता गौरी और भगवान शिव की पूजा करें। करवा चौथ की कथा सुनें।\"},\r\n    {\"step\":5,\"name\":\"चंद्रोदय पूजा\",\"description\":\"चंद्रोदय पर छलनी से चंद्रमा देखें, फिर पति को देखें।\"},\r\n    {\"step\":6,\"name\":\"आरती\",\"description\":\"माता गौरी की आरती करें।\"},\r\n    {\"step\":7,\"name\":\"पारण\",\"description\":\"पति के हाथ से जल ग्रहण कर व्रत खोलें।\"}\r\n]', 'करवा (मिट्टी का बर्तन), छलनी, सोलह श्रृंगार की वस्तुएं, माता गौरी की मूर्ति, फल, मिठाई, दीपक, धूप, कपूर, चंदन, कुमकुम, अक्षत', 'ॐ गौर्यै नमः। हे माता गौरी, मैं करवा चौथ व्रत का संकल्प लेती हूँ। मेरे पति की लंबी आयु के लिए यह व्रत कर रही हूँ।', 'ॐ गौर्यै नमः। हे माता गौरी, आपकी कृपा से करवा चौथ व्रत सफलतापूर्वक संपन्न हुआ। मेरे पति की आयु लंबी हो।', 'Jai Gauri Maiya', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'करवा चौथ का व्रत सुहागिन महिलाओं के लिए अत्यंत महत्वपूर्ण है। यह व्रत निर्जला किया जाता है। चंद्रोदय के समय आरती कर व्रत खोला जाता है।', '1 Day', 'करवा चौथ व्रत कार्तिक मास की कृष्ण चतुर्थी को किया जाता है। यह व्रत सुहागिन महिलाएं अपने पति की लंबी आयु, सुख-समृद्धि और सुरक्षा के लिए करती हैं।', 'Karva Chauth Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Gauri', 'करवा चौथ व्रत कार्तिक मास की कृष्ण चतुर्थी को किया जाता है। यह व्रत सुहागिन महिलाएं अपने पति की लंबी आयु, सुख-समृद्धि और सुरक्षा के लिए करती हैं।', NULL, NULL, NULL, 1),
(6, 'Ekadashi Vrat Katha', 'Vishnu', '1 Day', 'Not Specified', 'Throughout Year', 'Ekadashi', 'एकादशी व्रत हर महीने के शुक्ल और कृष्ण पक्ष की एकादशी तिथि को किया जाता है। यह व्रत भगवान विष्णु को समर्पित है।', 'एकादशी व्रत का विशेष महत्व है। यह व्रत भगवान विष्णु को अत्यंत प्रिय है। इस दिन भगवान विष्णु की पूजा करने से सभी पापों का नाश होता है।', 'इस व्रत को करने से पापों का नाश, आयु में वृद्धि, सुख-समृद्धि, संतान सुख और मोक्ष की प्राप्ति होती है।', 'निराहार या फलाहार व्रत रखें। अन्न का त्याग करें। सात्विक भोजन करें। भगवान विष्णु का ध्यान करें।', '[\r\n    {\"chapter\":1,\"title\":\"एकादशी की उत्पत्ति\",\"story\":\"प्राचीन काल में एक राक्षस मुर नामक दैत्य था। उसने देवताओं को पराजित कर स्वर्ग पर अधिकार कर लिया। देवता भगवान विष्णु के पास गए। भगवान विष्णु ने मुर से युद्ध किया। युद्ध के दौरान भगवान विष्णु थक गए और एक गुफा में विश्राम करने लगे। तब मुर ने उन पर आक्रमण कर दिया। तब भगवान विष्णु के शरीर से एक दिव्य कन्या प्रकट हुई। उसने मुर का वध कर दिया। भगवान विष्णु ने प्रसन्न होकर उस कन्या को एकादशी नाम दिया और वरदान दिया कि जो कोई एकादशी का व्रत करेगा, उसके सभी पाप नष्ट होंगे। तब से एकादशी व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"पांडवों की कथा\",\"story\":\"महाभारत के युद्ध के बाद पांडवों को राज्य मिला। युधिष्ठिर ने भगवान कृष्ण से पूछा कि सबसे श्रेष्ठ व्रत कौन सा है? भगवान कृष्ण ने एकादशी व्रत की महिमा बताई। युधिष्ठिर ने एकादशी व्रत किया और सभी पापों से मुक्त हुए।\"},\r\n    {\"chapter\":3,\"title\":\"फल श्रुति\",\"story\":\"जो व्यक्ति एकादशी का व्रत श्रद्धा और नियम से करता है, उसे हजार अश्वमेघ यज्ञ के बराबर फल मिलता है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। एकादशी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"भगवान विष्णु की पूजा\",\"description\":\"भगवान विष्णु की मूर्ति या चित्र स्थापित करें। तुलसी दल अर्पित करें।\"},\r\n    {\"step\":3,\"name\":\"कथा वाचन\",\"description\":\"एकादशी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":4,\"name\":\"भजन-कीर्तन\",\"description\":\"दिन भर भगवान विष्णु के भजन-कीर्तन करें।\"},\r\n    {\"step\":5,\"name\":\"जागरण\",\"description\":\"रात्रि में जागरण करें।\"},\r\n    {\"step\":6,\"name\":\"पारण\",\"description\":\"द्वादशी के दिन प्रातः पारण करें।\"}\r\n]', 'तुलसी दल, फल, मिठाई, पंचामृत, दीपक, धूप, कपूर, भगवान विष्णु की मूर्ति', 'ॐ नमो भगवते वासुदेवाय। हे भगवान विष्णु, मैं एकादशी व्रत का संकल्प लेता/लेती हूँ।', 'ॐ नमो भगवते वासुदेवाय। हे भगवान विष्णु, आपकी कृपा से एकादशी व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Vishnu Bhagwan', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'एकादशी व्रत का विशेष महत्व है। यह व्रत भगवान विष्णु को अत्यंत प्रिय है। इस दिन भगवान विष्णु की पूजा करने से सभी पापों का नाश होता है।', '1 Day', 'एकादशी व्रत हर महीने के शुक्ल और कृष्ण पक्ष की एकादशी तिथि को किया जाता है। यह व्रत भगवान विष्णु को समर्पित है।', 'Ekadashi Vrat Katha', NULL, NULL, 'vrat_katha', 'व्रत कथा', 'Vishnu', 'एकादशी व्रत हर महीने के शुक्ल और कृष्ण पक्ष की एकादशी तिथि को किया जाता है। यह व्रत भगवान विष्णु को समर्पित है।', NULL, NULL, NULL, 1),
(7, 'अहोई अष्टमी व्रत कथा (संतान रक्षा एवं दीर्घायु)', 'Ahoi Mata', '1 Day', 'Thursday', 'Kartik (Oct-Nov)', 'Krishna Ashtami', 'अहोई अष्टमी व्रत कार्तिक मास की कृष्ण अष्टमी को किया जाता है। यह व्रत संतान की सुरक्षा और सुख-समृद्धि के लिए माताएं करती हैं।', 'अहोई अष्टमी का व्रत संतान की लंबी आयु और सुरक्षा के लिए किया जाता है। यह व्रत दीपावली से 8 दिन पूर्व आता है।', 'इस व्रत को करने से संतान की लंबी आयु, सुख-समृद्धि, सुरक्षा और सभी मनोकामनाओं की पूर्ति होती है।', 'निर्जला व्रत रखें। सूर्यास्त के बाद तारे दिखने पर व्रत खोलें। सात्विक भोजन करें।', '[\r\n    {\"chapter\":1,\"title\":\"अहोई अष्टमी की उत्पत्ति\",\"story\":\"प्राचीन काल में एक गरीब महिला के सात पुत्र थे। एक दिन वह जंगल में मिट्टी खोद रही थी। उसने अनजाने में एक सियार के बच्चे को मार डाला। उसके सभी पुत्र मर गए। वह बहुत दुखी हुई। तब एक देवी ने उसे अहोई अष्टमी का व्रत करने को कहा। उसने श्रद्धा से व्रत किया। व्रत के प्रभाव से उसके सभी पुत्र पुनः जीवित हो गए। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"रानी की कथा\",\"story\":\"एक राजा की रानी के पुत्र मर गए थे। उसने अहोई अष्टमी का व्रत किया। व्रत के प्रभाव से उसके पुत्र पुनः जीवित हो गए।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। अहोई अष्टमी व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"अहोई माता की पूजा\",\"description\":\"अहोई माता की मूर्ति या चित्र स्थापित करें। सियार का चित्र भी बनाएं।\"},\r\n    {\"step\":3,\"name\":\"कथा वाचन\",\"description\":\"अहोई अष्टमी व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":4,\"name\":\"तारा दर्शन\",\"description\":\"सायंकाल तारे दिखने पर पूजा करें।\"},\r\n    {\"step\":5,\"name\":\"आरती\",\"description\":\"अहोई माता की आरती करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"}\r\n]', 'अहोई माता की मूर्ति, सियार का चित्र, फल, मिठाई, दीपक, धूप, कपूर, चंदन, कुमकुम, अक्षत, सूत के धागे', 'ॐ अहोई मातायै नमः। हे माता अहोई, मैं अपनी संतान की सुरक्षा के लिए यह व्रत कर रही हूँ।', 'ॐ अहोई मातायै नमः। हे माता अहोई, आपकी कृपा से यह व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Ahoi Mata', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'अहोई अष्टमी का व्रत संतान की लंबी आयु और सुरक्षा के लिए किया जाता है। यह व्रत दीपावली से 8 दिन पूर्व आता है।', '1 Day', 'अहोई अष्टमी व्रत कार्तिक मास की कृष्ण अष्टमी को किया जाता है। यह व्रत संतान की सुरक्षा और सुख-समृद्धि के लिए माताएं करती हैं।', 'अहोई अष्टमी व्रत कथा (संतान रक्षा एवं दीर्घायु)', NULL, 'अहोईअष्टमीव्रतकथा', 'vrat_katha', 'व्रत कथा', 'Ahoi Mata', 'प्राचीन काल में एक नगर में एक धर्मात्मा साहूकार रहता था। उसके सात पुत्र और सात बहुएं थीं। दीपावली से पूर्व कार्तिक मास की कृष्ण पक्ष की अष्टमी तिथि को घर की लिपाई-पुताई के लिए साहूकार की सातों बहुएं जंगल में खदान से पीली मिट्टी खोदने गईं। साहूकार की छोटी बहू जब खुरपी से मिट्टी खोद रही थी, तो उसकी खुरपी खदान के भीतर बने एक सेह (स्याही/साही) की मांद में जा लगी, जिससे सेह का एक नन्हा बच्चा कटकर मर गया।\n\nछोटी बहू को इस अनजाने में हुए पाप से अत्यधिक पश्चाताप हुआ। सेह की माता ने क्रोधित होकर शाप दिया—\'जिस प्रकार तुमने मेरे बच्चे को मारा है, उसी प्रकार मैं तुम्हारी कोख को बांधूंगी और तुम्हारी सन्तान जीवित नहीं रहेगी।\' शाप के प्रभाव से छोटी बहू के जन्म लेते ही एक के बाद एक सातों पुत्र अल्पायु में ही काल के गाल में समा गए। साहूकार की बहू विलाप करने लगी।\n\nएक दिन उसने एक वृद्ध तपस्वी मुनि से अपने कष्ट का कारण और निवारण पूछा। मुनि ने बताया—\'बेटी! अनजाने में तुमसे सेह के बच्चे की हत्या हुई थी, उसी के शाप से तुम्हारी सन्तान नहीं बचती। तुम कार्तिक कृष्ण अष्टमी को अहोई माता (भगवती पार्वती का स्वरूप) का निर्जला व्रत रखो, सेह और उसके बच्चों का चित्र दीवार पर बनाकर उनका पूजन करो और गौमाता की सेवा कर क्षमा याचना करो।\'\n\nसाहूकार की बहू ने पूर्ण श्रद्धा और निष्ठा के साथ कार्तिक कृष्ण अष्टमी को अहोई अष्टमी का व्रत रखा। सायंकाल आकाश में तारे दिखने पर उसने अर्घ्य दिया, अहोई माता की कथा सुनी और सेह माता से हाथ जोड़कर क्षमा मांगी। उसकी सच्ची भक्ति और प्रायश्चित से अहोई माता प्रसन्न हुईं और उसके सभी मृत पुत्रों को पुनर्जीवन प्रदान किया। तब से यह व्रत सन्तान की दीर्घायु और रक्षा के लिए विख्यात हुआ।', NULL, 'अहोई अष्टमी का व्रत माताओं द्वारा अपनी संतान की दीर्घायु, स्वास्थ्य और उज्ज्वल भविष्य के लिए किया जाता है। सच्ची प्रार्थना से हर अनिष्ट टल जाता है।', NULL, 1),
(8, 'वट सावित्री व्रत कथा (सती सावित्री एवं सत्यवान)', 'Savitri-Satyavan', '1 Day', 'Not Specified', 'Jyeshtha (May-Jun)', 'Amavasya/Purnima', 'वट सावित्री व्रत ज्येष्ठ मास की अमावस्या या पूर्णिमा को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं।', 'वट सावित्री व्रत का विशेष महत्व है। यह व्रत सावित्री के अद्भुत पतिव्रत धर्म का स्मरण है। सावित्री ने यमराज से अपने पति सत्यवान का प्राण वापस लिया था।', 'इस व्रत को करने से पति की लंबी आयु, सुखी वैवाहिक जीवन, संतान सुख और सभी मनोकामनाओं की पूर्ति होती है।', 'व्रत के दिन वट वृक्ष की पूजा करें। निर्जला व्रत रखें। सात्विक भोजन करें।', '[\r\n    {\"chapter\":1,\"title\":\"वट सावित्री व्रत की उत्पत्ति\",\"story\":\"सावित्री राजा अश्वपति की पुत्री थीं। उन्होंने सत्यवान को पति रूप में वरण किया। सत्यवान को एक वर्ष में मृत्यु का श्राप था। सत्यवान के मृत्यु के समय यमराज आए। सावित्री ने यमराज का पीछा किया। यमराज ने कहा - सावित्री, तुम वापस लौट जाओ। सावित्री ने कहा - जहाँ मेरे पति हैं, वहीं मैं हूँ। सावित्री की पतिव्रता से प्रसन्न होकर यमराज ने सत्यवान को पुनः जीवन दान दिया। तब से यह व्रत प्रचलित हुआ।\"},\r\n    {\"chapter\":2,\"title\":\"वट वृक्ष का महत्व\",\"story\":\"वट वृक्ष अजर-अमर माना जाता है। इस दिन वट वृक्ष की पूजा करने से पति की आयु लंबी होती है।\"}\r\n]', '[\r\n    {\"step\":1,\"name\":\"स्नान और संकल्प\",\"description\":\"प्रातः स्नान कर स्वच्छ वस्त्र धारण करें। वट सावित्री व्रत का संकल्प लें।\"},\r\n    {\"step\":2,\"name\":\"वट वृक्ष पूजा\",\"description\":\"वट वृक्ष के नीचे जाकर पूजा करें। वट वृक्ष की परिक्रमा करें।\"},\r\n    {\"step\":3,\"name\":\"सावित्री-सत्यवान की पूजा\",\"description\":\"सावित्री-सत्यवान की मूर्ति स्थापित करें। सोलह श्रृंगार की वस्तुएं अर्पित करें।\"},\r\n    {\"step\":4,\"name\":\"कथा वाचन\",\"description\":\"वट सावित्री व्रत की कथा सुनें या सुनाएं।\"},\r\n    {\"step\":5,\"name\":\"आरती\",\"description\":\"सावित्री माता की आरती करें।\"},\r\n    {\"step\":6,\"name\":\"प्रसाद वितरण\",\"description\":\"प्रसाद वितरित करें।\"}\r\n]', 'सावित्री-सत्यवान की मूर्ति, सोलह श्रृंगार की वस्तुएं, फल, मिठाई, दीपक, धूप, कपूर, चंदन, कुमकुम, अक्षत, सूत के धागे', 'ॐ सावित्र्यै नमः। हे माता सावित्री, मैं अपने पति की लंबी आयु के लिए यह व्रत कर रही हूँ।', 'ॐ सावित्र्यै नमः। हे माता सावित्री, आपकी कृपा से यह व्रत सफलतापूर्वक संपन्न हुआ।', 'Jai Savitri Mata', NULL, NULL, 0, 0, 0, '2026-03-27 14:26:50', '2026-10-31 09:54:11', NULL, NULL, NULL, NULL, NULL, NULL, 'वट सावित्री व्रत का विशेष महत्व है। यह व्रत सावित्री के अद्भुत पतिव्रत धर्म का स्मरण है। सावित्री ने यमराज से अपने पति सत्यवान का प्राण वापस लिया था।', '1 Day', 'वट सावित्री व्रत ज्येष्ठ मास की अमावस्या या पूर्णिमा को किया जाता है। यह व्रत विवाहित महिलाएं अपने पति की लंबी आयु और सुखी वैवाहिक जीवन के लिए करती हैं।', 'वट सावित्री व्रत कथा (सती सावित्री एवं सत्यवान)', NULL, 'वटसावित्रीव्रतमहात्म्यम्', 'vrat_katha', 'व्रत कथा', 'Savitri-Satyavan', 'भद्र देश के धर्मात्मा राजा अश्वपति की कोई संतान नहीं थी। राजा ने अठारह वर्षों तक माता सावित्री की कठोर तपस्या की, जिससे प्रसन्न होकर देवी ने उन्हें एक सर्वगुण सम्पन्न कन्या का वरदान दिया। देवी के अनुग्रह से जन्मी इस कन्या का नाम \'सावित्री\' रखा गया। जब सावित्री विवाह योग्य हुईं, तो राजा ने उन्हें स्वयं सुयोग्य वर खोजने का आदेश दिया। सावित्री ने तपोवन में जाकर शाल्व देश के द्युमत्सेन के पुत्र सत्यवान को अपने पति रूप में वरण किया। राजा द्युमत्सेन अंधे हो चुके थे और उनका राज्य शत्रुओं ने छीन लिया था, जिससे वे वन में सादा जीवन व्यतीत कर रहे थे।\n\nजब देवर्षि नारद ने सावित्री के इस वरण के बारे में सुना, तो वे राजा अश्वपति के पास पहुंचे और बोले—\'राजन्! सत्यवान शूरवीर, सत्यवादी और रूपवान हैं, किन्तु इनके भाग्य में एक भारी दोष है। आज से ठीक एक वर्ष पश्चात् इनकी मृत्यु निश्चित है।\' राजा अश्वपति चिंतित हो गए और उन्होंने सावित्री को किसी अन्य वर को चुनने को कहा। किन्तु सावित्री ने दृढ़ता से कहा—\'पिताजी! आर्य कन्या अपने जीवन में एक ही बार पति का वरण करती है। मैंने सत्यवान को चुन लिया है, चाहे वे अल्पायु हों या दीर्घायु, मेरे पति केवल वही होंगे।\'\n\nसावित्री का विवाह सत्यवान से हुआ। सावित्री ने राजसी वैभव त्याग कर वन में सास-ससुर और पति की अनन्य सेवा प्रारंभ की। नारद जी द्वारा बताई गई मृत्यु की तिथि जब निकट आई, तो सावित्री ने तीन दिन पूर्व से ही \'त्रिरात्र व्रत\' (कठोर निर्जला उपवास) प्रारंभ कर दिया। नियत दिन सत्यवान कुल्हाड़ी लेकर लकड़ी काटने वन में जाने लगे। सावित्री ने भी सास-ससुर की अनुमति लेकर उनके साथ जाने की प्रार्थना की। वन में वट वृक्ष के नीचे लकड़ी काटते समय सत्यवान के सिर में तीव्र पीड़ा होने लगी। वे सावित्री की गोद में सिर रखकर सो गए।\n\nउसी समय दक्षिण दिशा से साक्षात् मृत्यु के देवता यमराज भैंसे पर सवार होकर आए। उनके हाथ में कालपाश था। यमराज ने सत्यवान के शरीर से अंगूठे के बराबर जीवात्मा को पाश में बांध लिया और दक्षिण दिशा की ओर चल पड़े। सावित्री भी पति के जीवात्मा के पीछे-पीछे चलने लगीं। यमराज ने कहा—\'हे पतिव्रते! तुम वापस लौट जाओ और सत्यवान का श्राद्ध-तर्पण करो। जीवित प्राणी मेरे पीछे नहीं आ सकते।\' सावित्री ने उत्तर दिया—\'प्रभो! जहां मेरे पति जा रहे हैं, पत्नी होने के नाते मेरा कर्तव्य है कि मैं भी वहीं जाऊं। पातिव्रत्य धर्म के प्रभाव से मुझे कोई मार्ग दुर्गम नहीं लगता।\'\n\nसावित्री के धर्मयुक्त वचनों से प्रसन्न होकर यमराज ने कहा—\'हे कल्याणी! सत्यवान के जीवन को छोड़कर तुम कोई भी तीन वर मांग लो।\' सावित्री ने प्रथम वर में अपने अंधे सास-ससुर के नेत्रों की ज्योति मांगी। द्वितीय वर में उनका छिना हुआ राज्य वापस मांगा। तृतीय वर में अपने पिता के लिए सौ पुत्रों का वरदान मांगा। यमराज ने तथास्तु कहकर आगे बढ़ना चाहा, किन्तु सावित्री फिर भी पीछे चलती रहीं। उन्होंने धर्म, दया और सत्संग की महिमा पर ऐसे गूढ़ विचार व्यक्त किए कि यमराज अत्यंत विस्मित और मुदित हो गए। उन्होंने कहा—\'सावित्री! मैं तुम्हारी पवित्रता से अभिभूत हूं। एक और अंतिम वर मांगो, पर सत्यवान का प्राण मत मांगना।\'\n\nसावित्री ने हाथ जोड़कर कहा—\'हे धर्मराज! यदि आप मुझ पर वास्तव में प्रसन्न हैं, तो मुझे सत्यवान के वीर्य से सौ पराक्रमी और धर्मिष्ठ पुत्रों की माता बनने का वरदान दीजिए।\' यमराज ने बिना सोचे \'तथास्तु\' कह दिया। सावित्री मुस्कुराईं और बोलीं—\'हे प्रभु! आप सत्यवादी हैं। एक पतिव्रता नारी अपने पति के बिना पुत्र कैसे उत्पन्न कर सकती है? अतः आपको सत्यवान को जीवनदान देना ही होगा।\'\n\nयमराज अपनी प्रतिज्ञा में बंध गए। वे सावित्री के अदम्य पातिव्रत्य, तेज और वाकपटुता के आगे नतमस्तक हो गए। उन्होंने सत्यवान के सूक्ष्म शरीर को पाश से मुक्त करते हुए कहा—\'हे सती शिरोमणि! तुम्हारी जैसी पतिव्रता नारी तीनों लोकों में दुर्लभ है। मैंने तुम्हारे पति को चार सौ वर्षों की नवीन दीर्घायु प्रदान की। तुम्हारा यह वट सावित्री व्रत कल्प-कल्पान्तर तक स्त्रियों को अखण्ड सौभाग्य प्रदान करेगा।\'\n\nसावित्री उसी वट वृक्ष के नीचे लौटीं, जहां सत्यवान का शव पड़ा था। सत्यवान ऐसे उठ बैठे जैसे गहरी नींद से जागे हों। उधर उनके सास-ससुर की आंखों की ज्योति लौट आई और उनका राज्य भी वापस मिल गया।', NULL, 'वट सावित्री व्रत सती सावित्री के अदम्य पातिव्रत्य, बुद्धि और निष्ठा का पावन प्रतीक है। इस व्रत से सौभाग्य, पति की दीर्घायु और समस्त पारिवारिक सुखों की प्राप्ति होती है।', NULL, 1),
('katha_brihaspativar', 'गुरुवार (बृहस्पतिवार) व्रत कथा', 'देवगुरु बृहस्पति एवं श्री हरि विष्णु', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'વિદ્યા અને સદ્બુદ્ધિ જ સાચી સંપત્તિ છે. ગુરુવારના વ્રતથી જ્ઞાન, સંપત્તિ અને સુખી દાંપત્યજીવન પ્રાપ્ત થાય છે.', 'विद्या आणि विवेक हीच खरी संपत्ती आहे. गुरुवारच्या व्रताने विवेक जागृत होऊन ऐश्वर्य आणि शांती प्राप्त होते.', NULL, NULL, NULL, NULL, 'गुरुवार के व्रत से ज्ञान, विद्या, धन, सुखी वैवाहिक जीवन और देवगुरु बृहस्पति की कृपा से अटके हुए कार्य शीघ्र सिद्ध होते हैं।', '15-20 मिनट', 'अहंकारी रानी की दरिद्रता, देवगुरु बृहस्पति के व्रत-नियमों से पुनः ऐश्वर्य प्राप्ति और चने की दाल व गुड़ से पूजन का विधान।', 'गुरुवार (बृहस्पतिवार) व्रत कथा', 'बृहस्पतिवारव्रतकथा गुरुप्रीतिकरी', 'बृहस्पतिवारव्रतकथा गुरुप्रीतिकरी', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'देवगुरु बृहस्पति एवं श्री हरि विष्णु', 'एक प्रतापी राजा के राज्य में अपार सम्पदा थी, किन्तु उसकी रानी अत्यंत कृपण थी। जब भी कोई याचक महल के द्वार पर आता, वह उसे दुत्कार कर भगा देती। एक दिन देवगुरु बृहस्पति संन्यासी के वेश में पधारे और भिक्षा मांगी। रानी ने कहा—महाराज! मैं दान-पुण्य से तंग आ चुकी हूं, कोई ऐसा उपाय बताएं जिससे यह सारा धन समाप्त हो जाए और मुझे किसी को कुछ न देना पड़े। साधु ने कहा—यदि तुम्हारी यही इच्छा है, तो बृहस्पतिवार के दिन घर लीपकर पीली मिट्टी से पुतवाना, बाल धोना और पुरुषों से हजामत बनवाना।\n\nरानी ने वैसा ही किया। कुछ ही सप्ताह में राजा का सारा राजपाट और धन नष्ट हो गया। वे दाने-दाने को मोहताज हो गए। रानी पश्चाताप में रोने लगी। तब देवगुरु ने पुनः दर्शन देकर गुरुवार व्रत, चने की दाल, गुड़, हल्दी और केले के वृक्ष की पूजा का विधान बताया। रानी ने भक्तिपूर्वक व्रत किया और उसका वैभव पूर्ववत लौट आया।', NULL, 'विद्या और सद्बुद्धि ही सच्चा धन है। गुरुवार के व्रत से बुद्धि निर्मल होती है और अहंकार का नाश होकर जीवन में श्री-सम्पत्ति का वास होता है।', 'Wisdom and benevolence are true riches. Devotion on Thursdays cleanses ego, revives lost fortune, and bestows intellect and grace.', 1),
('katha_gajendra_moksha', 'गजेन्द्र मोक्ष पावन उद्धार कथा', 'भगवान श्री हरि विष्णु', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'જ્યારે માનવ અહંકાર છોડીને પ્રભુના શરણે જાય છે, ત્યારે ભગવાન પલભરમાં સહાય માટે દોડી આવે છે.', 'जेव्हा मनुष्य सर्व अहंकार सोडून ईश्वराला शरण जातो, तेव्हा परमात्मा एका क्षणात संकटमुक्त करतो.', NULL, NULL, NULL, NULL, 'गजेन्द्र मोक्ष का पाठ करने से असाध्य रोगों, मृत्यु भय, ऋण और जीवन के घोर संकटों से तत्काल मुक्ति मिलती है।', '15-18 मिनट', 'ऋतुमान पर्वत पर हाथियों के राजा गजेन्द्र का सरोवर में प्रवेश, ग्राह (मगरमच्छ) द्वारा पैर पकड़ना, हजार वर्षों का संघर्ष और एक कमल पुष्प अर्पित कर प्रभु की शरणागति।', 'गजेन्द्र मोक्ष पावन उद्धार कथा', 'गजेन्द्रमोक्षश्रीमद्भागवतमहात्म्य', 'गजेन्द्रमोक्षश्रीमद्भागवतमहात्म्य', 'pauranik_katha', 'पौराणिक लीला कथा', 'भगवान श्री हरि विष्णु', 'श्रीमद्भागवत महापुराण के अष्टम स्कन्ध में गजेन्द्र मोक्ष की परम पावन कथा है। त्रिकूट पर्वत पर गजेन्द्र नामक एक बलशाली गजराज रहता था। एक दिन वह अपनी हथिनियों और शावकों सहित एक रमणीक सरोवर में जलक्रीड़ा करने उतरा। उसी सरोवर में एक शक्तिशाली ग्राह (मगरमच्छ) रहता था। ग्राह ने गजेन्द्र के पैर को अपने जबड़ों में जकड़ लिया। गजेन्द्र ने छूटने का अथक प्रयास किया। उसके परिवार और साथी हाथियों ने भी खींचने की चेष्टा की, किन्तु जब ग्राह का बल बढ़ने लगा तो सभी साथी उसे असहाय छोड़कर चले गए।\n\nजल में ग्राह का बल हजार गुना था। यह द्वन्द्व युद्ध एक सहस्र (हजार) वर्षों तक चला। जब गजेन्द्र का शरीर अशक्त हो गया और अहंकार टूट गया, तब उसे पूर्वजन्म के संस्कारों से भगवान विष्णु का स्मरण हुआ। उसने सरोवर से अपनी सूंड में एक नीलकमल उठाया और आकाश की ओर उठाकर आर्तनाद किया: \"हे नाथ! हे नारायण! शरणागत की रक्षा करो।\" भक्त की करुण पुकार सुनते ही भगवान विष्णु गरुड़ पर सवार होकर तत्काल प्रकट हुए और अपने सुदर्शन चक्र से ग्राह का मुख विदीर्ण कर गजेन्द्र को जीवनदान और मोक्ष प्रदान किया।', NULL, 'जब मनुष्य अपने बल और सांसारिक सम्बन्धों का अहंकार त्यागकर प्रभु के चरणों में पूर्ण शरणागति लेता है, तब परमात्मा क्षणभर में संकट से उबार लेते हैं।', 'When one completely surrenders pride and worldly reliances to the Supreme Divine, salvation and grace descend instantaneously.', 1),
('katha_ganga_avataran', 'गंगा अवतरण एवं भागीरथ तपस्या', 'माता गंगा, भगवान शिव एवं श्री हरि', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'દ્રઢ સંકલ્પ અને શિવજીની કૃપાથી અસંભવ કાર્ય પણ સંભવ બને છે. ગંગા અવતરણ પવિત્રતા અને પુરુષાર્થનું પ્રતીક છે.', 'दृढ निश्चय आणि ईश्वराची कृपा असेल तर अशक्यही शक्य होते. भागीरथाचे प्रयत्न हेच मानवजातीचे आदर्श आहेत.', NULL, NULL, NULL, NULL, 'गंगा अवतरण कथा के श्रवण से पितृ दोष शान्त होते हैं, अंतःकरण पवित्र होता है और पूर्वजों को सद्गति प्राप्त होती है।', '18-22 मिनट', 'राजा सगर के साठ हजार पुत्रों का कपिल मुनि के कोप से भस्म होना, राजा भागीरथ की कठोर तपस्या, शिव जी की जटाओं में गंगा का वेग समाना और पाताल लोक का उद्धार।', 'गंगा अवतरण एवं भागीरथ तपस्या', 'गङ्गावतरणभागीरथतपःकथा', 'गङ्गावतरणभागीरथतपःकथा', 'pauranik_katha', 'पौराणिक लीला कथा', 'माता गंगा, भगवान शिव एवं श्री हरि', 'सूर्यवंशी राजा सगर ने अश्वमेध यज्ञ किया। देवराज इन्द्र ने ईर्ष्यावश यज्ञ का घोड़ा चुराकर पाताल लोक में महर्षि कपिल के आश्रम में बांध दिया। घोड़े को खोजते हुए राजा सगर के साठ हजार पुत्र पाताल पहुंचे और कपिल मुनि को चोर समझकर उन पर प्रहार करने दौड़े। मुनि ने जैसे ही नेत्र खोले, उनके तपोबल की क्रोधाग्नि से साठों हजार राजकुमार भस्म हो गए। उनकी आत्माएं बिना तर्पण के भटकने लगीं।\n\nअनेक पीढ़ियों के पश्चात् राजा भागीरथ ने अपने पूर्वजों के उद्धार का दृढ़ संकल्प लिया। उन्होंने हिमालय पर जाकर ब्रह्मा जी की घोर तपस्या की। ब्रह्मा जी ने कहा—मैं गंगा को पृथ्वी पर भेजने को तैयार हूं, किन्तु उनके वेग को केवल भगवान शिव ही धारण कर सकते हैं। भागीरथ ने फिर एक पैर पर खड़े होकर महादेव की तपस्या की। भगवान शिव प्रसन्न हुए और उन्होंने गंगा के प्रचंड वेग को अपनी जटाओं में समेट लिया। इसके बाद गंगा की एक निर्मल धारा जटाओं से निकली और भागीरथ के पीछे-पीछे पाताल लोक पहुंची, जहां साठ हजार पूर्वजों की भस्म का स्पर्श कर उन्हें वैकुण्ठ लोक पहुंचा दिया।', NULL, 'असंभव को भी संभव कर दिखाने वाले संकल्प को ही \\\"भागीरथ प्रयास\\\" कहते हैं। दृढ़ निष्ठा और शिव कृपा से कोई भी लक्ष्य अप्राप्य नहीं है।', 'Unrelenting perseverance aligned with divine grace can achieve the seemingly impossible, cleansing generations of hardship.', 1),
('katha_mangalvar', 'मंगलवार व्रत कथा (श्री हनुमान कृपा)', 'महावीर हनुमान जी', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'હનુમાનજી સંકટમોચન છે. મંગળવારનું વ્રત કરવાથી જીવનના તમામ અમંગળ દૂર થાય છે અને શક્તિ તથા સાહસ મળે છે.', 'हनुमान जी सर्व संकटांचे निवारण करणारे आहेत. मंगळवारच्या व्रताने भय, रोग आणि संकटे नष्ट होतात.', NULL, NULL, NULL, NULL, 'मंगलवार का व्रत रखने से मंगल ग्रह के क्रूर दोष शांत होते हैं, भय, भूत-पिशाच और शत्रुओं का नाश होता है तथा शक्ति और साहस की वृद्धि होती है।', '12-15 मिनट', 'ब्राह्मण दम्पति केशव और अंजलि की निष्ठा, पवनपुत्र हनुमान जी की परीक्षा और मंगल दोष निवारण कर तेजस्वी पुत्र प्राप्ति की कथा।', 'मंगलवार व्रत कथा (श्री हनुमान कृपा)', 'मङ्गलवारव्रतकथा हनुमत्कृपा', 'मङ्गलवारव्रतकथा हनुमत्कृपा', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'महावीर हनुमान जी', 'प्राचीन काल में एक ब्राह्मण दम्पति रहते थे। ब्राह्मण का नाम केशव और ब्राह्मणी का नाम अंजलि था। उनके कोई सन्तान नहीं थी। ब्राह्मणी मंगलवार को नियमपूर्वक हनुमान जी का व्रत रखती थी और भोग लगाए बिना अन्न ग्रहण नहीं करती थी। एक बार किसी कारणवश ब्राह्मणी मंगलवार को भोग न बना सकी। उसने संकल्प लिया कि अगले मंगलवार को ही भोग लगाकर भोजन करेगी। छह दिन तक वह भूखी-प्यासी रही।\n\nसातवें दिन मंगलवार को वह मूर्छित हो गई। हनुमान जी उसकी अनन्य भक्ति देखकर अत्यंत प्रसन्न हुए और साक्षात् प्रकट होकर उसे एक अति सुन्दर बालक का वरदान दिया। उस बालक का नाम मंगल रखा गया। जब ब्राह्मण घर लौटा तो बालक को देखकर सन्देह करने लगा। एक दिन उसने कुएं में बालक को गिरा दिया। जब वह घर पहुंचा तो बालक को पूर्ववत आंगन में खेलते देखा। उसी रात्रि हनुमान जी ने स्वप्न में ब्राह्मण को दर्शन देकर ब्राह्मणी की सत्यनिष्ठा बताई। ब्राह्मण ने लज्जित होकर क्षमा मांगी।', NULL, 'हनुमान जी संकटमोचन हैं। मंगलवार का व्रत करने वाले साधक के जीवन से समस्त अमंगल दूर होकर सदा मंगल ही मंगल होता है।', 'Lord Hanuman is the dispeller of all adversities. Tuesday observance cleanses astrological afflictions, instills immense valour, and bestows auspiciousness.', 1),
('katha_samudra_manthan', 'समुद्र मंथन एवं अमृत प्राकट्य', 'भगवान विष्णु, कुर्म अवतार एवं महादेव', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'જીવન પણ એક સમુદ્ર મંથન સમાન છે. સાધનામાં પહેલા કષ્ટો આવે છે, જેને ધૈર્યથી સહન કરવાથી અંતે પરમાનંદનું અમૃત મળે છે.', 'जीवन देखील एका समुद्र मंथनासारखे आहे. आधी संकटरूपी विष पचवावे लागते, तेव्हाच आत्मिक शांतीचे अमृत लाभते.', NULL, NULL, NULL, NULL, 'इस पावन कथा के श्रवण से मनुष्य का चित्त मंथन होता है, दुर्गुणों रूपी विष का शमन होकर सद्गुणों रूपी अमृत की प्राप्ति होती है।', '20-25 मिनट', 'दुर्वासा ऋषि का शाप, देवताओं का तेजहीन होना, मन्दराचल पर्वत और वासुकि नाग द्वारा क्षीरसागर मंथन, हलाहल विष और चौदह रत्नों का प्राकट्य।', 'समुद्र मंथन एवं अमृत प्राकट्य', 'समुद्रमन्थनलीलाकथा', 'समुद्रमन्थनलीलाकथा', 'pauranik_katha', 'पौराणिक लीला कथा', 'भगवान विष्णु, कुर्म अवतार एवं महादेव', 'श्रीमद्भागवत एवं विष्णु पुराण के अनुसार, एक बार महर्षि दुर्वासा ने देवराज इन्द्र को एक दिव्य पुष्पमाला भेंट की। ऐश्वर्य के मद में चूर इन्द्र ने वह माला अपने ऐरावत हाथी के मस्तक पर रख दी। हाथी ने माला को पैरों तले कुचल दिया। इस अपमान से कुपित होकर दुर्वासा ऋषि ने शाप दिया कि तुम्हारा तीनों लोकों का ऐश्वर्य और श्री नष्ट हो जाए। शाप के प्रभाव से देवता निर्बल हो गए और दैत्यराज बलि ने स्वर्ग पर अधिकार कर लिया।\n\nहताश देवता भगवान विष्णु की शरण में गए। श्रीहरि ने युक्ति दी कि दैत्यों से संधि कर क्षीरसागर का मंथन करो, जिससे अमृत निकलेगा। मन्दराचल पर्वत को मथानी और नागराज वासुकि को नेती बनाया गया। जब मन्दराचल समुद्र में डूबने लगा, तब भगवान विष्णु ने कच्छप (कूर्म) अवतार धारण कर पर्वत को अपनी पीठ पर संभाला। मंथन से सर्वप्रथम कालकूट हलाहल विष निकला, जिससे तीनों लोक जलने लगे। देवताओं की करुण पुकार पर भगवान शिव ने उस विष को पीकर अपने कण्ठ में धारण कर लिया, जिससे वे नीलकण्ठ कहलाए। तत्पश्चात् कामधेनु, उच्चैःश्रवा अश्व, ऐरावत, कौस्तुभ मणि, कल्पवृक्ष, रम्भा, महालक्ष्मी, वारुणी, धन्वन्तरि और अमृत कलश प्रकट हुए। मोहिनी रूप धरकर भगवान विष्णु ने देवताओं को अमृतपान कराया।', NULL, 'जीवन भी एक क्षीरसागर है। साधना रूपी मंथन में पहले विष (कष्ट और वासनाएं) बाहर आते हैं, जिन्हें धैर्य से सहना पड़ता है, तभी अंत में शांति रूपी अमृत प्राप्त होता है।', 'Life is a cosmic ocean. Spiritual churning initially surfaces latent poisons which require poise, ultimately yielding divine nectar and inner illumination.', 1),
('katha_satyanarayan', 'श्री सत्यनारायण व्रत कथा (सम्पूर्ण ५ अध्याय)', 'भगवान श्री सत्यनारायण (विष्णु)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'સત્ય જ નારાયણ છે અને નારાયણ જ પરમ સત્ય છે. જે માનવ સત્ય આચરીને પ્રભુની પૂજા કરે છે, તે પરમ સુખ અને મુક્તિ પામે છે.', 'सत्य हेच नारायण आणि नारायण हेच परम सत्य आहेत. जो मानव सत्याचे आचरण करून ईश्वराची पूजा करतो, त्याला सर्व सुख आणि मोक्ष प्राप्त होतो.', NULL, NULL, NULL, NULL, 'पूर्णिमा, संक्रान्ति अथवा किसी भी शुभ अवसर पर श्री सत्यनारायण व्रत करने से समस्त कष्टों का नाश और परमानन्द की प्राप्ति होती है।', '35-45 मिनट', 'स्कन्द पुराण के रेवाखण्ड से उद्धृत, भगवान सत्यनारायण की सर्वमनोरथ सिद्धि, दारिद्र्य नाश एवं सत्य धर्म प्रतिष्ठापना की पावन कथा।', 'श्री सत्यनारायण व्रत कथा (सम्पूर्ण ५ अध्याय)', 'श्रीमत्सत्यनारायणव्रतकथा', 'श्रीमत्सत्यनारायणव्रतकथा', 'vrat_katha', 'महापर्व व्रत कथा', 'भगवान श्री सत्यनारायण (विष्णु)', 'एक समय नैमिषारण्य तीर्थ में शौनकादि ऋषियों ने महर्षि सूत जी से पूछा कि कलियुग में मनुष्य किस सरल उपाय से मनोवांछित फल प्राप्त कर सकता है? सूत जी बोले—एक बार देवर्षि नारद जी ने भगवान विष्णु से यही प्रश्न किया था। तब भगवान ने कहा: वत्स! कलियुग में सत्यनारायण का व्रत सर्वफलप्रदाता है।\n\nकाशीपुरी में शतानन्द नाम का एक दरिद्र ब्राह्मण भिक्षाटन से जीवन यापन करता था। भगवान ने वृद्ध ब्राह्मण का रूप धारण कर उसे सत्यनारायण व्रत की विधि बताई। ब्राह्मण ने सपरिवार व्रत किया और अपार ऐश्वर्य प्राप्त किया। उसी ब्राह्मण को देखकर एक निर्धन काष्ठ विक्रेता (लकड़हारे) ने भी व्रत का संकल्प लिया और भगवान की कृपा से धनवान बना।\n\nतृतीय अध्याय में साधु वैश्य की कथा है, जिसने सन्तान प्राप्ति के लिए व्रत का संकल्प लिया था। कन्या कलावती के जन्म के बाद भी उसने लोभवश व्रत नहीं किया, जिससे उसे राजा चन्द्रकेतु के कारागार में बन्दी होना पड़ा। पश्चाताप कर जब उसकी पत्नी लीलावती ने व्रत किया, तब वे कारागार से मुक्त हुए।\n\nचतुर्थ अध्याय में साधु वैश्य के रत्न-नौका पर भगवान की परीक्षा और दण्डवत क्षमा याचना की कथा है।\n\nपंचम अध्याय में राजा तुंगध्वज की कथा है, जिन्होंने वन में गोपों द्वारा दिए गए सत्यनारायण प्रसाद का अनादर किया, जिससे उनका राजपाट नष्ट हो गया। पश्चात् उन्होंने गोपों सहित क्षमा मांगकर प्रसाद ग्रहण किया और पुनः अपना राज्य प्राप्त किया।', NULL, 'सत्य ही नारायण हैं और नारायण ही सत्य हैं। जो मनुष्य सत्य का आचरण करते हुए भगवान का पूजन करता है, वह इस लोक में सुख भोगकर मोक्ष प्राप्त करता है।', 'Truth alone is Narayana and Narayana is the Supreme Truth. Whosoever reveres the Lord through truthful conduct and steadfast devotion attains worldly joy and ultimate spiritual liberation.', 1),
('katha_shanivar', 'शनिवार व्रत कथा (शनि देव एवं नवग्रह)', 'कर्मफलदाता शनि देव', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'શનિદેવ ન્યાયના દેવ છે. સત્ય માર્ગે ચાલનાર અને ગરીબોની સેવા કરનાર પર શનિદેવ સદાય કૃપાળુ રહે છે.', 'शनिदेव कर्माचे फळ देणारे निष्पक्ष न्यायमूर्ती आहेत. सत्याचे आचरण करणाऱ्यांवर शनिदेवाची कृपा सदैव राहते.', NULL, NULL, NULL, NULL, 'शनिवार का व्रत रखने और पीपल पर दीप जलाने से साढ़ेसाती, ढैय्या, शनि पीड़ा और आकस्मिक संकटों का शमन होता है।', '18-22 मिनट', 'नवग्रहों में ज्येष्ठता का विवाद, राजा विक्रमादित्य का न्याय, शनि देव का प्रकोप एवं अन्ततः क्षमा याचना कर सुख-शांति की पुनः प्राप्ति।', 'शनिवार व्रत कथा (शनि देव एवं नवग्रह)', 'शनिवारव्रतकथा सौरिकृपा', 'शनिवारव्रतकथा सौरिकृपा', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'कर्मफलदाता शनि देव', 'एक बार स्वर्गलोक में सूर्य, चन्द्र, मंगल, बुध, बृहस्पति, शुक्र, शनि, राहु और केतु—इन नवग्रहों में विवाद हुआ कि हममें सबसे श्रेष्ठ कौन है? निर्णय के लिए वे देवराज इन्द्र के पास गए। इन्द्र ने असमर्थता जताते हुए उन्हें पृथ्वी पर न्यायप्रिय राजा विक्रमादित्य के पास भेज दिया।\n\nराजा विक्रमादित्य ने नौ धातुओं—स्वर्ण, रजत, कांस्य, ताम्र, सीसा, रांगा, जस्ता, अभ्रक और लोहे के नौ आसन बनवाए। लोहे का आसन सबसे अंत में रखा गया। शनि देव लोहे के आसन पर बैठे और इसे अपना अपमान समझा। शनि देव ने विक्रमादित्य से कहा—राजा! तुम मुझे नहीं जानते। मेरी दृष्टि से कोई नहीं बच सकता। इसके बाद राजा पर शनि की साढ़ेसाती प्रारंभ हुई। राजा को देश निकाला मिला, हाथ-पैर कटवा दिए गए और वे एक तेली के घर कोल्हू चलाने लगे। जब विक्रमादित्य ने अपनी भूल स्वीकार कर शनिवार को दीप जलाकर शनि स्तुति की, तब शनि देव प्रसन्न हुए और उनके अंग पूर्ववत कर पुनः उज्जैन का राजा बना दिया।', NULL, 'शनि देव शत्रु नहीं, निष्पक्ष कर्मफलदाता हैं। जो सत्य के मार्ग पर चलता है और दीन-दुखियों की सेवा करता है, शनि देव उस पर असीम कृपा बरसाते हैं।', 'Lord Shani is the righteous dispenser of karma. Genuine humility, service to the needy, and Saturday prayers avert distress and bless one with stability.', 1),
('katha_shiva_vivah', 'शिव-पार्वती पावन विवाह कथा', 'महादेव शिव एवं माता पार्वती', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'માતા પાર્વતીની તપસ્યા અને મહાદેવની કૃપા દર્શાવે છે કે સાચી ભક્તિ અને નિષ્ઠાથી ઈશ્વરને પણ પામી શકાય છે.', 'माता पार्वतींचे खडतर तप आणि शंकरांचे औदार्य हेच सिद्ध करते की शुद्ध प्रेमाने ईश्वरही वश होतो.', NULL, NULL, NULL, NULL, 'शिव-पार्वती विवाह कथा का पाठ करने से दांपत्य जीवन में मधुरता आती है, सुयोग्य जीवनसाथी मिलता है और घर में मंगलकारी ऊर्जा का संचार होता है।', '25-30 मिनट', 'सती का देहत्याग, गिरिराज हिमवान के घर पार्वती के रूप में पुनर्जन्म, कठोर तपस्या, कामदेव दहन और महाशिवरात्रि के पावन परिणय की अनुपम गाथा।', 'शिव-पार्वती पावन विवाह कथा', 'शिवपार्वतीकल्याणमहोत्सव', 'शिवपार्वतीकल्याणमहोत्सव', 'pauranik_katha', 'पौराणिक लीला कथा', 'महादेव शिव एवं माता पार्वती', 'दक्ष प्रजापति के यज्ञ में अपने पति महादेव का अपमान सहन न कर पाने के कारण माता सती ने योगाग्नि में अपने प्राणों की आहुति दे दी। इसके पश्चात् उन्होंने पर्वतराज हिमवान और मैनावती के घर उमा (पार्वती) के रूप में जन्म लिया। नारद जी ने माता-पिता को बताया कि इनका विवाह केवल दिगम्बर महादेव से ही सम्भव है। पार्वती जी ने वन में जाकर हजारों वर्षों तक निराहार रहकर कठोर तपस्या की।\n\nउनकी तपस्या की परीक्षा लेने स्वयं सप्तर्षि आए, किन्तु पार्वती जी अपने संकल्प पर अडिग रहीं—\"वरउँ संभु न त रहउँ कुआरी।\" दूसरी ओर तारकासुर के अत्याचार से त्रस्त देवताओं ने शिव जी की समाधि भंग करने कामदेव को भेजा। महादेव ने तीसरा नेत्र खोलकर कामदेव को भस्म कर दिया। अन्ततः पार्वती जी की अनन्य निष्ठा से प्रसन्न होकर भगवान शिव प्रकट हुए और विवाह का प्रस्ताव स्वीकार किया। महाशिवरात्रि के शुभ दिन नंदी, भृंगी, भूत, प्रेत और समस्त देवताओं की अद्भुत बारात लेकर महादेव हिमवान के नगर पहुंचे। ब्रह्मा जी ने विवाह के वैदिक मन्त्र पढ़े और माता पार्वती तथा महादेव का पावन परिणय सम्पन्न हुआ।', NULL, 'माता पार्वती का तप और भगवान शिव का संयम यह सिखाता है कि आत्मिक प्रेम और निष्ठा से ईश्वर को भी वशीभूत किया जा सकता है।', 'Mother Parvati’s unwavering penance and Shiva’s cosmic stillness illustrate that sincere love and dedication surmount all worldly impediments.', 1),
('katha_somvar', 'सोमवार व्रत कथा (भगवान शिव कृपा)', 'देवाधिदेव महादेव शिव', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'ભોળાનાથ માત્ર શ્રદ્ધા અને સમર્પણના ભૂખ્યા છે. સોમવારનું વ્રત જીવનના સઘળા સંકટો દૂર કરી સુખ અને દીર્ઘાયુ આપે છે.', 'भोळेनाथ केवळ निष्काम भक्तीने प्रसन्न होतात. सोमवारचे व्रत सर्व संकटांचे निवारण करून दीर्घायुष्य आणि शांती प्रदान करते.', NULL, NULL, NULL, NULL, 'सोमवार का व्रत रखने से मानसिक शान्ति, रोग-शोक से मुक्ति, सुयोग्य जीवनसाथी और भगवान आशुतोष का अक्षय आशीर्वाद प्राप्त होता है।', '15-20 मिनट', 'एक निःसंतान धर्मात्मा साहूकार की शिव भक्ति, पुत्र प्राप्ति, अल्पायु संकट एवं महादेव-पार्वती जी के अनुग्रह से दीर्घायु जीवन की अमर गाथा।', 'सोमवार व्रत कथा (भगवान शिव कृपा)', 'सोमवारव्रतकथा शिवप्रीतिकरी', 'सोमवारव्रतकथा शिवप्रीतिकरी', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'देवाधिदेव महादेव शिव', 'किसी नगर में एक गुणवान साहूकार रहता था। उसके घर में धन-धान्य की कोई कमी न थी, किन्तु कोई संतान न होने से वह अत्यधिक दुःखी रहता था। वह प्रतिदिन शिव मन्दिर जाकर शिवलिंग पर जल और बेलपत्र अर्पित करता था। माता पार्वती ने साहूकार की निष्काम भक्ति देखकर महादेव से उस पर कृपा करने की प्रार्थना की। महादेव ने कहा—देवी! इसके भाग्य में पुत्र योग नहीं है, यदि दिया भी जाए तो वह मात्र बारह वर्ष की आयु तक ही जीवित रहेगा। साहूकार ने यह सब सुन लिया, फिर भी वह विचलित न हुआ।\n\nसाहूकार के घर एक सुन्दर पुत्र ने जन्म लिया। जब वह ग्यारह वर्ष का हुआ, तो साहूकार ने उसे उसके मामा के साथ काशी विद्याध्ययन के लिए भेजा और मार्ग में यज्ञ-हवन करते हुए ब्राह्मणों को भोजन कराने का निर्देश दिया। मार्ग में एक राजकुमारी के विवाह में धोखे से इस बालक का विवाह संपन्न हुआ।\n\nकाशी में जब बालक बारहवें वर्ष में प्रविष्ट हुआ, तो काल के प्रभाव से उसके प्राण पखेरू उड़ गए। उसके मामा विलाप करने लगे। उसी समय भगवान शिव और माता पार्वती वहां से निकले। माता पार्वती के करुण अनुग्रह पर औघड़दानी महादेव ने बालक को जीवनदान प्रदान किया। बालक अपनी वधू के साथ सकुशल घर लौटा।', NULL, 'भगवान भोलेनाथ भाव के भूखे हैं। सच्चे हृदय से किया गया सोमवार का व्रत अल्पायु संकट को भी टालकर जीवन में नवप्रभात ला देता है।', 'Lord Shiva is easily pleased by pure devotion. Steadfast Monday fasting dispels all distress, prolongs longevity, and grants inner peace.', 1),
('katha_vaibhav_lakshmi', 'शुक्रवार वैभव लक्ष्मी व्रत कथा', 'माता वैभव लक्ष्मी', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-10-31 09:54:11', '2026-10-31 09:54:11', 'જ્યાં પ્રેમ, સદ્ભાવ અને પવિત્રતા હોય છે ત્યાં લક્ષ્મીજી વાસ કરે છે. વૈભવ લક્ષ્મી વ્રતથી સર્વ કષ્ટો નાશ પામે છે.', 'जिथे स्वच्छता आणि सद्भाव असतो तिथेच लक्ष्मीचा वास असतो. वैभव लक्ष्मी व्रताने सर्व दारिद्र्य दूर होते.', NULL, NULL, NULL, NULL, 'शुक्रवार को वैभव लक्ष्मी का व्रत करने से घर में दारिद्र्य का नाश होता है, सुख-समृद्धि, व्यापार में उन्नति और गृह-क्लेश से मुक्ति मिलती है।', '15-20 मिनट', 'शीला नामक साध्वी स्त्री की अटूट भक्ति, जुए और कुसंगत में फंसे पति का उद्धार और माता लक्ष्मी के अष्ट स्वरूपों की आराधना।', 'शुक्रवार वैभव लक्ष्मी व्रत कथा', 'वैभवलक्ष्मीव्रतकथा श्रीप्रदा', 'वैभवलक्ष्मीव्रतकथा श्रीप्रदा', 'vrat_katha', 'साप्ताहिक व्रत कथा', 'माता वैभव लक्ष्मी', 'एक बड़े शहर में शीला नाम की एक धर्मपरायण स्त्री अपने पति के साथ रहती थी। उसका पति अत्यंत परिश्रमी और सुशील था। दोनों सुखी जीवन व्यतीत कर रहे थे। कालान्तर में उसका पति कुसंगति में पड़ गया और मद्यपान तथा जुए का आदी हो गया। सारा संचित धन समाप्त हो गया और घर में भुखमरी की नौबत आ गई।\n\nएक शुक्रवार को शीला के द्वार पर एक वृद्ध तेजस्विनी मां आई। शीला ने सत्कार कर अपने आंसुओं से उनका स्वागत किया। मां ने कहा—बेटी! मैं लक्ष्मी का स्वरूप हूं। तू निराश न हो। मां ने उसे शुक्रवार वैभव लक्ष्मी व्रत की सरल विधि बताई: श्रीयंत्र का पूजन, खीर का भोग और शुक्रवार की शाम को दीप प्रज्वलन। शीला ने पूर्ण निष्ठा से व्रत किया। उसके पति की बुद्धि शुद्ध हो गई, उसने कुसंगति त्याग दी और पुनः परिश्रम कर धन अर्जित करने लगा। घर में पुनः सुख-शान्ति और वैभव छा गया।', NULL, 'माता लक्ष्मी का वास वहीं होता है जहां सद्भाव, स्वच्छता और प्रेम है। वैभव लक्ष्मी व्रत से हर प्रकार का दारिद्र्य मिट जाता है।', 'Goddess Lakshmi abides where truth, cleanliness, and harmony reign. Friday observance dispels poverty and fills homes with peace and prosperity.', 1);
